/* src/webview/webviewScrollStateScripts.js */
(function () {
    'use strict';

    function capture(container, options) {
        if (!container || !options || typeof options.getKey !== 'function') return null;
        var selector = options.itemSelector;
        var items = selector && container.querySelectorAll
            ? Array.from(container.querySelectorAll(selector))
            : [];
        var containerRect = container.getBoundingClientRect();
        var anchorItem = items.find(function (item) {
            var rect = item.getBoundingClientRect();
            return rect.bottom > containerRect.top && rect.top < containerRect.bottom;
        }) || null;
        var key = anchorItem ? options.getKey(anchorItem) : null;
        var endThreshold = Number(options.endThreshold);
        var atEnd = Number.isFinite(endThreshold)
            && endThreshold >= 0
            && container.scrollHeight - container.clientHeight - container.scrollTop <= endThreshold;
        return {
            scrollTop: Math.max(0, Number(container.scrollTop) || 0),
            itemKey: typeof key === 'string' && key ? key : null,
            itemOffset: anchorItem
                ? anchorItem.getBoundingClientRect().top - containerRect.top
                : 0,
            atEnd: atEnd,
        };
    }

    function restore(container, anchor, options) {
        if (!container || !anchor || !options || typeof options.getKey !== 'function') return false;
        if (options.followEnd && anchor.atEnd) {
            container.scrollTop = Math.max(0, container.scrollHeight - container.clientHeight);
            return true;
        }
        var items = options.itemSelector && container.querySelectorAll
            ? Array.from(container.querySelectorAll(options.itemSelector))
            : [];
        var item = anchor.itemKey
            ? items.find(function (candidate) {
                return options.getKey(candidate) === anchor.itemKey;
            })
            : null;
        if (item) {
            var containerTop = container.getBoundingClientRect().top;
            container.scrollTop += item.getBoundingClientRect().top
                - containerTop
                - anchor.itemOffset;
            return true;
        }
        var maxScrollTop = Math.max(0, container.scrollHeight - container.clientHeight);
        container.scrollTop = Math.min(
            Math.max(0, Number(anchor.scrollTop) || 0),
            maxScrollTop
        );
        return true;
    }

    window.__agentPivotScrollState = Object.freeze({
        capture: capture,
        restore: restore,
    });
})();

/* src/webview/webviewAiSessionViewStateScripts.js */
function normalizeAiSessionTab(value) {
    return value === 'active' ? 'active' : 'sessions';
}

function normalizeAiSessionSurface(value) {
    return value === 'worktree' ? 'worktree' : 'chats';
}

function getAdjacentAiSessionSurface(surface, key) {
    surface = normalizeAiSessionSurface(surface);
    if (key === 'ArrowLeft' || key === 'ArrowRight') {
        return surface === 'worktree' ? 'chats' : 'worktree';
    }
    if (key === 'Home') return 'worktree';
    if (key === 'End') return 'chats';
    return surface;
}

function readAiSessionSurfaceState(vscodeApi) {
    var state = vscodeApi && typeof vscodeApi.getState === 'function'
        ? vscodeApi.getState() || {}
        : {};
    return state.aiSessionSurfaces && typeof state.aiSessionSurfaces === 'object'
        && !Array.isArray(state.aiSessionSurfaces)
        ? Object.assign({}, state.aiSessionSurfaces)
        : {};
}

function writeAiSessionSurfaceState(vscodeApi, projectId, surface) {
    if (!vscodeApi || typeof vscodeApi.setState !== 'function' || !projectId) return;
    var state = typeof vscodeApi.getState === 'function' ? vscodeApi.getState() || {} : {};
    var surfaces = readAiSessionSurfaceState(vscodeApi);
    surfaces[projectId] = normalizeAiSessionSurface(surface);
    vscodeApi.setState(Object.assign({}, state, { aiSessionSurfaces: surfaces }));
}

function selectAiSessionSurfaceDom(projectDiv, surface) {
    if (!projectDiv || typeof projectDiv.querySelectorAll !== 'function') return null;
    surface = normalizeAiSessionSurface(surface);
    var sessionSection = projectDiv.querySelector('.codex-sessions');
    if (sessionSection && typeof sessionSection.setAttribute === 'function') {
        sessionSection.setAttribute('data-selected-ai-session-surface', surface);
    }
    var selectedTab = null;
    projectDiv.querySelectorAll('[data-ai-session-surface-tab]').forEach(tab => {
        var selected = tab.getAttribute('data-ai-session-surface-tab') === surface;
        tab.setAttribute('aria-selected', selected ? 'true' : 'false');
        tab.setAttribute('tabindex', selected ? '0' : '-1');
        if (selected) selectedTab = tab;
    });
    projectDiv.querySelectorAll('[data-ai-session-surface-panel]').forEach(panel => {
        panel.toggleAttribute(
            'hidden',
            panel.getAttribute('data-ai-session-surface-panel') !== surface
        );
    });
    return selectedTab;
}

function restoreAiSessionSurfaceFromState(projectDiv, vscodeApi) {
    if (!projectDiv) return null;
    var projectId = projectDiv.getAttribute('data-id');
    var surfaces = readAiSessionSurfaceState(vscodeApi);
    var section = projectDiv.querySelector('.codex-sessions');
    var fallback = section && typeof section.getAttribute === 'function'
        ? section.getAttribute('data-selected-ai-session-surface') || 'worktree'
        : 'worktree';
    return selectAiSessionSurfaceDom(
        projectDiv,
        Object.prototype.hasOwnProperty.call(surfaces, projectId)
            ? surfaces[projectId]
            : fallback
    );
}

function getSelectedAiSessionSurface(projectDiv) {
    if (!projectDiv || typeof projectDiv.querySelector !== 'function') return null;
    var selected = projectDiv.querySelector(
        '[data-ai-session-surface-tab][aria-selected="true"]'
    );
    return selected
        ? normalizeAiSessionSurface(selected.getAttribute('data-ai-session-surface-tab'))
        : null;
}

function readAiSessionWorktreeCollapseState(vscodeApi) {
    var state = vscodeApi && typeof vscodeApi.getState === 'function' ? vscodeApi.getState() || {} : {};
    return state.aiSessionCollapsedWorktrees
        && typeof state.aiSessionCollapsedWorktrees === 'object'
        && !Array.isArray(state.aiSessionCollapsedWorktrees)
        ? Object.assign({}, state.aiSessionCollapsedWorktrees)
        : {};
}

function readAiSessionMemberDetailsState(vscodeApi) {
    var state = vscodeApi && typeof vscodeApi.getState === 'function' ? vscodeApi.getState() || {} : {};
    return state.aiSessionExpandedGroupMembers
        && typeof state.aiSessionExpandedGroupMembers === 'object'
        && !Array.isArray(state.aiSessionExpandedGroupMembers)
        ? Object.assign({}, state.aiSessionExpandedGroupMembers)
        : {};
}

// M3: the member summary toggles per-member details (PRD §10). Expansion is
// transient view state — preserved across reloads and authoritative
// replacements exactly like the group collapse state.
function setWorktreeGroupMemberDetailsExpanded(group, expanded) {
    if (!group) return false;
    var toggle = group.querySelector('[data-action="toggle-group-member-details"]');
    var details = group.querySelector('.ai-session-worktree-member-details');
    if (!toggle || !details) return false;
    expanded = expanded !== false;
    toggle.setAttribute('aria-expanded', expanded ? 'true' : 'false');
    // Keep the accessible name honest about what the toggle will do next.
    var label = expanded
        ? toggle.getAttribute('data-label-collapse')
        : toggle.getAttribute('data-label-expand');
    if (label) {
        toggle.setAttribute('aria-label', label);
    }
    group.toggleAttribute('data-member-details-expanded', expanded);
    details.toggleAttribute('hidden', !expanded);
    return true;
}

function getAiSessionWorktreeGroupKey(group) {
    // Reserved identities first: the anchor and manifest groups must never
    // collide with each other or with unmanaged rows on an empty
    // repository/path pair.
    if (group?.hasAttribute('data-worktree-anchor')) {
        return '["__anchor__"]';
    }
    var groupId = group?.getAttribute('data-group-id');
    if (groupId) {
        return JSON.stringify(['group', groupId]);
    }
    return JSON.stringify([
        group?.getAttribute('data-worktree-repository-key') || '',
        group?.getAttribute('data-worktree-path') || '',
        !!group?.hasAttribute('data-worktree-unmanaged'),
    ]);
}

function writeAiSessionWorktreeCollapseState(vscodeApi, projectDiv) {
    if (!vscodeApi || typeof vscodeApi.setState !== 'function' || !projectDiv) return;
    var projectId = projectDiv.getAttribute('data-id');
    if (!projectId) return;
    var state = typeof vscodeApi.getState === 'function' ? vscodeApi.getState() || {} : {};
    var projects = readAiSessionWorktreeCollapseState(vscodeApi);
    projects[projectId] = Array.from(new Set(Array.from(projectDiv.querySelectorAll(
        '.ai-session-worktree-group[data-worktree-collapsed]'
    )).map(getAiSessionWorktreeGroupKey)));
    var memberDetails = readAiSessionMemberDetailsState(vscodeApi);
    memberDetails[projectId] = Array.from(new Set(Array.from(projectDiv.querySelectorAll(
        '.ai-session-worktree-group[data-member-details-expanded]'
    )).map(getAiSessionWorktreeGroupKey)));
    vscodeApi.setState(Object.assign({}, state, {
        aiSessionCollapsedWorktrees: projects,
        aiSessionExpandedGroupMembers: memberDetails,
    }));
    // M2 transition: mirror the collapsed set into the host-persisted window
    // view state so the PR-D tree view restores it across reloads. Every
    // caller is a user-intent path (toggle / collapse-all / reveal-expand),
    // never a replacement replay, so this posts exactly once per gesture.
    if (typeof vscodeApi.postMessage === 'function') {
        vscodeApi.postMessage({
            type: 'set-ai-session-collapsed-worktree-groups',
            version: 1,
            projectId: projectId,
            collapsedKeys: projects[projectId],
        });
    }
    syncAiSessionWorktreeCollapseAllButton(projectDiv);
}

// The collapse-all affordance acts like every group toggle at once: any
// expanded group collapses everything, otherwise everything expands.
function toggleAllAiSessionWorktrees(projectDiv) {
    if (!projectDiv || typeof projectDiv.querySelectorAll !== 'function') return;
    var groups = Array.from(projectDiv.querySelectorAll('.ai-session-worktree-group'));
    if (!groups.length) return;
    var anyExpanded = groups.some(group => !group.hasAttribute('data-worktree-collapsed'));
    groups.forEach(group => {
        setAiSessionWorktreeExpanded(
            group.querySelector('.ai-session-worktree-header'),
            !anyExpanded
        );
    });
    writeAiSessionWorktreeCollapseState(window.vscode, projectDiv);
}

function syncAiSessionWorktreeCollapseAllButton(projectDiv) {
    if (!projectDiv || typeof projectDiv.querySelector !== 'function') return;
    var button = projectDiv.querySelector('[data-action="toggle-all-ai-session-worktrees"]');
    if (!button) return;
    var anyExpanded = Array.from(projectDiv.querySelectorAll('.ai-session-worktree-group'))
        .some(group => !group.hasAttribute('data-worktree-collapsed'));
    button.setAttribute('data-collapse-all-state', anyExpanded ? 'expanded' : 'collapsed');
    var label = anyExpanded ? 'Collapse all worktrees' : 'Expand all worktrees';
    button.setAttribute('aria-label', label);
    button.setAttribute('data-tooltip', label);
}

function setAiSessionWorktreeExpanded(header, expanded) {
    if (!header) return false;
    var group = header.closest('.ai-session-worktree-group');
    if (!group) return false;
    expanded = expanded !== false;
    header.setAttribute('aria-expanded', expanded ? 'true' : 'false');
    group.toggleAttribute('data-worktree-collapsed', !expanded);
    var list = group.querySelector('.ai-session-worktree-session-list');
    if (list) list.toggleAttribute('hidden', !expanded);
    return true;
}

function setAiSessionWorktreeGroupExpanded(projectDiv, group, expanded) {
    if (!projectDiv || !group) return false;
    var key = getAiSessionWorktreeGroupKey(group);
    var changed = false;
    projectDiv.querySelectorAll('.ai-session-worktree-group').forEach(candidate => {
        if (getAiSessionWorktreeGroupKey(candidate) !== key) return;
        changed = setAiSessionWorktreeExpanded(
            candidate.querySelector('.ai-session-worktree-header'),
            expanded
        ) || changed;
    });
    return changed;
}

function restoreAiSessionWorktreeCollapseState(projectDiv, vscodeApi) {
    if (!projectDiv) return;
    var projectId = projectDiv.getAttribute('data-id');
    var projects = readAiSessionWorktreeCollapseState(vscodeApi);
    var collapsed = new Set(Array.isArray(projects[projectId]) ? projects[projectId] : []);
    projectDiv.querySelectorAll('.ai-session-worktree-group').forEach(group => {
        setAiSessionWorktreeExpanded(
            group.querySelector('.ai-session-worktree-header'),
            !collapsed.has(getAiSessionWorktreeGroupKey(group))
        );
    });
    var memberDetails = readAiSessionMemberDetailsState(vscodeApi);
    var expandedMembers = new Set(
        Array.isArray(memberDetails[projectId]) ? memberDetails[projectId] : []);
    projectDiv.querySelectorAll('.ai-session-worktree-group[data-group-id]').forEach(group => {
        if (expandedMembers.has(getAiSessionWorktreeGroupKey(group))) {
            setWorktreeGroupMemberDetailsExpanded(group, true);
        }
    });
    syncAiSessionWorktreeCollapseAllButton(projectDiv);
}

function parseAiSessionConversationFocusOrigin(message) {
    var expectedKeys = [
        'type',
        'version',
        'projectId',
        'provider',
        'sessionId',
        'interactionId',
    ];
    if (!message || typeof message !== 'object' || Array.isArray(message)
        || Object.keys(message).length !== expectedKeys.length
        || !expectedKeys.every(key =>
            Object.prototype.hasOwnProperty.call(message, key))
        || message.type !== 'focus-ai-session-conversation-origin'
        || message.version !== 1
        || (message.provider !== 'codex'
            && message.provider !== 'kimi'
            && message.provider !== 'claude')
        || !['projectId', 'sessionId', 'interactionId'].every(key =>
            typeof message[key] === 'string' && message[key].trim())) {
        return null;
    }
    return message;
}

function parseAiSessionRevealRequest(message) {
    var expectedKeys = ['projectId', 'provider', 'sessionId', 'type', 'version'];
    if (!message || typeof message !== 'object' || Array.isArray(message)
        || Object.keys(message).length !== expectedKeys.length
        || !expectedKeys.every(key =>
            Object.prototype.hasOwnProperty.call(message, key))
        || message.type !== 'reveal-ai-session-requested'
        || message.version !== 1
        || (message.provider !== 'codex'
            && message.provider !== 'kimi'
            && message.provider !== 'claude')
        || !['projectId', 'sessionId'].every(key =>
            typeof message[key] === 'string' && message[key].trim())) {
        return null;
    }
    return message;
}

// Session-switch commands land here: the view follows the switched session
// to wherever it lives — its worktree group (expanded, scrolled into view)
// or the Chats active list. Scroll-only; keyboard focus stays put.
function revealAiSessionInWorkspace(message) {
    var request = parseAiSessionRevealRequest(message);
    if (!request || typeof document === 'undefined'
        || typeof document.querySelectorAll !== 'function') {
        return false;
    }
    var projectDiv = Array.from(document.querySelectorAll(
        '.workspace-card[data-current-workspace][data-id]'
    )).find(candidate =>
        candidate.getAttribute('data-id') === request.projectId
    );
    if (!projectDiv) {
        return false;
    }
    var rowSelector = '[data-session-provider][data-session-id]';
    var matches = candidate =>
        candidate.getAttribute('data-session-provider') === request.provider
        && candidate.getAttribute('data-session-id') === request.sessionId;
    var worktreeRow = Array.from(projectDiv.querySelectorAll(
        '[data-ai-session-surface-panel="worktree"] ' + rowSelector
    )).find(matches);
    var surface = worktreeRow ? 'worktree' : 'chats';
    selectAiSessionSurfaceDom(projectDiv, surface);
    writeAiSessionSurfaceState(window.vscode, request.projectId, surface);
    if (window.vscode && typeof window.vscode.postMessage === 'function') {
        window.vscode.postMessage({
            type: 'select-ai-session-surface',
            version: 1,
            projectId: request.projectId,
            surface: surface,
        });
    }
    if (worktreeRow) {
        var group = worktreeRow.closest('.ai-session-worktree-group');
        if (group) {
            setAiSessionWorktreeGroupExpanded(projectDiv, group, true);
            writeAiSessionWorktreeCollapseState(window.vscode, projectDiv);
        }
        worktreeRow.scrollIntoView({ block: 'nearest' });
        return true;
    }
    selectAiSessionTabDom(projectDiv, 'active');
    writeAiSessionTabState(window.vscode, request.projectId, 'active');
    var activeRow = Array.from(projectDiv.querySelectorAll(
        '.active-ai-session-row' + rowSelector
    )).find(matches) || Array.from(projectDiv.querySelectorAll(
        '[data-ai-session-surface-panel="chats"] ' + rowSelector
    )).find(matches);
    if (activeRow) {
        activeRow.scrollIntoView({ block: 'nearest' });
        return true;
    }
    return false;
}

function focusAiSessionConversationOrigin(message) {
    var origin = parseAiSessionConversationFocusOrigin(message);
    if (!origin || typeof document === 'undefined'
        || typeof document.querySelectorAll !== 'function') {
        return false;
    }
    var projectDiv = Array.from(document.querySelectorAll(
        '.workspace-card[data-current-workspace][data-id]'
    )).find(candidate =>
        candidate.getAttribute('data-id') === origin.projectId
    );
    if (!projectDiv) {
        return false;
    }
    var rowSelector = '[data-session-provider][data-session-id]';
    var matches = candidate =>
        candidate.getAttribute('data-session-provider') === origin.provider
        && candidate.getAttribute('data-session-id') === origin.sessionId;
    // The view follows the session to the surface it lives on (same probe as
    // revealAiSessionInWorkspace): closing a conversation viewed from a
    // worktree group must not yank the Worktree surface back to Chats.
    var worktreeRow = Array.from(projectDiv.querySelectorAll(
        '[data-ai-session-surface-panel="worktree"] ' + rowSelector
    )).find(matches);
    var surface = worktreeRow ? 'worktree' : 'chats';
    selectAiSessionSurfaceDom(projectDiv, surface);
    writeAiSessionSurfaceState(window.vscode, origin.projectId, surface);
    if (window.vscode && typeof window.vscode.postMessage === 'function') {
        window.vscode.postMessage({
            type: 'select-ai-session-surface',
            version: 1,
            projectId: origin.projectId,
            surface: surface,
        });
    }
    if (worktreeRow) {
        var group = worktreeRow.closest('.ai-session-worktree-group');
        if (group) {
            setAiSessionWorktreeGroupExpanded(projectDiv, group, true);
            writeAiSessionWorktreeCollapseState(window.vscode, projectDiv);
        }
        var worktreeAction = worktreeRow.querySelector('.ai-session-primary-action');
        if (worktreeAction && typeof worktreeAction.focus === 'function') {
            worktreeAction.focus({ preventScroll: true });
        }
        worktreeRow.scrollIntoView({ block: 'nearest' });
        if (worktreeAction && document.activeElement === worktreeAction) {
            return true;
        }
        var worktreeSurfaceTab = Array.from(projectDiv.querySelectorAll(
            '[data-ai-session-surface-tab]'
        )).find(candidate =>
            candidate.getAttribute('data-ai-session-surface-tab') === 'worktree'
        );
        if (worktreeSurfaceTab && typeof worktreeSurfaceTab.focus === 'function') {
            worktreeSurfaceTab.focus({ preventScroll: true });
            return document.activeElement === worktreeSurfaceTab;
        }
        return false;
    }
    selectAiSessionTabDom(projectDiv, 'active');
    writeAiSessionTabState(window.vscode, origin.projectId, 'active');
    var row = Array.from(projectDiv.querySelectorAll(
        '.active-ai-session-row[data-session-focused]'
        + '[data-session-provider][data-session-id]'
    )).find(matches);
    if (row) {
        var header = row.querySelector('.ai-session-primary-action');
        if (header && typeof header.focus === 'function') {
            header.focus({ preventScroll: true });
        }
        row.scrollIntoView({ block: 'nearest' });
        if (header && document.activeElement === header) {
            return true;
        }
    }
    var activeTab = Array.from(projectDiv.querySelectorAll(
        '[data-ai-session-tab]'
    )).find(candidate =>
        candidate.getAttribute('data-ai-session-tab') === 'active'
    );
    if (activeTab && typeof activeTab.focus === 'function') {
        activeTab.focus({ preventScroll: true });
        return document.activeElement === activeTab;
    }
    return false;
}

function getAdjacentAiSessionTab(tab, key) {
    tab = normalizeAiSessionTab(tab);
    if (key === 'ArrowLeft' || key === 'ArrowRight') return tab === 'active' ? 'sessions' : 'active';
    if (key === 'Home') return 'active';
    if (key === 'End') return 'sessions';
    return tab;
}

function readAiSessionTabState(vscodeApi) {
    var state = vscodeApi && typeof vscodeApi.getState === 'function' ? vscodeApi.getState() || {} : {};
    return state.aiSessionTabs && typeof state.aiSessionTabs === 'object' && !Array.isArray(state.aiSessionTabs)
        ? Object.assign({}, state.aiSessionTabs)
        : {};
}

function writeAiSessionTabState(vscodeApi, projectId, tab) {
    if (!vscodeApi || typeof vscodeApi.setState !== 'function' || !projectId) return;
    var state = typeof vscodeApi.getState === 'function' ? vscodeApi.getState() || {} : {};
    var tabs = readAiSessionTabState(vscodeApi);
    tabs[projectId] = normalizeAiSessionTab(tab);
    vscodeApi.setState(Object.assign({}, state, { aiSessionTabs: tabs }));
}

function selectAiSessionTabDom(projectDiv, tab) {
    if (!projectDiv || typeof projectDiv.querySelectorAll !== 'function') return null;
    tab = normalizeAiSessionTab(tab);
    var sessionSection = projectDiv.querySelector('.codex-sessions');
    if (sessionSection && typeof sessionSection.setAttribute === 'function') {
        sessionSection.setAttribute('data-selected-ai-session-tab', tab);
    }
    var selectedTab = null;
    projectDiv.querySelectorAll('[data-ai-session-tab]').forEach(tabElement => {
        var selected = tabElement.getAttribute('data-ai-session-tab') === tab;
        tabElement.setAttribute('aria-selected', selected ? 'true' : 'false');
        tabElement.setAttribute('tabindex', selected ? '0' : '-1');
        if (selected) selectedTab = tabElement;
    });
    projectDiv.querySelectorAll('[data-ai-session-panel]').forEach(panel => {
        var selected = panel.getAttribute('data-ai-session-panel') === tab;
        panel.toggleAttribute('hidden', !selected);
    });
    return selectedTab;
}

function restoreAiSessionTabsFromState(root, vscodeApi) {
    if (!root || typeof root.querySelectorAll !== 'function') return;
    var tabs = readAiSessionTabState(vscodeApi);
    root.querySelectorAll('.workspace-card[data-current-workspace][data-id]').forEach(projectDiv => {
        var projectId = projectDiv.getAttribute('data-id');
        if (Object.prototype.hasOwnProperty.call(tabs, projectId)) {
            selectAiSessionTabDom(projectDiv, tabs[projectId]);
        }
        restoreAiSessionSurfaceFromState(projectDiv, vscodeApi);
        restoreAiSessionWorktreeCollapseState(projectDiv, vscodeApi);
    });
}

function getSelectedAiSessionTab(projectDiv) {
    if (!projectDiv || typeof projectDiv.querySelector !== 'function') return null;
    var selected = projectDiv.querySelector('[data-ai-session-tab][aria-selected="true"]');
    return selected ? normalizeAiSessionTab(selected.getAttribute('data-ai-session-tab')) : null;
}

// M2 transition: import the webview-held legacy sub-tab selection into the
// host-persisted window view state exactly once per boot ('sessions' → ALL;
// anything else is the CHATS default). The host first-writer-wins per scope,
// so a live post-upgrade selection is never clobbered by a stale boot import.
var legacyAiSessionTabImportDone = false;

function maybeImportLegacyAiSessionViewState(vscodeApi, root) {
    if (legacyAiSessionTabImportDone) {
        return;
    }
    legacyAiSessionTabImportDone = true;
    if (!vscodeApi || typeof vscodeApi.postMessage !== 'function') {
        return;
    }
    var tabs = readAiSessionTabState(vscodeApi);
    var currentCard = (root || document).querySelector(
        '.workspace-card[data-current-workspace][data-id]'
    );
    var projectId = currentCard && currentCard.getAttribute('data-id');
    var legacyTab = projectId && Object.prototype.hasOwnProperty.call(tabs, projectId)
        ? tabs[projectId]
        : null;
    if (!legacyTab) {
        return;
    }
    vscodeApi.postMessage({
        type: 'migrate-ai-session-view-state',
        version: 1,
        projectId: projectId,
        tab: legacyTab === 'sessions' ? 'all' : 'chats',
    });
}

function getAiSessionScrollItemKey(row) {
    var panel = row.closest('[data-ai-session-panel]');
    return JSON.stringify([
        panel ? panel.getAttribute('data-ai-session-panel') || '' : '',
        row.getAttribute('data-session-provider') || '',
        row.getAttribute('data-session-id') || '',
        row.getAttribute('data-pending-created-at') || '',
    ]);
}

function captureAiSessionListAnchor(list) {
    return window.__agentPivotScrollState.capture(list, {
        itemSelector: '.codex-session-row',
        getKey: getAiSessionScrollItemKey,
    });
}

function restoreAiSessionListAnchor(list, anchor) {
    return window.__agentPivotScrollState.restore(list, anchor, {
        itemSelector: '.codex-session-row',
        getKey: getAiSessionScrollItemKey,
    });
}

function getFocusedAiSessionCardIdentity(projectDiv) {
    if (!projectDiv || typeof projectDiv.querySelector !== 'function') return null;
    var row = projectDiv.querySelector(
        '.ai-session-chats-surface .codex-session-row'
        + '[data-session-focused][data-session-provider][data-session-id]'
    );
    return row ? {
        provider: row.getAttribute('data-session-provider') || '',
        sessionId: row.getAttribute('data-session-id') || '',
    } : null;
}

function captureAiSessionViewState(projectDiv) {
    var activeList = projectDiv.querySelector('.ai-session-active-panel .codex-sessions-list');
    var historyList = projectDiv.querySelector('.ai-session-history-panel .codex-sessions-list');
    var focused = typeof document !== 'undefined' ? document.activeElement : null;
    var focusedSession = getFocusedAiSessionCardIdentity(projectDiv);
    var focusedInside = focused && typeof focused.closest === 'function' && focused.closest('.project[data-id]') === projectDiv;
    var focusedRow = focusedInside ? focused.closest('.codex-session-row') : null;
    var focusedTab = focusedInside ? focused.closest('[data-ai-session-tab]') : null;
    var focusedSurfaceTab = focusedInside
        ? focused.closest('[data-ai-session-surface-tab]')
        : null;
    var selectedTab = getSelectedAiSessionTab(projectDiv);
    var selectedSurface = getSelectedAiSessionSurface(projectDiv);
    selectAiSessionSurfaceDom(projectDiv, 'chats');
    selectAiSessionTabDom(projectDiv, 'active');
    var activeAnchor = captureAiSessionListAnchor(activeList);
    selectAiSessionTabDom(projectDiv, 'sessions');
    var historyAnchor = captureAiSessionListAnchor(historyList);
    selectAiSessionTabDom(projectDiv, selectedTab);
    selectAiSessionSurfaceDom(projectDiv, selectedSurface);
    return {
        selectedSurface: selectedSurface,
        selectedTab: selectedTab,
        activeAnchor: activeAnchor,
        historyAnchor: historyAnchor,
        pendingCount: projectDiv.querySelectorAll('.active-ai-session-row[data-session-pending]').length,
        activeCount: projectDiv.querySelectorAll('.active-ai-session-row[data-session-active]').length,
        restoreFocus: !!focusedInside,
        focusedSession: focusedSession,
        focusedTab: focusedTab && focusedTab.getAttribute('data-ai-session-tab'),
        focusedSurfaceTab: focusedSurfaceTab
            && focusedSurfaceTab.getAttribute('data-ai-session-surface-tab'),
        focusedRow: focusedRow ? {
            provider: focusedRow.getAttribute('data-session-provider') || '',
            sessionId: focusedRow.getAttribute('data-session-id') || '',
            pendingCreatedAt: focusedRow.getAttribute('data-pending-created-at') || '',
            panel: focusedRow.closest('[data-ai-session-panel]')?.getAttribute('data-ai-session-panel') || '',
        } : null,
        collapsedWorktrees: Array.from(projectDiv.querySelectorAll(
            '.ai-session-worktree-group[data-worktree-collapsed]'
        )).map(getAiSessionWorktreeGroupKey),
        expandedMemberDetails: Array.from(projectDiv.querySelectorAll(
            '.ai-session-worktree-group[data-member-details-expanded]'
        )).map(getAiSessionWorktreeGroupKey),
        groupRename: window.__agentPivotWorktreeGroupRename
            && typeof window.__agentPivotWorktreeGroupRename.capture === 'function'
            ? window.__agentPivotWorktreeGroupRename.capture(projectDiv)
            : null,
        groupDeletion: window.__agentPivotWorktreeGroupDeletion
            && typeof window.__agentPivotWorktreeGroupDeletion.capture === 'function'
            ? window.__agentPivotWorktreeGroupDeletion.capture(projectDiv)
            : null,
        worktreeAdopt: window.__agentPivotWorktreeAdopt
            && typeof window.__agentPivotWorktreeAdopt.capture === 'function'
            ? window.__agentPivotWorktreeAdopt.capture(projectDiv)
            : null,
        worktreeKeys: Array.from(new Set(Array.from(projectDiv.querySelectorAll(
            '.ai-session-worktree-group'
        )).map(getAiSessionWorktreeGroupKey))),
    };
}

function restoreAiSessionViewFocus(projectDiv, viewState, selectedTab) {
    if (!viewState || !viewState.restoreFocus) return;
    if (viewState.focusedSurfaceTab) {
        var surfaceTabToFocus = Array.from(projectDiv.querySelectorAll(
            '[data-ai-session-surface-tab]'
        )).find(tab =>
            tab.getAttribute('data-ai-session-surface-tab') === viewState.focusedSurfaceTab
        );
        surfaceTabToFocus?.focus({ preventScroll: true });
        return;
    }
    if (viewState.focusedTab) {
        var tabToFocus = Array.from(projectDiv.querySelectorAll('[data-ai-session-tab]'))
            .find(tab => tab.getAttribute('data-ai-session-tab') === viewState.focusedTab);
        (tabToFocus || selectedTab)?.focus({ preventScroll: true });
        return;
    }
    if (!viewState.focusedRow) return;
    var rows = Array.from(projectDiv.querySelectorAll(
        '.ai-session-chats-surface .codex-session-row'
    ));
    var match = rows.find(row => {
        var panel = row.closest('[data-ai-session-panel]');
        return (row.getAttribute('data-session-provider') || '') === viewState.focusedRow.provider
            && (row.getAttribute('data-session-id') || '') === viewState.focusedRow.sessionId
            && (row.getAttribute('data-pending-created-at') || '') === viewState.focusedRow.pendingCreatedAt
            && (!viewState.focusedRow.panel || panel?.getAttribute('data-ai-session-panel') === viewState.focusedRow.panel);
    });
    (match?.querySelector('.ai-session-primary-action') || selectedTab)?.focus({ preventScroll: true });
}

function restoreAiSessionViewState(projectDiv, viewState, requestedTab, options) {
    if (!projectDiv || !viewState) return null;
    var collapsed = new Set(viewState.collapsedWorktrees || []);
    projectDiv.querySelectorAll('.ai-session-worktree-group').forEach(group => {
        var key = getAiSessionWorktreeGroupKey(group);
        setAiSessionWorktreeExpanded(
            group.querySelector('.ai-session-worktree-header'),
            !collapsed.has(key)
        );
    });
    var expandedMemberDetails = new Set(viewState.expandedMemberDetails || []);
    projectDiv.querySelectorAll('.ai-session-worktree-group[data-group-id]').forEach(group => {
        if (expandedMemberDetails.has(getAiSessionWorktreeGroupKey(group))) {
            setWorktreeGroupMemberDetailsExpanded(group, true);
        }
    });
    if (viewState.groupRename
        && window.__agentPivotWorktreeGroupRename
        && typeof window.__agentPivotWorktreeGroupRename.restore === 'function') {
        window.__agentPivotWorktreeGroupRename.restore(projectDiv, viewState.groupRename);
    }
    if (viewState.groupDeletion
        && window.__agentPivotWorktreeGroupDeletion
        && typeof window.__agentPivotWorktreeGroupDeletion.restore === 'function') {
        window.__agentPivotWorktreeGroupDeletion.restore(projectDiv, viewState.groupDeletion);
    }
    if (viewState.worktreeAdopt
        && window.__agentPivotWorktreeAdopt
        && typeof window.__agentPivotWorktreeAdopt.restore === 'function') {
        window.__agentPivotWorktreeAdopt.restore(projectDiv, viewState.worktreeAdopt);
    }
    var currentWorktreeKeys = Array.from(new Set(Array.from(projectDiv.querySelectorAll(
        '.ai-session-worktree-group'
    )).map(getAiSessionWorktreeGroupKey)));
    if (Array.isArray(viewState.worktreeKeys)
        && JSON.stringify(viewState.worktreeKeys) !== JSON.stringify(currentWorktreeKeys)) {
        var liveRegion = projectDiv.querySelector('[data-ai-session-live-region]');
        if (liveRegion) {
            liveRegion.textContent = 'Worktree list updated. ' + currentWorktreeKeys.length
                + ' worktree' + (currentWorktreeKeys.length === 1 ? ' shown.' : 's shown.');
        }
    }
    var activeList = projectDiv.querySelector('.ai-session-active-panel .codex-sessions-list');
    var historyList = projectDiv.querySelector('.ai-session-history-panel .codex-sessions-list');
    selectAiSessionSurfaceDom(projectDiv, 'chats');
    selectAiSessionTabDom(projectDiv, 'active');
    restoreAiSessionListAnchor(activeList, viewState.activeAnchor);
    selectAiSessionTabDom(projectDiv, 'sessions');
    restoreAiSessionListAnchor(historyList, viewState.historyAnchor);
    var selectedTab = selectAiSessionTabDom(projectDiv, requestedTab || viewState.selectedTab);
    selectAiSessionSurfaceDom(projectDiv, viewState.selectedSurface);
    if (!options || options.restoreFocus !== false) {
        restoreAiSessionViewFocus(projectDiv, viewState, selectedTab);
    }
    return selectedTab;
}

function revealChangedFocusedAiSessionCard(root, states) {
    if (!root || typeof root.querySelectorAll !== 'function'
        || !states || typeof states.get !== 'function') return;
    root.querySelectorAll('.workspace-card[data-current-workspace][data-id]').forEach(projectDiv => {
        var state = states.get(projectDiv.getAttribute('data-id'));
        var previous = state && state.view ? state.view.focusedSession : null;
        var row = projectDiv.querySelector(
            '.ai-session-active-panel .codex-session-row[data-session-focused]'
            + '[data-session-provider][data-session-id]'
        );
        if (!row) return;
        var provider = row.getAttribute('data-session-provider') || '';
        var sessionId = row.getAttribute('data-session-id') || '';
        if (previous && previous.provider === provider && previous.sessionId === sessionId) {
            return;
        }
        // Session focus moved to this card during the authoritative refresh:
        // surface it instead of preserving the stale scroll position.
        var panel = row.closest('[data-ai-session-panel]');
        if (panel && panel.hidden) {
            selectAiSessionSurfaceDom(projectDiv, 'chats');
            writeAiSessionSurfaceState(
                window.vscode,
                projectDiv.getAttribute('data-id'),
                'chats'
            );
            selectAiSessionTabDom(projectDiv, 'active');
            writeAiSessionTabState(window.vscode, projectDiv.getAttribute('data-id'), 'active');
        }
        row.scrollIntoView({ block: 'nearest' });
    });
}

function captureAiSessionProviderMenuState(projectDiv) {
    if (!projectDiv || typeof projectDiv.querySelector !== 'function') {
        return { open: false, focus: null };
    }
    var trigger = projectDiv.querySelector('[data-ai-provider-menu-trigger]');
    var menu = projectDiv.querySelector('[data-ai-provider-menu]');
    var focused = typeof document !== 'undefined' ? document.activeElement : null;
    var focusedTrigger = focused === trigger;
    var focusedOption = focused && typeof focused.closest === 'function'
        ? focused.closest('[data-ai-provider-option][data-provider]')
        : null;
    return {
        open: !!trigger && !!menu
            && trigger.getAttribute('aria-expanded') === 'true'
            && !menu.hidden,
        focus: focusedTrigger
            ? { kind: 'trigger' }
            : focusedOption && focusedOption.closest('.project[data-id]') === projectDiv
                ? {
                    kind: 'option',
                    provider: focusedOption.getAttribute('data-provider') || '',
                }
                : null,
    };
}

function restoreAiSessionProviderMenuState(projectDiv, menuState, allowed) {
    if (!allowed || !menuState || !menuState.open) {
        return;
    }
    var trigger = projectDiv.querySelector('[data-ai-provider-menu-trigger]');
    var menu = projectDiv.querySelector('[data-ai-provider-menu]');
    if (!trigger || !menu) {
        return;
    }
    trigger.setAttribute('aria-expanded', 'true');
    menu.hidden = false;
    if (menuState.focus?.kind === 'trigger') {
        trigger.focus({ preventScroll: true });
        return;
    }
    if (menuState.focus?.kind !== 'option') {
        return;
    }
    var option = Array.from(
        projectDiv.querySelectorAll('[data-ai-provider-option][data-provider]')
    ).find(candidate =>
        candidate.getAttribute('data-provider') === menuState.focus.provider
    );
    option?.focus({ preventScroll: true });
}

function captureCurrentWorkspaceAiSessionStates(root) {
    var states = new Map();
    if (!root || typeof root.querySelectorAll !== 'function') return states;
    root.querySelectorAll('.workspace-card[data-current-workspace][data-id]')
        .forEach(projectDiv => {
            var projectId = projectDiv.getAttribute('data-id');
            if (!projectId) return;
            states.set(projectId, {
                view: captureAiSessionViewState(projectDiv),
                providerMenu: captureAiSessionProviderMenuState(projectDiv),
                listScrolls: captureAiSessionListScrolls(projectDiv),
            });
        });
    return states;
}

// The worktree/chats panels scroll independently of the outer workspace
// list, so an authoritative HTML replacement must carry each inner list's
// scroll position across the new nodes; otherwise every refresh snaps the
// panel back to the top.
function captureAiSessionListScrolls(projectDiv) {
    var scrolls = [];
    projectDiv.querySelectorAll(
        '[data-ai-session-surface-panel] .ai-session-worktree-list,'
        + ' [data-ai-session-panel] .codex-sessions-list'
    ).forEach(list => {
        var panel = list.closest('[data-ai-session-surface-panel], [data-ai-session-panel]');
        if (!panel) return;
        var key = panel.getAttribute('data-ai-session-surface-panel')
            || panel.getAttribute('data-ai-session-panel');
        // Record every keyed panel list, including scrollTop 0: a capture
        // taken while the list is momentarily hidden reads 0, and skipping
        // it would leave the replacement DOM to snap back to the top.
        if (key) {
            scrolls.push({ key: key, scrollTop: Math.max(0, Number(list.scrollTop) || 0) });
        }
    });
    return scrolls;
}

function restoreAiSessionListScrolls(projectDiv, scrolls) {
    (scrolls || []).forEach(saved => {
        var panel = projectDiv.querySelector(
            '[data-ai-session-surface-panel="' + saved.key + '"],'
            + ' [data-ai-session-panel="' + saved.key + '"]'
        );
        var list = panel
            ? panel.querySelector('.ai-session-worktree-list, .codex-sessions-list')
            : null;
        if (!list) return;
        var maxScrollTop = Math.max(0, list.scrollHeight - list.clientHeight);
        list.scrollTop = Math.min(saved.scrollTop, maxScrollTop);
    });
}

function restoreCurrentWorkspaceAiSessionViewStates(root, states, canRestoreProviderMenu) {
    if (!root || typeof root.querySelectorAll !== 'function') return;
    root.querySelectorAll('.workspace-card[data-current-workspace][data-id]')
        .forEach(projectDiv => {
            var projectId = projectDiv.getAttribute('data-id');
            var state = states.get(projectId);
            if (!state) return;
            restoreAiSessionViewState(projectDiv, state.view, state.view.selectedTab, {
                restoreFocus: false,
            });
            restoreAiSessionListScrolls(projectDiv, state.listScrolls);
            restoreAiSessionProviderMenuState(
                projectDiv,
                state.providerMenu,
                !canRestoreProviderMenu || canRestoreProviderMenu(projectId)
            );
        });
}

function restoreCurrentWorkspaceAiSessionAnchorsAndFocus(root, states) {
    if (!root || typeof root.querySelectorAll !== 'function') return;
    root.querySelectorAll('.workspace-card[data-current-workspace][data-id]')
        .forEach(projectDiv => {
            var state = states.get(projectDiv.getAttribute('data-id'));
            if (!state) return;
            var selectedTab = restoreAiSessionViewState(
                projectDiv,
                state.view,
                state.view.selectedTab,
                { restoreFocus: false }
            );
            restoreAiSessionViewFocus(projectDiv, state.view, selectedTab);
        });
}

/* src/webview/webviewWorkspaceUpdateScripts.js */
function getWorkspaceUpdateDomState(root) {
    var currentGroup = root.matches?.('.open-current-workspace-group')
        ? root
        : root.querySelector('.open-current-workspace-group');
    return {
        currentWorkspaceCount: currentGroup
            ? currentGroup.querySelectorAll('.workspace-card[data-workspace-scope-identity]').length
            : 0,
    };
}

function isWorkspaceUpdateDomConsistent(message, root) {
    if (message.currentWorkspaceCount !== 0 && message.currentWorkspaceCount !== 1) {
        return false;
    }
    return getWorkspaceUpdateDomState(root).currentWorkspaceCount === message.currentWorkspaceCount;
}

// The OPEN tab regions scroll independently, so an authoritative replacement
// must carry each list's scroll position across the new nodes (same
// anchor-based pattern as the todo/skills panes; the scroll-state helper is
// optional and falls back to a clamped scrollTop).
function captureOpenTabListScroll(list, itemSelector, keyAttribute) {
    if (!list) {
        return null;
    }
    if (window.__agentPivotScrollState
        && typeof window.__agentPivotScrollState.capture === 'function') {
        return {
            anchor: window.__agentPivotScrollState.capture(list, {
                itemSelector: itemSelector,
                getKey: function (el) { return el.getAttribute(keyAttribute) || ''; },
            }),
        };
    }
    return { scrollTop: Math.max(0, Number(list.scrollTop) || 0) };
}

function restoreOpenTabListScroll(list, saved, itemSelector, keyAttribute) {
    if (!list || !saved) {
        return;
    }
    if (saved.anchor && window.__agentPivotScrollState
        && typeof window.__agentPivotScrollState.restore === 'function'
        && window.__agentPivotScrollState.restore(list, saved.anchor, {
            itemSelector: itemSelector,
            getKey: function (el) { return el.getAttribute(keyAttribute) || ''; },
        })) {
        return;
    }
    var fallbackTop = saved.anchor ? saved.anchor.scrollTop : saved.scrollTop;
    var maxScrollTop = Math.max(0, list.scrollHeight - list.clientHeight);
    list.scrollTop = Math.min(Math.max(0, Number(fallbackTop) || 0), maxScrollTop);
}

var OPEN_TAB_CURRENT_LIST_SELECTOR = '.open-current-workspace-group .group-list';
var OPEN_TAB_CURRENT_ITEM_SELECTOR = '.workspace-card[data-workspace-scope-identity]';
var OPEN_TAB_OTHER_LIST_SELECTOR = '.open-window-switcher-group [data-open-window-switcher-list]';
var OPEN_TAB_OTHER_ITEM_SELECTOR = '[data-open-window-row][data-workspace-navigation-identity]';

// Minimal test doubles may not implement querySelector — treat them as
// "no scrollable list" instead of throwing mid-replacement.
function queryOpenTabList(root, selector) {
    return root && typeof root.querySelector === 'function'
        ? root.querySelector(selector)
        : null;
}

function applyWorkspaceUpdate(message, options) {
    if (!message
        || message.type !== 'workspace-updated'
        || message.version !== 2
        || (message.currentWorkspaceCount !== 0 && message.currentWorkspaceCount !== 1)
        || typeof message.html !== 'string') {
        return false;
    }

    var wrapper = document.querySelector('.sticky-groups-wrapper');
    var currentGroup = wrapper && wrapper.querySelector('.open-current-workspace-group');
    if (!wrapper || !currentGroup || typeof document.createElement !== 'function') {
        return false;
    }
    var currentCards = Array.from(wrapper.querySelectorAll('.workspace-card[data-current-workspace][data-workspace-scope-identity]'));
    if (currentCards.some(card => !currentGroup.contains(card))) {
        return false;
    }
    var holder = document.createElement('div');
    holder.innerHTML = message.html.trim();
    var replacement = holder.firstElementChild;
    if (!replacement
        || holder.children.length !== 1
        || !replacement.matches('.open-current-workspace-group')
        || !isWorkspaceUpdateDomConsistent(message, replacement)) {
        return false;
    }
    if (options && typeof options.validateReplacement === 'function'
        && !options.validateReplacement(replacement)) {
        return false;
    }

    var aiSessionStates = captureCurrentWorkspaceAiSessionStates(currentGroup);
    var currentListScroll = captureOpenTabListScroll(
        queryOpenTabList(currentGroup, '.group-list'),
        OPEN_TAB_CURRENT_ITEM_SELECTOR,
        'data-workspace-scope-identity'
    );
    // The creation form re-renders after the replacement (reconcileDom), so
    // its focus must be captured while the old DOM is still mounted.
    if (window.__agentPivotWorktreeGroupForm
        && typeof window.__agentPivotWorktreeGroupForm.captureFocus === 'function') {
        window.__agentPivotWorktreeGroupForm.captureFocus();
    }
    currentGroup.replaceWith(replacement);
    restoreOpenTabListScroll(
        queryOpenTabList(replacement, '.group-list'),
        currentListScroll,
        OPEN_TAB_CURRENT_ITEM_SELECTOR,
        'data-workspace-scope-identity'
    );
    if (typeof restoreAiSessionTabsFromState === 'function') {
        restoreAiSessionTabsFromState(replacement, window.vscode);
    }
    restoreCurrentWorkspaceAiSessionViewStates(
        replacement,
        aiSessionStates,
        projectId => options
            && typeof options.canRestoreAiSessionProviderMenu === 'function'
            && options.canRestoreAiSessionProviderMenu(projectId)
    );
    restoreCurrentWorkspaceAiSessionAnchorsAndFocus(replacement, aiSessionStates);
    revealChangedFocusedAiSessionCard(replacement, aiSessionStates);
    if (typeof window.__agentPivotSyncCollapseButton === 'function') {
        window.__agentPivotSyncCollapseButton();
    }
    if (typeof window.__agentPivotRevealPendingWorkspaceSession === 'function') {
        window.__agentPivotRevealPendingWorkspaceSession();
    }
    return true;
}

var lastAppliedOpenWorkspacesSemanticRevision = null;
var pendingOpenWorkspacePins = new Map();
var nextOpenWorkspacePinRequestId = 0;

function findOpenWorkspacePinButton(cardId, root) {
    return Array.from((root || document).querySelectorAll(
        '[data-open-window-row][data-id] [data-action="toggle-open-workspace-pin"]'
    )).find(button => button.closest('[data-open-window-row]')?.getAttribute('data-id') === cardId) || null;
}

function announceOpenWorkspacePin(message) {
    var region = document.querySelector('[data-open-workspace-pin-live-region]');
    if (region) {
        region.textContent = message;
    }
}

function setOpenWorkspacePinPending(button, pending) {
    if (!button) return;
    if (pending) {
        button.setAttribute('data-pin-pending', '');
        button.setAttribute('aria-disabled', 'true');
    } else {
        button.removeAttribute('data-pin-pending');
        button.removeAttribute('aria-disabled');
    }
}

function clearOpenWorkspacePinPending(cardId, button) {
    var pending = pendingOpenWorkspacePins.get(cardId);
    if (pending && pending.timeoutHandle !== null
        && typeof window.clearTimeout === 'function') {
        window.clearTimeout(pending.timeoutHandle);
    }
    pendingOpenWorkspacePins.delete(cardId);
    setOpenWorkspacePinPending(button, false);
}

// Window-row focus capture/restore across authoritative replacements: the
// keyboard user may be on any of the row's controls (primary, pin, more,
// retry), so record {cardId, controlKind} and re-focus the same control in
// the rebuilt row (retry is re-unhidden by the navigation reconcile first).
var OPEN_WINDOW_ROW_FOCUS_CONTROLS = [
    { kind: 'focus', selector: '[data-action="focus-open-window"]' },
    { kind: 'pin', selector: '[data-action="toggle-open-workspace-pin"]' },
    { kind: 'more', selector: '[data-action="open-window-menu"]' },
    { kind: 'retry', selector: '[data-action="retry-open-window-navigation"]' },
];

function captureOpenWindowRowFocus() {
    var active = document.activeElement;
    if (!active || typeof active.closest !== 'function') {
        return null;
    }
    var row = active.closest('[data-open-window-row][data-id]');
    if (!row) {
        return null;
    }
    if (typeof active.matches !== 'function') {
        return null;
    }
    for (var i = 0; i < OPEN_WINDOW_ROW_FOCUS_CONTROLS.length; i++) {
        if (active.matches(OPEN_WINDOW_ROW_FOCUS_CONTROLS[i].selector)) {
            return {
                cardId: row.getAttribute('data-id'),
                controlKind: OPEN_WINDOW_ROW_FOCUS_CONTROLS[i].kind,
            };
        }
    }
    return null;
}

function findOpenWindowRowControl(cardId, controlKind, root) {
    var selector = null;
    for (var i = 0; i < OPEN_WINDOW_ROW_FOCUS_CONTROLS.length; i++) {
        if (OPEN_WINDOW_ROW_FOCUS_CONTROLS[i].kind === controlKind) {
            selector = OPEN_WINDOW_ROW_FOCUS_CONTROLS[i].selector;
            break;
        }
    }
    if (!selector) {
        return null;
    }
    var rows = (root || document).querySelectorAll('[data-open-window-row][data-id]');
    for (var j = 0; j < rows.length; j++) {
        if (rows[j].getAttribute('data-id') === cardId) {
            return rows[j].querySelector(selector);
        }
    }
    return null;
}

function reconcilePendingOpenWorkspacePins(root) {
    pendingOpenWorkspacePins.forEach((pending, cardId) => {
        var button = findOpenWorkspacePinButton(cardId, root || document);
        if (button && (button.getAttribute('aria-pressed') === 'true') === pending.pinned) {
            clearOpenWorkspacePinPending(cardId, button);
            announceOpenWorkspacePin(pending.pinned ? 'Window pinned.' : 'Window unpinned.');
            flashOpenWindowRow(cardId);
            return;
        }
        if (!button && pending.acknowledged) {
            clearOpenWorkspacePinPending(cardId, null);
            announceOpenWorkspacePin(pending.pinned ? 'Window pinned.' : 'Window unpinned.');
            flashOpenWindowRow(cardId);
            return;
        }
        setOpenWorkspacePinPending(button, true);
    });
}

// PRD：pin 置顶导致行跳动时，该行保持可见并给一次 ≤150ms 短闪烁确认。
function flashOpenWindowRow(cardId) {
    var button = findOpenWorkspacePinButton(cardId);
    var row = button && button.closest('[data-open-window-row]');
    if (!row) {
        return;
    }
    if (typeof row.scrollIntoView === 'function') {
        row.scrollIntoView({ block: 'nearest' });
    }
    if (row.classList && typeof row.classList.add === 'function') {
        row.classList.add('open-window-row-pin-flash');
        if (typeof window.setTimeout === 'function' && row.classList.remove) {
            window.setTimeout(() => row.classList.remove('open-window-row-pin-flash'), 150);
        }
    }
}

function requestOpenWorkspacePin(button, cardId) {
    if (!button || pendingOpenWorkspacePins.has(cardId)) {
        return;
    }
    nextOpenWorkspacePinRequestId = nextOpenWorkspacePinRequestId >= Number.MAX_SAFE_INTEGER
        ? 1
        : nextOpenWorkspacePinRequestId + 1;
    var pinned = button.getAttribute('aria-pressed') !== 'true';
    var card = button.closest('[data-open-window-row]') || button.closest('.workspace-card');
    var name = card?.querySelector('.open-window-name, .project-header')?.textContent?.trim() || 'window';
    var pending = {
        requestId: nextOpenWorkspacePinRequestId,
        pinned: pinned,
        acknowledged: false,
        timeoutHandle: null,
    };
    if (typeof window.setTimeout === 'function') {
        pending.timeoutHandle = window.setTimeout(() => {
            if (pendingOpenWorkspacePins.get(cardId) !== pending) {
                return;
            }
            clearOpenWorkspacePinPending(cardId, findOpenWorkspacePinButton(cardId));
            announceOpenWorkspacePin('Pinned window update timed out. Try again.');
            requestFullRefresh('open-workspace-pin-timeout');
        }, 15_000);
    }
    pendingOpenWorkspacePins.set(cardId, pending);
    setOpenWorkspacePinPending(button, true);
    announceOpenWorkspacePin(`${pinned ? 'Pinning' : 'Unpinning'} ${name}…`);
    window.vscode.postMessage({
        type: 'set-open-workspace-pin',
        version: 1,
        requestId: pending.requestId,
        cardId: cardId,
        pinned: pinned,
    });
}

function completeOpenWorkspacePin(message) {
    if (!message
        || Object.keys(message).sort().join('\n') !== [
            'cardId', 'pinned', 'requestId', 'success', 'type', 'version',
        ].sort().join('\n')
        || message.type !== 'open-workspace-pin-result'
        || message.version !== 1
        || !Number.isSafeInteger(message.requestId)
        || message.requestId < 1
        || typeof message.cardId !== 'string'
        || typeof message.pinned !== 'boolean'
        || typeof message.success !== 'boolean') {
        return false;
    }
    var pending = pendingOpenWorkspacePins.get(message.cardId);
    if (!pending
        || pending.requestId !== message.requestId
        || pending.pinned !== message.pinned) {
        return true;
    }
    if (!message.success) {
        clearOpenWorkspacePinPending(
            message.cardId,
            findOpenWorkspacePinButton(message.cardId),
        );
        announceOpenWorkspacePin('Could not update the pinned window.');
        return true;
    }
    pending.acknowledged = true;
    reconcilePendingOpenWorkspacePins(document);
    return true;
}

function applyOpenWorkspacesUpdate(message, options) {
    if (!message
        || message.type !== 'open-workspaces-updated'
        || message.version !== 4
        || typeof message.semanticRevision !== 'string'
        || !message.semanticRevision
        || !Number.isSafeInteger(message.windowRowCount)
        || message.windowRowCount < 0
        || (message.currentWindowRowCount !== 0 && message.currentWindowRowCount !== 1)
        || !Number.isSafeInteger(message.navigationWindowRowCount)
        || message.navigationWindowRowCount < 0
        || (message.currentDetailCount !== 0 && message.currentDetailCount !== 1)
        || (message.otherWindowsStatus !== 'ready'
            && message.otherWindowsStatus !== 'connecting'
            && message.otherWindowsStatus !== 'unavailable'
            && message.otherWindowsStatus !== 'update-required')
        || typeof message.html !== 'string'
        || typeof normalizeDashboardSearchCatalog !== 'function'
        || normalizeDashboardSearchCatalog(message.searchCatalog) !== message.searchCatalog
        || message.searchCatalog.version !== 3) {
        return false;
    }
    if (message.semanticRevision === lastAppliedOpenWorkspacesSemanticRevision) {
        reconcilePendingOpenWorkspacePins(document);
        return true;
    }
    var wrapper = document.querySelector('.sticky-groups-wrapper');
    if (!wrapper) return false;
    var holder = null;
    if (typeof document.createElement === 'function') {
        holder = document.createElement('div');
        holder.innerHTML = message.html;
        if (!isOpenWorkspacesUpdateDomConsistent(message, holder)
            || (options && typeof options.validateReplacement === 'function'
                && !options.validateReplacement(holder))) {
            return false;
        }
    } else if (options && typeof options.validateReplacement === 'function') {
        return false;
    }
    var previousHtml = wrapper.innerHTML;
    var focusedRowControl = captureOpenWindowRowFocus();
    var aiSessionStates = captureCurrentWorkspaceAiSessionStates(wrapper);
    // This path replaces the whole wrapper, so beyond the other-windows list
    // it must also carry the current-workspace list scroll (path A keeps it
    // across workspace-updated) and the window position.
    var currentListScroll = captureOpenTabListScroll(
        queryOpenTabList(wrapper, OPEN_TAB_CURRENT_LIST_SELECTOR),
        OPEN_TAB_CURRENT_ITEM_SELECTOR,
        'data-workspace-scope-identity'
    );
    var otherListScroll = captureOpenTabListScroll(
        queryOpenTabList(wrapper, OPEN_TAB_OTHER_LIST_SELECTOR),
        OPEN_TAB_OTHER_ITEM_SELECTOR,
        'data-workspace-navigation-identity'
    );
    var windowScrollY = typeof window.scrollY === 'number' ? window.scrollY : 0;
    // Capture the open creation form's focus before destroying its slot.
    if (window.__agentPivotWorktreeGroupForm
        && typeof window.__agentPivotWorktreeGroupForm.captureFocus === 'function') {
        window.__agentPivotWorktreeGroupForm.captureFocus();
    }
    wrapper.innerHTML = holder ? holder.innerHTML : message.html;
    if (!isOpenWorkspacesUpdateDomConsistent(message)) {
        wrapper.innerHTML = previousHtml;
        restoreOpenTabListScroll(
            queryOpenTabList(wrapper, OPEN_TAB_CURRENT_LIST_SELECTOR),
            currentListScroll,
            OPEN_TAB_CURRENT_ITEM_SELECTOR,
            'data-workspace-scope-identity'
        );
        restoreOpenTabListScroll(
            queryOpenTabList(wrapper, OPEN_TAB_OTHER_LIST_SELECTOR),
            otherListScroll,
            OPEN_TAB_OTHER_ITEM_SELECTOR,
            'data-workspace-navigation-identity'
        );
        if (typeof window.scrollTo === 'function') {
            window.scrollTo(0, windowScrollY);
        }
        if (typeof restoreAiSessionTabsFromState === 'function') {
            restoreAiSessionTabsFromState(document, window.vscode);
        }
        restoreCurrentWorkspaceAiSessionViewStates(wrapper, aiSessionStates);
        restoreCurrentWorkspaceAiSessionAnchorsAndFocus(wrapper, aiSessionStates);
        return false;
    }
    restoreOpenTabListScroll(
        queryOpenTabList(wrapper, OPEN_TAB_CURRENT_LIST_SELECTOR),
        currentListScroll,
        OPEN_TAB_CURRENT_ITEM_SELECTOR,
        'data-workspace-scope-identity'
    );
    restoreOpenTabListScroll(
        queryOpenTabList(wrapper, OPEN_TAB_OTHER_LIST_SELECTOR),
        otherListScroll,
        OPEN_TAB_OTHER_ITEM_SELECTOR,
        'data-workspace-navigation-identity'
    );
    if (typeof window.scrollTo === 'function') {
        window.scrollTo(0, windowScrollY);
    }
    if (window.__agentPivotDashboard) {
        window.__agentPivotDashboard.replaceSearchCatalog(message.searchCatalog);
    }
    if (typeof restoreAiSessionTabsFromState === 'function') {
        restoreAiSessionTabsFromState(document, window.vscode);
    }
    restoreCurrentWorkspaceAiSessionViewStates(wrapper, aiSessionStates);
    restoreCurrentWorkspaceAiSessionAnchorsAndFocus(wrapper, aiSessionStates);
    revealChangedFocusedAiSessionCard(wrapper, aiSessionStates);
    reconcilePendingOpenWorkspacePins(wrapper);
    // Replay the navigation pending/error row state before restoring focus so
    // an error row's Retry control is visible (focusable) again. The caller
    // reconciles once more afterwards; both passes are idempotent.
    if (window.__agentPivotOpenWindowNavigation
        && typeof window.__agentPivotOpenWindowNavigation.reconcile === 'function') {
        window.__agentPivotOpenWindowNavigation.reconcile(wrapper);
    }
    var restoredRowControl = focusedRowControl
        ? findOpenWindowRowControl(focusedRowControl.cardId, focusedRowControl.controlKind, wrapper)
        : null;
    if (restoredRowControl && typeof restoredRowControl.focus === 'function') {
        restoredRowControl.focus({ preventScroll: true });
    }
    if (typeof window.__agentPivotSyncCollapseButton === 'function') {
        window.__agentPivotSyncCollapseButton();
    }
    lastAppliedOpenWorkspacesSemanticRevision = message.semanticRevision;
    return true;
}

function getOpenWorkspacesUpdateDomState(root) {
    var projectionRoot = root || document;
    var wrapperPrefix = root ? '' : '.sticky-groups-wrapper ';
    var switcherGroup = projectionRoot.querySelector(
        wrapperPrefix + '.open-window-switcher-group[data-other-windows-status]'
    );
    var windowRows = Array.from(projectionRoot.querySelectorAll(
        wrapperPrefix + '[data-open-window-row][data-workspace-navigation-identity]'
    ));
    var navigationRows = windowRows.filter(row =>
        row.getAttribute('data-window-kind') === 'navigation'
    );
    var navigationIdentities = navigationRows.map(row =>
        row.getAttribute('data-workspace-navigation-identity')
    );
    return {
        windowRowCount: windowRows.length,
        currentWindowRowCount: windowRows.filter(row =>
            row.getAttribute('data-window-kind') === 'current'
        ).length,
        navigationWindowRowCount: navigationRows.length,
        currentDetailCount: projectionRoot.querySelectorAll(
            wrapperPrefix
                + '.workspace-card[data-current-workspace][data-workspace-scope-identity]'
        ).length,
        hasUniqueNavigationIdentities: navigationIdentities.every(identity => !!identity)
            && new Set(navigationIdentities).size === navigationIdentities.length,
        hasWindowSwitcher: !!switcherGroup,
        otherWindowsStatus: switcherGroup
            ? switcherGroup.getAttribute('data-other-windows-status')
            : 'ready',
    };
}

function isOpenWorkspacesUpdateDomConsistent(message, root) {
    var rendered = getOpenWorkspacesUpdateDomState(root);
    return rendered.currentWindowRowCount === message.currentWindowRowCount
        && rendered.navigationWindowRowCount === message.navigationWindowRowCount
        && rendered.windowRowCount === message.windowRowCount
        && rendered.currentDetailCount === message.currentDetailCount
        && rendered.hasUniqueNavigationIdentities
        && rendered.otherWindowsStatus === message.otherWindowsStatus
        && rendered.hasWindowSwitcher
        && message.windowRowCount
            === message.currentWindowRowCount + message.navigationWindowRowCount
        && message.searchCatalog.openWorkspaces.length
            === message.currentWindowRowCount + message.navigationWindowRowCount;
}

/* src/webview/webviewTodoGroupScripts.js */
function getCollapseButtonState(tab, collapsedStates) {
    tab = tab === 'projects' || tab === 'todo' || tab === 'ai' ? tab : 'open';
    if (tab === 'ai') {
        return {
            disabled: true,
            collapsed: false,
            title: 'No groups to collapse in AI',
        };
    }
    var labels = tab === 'todo'
        ? {
            empty: 'No TODO groups to collapse',
            collapse: 'Collapse TODO Groups',
            expand: 'Expand TODO Groups',
        }
        : tab === 'open'
            ? {
                empty: 'No open windows to collapse',
                collapse: 'Collapse Open Windows',
                expand: 'Expand Open Windows',
            }
            : {
                empty: 'No project groups to collapse',
                collapse: 'Collapse All Groups',
                expand: 'Expand All Groups',
            };
    if (!collapsedStates.length) {
        return {
            disabled: true,
            collapsed: false,
            title: labels.empty,
        };
    }

    var collapsed = collapsedStates.every(Boolean);
    return {
        disabled: false,
        collapsed,
        title: collapsed ? labels.expand : labels.collapse,
    };
}

function syncTodoGroupCollapseControl(group) {
    if (!group || typeof group.querySelector !== 'function') {
        return;
    }
    var control = group.querySelector('[data-action="todo-collapse-group"]');
    if (!control) {
        return;
    }
    var collapsed = group.classList.contains('collapsed');
    var action = collapsed ? 'Expand' : 'Collapse';
    var heading = group.querySelector('h2');
    var groupTitle = heading ? String(heading.textContent || '').trim() : '';
    control.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
    control.setAttribute('title', action + ' todo group');
    control.setAttribute('aria-label', action + (groupTitle ? ' ' + groupTitle : ' todo group'));
}

function syncTodoExpandControl(item, expanded) {
    if (!item || typeof item.querySelector !== 'function') {
        return;
    }
    var control = item.querySelector('[data-action="todo-toggle-expanded"]');
    if (!control) {
        return;
    }
    var action = expanded ? 'Collapse' : 'Expand';
    var titleElement = item.querySelector('.todo-title-text');
    var todoTitle = titleElement ? String(titleElement.textContent || '').trim() : '';
    control.setAttribute('aria-expanded', expanded ? 'true' : 'false');
    control.setAttribute('title', action + ' todo');
    control.setAttribute('aria-label', action + (todoTitle ? ' ' + todoTitle : ' todo'));
}

function collapseTodoGroups(groups, collapsed, postMessage) {
    groups.forEach(group => {
        group.classList.toggle('collapsed', collapsed);
        syncTodoGroupCollapseControl(group);
    });
    postMessage({
        type: 'todo-collapse-groups',
        collapsed,
    });
}

var nextTodoMutationRequestId = 0;

function getTodoFormValue(form, name) {
    var checkedElement = form.querySelector('[name="' + name + '"]:checked');
    if (checkedElement) {
        return String(checkedElement.value || '').trim();
    }
    var element = form.querySelector('[name="' + name + '"]');
    return element ? String(element.value || '').trim() : '';
}

function setTodoComposePending(form, pending) {
    form.setAttribute('data-todo-pending', pending ? 'true' : 'false');
    var submitButton = form.querySelector('[type="submit"]');
    if (!submitButton)
        return;

    submitButton.disabled = pending;
    if (pending) {
        submitButton.setAttribute('aria-busy', 'true');
    } else {
        submitButton.removeAttribute('aria-busy');
    }
}

function submitTodoComposeForm(form, postMessage) {
    if (form.getAttribute('data-todo-pending') === 'true')
        return false;

    var title = getTodoFormValue(form, 'title');
    if (!title)
        return false;

    nextTodoMutationRequestId += 1;
    var requestId = nextTodoMutationRequestId;
    form.setAttribute('data-todo-request-id', String(requestId));
    setTodoComposePending(form, true);
    postMessage({
        type: 'todo-add',
        requestId,
        title,
        notes: getTodoFormValue(form, 'notes'),
        priority: getTodoFormValue(form, 'priority'),
        groupId: getTodoFormValue(form, 'groupId'),
    });
    return true;
}

function applyTodoMutationResult(message, root) {
    if (!message
        || message.type !== 'todo-mutation-result'
        || message.version !== 1
        || !Number.isSafeInteger(message.requestId)
        || message.requestId < 1
        || typeof message.success !== 'boolean') {
        return false;
    }

    var form = root.querySelector('.todo-add-form[data-todo-request-id="' + message.requestId + '"]');
    if (!form)
        return false;
    if (!message.success) {
        setTodoComposePending(form, false);
        form.removeAttribute('data-todo-request-id');
    } else if (message.panelRefreshed === false) {
        form.reset();
        setTodoComposePending(form, false);
        form.removeAttribute('data-todo-request-id');
    }
    return true;
}

/* src/webview/webviewProjectCollapseScripts.js */
function initProjectGroupCollapse() {
    'use strict';

    function updateToggleAllGroupsButton(state) {
        document.body.classList.toggle("steward-all-collapsed", state.collapsed);
        var button = document.querySelector('[data-action="toggle-all-groups"]');
        if (!button)
            return;

        button.disabled = state.disabled;
        button.setAttribute('aria-disabled', state.disabled ? 'true' : 'false');
        button.setAttribute("title", state.title);
        button.setAttribute("aria-label", state.title);
    }

    function getActiveDashboardTab() {
        var dashboard = window.__agentPivotDashboard;
        var selectedTab = !dashboard && document.querySelector
            ? document.querySelector('[data-dashboard-tab][aria-selected="true"]')
            : null;
        var activeTab = dashboard && typeof dashboard.getActiveTab === 'function'
            ? dashboard.getActiveTab()
            : selectedTab && selectedTab.getAttribute('data-dashboard-tab');
        return activeTab === 'projects' || activeTab === 'todo' || activeTab === 'ai'
            ? activeTab
            : 'open';
    }

    function getActiveCollapsibleGroups() {
        var activeTab = getActiveDashboardTab();
        var selector = activeTab === 'projects'
            ? '#dashboard-tab-projects .group[data-group-id]'
            : activeTab === 'todo'
                ? '#dashboard-tab-todo .todo-group[data-todo-group-id]'
                : null;
        if (!selector) {
            return [];
        }
        return [...document.querySelectorAll(selector)];
    }

    function setGroupCollapsed(group, collapsed, persist) {
        group.classList.toggle('collapsed', collapsed);
        if (persist) {
            var isTodoGroup = group.classList.contains('todo-group');
            window.vscode.postMessage({
                type: isTodoGroup ? 'todo-collapse-group' : 'collapse-group',
                groupId: isTodoGroup
                    ? group.getAttribute('data-todo-group-id')
                    : group.getAttribute('data-group-id'),
                collapsed,
            });
        }
    }

    function syncCollapseButton() {
        var activeTab = getActiveDashboardTab();
        var groups = getActiveCollapsibleGroups();
        updateToggleAllGroupsButton(getCollapseButtonState(
            activeTab,
            groups.map(group => group.classList.contains('collapsed'))
        ));
    }

    function toggleAllGroups() {
        var activeTab = getActiveDashboardTab();
        var groups = getActiveCollapsibleGroups();
        var shouldCollapse = groups.some(group => !group.classList.contains("collapsed"));

        if (activeTab === 'todo') {
            if (window.__agentPivotTodo
                && typeof window.__agentPivotTodo.dispatch === 'function') {
                window.__agentPivotTodo.dispatch('collapse-groups', { collapsed: shouldCollapse });
            } else {
                collapseTodoGroups(groups, shouldCollapse, message => window.vscode.postMessage(message));
            }
            syncCollapseButton();
            return;
        }

        groups.forEach(group => setGroupCollapsed(group, shouldCollapse, true));
        syncCollapseButton();
    }


    window.__agentPivotSyncCollapseButton = syncCollapseButton;

    return {
        setGroupCollapsed: setGroupCollapsed,
        syncCollapseButton: syncCollapseButton,
        toggleAllGroups: toggleAllGroups,
    };
}

/* src/webview/webviewOpenWindowNavigationScripts.js */
'use strict';

// OPEN tab window-switcher navigation pending manager (PR-A; row clicks are
// wired to this in PR-B). Implements the webview half of the versioned
// open-window navigation request/settlement protocol:
// - every request carries a fresh requestId and goes pending;
// - settlements are matched by cardId + requestId, stale/duplicate receipts
//   are ignored;
// - consecutive requests on the same row supersede earlier pending ones;
// - requests time out into the error state;
// - pending/error row state is replayed after authoritative DOM replacements.
var agentPivotOpenWindowNavigation = (function () {
    var MESSAGE_TYPE_REQUEST = 'open-window-navigation-request';
    var MESSAGE_TYPE_RESULT = 'open-window-navigation-result';
    var PROTOCOL_VERSION = 1;
    var PENDING_TIMEOUT_MS = 5000;
    var VALID_OUTCOMES = ['focused', 'stale-target', 'untitled-workspace', 'failed', 'malformed-request'];

    var nextRequestId = 0;
    // cardId -> { requestId, timeoutHandle }
    var pendingByCardId = new Map();
    // cardId -> { outcome, requestId } (drives the row error state until the
    // next request; the requestId lets a late 'focused' receipt clear the
    // error its own timeout created, as long as no newer request superseded it)
    var errorByCardId = new Map();

    // PRD live region：导航 pending/error 通过切换器内的播报区触达屏幕阅读器。
    function announce(cardId, message) {
        var region = document.querySelector('[data-open-window-nav-live-region]');
        if (!region) {
            return;
        }
        var row = findRow(cardId);
        var name = row && row.querySelector('.open-window-name');
        var label = name && name.textContent ? name.textContent.trim() : '';
        region.textContent = label ? message + ' ' + label : message;
    }

    function findRow(cardId, root) {
        return Array.from((root || document).querySelectorAll(
            '[data-open-window-row][data-id]'
        )).find(function (row) {
            return row.getAttribute('data-id') === cardId;
        }) || null;
    }

    function applyRowState(cardId, state, outcome, root) {
        var row = findRow(cardId, root);
        if (!row) {
            return;
        }
        if (state === 'idle') {
            row.removeAttribute('data-navigation-state');
            row.removeAttribute('data-navigation-outcome');
        } else {
            row.setAttribute('data-navigation-state', state);
            if (state === 'error' && outcome) {
                row.setAttribute('data-navigation-outcome', outcome);
            } else {
                row.removeAttribute('data-navigation-outcome');
            }
        }
        var retry = row.querySelector('[data-action="retry-open-window-navigation"]');
        if (retry) {
            retry.hidden = state !== 'error';
        }
    }

    function clearPending(cardId, pending) {
        if (pending && pending.timeoutHandle !== null
            && typeof window.clearTimeout === 'function') {
            window.clearTimeout(pending.timeoutHandle);
        }
        if (pendingByCardId.get(cardId) === pending) {
            pendingByCardId.delete(cardId);
        }
    }

    function failPending(cardId, pending, outcome) {
        clearPending(cardId, pending);
        errorByCardId.set(cardId, { outcome: outcome, requestId: pending.requestId });
        applyRowState(cardId, 'error', outcome);
    }

    function request(cardId) {
        if (typeof cardId !== 'string' || !cardId) {
            return;
        }
        var existing = pendingByCardId.get(cardId);
        if (existing) {
            // Consecutive clicks supersede: the old request's settlement is
            // ignored when it arrives (requestId no longer matches).
            clearPending(cardId, existing);
        }
        nextRequestId = nextRequestId >= Number.MAX_SAFE_INTEGER ? 1 : nextRequestId + 1;
        var pending = {
            requestId: nextRequestId,
            timeoutHandle: null,
        };
        if (typeof window.setTimeout === 'function') {
            pending.timeoutHandle = window.setTimeout(function () {
                if (pendingByCardId.get(cardId) !== pending) {
                    return;
                }
                failPending(cardId, pending, 'failed');
                announce(cardId, 'Window switch timed out. Retry available on');
            }, PENDING_TIMEOUT_MS);
        }
        pendingByCardId.set(cardId, pending);
        errorByCardId.delete(cardId);
        applyRowState(cardId, 'pending');
        announce(cardId, 'Switching to window');
        if (window.vscode && typeof window.vscode.postMessage === 'function') {
            window.vscode.postMessage({
                type: MESSAGE_TYPE_REQUEST,
                version: PROTOCOL_VERSION,
                requestId: pending.requestId,
                cardId: cardId,
            });
        }
    }

    function retry(cardId) {
        request(cardId);
    }

    function isValidResult(message) {
        return !!message
            && Object.keys(message).sort().join('\n') === [
                'cardId', 'outcome', 'requestId', 'type', 'version',
            ].sort().join('\n')
            && message.type === MESSAGE_TYPE_RESULT
            && message.version === PROTOCOL_VERSION
            && Number.isSafeInteger(message.requestId)
            && message.requestId >= 1
            && typeof message.cardId === 'string'
            && VALID_OUTCOMES.indexOf(message.outcome) !== -1;
    }

    function complete(message) {
        if (!isValidResult(message)) {
            return false;
        }
        var pending = pendingByCardId.get(message.cardId);
        if (!pending || pending.requestId !== message.requestId) {
            // Stale (superseded) or duplicate settlement: ignore — with one
            // exception. The host never cancels a timed-out request, so a
            // late 'focused' receipt still describes a real switch: let it
            // clear the error its own timeout created. A newer request would
            // have deleted the error entry, so a requestId match proves the
            // row has not been superseded.
            var errored = errorByCardId.get(message.cardId);
            if (errored
                && errored.requestId === message.requestId
                && message.outcome === 'focused') {
                errorByCardId.delete(message.cardId);
                applyRowState(message.cardId, 'idle');
            }
            return true;
        }
        clearPending(message.cardId, pending);
        if (message.outcome === 'focused') {
            errorByCardId.delete(message.cardId);
            applyRowState(message.cardId, 'idle');
        } else {
            errorByCardId.set(message.cardId, {
                outcome: message.outcome,
                requestId: message.requestId,
            });
            applyRowState(message.cardId, 'error', message.outcome);
            announce(message.cardId, 'Could not switch to window');
        }
        return true;
    }

    // Re-applies pending/error row state after an authoritative DOM
    // replacement rebuilt the rows.
    function reconcile(root) {
        // 替换后菜单的 __row/origin 指向已分离节点，先关掉。
        closeMenu();
        pendingByCardId.forEach(function (_pending, cardId) {
            applyRowState(cardId, 'pending', undefined, root);
        });
        errorByCardId.forEach(function (entry, cardId) {
            applyRowState(cardId, 'error', entry.outcome, root);
        });
    }

    // --- window-row ⋯ menu ---------------------------------------------------
    // One shared menu element (#openWindowMenu), positioned next to the row's
    // ⋯ button. Items: Focus Window (non-current rows), Pin/Unpin, Save
    // Workspace (current row). Keyboard: ↑/↓ 导航，Enter 执行，Esc 关闭并焦点返回。
    var menuOriginButton = null;

    function closeMenu(restoreFocus) {
        var menu = document.getElementById('openWindowMenu');
        if (!menu) {
            return;
        }
        menu.classList.remove('visible');
        if (menuOriginButton) {
            menuOriginButton.setAttribute('aria-expanded', 'false');
            // Only keyboard dismissal (Escape) returns focus to the trigger;
            // blur, outside clicks, and item activation each own their focus.
            if (restoreFocus === true && typeof menuOriginButton.focus === 'function') {
                menuOriginButton.focus({ preventScroll: true });
            }
            menuOriginButton = null;
        }
    }

    function openMenu(button) {
        var menu = document.getElementById('openWindowMenu');
        if (!menu) {
            return;
        }
        var row = button.closest('[data-open-window-row]');
        if (!row) {
            return;
        }
        var isCurrent = row.getAttribute('data-window-kind') === 'current';
        var rowDisabled = row.getAttribute('data-navigation-disabled') === 'true';
        var pinned = row.classList.contains('open-window-row-pinned');
        menu.querySelectorAll('[data-open-window-menu-non-current]').forEach(function (item) {
            item.hidden = isCurrent || rowDisabled;
        });
        menu.querySelectorAll('[data-open-window-menu-current]').forEach(function (item) {
            item.hidden = !isCurrent;
        });
        var canPin = row.getAttribute('data-can-pin') !== 'false';
        var pinItem = menu.querySelector('[data-open-window-menu-pin]');
        if (pinItem) {
            pinItem.hidden = !canPin;
            if (canPin) {
                pinItem.textContent = pinned ? 'Unpin Window' : 'Pin Window';
            }
        }
        menu.__row = row;
        if (menuOriginButton && menuOriginButton !== button) {
            menuOriginButton.setAttribute('aria-expanded', 'false');
        }
        menuOriginButton = button;
        button.setAttribute('aria-expanded', 'true');
        menu.style.visibility = 'hidden';
        menu.style.left = '0px';
        menu.style.top = '0px';
        menu.classList.add('visible');
        var buttonRect = button.getBoundingClientRect();
        var menuRect = menu.getBoundingClientRect();
        var viewportPadding = 4;
        var left = Math.max(viewportPadding, Math.min(
            buttonRect.right - menuRect.width,
            window.innerWidth - menuRect.width - viewportPadding
        ));
        var top = buttonRect.bottom + 2;
        if (top + menuRect.height > window.innerHeight - viewportPadding) {
            top = Math.max(viewportPadding, buttonRect.top - menuRect.height - 2);
        }
        menu.style.left = left + 'px';
        menu.style.top = top + 'px';
        menu.style.visibility = 'visible';
        var firstItem = menu.querySelector('[role="menuitem"]:not([hidden])');
        if (firstItem && typeof firstItem.focus === 'function') {
            firstItem.focus();
        }
    }

    function toggleMenu(button) {
        var menu = document.getElementById('openWindowMenu');
        var isOpen = menu && menu.classList.contains('visible')
            && menuOriginButton === button;
        if (isOpen) {
            closeMenu();
        } else {
            openMenu(button);
        }
    }

    function activateMenuItem(item) {
        var menu = document.getElementById('openWindowMenu');
        var row = menu && menu.__row;
        if (!row) {
            closeMenu();
            return;
        }
        var cardId = row.getAttribute('data-id');
        var action = item.getAttribute('data-action');
        closeMenu();
        if (action === 'focus-open-window') {
            request(cardId);
        } else if (action === 'toggle-open-workspace-pin'
            && typeof requestOpenWorkspacePin === 'function') {
            var pinButton = row.querySelector('[data-action="toggle-open-workspace-pin"]');
            if (pinButton) {
                requestOpenWorkspacePin(pinButton, cardId);
            }
        } else if (action === 'save-current-workspace'
            && window.vscode && typeof window.vscode.postMessage === 'function') {
            window.vscode.postMessage({ type: 'save-current-workspace', projectId: cardId });
        }
    }

    function onMenuClick(e) {
        var item = e.target.closest('[role="menuitem"][data-action]');
        if (!item) {
            return;
        }
        e.preventDefault();
        e.stopPropagation();
        activateMenuItem(item);
    }

    function onMenuKeydown(e) {
        var menu = document.getElementById('openWindowMenu');
        if (!menu || !menu.classList.contains('visible')) {
            return;
        }
        var items = Array.from(menu.querySelectorAll('[role="menuitem"]:not([hidden])'));
        var index = items.indexOf(document.activeElement);
        if (e.key === 'Escape') {
            e.preventDefault();
            closeMenu(true);
        } else if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
            e.preventDefault();
            var next = e.key === 'ArrowDown'
                ? (index + 1) % items.length
                : (index - 1 + items.length) % items.length;
            if (items[next]) {
                items[next].focus();
            }
        } else if ((e.key === 'Enter' || e.key === ' ') && index >= 0) {
            e.preventDefault();
            activateMenuItem(items[index]);
        }
    }

    // 行间 ↑/↓ 增强导航（PRD 键盘章节）：在切换器列表内移动焦点。
    document.addEventListener('keydown', function (e) {
        if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') {
            return;
        }
        var row = e.target && e.target.closest
            ? e.target.closest('[data-open-window-row]')
            : null;
        if (!row) {
            return;
        }
        var list = row.closest('[data-open-window-switcher-list]');
        if (!list) {
            return;
        }
        var rows = Array.from(list.querySelectorAll('[data-open-window-row]'));
        var index = rows.indexOf(row);
        if (index === -1) {
            return;
        }
        e.preventDefault();
        var next = e.key === 'ArrowDown'
            ? Math.min(index + 1, rows.length - 1)
            : Math.max(index - 1, 0);
        var focusTarget = rows[next]
            && rows[next].querySelector('[data-action="focus-open-window"]');
        if (focusTarget && typeof focusTarget.focus === 'function') {
            focusTarget.focus();
        }
    });

    if (typeof window !== 'undefined' && window.addEventListener) {
        window.addEventListener('blur', function () { closeMenu(); });
    }

    if (typeof document !== 'undefined' && document.addEventListener) {
        document.addEventListener('click', function (e) {
            var menu = document.getElementById('openWindowMenu');
            if (!menu || !menu.classList.contains('visible')) {
                return;
            }
            if (menu.contains(e.target)) {
                onMenuClick(e);
                return;
            }
            var trigger = e.target.closest
                && e.target.closest('[data-action="open-window-menu"]');
            if (!trigger) {
                closeMenu();
            }
        });
        document.addEventListener('keydown', onMenuKeydown);
    }

    return {
        request: request,
        retry: retry,
        complete: complete,
        reconcile: reconcile,
        toggleMenu: toggleMenu,
        closeMenu: closeMenu,
        isPending: function (cardId) { return pendingByCardId.has(cardId); },
        _pendingByCardId: pendingByCardId,
        _errorByCardId: errorByCardId,
        PENDING_TIMEOUT_MS: PENDING_TIMEOUT_MS,
    };
})();

window.__agentPivotOpenWindowNavigation = agentPivotOpenWindowNavigation;

/* src/webview/webviewTodoControlScripts.js */
function initProjectTodoControls(options) {
    'use strict';

    options = options || {};
    var syncCollapseButton = typeof options.syncCollapseButton === 'function'
        ? options.syncCollapseButton
        : function () {};

    function isDedicatedTodoTarget(target) {
        return Boolean(window.__agentPivotTodo
            && target
            && target.closest
            && target.closest('#dashboard-tab-todo'));
    }

    function onInsideGroupClick(e, groupDiv) {
        var groupId = groupDiv.getAttribute("data-group-id");
        if (groupId == null)
            return;

        var actionDiv = e.target.closest('[data-action]')
        var action = actionDiv != null ? actionDiv.getAttribute("data-action") : null;
        if (!action)
            return;

        if (action === "add") {
            window.vscode.postMessage({
                type: 'add-project',
                groupId: groupId,
            });

            return;
        }

        var collapsed = groupDiv.classList.contains("collapsed");
        if (action === "collapse") {
            groupDiv.classList.toggle("collapsed");
            collapsed = groupDiv.classList.contains("collapsed");
        }

        window.vscode.postMessage({
            type: action + '-group',
            groupId: groupId,
            collapsed,
        });
        syncCollapseButton();
    }

    function onTodoAction(e) {
        var addTodoAction = e.target.closest('[data-action="todo-add"]');
        if (addTodoAction && !addTodoAction.closest('.todo-add-form')) {
            setTodoAddFormVisible(true, addTodoAction.getAttribute('data-group-id'));
            return true;
        }

        var addGroupAction = e.target.closest('[data-action="todo-add-group"]');
        if (addGroupAction) {
            window.vscode.postMessage({
                type: 'todo-add-group',
            });
            return true;
        }

        var toggleAction = e.target.closest('[data-action="todo-toggle"]');
        if (toggleAction) {
            window.vscode.postMessage({
                type: 'todo-toggle',
                todoId: toggleAction.getAttribute('data-todo-id'),
                completed: toggleAction.checked === true,
            });
            return true;
        }

        var deleteAction = e.target.closest('[data-action="todo-delete"]');
        if (deleteAction) {
            window.vscode.postMessage({
                type: 'todo-delete',
                todoId: deleteAction.getAttribute('data-todo-id'),
            });
            return true;
        }

        var deleteGroupAction = e.target.closest('[data-action="todo-delete-group"]');
        if (deleteGroupAction) {
            window.vscode.postMessage({
                type: 'todo-delete-group',
                groupId: deleteGroupAction.getAttribute('data-group-id'),
            });
            return true;
        }

        var renameGroupAction = e.target.closest('[data-action="todo-rename-group"]');
        if (renameGroupAction) {
            window.vscode.postMessage({
                type: 'todo-rename-group',
                groupId: renameGroupAction.getAttribute('data-group-id'),
            });
            return true;
        }

        var collapseGroupAction = e.target.closest('[data-action="todo-collapse-group"]');
        if (collapseGroupAction) {
            var todoGroup = collapseGroupAction.closest('.todo-group');
            if (!todoGroup)
                return true;
            todoGroup.classList.toggle('collapsed');
            syncTodoGroupCollapseControl(todoGroup);
            window.vscode.postMessage({
                type: 'todo-collapse-group',
                groupId: todoGroup.getAttribute('data-todo-group-id'),
                collapsed: todoGroup.classList.contains('collapsed'),
            });
            syncCollapseButton();
            return true;
        }

        var sortAction = e.target.closest('[data-action="todo-sort-priority"]');
        if (sortAction) {
            window.vscode.postMessage({
                type: 'todo-sort-priority',
                groupId: sortAction.getAttribute('data-group-id'),
            });
            return true;
        }

        var showCompletedAction = e.target.closest('[data-action="todo-toggle-show-completed"]');
        if (showCompletedAction) {
            window.vscode.postMessage({
                type: 'todo-toggle-show-completed',
                showCompleted: showCompletedAction.checked === true,
            });
            return true;
        }

        var focusAddAction = e.target.closest('[data-action="todo-focus-add"]');
        if (focusAddAction) {
            setTodoAddFormVisible(true, focusAddAction.getAttribute('data-group-id'));
            return true;
        }

        var cancelAddAction = e.target.closest('[data-action="todo-cancel-add"]');
        if (cancelAddAction) {
            setTodoAddFormVisible(false);
            return true;
        }

        var editAction = e.target.closest('[data-action="todo-edit"]');
        if (editAction) {
            setTodoEditing(editAction.getAttribute('data-todo-id'), true);
            return true;
        }

        var expandAction = e.target.closest('[data-action="todo-toggle-expanded"]');
        if (expandAction) {
            toggleTodoItemExpanded(expandAction.closest('.todo-item'));
            return true;
        }

        var cancelEditAction = e.target.closest('[data-action="todo-cancel-edit"]');
        if (cancelEditAction) {
            setTodoEditing(cancelEditAction.getAttribute('data-todo-id'), false);
            return true;
        }

        return false;
    }

    function syncTodoPrioritySegment(segment) {
        if (!segment)
            return;

        Array.from(segment.querySelectorAll('.todo-priority-choice')).forEach(choice => {
            var input = choice.querySelector('input[name="priority"]');
            choice.classList.toggle('active', !!input && input.checked === true);
        });
    }

    function resetTodoEditForm(form) {
        form.reset();
        syncTodoPrioritySegment(form.querySelector('.todo-priority-segment'));
    }

    function syncTodoListExpandedHeight(list) {
        if (!list)
            return;

        var panel = list.closest('.todo-panel');
        var collapsedHeightValue = panel
            ? getComputedStyle(panel).getPropertyValue('--todo-collapsed-item-height')
            : '';
        var collapsedHeight = parseFloat(collapsedHeightValue) || 58;
        var expandedExtraHeight = Array.from(list.querySelectorAll('.todo-item.expanded'))
            .reduce((total, expandedItem) => total + Math.max(0, expandedItem.offsetHeight - collapsedHeight), 0);
        list.style.setProperty('--todo-list-expanded-extra-height', expandedExtraHeight + 'px');
    }

    function toggleTodoItemExpanded(item, expanded) {
        if (!item)
            return;

        var nextExpanded = typeof expanded === 'boolean'
            ? expanded
            : !item.classList.contains('expanded');
        item.classList.toggle('expanded', nextExpanded);
        syncTodoExpandControl(item, nextExpanded);
        syncTodoListExpandedHeight(item.closest('.todo-list'));
    }

    function isTodoInteractiveTarget(target) {
        return !!(target && target.closest && target.closest('button, input, textarea, select, label, a, [data-action], .todo-edit-form'));
    }

    function setTodoAddFormVisible(visible, groupId) {
        var form = document.querySelector('.todo-add-form');
        if (!form)
            return;

        var groupSelect = form.querySelector('[name="groupId"]');
        if (visible && groupSelect) {
            groupSelect.value = groupId || '';
        }
        form.hidden = !visible;
        if (!visible)
            return;

        var titleInput = form.querySelector('[name="title"]');
        if (titleInput) {
            titleInput.focus();
        }
        form.scrollIntoView({ block: 'nearest' });
    }

    function setTodoEditing(todoId, editing) {
        if (!todoId)
            return;

        var item = Array.from(document.querySelectorAll('.todo-item[data-todo-id]'))
            .find(candidate => candidate.getAttribute('data-todo-id') === todoId);
        if (!item)
            return;

        var wasEditing = item.classList.contains('editing');
        var expandedBeforeEdit = item.getAttribute('data-expanded-before-edit');
        if (editing && !wasEditing) {
            item.setAttribute(
                'data-expanded-before-edit',
                item.classList.contains('expanded') ? 'true' : 'false'
            );
            expandedBeforeEdit = item.getAttribute('data-expanded-before-edit');
        }
        var view = item.querySelector('.todo-item-view');
        var form = item.querySelector('.todo-edit-form');
        var list = item.closest('.todo-list');
        if (form && !editing) {
            resetTodoEditForm(form);
        }
        item.classList.toggle('editing', editing);
        if (view) {
            view.hidden = false;
        }
        if (form) {
            form.hidden = !editing;
        }
        toggleTodoItemExpanded(item, editing ? true : expandedBeforeEdit === 'true');
        if (!editing) {
            item.removeAttribute('data-expanded-before-edit');
        }
        if (list) {
            list.classList.toggle('has-editing-item', !!list.querySelector('.todo-item.editing'));
        }
        if (form && editing) {
            var titleInput = form.querySelector('[name="title"]');
            if (titleInput) {
                titleInput.focus();
            }
            item.scrollIntoView({ block: 'nearest' });
        }
    }

    function onTodoFormSubmit(e) {
        if (window.__agentPivotTodo
            && e.target
            && e.target.closest
            && e.target.closest('#dashboard-tab-todo')) {
            return;
        }
        var addForm = e.target && e.target.closest ? e.target.closest('.todo-add-form') : null;
        if (addForm) {
            e.preventDefault();
            submitTodoComposeForm(addForm, message => window.vscode.postMessage(message));
            return;
        }

        var editForm = e.target && e.target.closest ? e.target.closest('.todo-edit-form') : null;
        if (editForm) {
            e.preventDefault();
            var todoId = editForm.getAttribute('data-todo-id');
            var editTitle = getTodoFormValue(editForm, 'title');
            if (!todoId || !editTitle)
                return;
            window.vscode.postMessage({
                type: 'todo-update',
                todoId,
                title: editTitle,
                notes: getTodoFormValue(editForm, 'notes'),
                priority: getTodoFormValue(editForm, 'priority'),
            });
        }
    }

    return {
        isDedicatedTodoTarget: isDedicatedTodoTarget,
        isTodoInteractiveTarget: isTodoInteractiveTarget,
        onInsideGroupClick: onInsideGroupClick,
        onTodoAction: onTodoAction,
        onTodoFormSubmit: onTodoFormSubmit,
        resetTodoEditForm: resetTodoEditForm,
        setTodoAddFormVisible: setTodoAddFormVisible,
        setTodoEditing: setTodoEditing,
        syncTodoListExpandedHeight: syncTodoListExpandedHeight,
        syncTodoPrioritySegment: syncTodoPrioritySegment,
        toggleTodoItemExpanded: toggleTodoItemExpanded,
    };
}

/* src/webview/webviewProjectContextMenuScripts.js */
function initProjectContextMenus(options) {
    'use strict';

    options = options || {};
    var openProject = options.openProject;
    var ProjectOpenType = options.ProjectOpenType;
    var getResumeAiSessionMessageType = options.getResumeAiSessionMessageType;
    var getArchiveAiSessionMessageType = options.getArchiveAiSessionMessageType;
    var isAiSessionProvider = options.isAiSessionProvider;

    function onTriggerProjectAction(target, projectId) {
        var actionDiv = target.closest('[data-action]')
        if (actionDiv == null)
            return false;

        var action = actionDiv.getAttribute("data-action");
        if (!action)
            return false;

        if (action === 'save-current-workspace') {
            window.vscode.postMessage({
                type: 'save-current-workspace',
                projectId,
            });
            return true;
        }

        if (action === 'toggle-open-workspace-pin') {
            requestOpenWorkspacePin(actionDiv, projectId);
            return true;
        }

        window.vscode.postMessage({
            type: action + '-project',
            projectId,
        });

        return true;
    }

    var contextMenuProjectId = null;
    var contextMenuGroupId = null;
    var contextMenuAiSessionId = null;
    var contextMenuAiSessionProvider = null;
    var contextMenuAiSessionProjectId = null;
    var contextMenuAiSessionActive = false;
    var contextMenuAiSessionBackend = null;
    var contextMenuAiSessionAttached = false;
    var contextMenuAiSessionConflict = false;
    var contextMenuAiSessionOrigin = null;

    function showContextMenu(contextMenuElement, e) {
        contextMenuElement.style.visibility = "hidden";
        contextMenuElement.style.left = "0px";
        contextMenuElement.style.top = "0px";
        contextMenuElement.classList.add("visible");

        var rect = contextMenuElement.getBoundingClientRect();
        var viewportPadding = 4;
        var left = e.clientX;
        var top = e.clientY;

        if (left + rect.width + viewportPadding > window.innerWidth) {
            left = Math.max(viewportPadding, window.innerWidth - rect.width - viewportPadding);
        }

        if (top + rect.height + viewportPadding > window.innerHeight) {
            top = Math.max(viewportPadding, window.innerHeight - rect.height - viewportPadding);
        }

        contextMenuElement.style.left = left + "px";
        contextMenuElement.style.top = top + "px";
        contextMenuElement.style.visibility = "";
    }

    function onContextMenu(e) {
        closeContextMenus(); // Close previews

        var sessionRow = e.target.closest('.codex-session-row[data-session-id][data-session-provider]');
        if (sessionRow) {
            contextMenuAiSessionOrigin = sessionRow.querySelector('.ai-session-primary-action') || sessionRow;
            contextMenuAiSessionId = sessionRow.getAttribute("data-session-id");
            contextMenuAiSessionProvider = sessionRow.getAttribute("data-session-provider");
            var sessionProjectDiv = sessionRow.closest('.project[data-id]');
            contextMenuAiSessionProjectId = sessionProjectDiv ? sessionProjectDiv.getAttribute("data-id") : null;
            contextMenuAiSessionActive = sessionRow.hasAttribute('data-session-active');
            contextMenuAiSessionBackend = sessionRow.getAttribute('data-session-backend') || 'vscode';
            contextMenuAiSessionAttached = sessionRow.getAttribute('data-session-attached') === 'true';
            contextMenuAiSessionConflict = sessionRow.hasAttribute('data-session-conflict');
            if (!contextMenuAiSessionId || !isAiSessionProvider(contextMenuAiSessionProvider))
                return;

            e.preventDefault();
            var sessionContextMenuElement = document.getElementById("aiSessionContextMenu");
            if (!sessionContextMenuElement)
                return;
            sessionContextMenuElement.querySelectorAll(':scope > *').forEach(element => element.classList.remove('disabled'));
            var archiveMenuItem = sessionContextMenuElement.querySelector('[data-action="archive"]');
            var closeMenuItem = sessionContextMenuElement.querySelector('[data-action="close-terminal"]');
            if (archiveMenuItem) archiveMenuItem.classList.toggle('disabled', contextMenuAiSessionActive);
            if (closeMenuItem) {
                var terminalActionLabel = contextMenuAiSessionBackend === 'tmux'
                    ? 'Detach Terminal…' : 'Close Terminal…';
                closeMenuItem.textContent = terminalActionLabel;
                closeMenuItem.setAttribute('aria-label', terminalActionLabel);
                closeMenuItem.toggleAttribute('hidden', contextMenuAiSessionConflict);
                closeMenuItem.classList.toggle(
                    'disabled', !contextMenuAiSessionActive || contextMenuAiSessionConflict
                        || (contextMenuAiSessionBackend === 'tmux' && !contextMenuAiSessionAttached)
                );
            }
            var stopMenuItem = sessionContextMenuElement.querySelector('[data-action="stop-session"]');
            if (stopMenuItem) {
                stopMenuItem.toggleAttribute(
                    'hidden', contextMenuAiSessionBackend !== 'tmux' || contextMenuAiSessionConflict
                );
                stopMenuItem.classList.toggle(
                    'disabled', !contextMenuAiSessionActive || contextMenuAiSessionConflict
                );
            }

            showContextMenu(sessionContextMenuElement, e);
            if (e.keyboardTrigger) {
                var firstMenuItem = sessionContextMenuElement.querySelector('.custom-context-menu-item[data-action]:not(.disabled)');
                firstMenuItem?.focus();
            }
            return;
        }

        var projectDiv = e.target.closest('.project[data-id]');
        var groupDiv = e.target.closest('.group-title')
        if (!projectDiv && !groupDiv)
            return;

        if (projectDiv && projectDiv.hasAttribute("data-readonly-project"))
            return;

        e.preventDefault();

        let contextMenuForProject = projectDiv != null;
        var contextMenuElement;
        if (contextMenuForProject) {
            contextMenuProjectId = projectDiv.getAttribute("data-id");
            if (contextMenuProjectId == null)
                return;

            contextMenuElement = document.getElementById("projectContextMenu");
        } else {
            let groupIdDiv = groupDiv.closest(".group[data-group-id]");
            if (groupIdDiv && groupIdDiv.hasAttribute("data-virtual-group"))
                return;

            contextMenuGroupId = groupIdDiv ? groupIdDiv.getAttribute("data-group-id") : null;
            if (contextMenuGroupId == null)
                return;

            contextMenuElement = document.getElementById("groupContextMenu");
        }

        // disable elements if needed
        contextMenuElement.querySelectorAll(":scope > *").forEach(e => e.classList.remove("disabled"));

        if (projectDiv && projectDiv.hasAttribute("data-is-remote")) {
            contextMenuElement.querySelectorAll(".not-remote").forEach(e => e.classList.add("disabled"));
        }

        // place and show contextmenu

        showContextMenu(contextMenuElement, e);
    }

    function onProjectContextMenuActionClicked(el) {
        var action = el.getAttribute("data-action");

        if (action == null || contextMenuProjectId == null)
            return;

        switch (action) {
            case 'open':
                openProject(contextMenuProjectId, ProjectOpenType.CurrentWindow);
                break;
            case 'open-add-to-workspace':
                openProject(contextMenuProjectId, ProjectOpenType.AddToWorkspace);
                break;
            default:
                window.vscode.postMessage({
                    type: action + '-project',
                    projectId: contextMenuProjectId,
                });
                break;
        }

        closeContextMenus();
    }

    function onGroupContextMenuActionClicked(el) {
        var action = el.getAttribute("data-action");

        if (action == null || contextMenuGroupId == null)
            return;

        switch (action) {
            case 'add':
                window.vscode.postMessage({
                    type: 'add-project',
                    groupId: contextMenuGroupId,
                });
                break;
            default:
                window.vscode.postMessage({
                    type: action + '-group',
                    groupId: contextMenuGroupId,
                });
                break;
        }

        closeContextMenus();
    }

    function onAiSessionContextMenuActionClicked(el) {
        var action = el.getAttribute("data-action");
        var origin = contextMenuAiSessionOrigin;

        if (action == null || contextMenuAiSessionId == null || contextMenuAiSessionProvider == null)
            return;

        switch (action) {
            case 'resume':
                window.vscode.postMessage(contextMenuAiSessionActive ? {
                    type: 'focus-ai-session-terminal',
                    provider: contextMenuAiSessionProvider,
                    projectId: contextMenuAiSessionProjectId,
                    sessionId: contextMenuAiSessionId,
                } : {
                    type: getResumeAiSessionMessageType(contextMenuAiSessionProvider),
                    provider: contextMenuAiSessionProvider,
                    projectId: contextMenuAiSessionProjectId,
                    sessionId: contextMenuAiSessionId,
                });
                break;
            case 'rename':
                window.vscode.postMessage({
                    type: 'rename-ai-session',
                    provider: contextMenuAiSessionProvider,
                    sessionId: contextMenuAiSessionId,
                });
                break;
            case 'copy-id':
                window.vscode.postMessage({
                    type: 'copy-ai-session-id',
                    provider: contextMenuAiSessionProvider,
                    sessionId: contextMenuAiSessionId,
                });
                break;
            case 'pin':
                window.vscode.postMessage({
                    type: 'toggle-ai-session-pin',
                    provider: contextMenuAiSessionProvider,
                    sessionId: contextMenuAiSessionId,
                });
                break;
            case 'archive':
                if (contextMenuAiSessionActive) break;
                window.vscode.postMessage({
                    type: getArchiveAiSessionMessageType(contextMenuAiSessionProvider),
                    projectId: contextMenuAiSessionProjectId,
                    provider: contextMenuAiSessionProvider,
                    sessionId: contextMenuAiSessionId,
                });
                break;
            case 'close-terminal':
                if (!contextMenuAiSessionActive || contextMenuAiSessionConflict
                    || (contextMenuAiSessionBackend === 'tmux' && !contextMenuAiSessionAttached)) break;
                window.vscode.postMessage({
                    type: contextMenuAiSessionBackend === 'tmux'
                        ? 'detach-ai-session-terminal' : 'close-ai-session-terminal',
                    projectId: contextMenuAiSessionProjectId,
                    provider: contextMenuAiSessionProvider,
                    sessionId: contextMenuAiSessionId,
                });
                break;
            case 'stop-session':
                if (!contextMenuAiSessionActive || contextMenuAiSessionConflict
                    || contextMenuAiSessionBackend !== 'tmux') break;
                window.vscode.postMessage({
                    type: 'stop-ai-session-runtime',
                    projectId: contextMenuAiSessionProjectId,
                    provider: contextMenuAiSessionProvider,
                    sessionId: contextMenuAiSessionId,
                });
                break;
        }

        closeContextMenus();
        origin?.focus();
    }

    function closeContextMenus() {
        contextMenuProjectId = null;
        contextMenuGroupId = null;
        contextMenuAiSessionId = null;
        contextMenuAiSessionProvider = null;
        contextMenuAiSessionProjectId = null;
        contextMenuAiSessionActive = false;
        contextMenuAiSessionBackend = null;
        contextMenuAiSessionAttached = false;
        contextMenuAiSessionConflict = false;
        contextMenuAiSessionOrigin = null;
        // Only close menus this script owns; the dashboard script owns the
        // skill folder menu and keeps it open across per-agent toggles.
        document.querySelectorAll(".custom-context-menu:not(.skill-folder-menu)").forEach(element =>
            element.classList.remove("visible")
        );
        // The create-dropdown arrows mirror the shared menu's visibility.
        document.querySelectorAll('[data-action="create-ai-session-dropdown"][aria-expanded="true"]')
            .forEach(button => button.setAttribute("aria-expanded", "false"));
        document.querySelectorAll('[data-action="ai-session-worktree-menu"][aria-expanded="true"]')
            .forEach(button => button.setAttribute("aria-expanded", "false"));
    }

    function getAiSessionContextMenuOrigin() {
        return contextMenuAiSessionOrigin;
    }

    return {
        closeContextMenus: closeContextMenus,
        getAiSessionContextMenuOrigin: getAiSessionContextMenuOrigin,
        onAiSessionContextMenuActionClicked: onAiSessionContextMenuActionClicked,
        onContextMenu: onContextMenu,
        onGroupContextMenuActionClicked: onGroupContextMenuActionClicked,
        onProjectContextMenuActionClicked: onProjectContextMenuActionClicked,
        onTriggerProjectAction: onTriggerProjectAction,
        showContextMenu: showContextMenu,
    };
}

/* src/webview/webviewProjectAiUpdateScripts.js */
function initAiSessionPresentationStateStore(options) {
    'use strict';

    options = options || {};
    var isAiSessionProvider = options.isAiSessionProvider;
    var currentPresentation = null;

    function isValid(message) {
        return message && message.type === 'ai-session-presentation-state'
            && message.version === 1
            && Number.isSafeInteger(message.projectionRevision)
            && message.projectionRevision > 0
            && (typeof message.workspaceScopeIdentity === 'string'
                || message.workspaceScopeIdentity === null)
            && (typeof message.workspaceNavigationIdentity === 'string'
                || message.workspaceNavigationIdentity === null)
            && (typeof message.worktreeGroupsAggregateRevision === 'undefined'
                || message.worktreeGroupsAggregateRevision === null
                || (Number.isSafeInteger(message.worktreeGroupsAggregateRevision)
                    && message.worktreeGroupsAggregateRevision >= 0))
            && Number.isSafeInteger(message.attentionCount) && message.attentionCount >= 0
            && Number.isSafeInteger(message.activeAttentionCount)
            && message.activeAttentionCount >= 0
            && Number.isSafeInteger(message.runningSessionCount)
            && message.runningSessionCount >= 0
            && ['current', 'sweep', 'orbit', 'halo', 'ripple', 'breath', 'custom', 'none']
                .includes(message.runningCardAnimation)
            && ['current', 'halo', 'custom', 'none'].includes(message.runningIconAnimation)
            && typeof message.revealFocused === 'boolean'
            && (message.focusedTarget === null
                || (message.focusedTarget
                    && isAiSessionProvider(message.focusedTarget.provider)
                    && ((typeof message.focusedTarget.sessionId === 'string'
                        && !!message.focusedTarget.sessionId
                        && typeof message.focusedTarget.pendingId === 'undefined')
                        || (typeof message.focusedTarget.pendingId === 'string'
                            && !!message.focusedTarget.pendingId
                            && typeof message.focusedTarget.sessionId === 'undefined'))))
            && Array.isArray(message.sessions) && message.sessions.length <= 1000
            && message.sessions.every(session => session
                && isAiSessionProvider(session.provider)
                && typeof session.sessionId === 'string' && !!session.sessionId
                && (session.executionState === 'running'
                    || session.executionState === 'stopped')
                && typeof session.focused === 'boolean'
                && typeof session.needsAttention === 'boolean'
                && typeof session.conflict === 'boolean'
                && Array.isArray(session.eventIds)
                && session.eventIds.length <= 1000
                && session.eventIds.every(eventId => typeof eventId === 'string' && !!eventId))
            && Array.isArray(message.attentionSessions)
            && message.attentionSessions.length <= 1000
            && message.attentionSessions.every(session => session
                && typeof session.sessionKey === 'string' && !!session.sessionKey
                && Array.isArray(session.eventIds)
                && session.eventIds.length <= 1000
                && session.eventIds.every(eventId => typeof eventId === 'string' && !!eventId));
    }

    function adopt(message) {
        if (!isValid(message)) return false;
        currentPresentation = message;
        return true;
    }

    function getCurrent() {
        return currentPresentation;
    }

    function getFocusedTarget() {
        return currentPresentation ? currentPresentation.focusedTarget : null;
    }

    function getAttentionEventIds(provider, sessionId) {
        if (!currentPresentation) return [];
        var sessionKey = provider + ':' + sessionId;
        var owner = currentPresentation.attentionSessions.find(session =>
            session && session.sessionKey === sessionKey
        );
        return owner ? owner.eventIds.slice() : [];
    }

    return {
        adopt: adopt,
        getAttentionEventIds: getAttentionEventIds,
        getCurrent: getCurrent,
        getFocusedTarget: getFocusedTarget,
        isValid: isValid,
    };
}

function initAiSessionPresentationTransactions(options) {
    'use strict';

    options = options || {};
    var isValidAiSessionPresentationState = options.isValidAiSessionPresentationState;
    var canApplyAiSessionPresentationState = options.canApplyAiSessionPresentationState;
    var applyValidatedAiSessionPresentationState = options.applyValidatedAiSessionPresentationState;
    var latestAiSessionProjectionRevision = 0;
    var latestAiSessionPresentationProjectionRevision = 0;
    var latestAiSessionClosedPresentationRevision = 0;

    function requestFullRefresh(reason) {
        window.vscode.postMessage({
            type: 'request-full-refresh',
            reason,
        });
    }

    function hasMatchingPresentationWorkspace(message) {
        if (canApplyAiSessionPresentationState(message)) return true;
        requestFullRefresh('mismatched-ai-session-presentation-workspace');
        return false;
    }

    function canApplyRevision(revision, latestRevision) {
        if (typeof revision === 'undefined') {
            return latestRevision === 0;
        }
        return Number.isSafeInteger(revision)
            && revision > 0
            && revision > latestRevision;
    }

    function canApplyProjectionRevision(revision) {
        return canApplyRevision(revision, latestAiSessionProjectionRevision);
    }

    function canApplyAtomicPresentationProjectionRevision(revision) {
        return Number.isSafeInteger(revision)
            && revision > 0
            && revision >= latestAiSessionPresentationProjectionRevision
            && revision > latestAiSessionClosedPresentationRevision;
    }

    function commitAtomicProjectionRevision(revision) {
        latestAiSessionProjectionRevision = revision;
        latestAiSessionPresentationProjectionRevision = Math.max(
            latestAiSessionPresentationProjectionRevision,
            revision
        );
        latestAiSessionClosedPresentationRevision = Math.max(
            latestAiSessionClosedPresentationRevision,
            revision
        );
    }

    function acceptPresentationProjectionRevision(revision) {
        if (!Number.isSafeInteger(revision)
            || revision <= 0
            || revision < latestAiSessionProjectionRevision
            || revision <= latestAiSessionPresentationProjectionRevision
            || revision <= latestAiSessionClosedPresentationRevision) {
            return false;
        }
        latestAiSessionPresentationProjectionRevision = revision;
        return true;
    }

    function acceptInitialPresentationProjectionRevision(revision) {
        if (!Number.isSafeInteger(revision)
            || revision <= 0
            || latestAiSessionProjectionRevision !== 0
            || latestAiSessionPresentationProjectionRevision !== 0
            || latestAiSessionClosedPresentationRevision !== 0) {
            return false;
        }
        latestAiSessionProjectionRevision = revision;
        latestAiSessionPresentationProjectionRevision = revision;
        latestAiSessionClosedPresentationRevision = revision;
        return true;
    }

    function applyInitialPresentation(message) {
        if (!isValidAiSessionPresentationState(message)) {
            requestFullRefresh('invalid-initial-ai-session-presentation-state');
            return false;
        }
        if (!hasMatchingPresentationWorkspace(message)) return false;
        if (!acceptInitialPresentationProjectionRevision(message.projectionRevision)) {
            return false;
        }
        applyValidatedAiSessionPresentationState(message);
        return true;
    }

    function applyDirectPresentation(message) {
        if (!isValidAiSessionPresentationState(message)
            || message.revealFocused !== true) {
            requestFullRefresh('invalid-direct-ai-session-presentation-state');
            return false;
        }
        if (!hasMatchingPresentationWorkspace(message)) return false;
        if (!acceptPresentationProjectionRevision(message.projectionRevision)) {
            return false;
        }
        applyValidatedAiSessionPresentationState(message);
        return true;
    }

    function applyAtomicEnvelope(input) {
        var message = input.message;
        if (!Number.isSafeInteger(message.projectionRevision)
            || message.projectionRevision <= 0
            || !isValidAiSessionPresentationState(message.presentation)
            || message.presentation.projectionRevision !== message.projectionRevision
            || message.presentation.revealFocused !== false) {
            requestFullRefresh(input.invalidPresentationReason);
            return false;
        }
        if (!canApplyProjectionRevision(message.projectionRevision)
            || !canApplyAtomicPresentationProjectionRevision(message.projectionRevision)) {
            return false;
        }
        var replacementWorkspaceMatches = null;
        if (!input.replaceContent(replacementRoot => {
            replacementWorkspaceMatches = canApplyAiSessionPresentationState(
                message.presentation,
                replacementRoot
            );
            return replacementWorkspaceMatches;
        })) {
            requestFullRefresh(replacementWorkspaceMatches === false
                ? 'mismatched-ai-session-presentation-workspace'
                : input.invalidReplacementReason);
            return false;
        }
        if (!hasMatchingPresentationWorkspace(message.presentation)) return false;
        commitAtomicProjectionRevision(message.projectionRevision);
        if (typeof input.afterReplacement === 'function') {
            input.afterReplacement();
        }
        applyValidatedAiSessionPresentationState(message.presentation);
        return true;
    }

    return {
        applyAtomicEnvelope: applyAtomicEnvelope,
        applyDirectPresentation: applyDirectPresentation,
        applyInitialPresentation: applyInitialPresentation,
        requestFullRefresh: requestFullRefresh,
    };
}

function initAiSessionPresentationDom(options) {
    'use strict';

    options = options || {};
    var presentationStateStore = options.presentationStateStore;

    function syncActiveAiSessionProjectionDom(revealFocused) {
        var focusedTarget = presentationStateStore.getFocusedTarget();
        var projectedFocusedRow = null;
        document.querySelectorAll(
            '.codex-session-row[data-session-provider][data-session-id],'
                + '.codex-session-row[data-session-provider][data-pending-id]'
        ).forEach(row => {
            var providerMatches = focusedTarget
                && row.getAttribute('data-session-provider') === focusedTarget.provider;
            var focused = providerMatches && (
                (typeof focusedTarget.sessionId === 'string'
                    && row.getAttribute('data-session-id') === focusedTarget.sessionId)
                || (typeof focusedTarget.pendingId === 'string'
                    && row.getAttribute('data-pending-id') === focusedTarget.pendingId)
            );
            if (focused) projectedFocusedRow = row;
            row.toggleAttribute('data-session-focused', focused);
            var focusedConversation = focused && row.hasAttribute('data-session-id');
            row.toggleAttribute('data-ai-session-active-terminal', focusedConversation);
            var primaryAction = row.querySelector('.ai-session-primary-action');
            if (primaryAction) {
                var actionState = focusedConversation ? 'conversation' : 'focus';
                var actionAriaLabel = primaryAction.getAttribute(
                    'data-' + actionState + '-aria-label'
                );
                var actionTitle = primaryAction.getAttribute(
                    'data-' + actionState + '-title'
                );
                if (actionAriaLabel) primaryAction.setAttribute('aria-label', actionAriaLabel);
                if (actionTitle) primaryAction.setAttribute('title', actionTitle);
            }
            var conversationHint = row.querySelector('.ai-session-open-conversation-hint');
            if (focusedConversation && primaryAction && !conversationHint) {
                conversationHint = document.createElement('span');
                conversationHint.className = 'ai-session-open-conversation-hint';
                conversationHint.setAttribute('aria-hidden', 'true');
                conversationHint.textContent = '›';
                primaryAction.appendChild(conversationHint);
            } else if (!focused && conversationHint) {
                conversationHint.remove();
            }
        });
        if (projectedFocusedRow && revealFocused) {
            projectedFocusedRow.scrollIntoView({ block: 'nearest' });
        }
    }
    function setAiSessionAttentionDom(row, eventIds, needsAttention) {
        row.toggleAttribute('data-session-needs-attention', needsAttention);
        row.toggleAttribute('data-ai-session-attention', needsAttention);
        if (needsAttention && eventIds.length) {
            row.setAttribute('data-session-event-id', eventIds[0]);
        } else {
            row.removeAttribute('data-session-event-id');
        }
        var primaryAction = row.querySelector('.ai-session-primary-action');
        var indicator = row.querySelector('.ai-session-attention-indicator');
        if (needsAttention && primaryAction && !indicator) {
            indicator = document.createElement('span');
            indicator.className = 'ai-session-attention-indicator';
            indicator.title = 'AI session needs attention';
            indicator.setAttribute('aria-label', 'AI session needs attention');
            primaryAction.insertBefore(indicator, primaryAction.firstChild);
        } else if (!needsAttention && indicator) {
            indicator.remove();
        }
    }
    function setAiSessionExecutionDom(row, presentation, iconAnimation) {
        row.setAttribute('data-execution-state', presentation.executionState);
        if (presentation.executionState === 'running' && iconAnimation !== 'none') {
            row.setAttribute('data-session-icon-fx', iconAnimation);
        } else {
            row.removeAttribute('data-session-icon-fx');
        }
        row.toggleAttribute('data-session-conflict', presentation.conflict);
        var status = row.querySelector('.ai-session-execution-status');
        if (status) {
            var running = presentation.executionState === 'running';
            status.setAttribute(
                'aria-label',
                running ? 'AI is currently executing' : 'AI is not currently executing'
            );
            var label = status.lastChild;
            if (label && label.nodeType === Node.TEXT_NODE) {
                label.nodeValue = running ? 'Running' : 'Stopped';
            }
        }
    }
    function setActiveSessionTabAttentionDom(projectDiv, attentionCount) {
        var tab = projectDiv.querySelector('[data-ai-session-tab="active"]');
        if (!tab) return;
        var dot = tab.querySelector('.ai-session-tab-attention');
        if (attentionCount > 0 && !dot) {
            dot = document.createElement('span');
            dot.className = 'ai-session-tab-attention';
            tab.appendChild(dot);
        } else if (attentionCount === 0 && dot) {
            dot.remove();
            return;
        }
        if (dot) {
            dot.setAttribute(
                'aria-label',
                attentionCount + ' active AI session'
                    + (attentionCount === 1 ? ' needs' : 's need') + ' attention'
            );
        }
    }
    function setCurrentWorkspaceSummaryAttentionDom(projectDiv, attentionCount) {
        var summary = projectDiv.querySelector('.project-codex-badge');
        if (!summary && attentionCount > 0) {
            summary = document.createElement('span');
            summary.className = 'project-codex-badge';
            summary.setAttribute('data-ai-session-total-count', '0');
            summary.setAttribute('data-ai-session-active-count', '0');
            projectDiv.appendChild(summary);
        }
        if (!summary) return;
        summary.setAttribute('data-ai-session-attention-count', String(attentionCount));
        var count = summary.querySelector('.ai-session-attention-count');
        if (attentionCount > 0 && !count) {
            count = document.createElement('b');
            count.className = 'ai-session-attention-count';
            summary.appendChild(count);
        } else if (attentionCount === 0 && count) {
            count.remove();
            count = null;
        }
        if (count) {
            count.textContent = String(attentionCount);
            count.setAttribute(
                'aria-label',
                attentionCount + ' AI session'
                    + (attentionCount === 1 ? ' needs' : 's need') + ' attention'
            );
        }
        var total = Number(summary.getAttribute('data-ai-session-total-count')) || 0;
        var active = Number(summary.getAttribute('data-ai-session-active-count')) || 0;
        var parts = [];
        if (total) parts.push(total + ' AI session' + (total === 1 ? '' : 's'));
        if (active) parts.push(active + ' active AI session' + (active === 1 ? '' : 's'));
        if (attentionCount) parts.push(attentionCount + ' AI session'
            + (attentionCount === 1 ? ' needs' : 's need') + ' attention');
        if (!parts.length) {
            summary.remove();
            projectDiv.removeAttribute('data-has-ai-session-badge');
            return;
        }
        projectDiv.setAttribute('data-has-ai-session-badge', '');
        summary.title = parts.join(', ');
        summary.setAttribute('aria-label', parts.join(', '));
    }
    function setCurrentWorkspaceRunningDom(projectDiv, message) {
        var running = message.runningSessionCount > 0;
        projectDiv.classList.toggle('session-running', running);
        if (running) {
            projectDiv.setAttribute('data-session-fx', message.runningCardAnimation);
            projectDiv.title = 'Workspace — ' + message.runningSessionCount + ' active session'
                + (message.runningSessionCount === 1 ? '' : 's') + ' running';
        } else {
            projectDiv.removeAttribute('data-session-fx');
            projectDiv.removeAttribute('title');
        }
        var effect = projectDiv.querySelector('.project-session-fx');
        var showEffect = running && message.runningCardAnimation !== 'none';
        if (showEffect && !effect) {
            effect = document.createElement('div');
            effect.className = 'project-session-fx';
            projectDiv.appendChild(effect);
        } else if (!showEffect && effect) {
            effect.remove();
        }
    }
    function setCurrentOpenWorkspaceSummaryDom(projectDiv, message) {
        var runningBadge = projectDiv.querySelector('.project-codex-badge');
        if (message.runningSessionCount > 0 && !runningBadge) {
            runningBadge = document.createElement('span');
            runningBadge.className = 'project-codex-badge';
            var runningCount = document.createElement('span');
            runningCount.className = 'ai-session-active-count';
            runningBadge.appendChild(runningCount);
            projectDiv.appendChild(runningBadge);
        } else if (message.runningSessionCount === 0 && runningBadge) {
            runningBadge.remove();
            runningBadge = null;
        }
        if (runningBadge) {
            var runningLabel = message.runningSessionCount + ' active AI session'
                + (message.runningSessionCount === 1 ? '' : 's');
            runningBadge.setAttribute(
                'data-ai-session-active-count', String(message.runningSessionCount)
            );
            runningBadge.title = runningLabel;
            runningBadge.setAttribute('aria-label', runningLabel);
            var runningCount = runningBadge.querySelector('.ai-session-active-count');
            runningCount.textContent = '●' + message.runningSessionCount;
            runningCount.setAttribute('aria-label', runningLabel);
        }
        var attentionBadge = projectDiv.querySelector('.project-ai-attention-badge');
        if (message.attentionCount > 0 && !attentionBadge) {
            attentionBadge = document.createElement('span');
            attentionBadge.className = 'project-ai-attention-badge';
            projectDiv.appendChild(attentionBadge);
        } else if (message.attentionCount === 0 && attentionBadge) {
            attentionBadge.remove();
            attentionBadge = null;
        }
        if (attentionBadge) {
            var attentionLabel = message.attentionCount + ' item'
                + (message.attentionCount === 1 ? '' : 's') + ' need'
                + (message.attentionCount === 1 ? 's' : '') + ' attention';
            attentionBadge.textContent = String(message.attentionCount);
            attentionBadge.title = attentionLabel;
            attentionBadge.setAttribute('aria-label', attentionLabel);
        }
        projectDiv.toggleAttribute(
            'data-has-ai-session-badge',
            message.runningSessionCount > 0 || message.attentionCount > 0
        );
        setCurrentWorkspaceRunningDom(projectDiv, message);
    }
    function getAiSessionPresentationCurrentCards(message, root) {
        if (typeof message.workspaceNavigationIdentity !== 'string'
            || !message.workspaceNavigationIdentity) return [];
        return Array.from((root || document).querySelectorAll(
            '.workspace-card[data-workspace-navigation-identity="'
                + CSS.escape(message.workspaceNavigationIdentity || '') + '"]'
                + '[data-current-workspace]'
        ));
    }
    function canApplyAiSessionPresentationDom(message, root) {
        var projectionRoot = root || document;
        if (message.workspaceNavigationIdentity === null) {
            return !projectionRoot.querySelector(
                '.workspace-card[data-current-workspace]'
            );
        }
        return getAiSessionPresentationCurrentCards(message, projectionRoot).length > 0;
    }
    function applyAiSessionPresentationDom(message) {
        var currentCards = getAiSessionPresentationCurrentCards(message);
        syncActiveAiSessionProjectionDom(message.revealFocused);
        if (!currentCards.length) return;
        var projectDiv = currentCards.find(card => card.hasAttribute('data-current-workspace'));
        var presentations = {};
        message.sessions.forEach(presentation => {
            presentations[presentation.provider + ':' + presentation.sessionId] = presentation;
        });
        var attentionEvents = {};
        message.attentionSessions.forEach(session => {
            attentionEvents[session.sessionKey] = session.eventIds.slice();
        });
        projectDiv?.querySelectorAll(
            '.codex-session-row[data-session-provider][data-session-id]'
        ).forEach(row => {
            var sessionKey = row.getAttribute('data-session-provider')
                + ':' + row.getAttribute('data-session-id');
            var presentation = presentations[sessionKey];
            var eventIds = attentionEvents[sessionKey] || [];
            if (presentation) {
                setAiSessionExecutionDom(row, presentation, message.runningIconAnimation);
                setAiSessionAttentionDom(
                    row,
                    presentation.eventIds,
                    presentation.needsAttention
                );
            } else if (row.classList.contains('active-ai-session-row')) {
                setAiSessionAttentionDom(row, [], false);
            } else {
                setAiSessionAttentionDom(row, eventIds, eventIds.length > 0);
            }
        });
        if (projectDiv) {
            setActiveSessionTabAttentionDom(projectDiv, message.activeAttentionCount);
            setCurrentWorkspaceSummaryAttentionDom(projectDiv, message.attentionCount);
            setCurrentWorkspaceRunningDom(projectDiv, message);
        }
        currentCards.filter(card => card.hasAttribute('data-open-workspace-current'))
            .forEach(card => setCurrentOpenWorkspaceSummaryDom(card, message));
    }

    return {
        apply: applyAiSessionPresentationDom,
        canApply: canApplyAiSessionPresentationDom,
    };
}

function initProjectAiSessionsUpdate(options) {
    'use strict';

    options = options || {};
    var batchAiSessionState = options.batchAiSessionState;
    var batchAiSessionManager = options.batchAiSessionManager;
    var getPendingAiSessionProviderSelectionProjectId = options.getPendingAiSessionProviderSelectionProjectId;
    var getSelectedAiSessionProviders = options.getSelectedAiSessionProviders;
    var syncAiSessionBatchManagementDom = options.syncAiSessionBatchManagementDom;
    var reconcilePendingAiSessionProviderSelectionDom = options.reconcilePendingAiSessionProviderSelectionDom;
    var reconcileWorktreeGroupFormDom = options.reconcileWorktreeGroupFormDom;
    var submitAiSessionProviderSelection = options.submitAiSessionProviderSelection;
    var toggleCodexSessions = options.toggleCodexSessions;
    var exitAiSessionBatchManagement = options.exitAiSessionBatchManagement;
    var isAiSessionProvider = options.isAiSessionProvider;
    var updateStickyGroupHeaderOffset = options.updateStickyGroupHeaderOffset;
    var presentationTransactions = options.presentationTransactions;

    var pendingWorkspaceSessionReveal = null;

    function applyAiSessionsUpdate(message) {
        if (message.version !== 3
            || typeof message.sequence !== 'number'
            || (message.currentWorkspaceCount !== 0 && message.currentWorkspaceCount !== 1)
            || typeof message.html !== 'string'
            || typeof normalizeDashboardSearchCatalog !== 'function'
            || normalizeDashboardSearchCatalog(message.searchCatalog) !== message.searchCatalog
            || message.searchCatalog.version !== 3) {
            presentationTransactions.requestFullRefresh('unsupported-ai-session-message');
            return;
        }

        if (!Number.isSafeInteger(message.projectionRevision)
                || message.projectionRevision <= 0
                || message.sequence !== message.projectionRevision
                || typeof message.generatedAt !== 'string'
                || !message.generatedAt) {
            presentationTransactions.requestFullRefresh(
                'invalid-ai-session-presentation-envelope'
            );
            return;
        }

        if (!presentationTransactions.applyAtomicEnvelope({
            message: message,
            invalidPresentationReason: 'invalid-ai-session-presentation-envelope',
            invalidReplacementReason: 'invalid-ai-session-workspace-update',
            replaceContent: validateReplacement => applyWorkspaceUpdate({
                type: 'workspace-updated',
                version: 2,
                currentWorkspaceCount: message.currentWorkspaceCount,
                html: message.html,
            }, {
                canRestoreAiSessionProviderMenu: () =>
                    !getPendingAiSessionProviderSelectionProjectId()
                    && !batchAiSessionState.pending,
                validateReplacement: validateReplacement,
            }),
            afterReplacement: () => {
                if (batchAiSessionState.projectId) {
                    var projectDiv = findCurrentWorkspaceDiv(batchAiSessionState.projectId);
                    if (projectDiv) {
                        batchAiSessionManager.reconcileVisible(projectDiv);
                        syncAiSessionBatchManagementDom(projectDiv);
                    } else {
                        exitAiSessionBatchManagement();
                    }
                }
                reconcilePendingAiSessionProviderSelectionDom();
                if (reconcileWorktreeGroupFormDom) {
                    reconcileWorktreeGroupFormDom();
                }
            },
        })) {
            return;
        }
        updateStickyGroupHeaderOffset();
        if (window.__agentPivotDashboard) {
            window.__agentPivotDashboard.replaceSearchCatalog(message.searchCatalog);
        }
    }

    function findCurrentWorkspaceDiv(projectId) {
        if (!projectId) {
            return null;
        }

        var projects = document.querySelectorAll('.workspace-card[data-current-workspace][data-id]');
        for (var projectDiv of projects) {
            if (projectDiv.getAttribute("data-id") === projectId) {
                return projectDiv;
            }
        }

        return null;
    }

    function findWorkspaceDiv(navigationIdentity) {
        if (!navigationIdentity) {
            return null;
        }
        var workspaces = document.querySelectorAll('.workspace-card[data-workspace-navigation-identity]');
        for (var workspaceDiv of workspaces) {
            if (workspaceDiv.getAttribute('data-workspace-navigation-identity') === navigationIdentity) {
                return workspaceDiv;
            }
        }
        return null;
    }

    function focusSearchRevealTarget(target) {
        target.setAttribute('tabindex', '-1');
        target.focus();
        target.scrollIntoView({ block: 'nearest' });
        target.addEventListener('blur', () => target.removeAttribute('tabindex'), { once: true });
    }

    window.__agentPivotRevealWorkspace = navigationIdentity => {
        var workspaceDiv = findWorkspaceDiv(navigationIdentity);
        if (!workspaceDiv) {
            return false;
        }
        focusSearchRevealTarget(workspaceDiv);
        return true;
    };

    function revealWorkspaceSession(navigationIdentity, provider, sessionId) {
        if (!isAiSessionProvider(provider) || !sessionId) {
            return false;
        }
        var workspaceDiv = findWorkspaceDiv(navigationIdentity);
        if (!workspaceDiv) {
            return false;
        }
        var workspaceId = workspaceDiv.getAttribute('data-id');
        if (!workspaceDiv.hasAttribute('data-codex-expanded')) {
            toggleCodexSessions(workspaceDiv, workspaceId);
        }
        selectAiSessionTabDom(workspaceDiv, 'sessions');
        writeAiSessionTabState(window.vscode, workspaceId, 'sessions');
        var sessionRow = Array.from(workspaceDiv.querySelectorAll('.codex-session-row[data-session-id][data-session-provider]'))
            .find(row => row.getAttribute('data-session-provider') === provider
                && row.getAttribute('data-session-id') === sessionId);
        if (sessionRow) {
            pendingWorkspaceSessionReveal = null;
            focusSearchRevealTarget(sessionRow);
            return true;
        }
        var selectedProviders = getSelectedAiSessionProviders(workspaceDiv);
        if (!selectedProviders.includes(provider)) {
            pendingWorkspaceSessionReveal = { navigationIdentity, provider, sessionId };
            submitAiSessionProviderSelection(
                workspaceDiv,
                selectedProviders.concat(provider)
            );
            return true;
        }
        pendingWorkspaceSessionReveal = null;
        focusSearchRevealTarget(workspaceDiv);
        return false;
    }

    function revealWorkspaceWorktree(navigationIdentity, repositoryKey, canonicalWorktreePath) {
        if (!repositoryKey || !canonicalWorktreePath) {
            return false;
        }
        var workspaceDiv = findWorkspaceDiv(navigationIdentity);
        if (!workspaceDiv) {
            return false;
        }
        var workspaceId = workspaceDiv.getAttribute('data-id');
        if (!workspaceDiv.hasAttribute('data-codex-expanded')) {
            toggleCodexSessions(workspaceDiv, workspaceId);
        }
        selectAiSessionSurfaceDom(workspaceDiv, 'worktree');
        writeAiSessionSurfaceState(window.vscode, workspaceId, 'worktree');
        if (window.vscode && typeof window.vscode.postMessage === 'function') {
            window.vscode.postMessage({
                type: 'select-ai-session-surface',
                version: 1,
                projectId: workspaceId,
                surface: 'worktree',
            });
        }
        var group = Array.from(workspaceDiv.querySelectorAll(
            '.ai-session-worktree-group[data-worktree-repository-key][data-worktree-path]'
        )).find(candidate =>
            candidate.getAttribute('data-worktree-repository-key') === repositoryKey
            && candidate.getAttribute('data-worktree-path') === canonicalWorktreePath
        );
        if (!group) {
            focusSearchRevealTarget(workspaceDiv);
            return false;
        }
        var header = group.querySelector('.ai-session-worktree-header');
        setAiSessionWorktreeGroupExpanded(workspaceDiv, group, true);
        writeAiSessionWorktreeCollapseState(window.vscode, workspaceDiv);
        focusSearchRevealTarget(header || group);
        return true;
    }

    window.__agentPivotRevealWorkspaceSession = revealWorkspaceSession;
    window.__agentPivotRevealWorkspaceWorktree = revealWorkspaceWorktree;
    window.__agentPivotRevealPendingWorkspaceSession = () => {
        if (!pendingWorkspaceSessionReveal) {
            return false;
        }
        var pending = pendingWorkspaceSessionReveal;
        return revealWorkspaceSession(
            pending.navigationIdentity,
            pending.provider,
            pending.sessionId
        );
    };

    return {
        applyAiSessionsUpdate: applyAiSessionsUpdate,
        findCurrentWorkspaceDiv: findCurrentWorkspaceDiv,
        findWorkspaceDiv: findWorkspaceDiv,
        focusSearchRevealTarget: focusSearchRevealTarget,
        requestFullRefresh: presentationTransactions.requestFullRefresh,
    };
}

/* src/webview/webviewGroupFormScripts.js */
'use strict';

/**
 * The M2 inline worktree group creation form (PRD §6.1): an in-place card
 * at the top of the Worktree panel with a real-time per-member preview.
 *
 * Form state lives here (not in the DOM) because authoritative workspace
 * updates replace the surface HTML wholesale; reconcileDom re-renders the
 * form after every applied update. Closing the form keeps the unsubmitted
 * input for the next open.
 */
function initWorktreeGroupForm(options) {
    options = options || {};
    var getCurrentWorkspaceDiv = options.findCurrentWorkspaceDiv;

    var PREVIEW_DEBOUNCE_MS = 300;
    var statesByProject = new Map();
    var nextRequestSerial = 0;
    // Focus captured BEFORE an authoritative replacement destroys the form
    // slot; renderForm prefers it over the live DOM read (which can only see
    // document.body once the old slot is gone).
    var replacementFocusByProject = new Map();

    function nextRequestId(prefix) {
        nextRequestSerial = nextRequestSerial >= Number.MAX_SAFE_INTEGER
            ? 1 : nextRequestSerial + 1;
        return prefix + '-' + nextRequestSerial.toString(36);
    }

    function getState(projectId) {
        return statesByProject.get(projectId) || null;
    }

    function ensureState(projectId) {
        var state = statesByProject.get(projectId);
        if (!state) {
            state = {
                open: false,
                bootstrapping: false,
                name: '',
                repositories: [],
                checked: {},
                baseRefOverrides: {},
                setupDisabled: {},
                primaryRepositoryKey: '',
                preview: null,
                previewId: '',
                previewDirty: false,
                previewRequestId: '',
                previewTimer: 0,
                baseDropdown: null,
                confirming: false,
                confirmRequestId: '',
                formError: '',
                pendingFocusGroupId: '',
                pendingMemberRequests: {},
                derive: null,
                addRepo: null,
            };
            statesByProject.set(projectId, state);
        }
        return state;
    }

    function escapeHtml(value) {
        return String(value == null ? '' : value)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    function shortRefName(ref) {
        var value = String(ref || '');
        return value.indexOf('refs/heads/') === 0
            ? value.slice('refs/heads/'.length)
            : value;
    }

    function checkedRepositories(state) {
        return state.repositories.filter(function (repository) {
            return state.checked[repository.repositoryKey];
        });
    }

    function openForm(projectId, seed) {
        var state = ensureState(projectId);
        if (state.open) {
            return;
        }
        state.open = true;
        state.bootstrapping = true;
        state.formError = '';
        renderForm(projectId);
        var message = {
            type: 'open-worktree-group-form',
            version: 1,
            projectId: projectId,
        };
        if (seed && seed.repositoryKey && seed.worktreePath) {
            message.seedRepositoryKey = seed.repositoryKey;
            message.seedWorktreePath = seed.worktreePath;
        }
        if (seed && seed.sourceGroupId) {
            message.sourceGroupId = seed.sourceGroupId;
        }
        if (seed && seed.targetGroupId) {
            message.targetGroupId = seed.targetGroupId;
        }
        window.vscode.postMessage(message);
        focusNameInput(projectId);
    }

    function closeForm(projectId, keepInput) {
        var state = getState(projectId);
        if (!state || !state.open) {
            return;
        }
        state.open = false;
        state.bootstrapping = false;
        state.confirming = false;
        state.previewDirty = false;
        if (state.previewTimer) {
            clearTimeout(state.previewTimer);
            state.previewTimer = 0;
        }
        if (!keepInput) {
            var focusGroupId = state.pendingFocusGroupId;
            statesByProject.delete(projectId);
            if (focusGroupId) {
                ensureState(projectId).pendingFocusGroupId = focusGroupId;
            }
        }
        renderForm(projectId);
    }

    function applyFormState(message) {
        if (!message || message.type !== 'worktree-group-form-state'
            || message.version !== 1 || typeof message.projectId !== 'string'
            || !Array.isArray(message.repositories)) {
            return false;
        }
        var state = getState(message.projectId);
        if (!state || !state.open) {
            return true;
        }
        state.bootstrapping = false;
        state.repositories = message.repositories.filter(function (repository) {
            return repository && typeof repository.repositoryKey === 'string';
        });
        if (!Object.keys(state.checked).length) {
            state.repositories.forEach(function (repository) {
                state.checked[repository.repositoryKey] = !!repository.defaultChecked;
            });
        }
        if (message.derive && typeof message.derive === 'object'
            && typeof message.derive.sourceGroupId === 'string') {
            // Derive mode (PRD §6.2): precheck the source group's member
            // repositories, override each base ref to the source branch,
            // and prefill the default name 源名-2 (until the user types).
            state.derive = {
                sourceGroupId: message.derive.sourceGroupId,
                sourceName: typeof message.derive.sourceName === 'string'
                    ? message.derive.sourceName : '',
                skipped: Array.isArray(message.derive.skipped)
                    ? message.derive.skipped.filter(function (entry) {
                        return entry && typeof entry.repositoryLabel === 'string'
                            && typeof entry.reason === 'string';
                    })
                    : [],
            };
            var deriveChecked = Array.isArray(message.derive.checkedRepositories)
                ? message.derive.checkedRepositories : [];
            state.repositories.forEach(function (repository) {
                state.checked[repository.repositoryKey] =
                    deriveChecked.indexOf(repository.repositoryKey) >= 0;
            });
            if (message.derive.baseOverrides
                && typeof message.derive.baseOverrides === 'object') {
                Object.keys(message.derive.baseOverrides).forEach(function (repositoryKey) {
                    if (typeof message.derive.baseOverrides[repositoryKey] === 'string') {
                        state.baseRefOverrides[repositoryKey] =
                            message.derive.baseOverrides[repositoryKey];
                    }
                });
            }
            if (!state.name.trim() && typeof message.derive.suggestedName === 'string') {
                state.name = message.derive.suggestedName;
            }
        }
        if (message.addRepo && typeof message.addRepo === 'object'
            && typeof message.addRepo.groupId === 'string'
            && typeof message.addRepo.displayName === 'string') {
            // Add-repo mode (PRD §6.3): the group name and slug are locked;
            // the form only picks the repositories to add.
            state.addRepo = {
                groupId: message.addRepo.groupId,
                displayName: message.addRepo.displayName,
            };
            state.name = message.addRepo.displayName;
        }
        if (message.seed && typeof message.seed.repositoryKey === 'string'
            && typeof message.seed.baseRef === 'string') {
            // Branch-from-here: check only the seeded repository and prefill
            // its branch as the base-ref override (PRD §6.1 entry rules).
            state.repositories.forEach(function (repository) {
                state.checked[repository.repositoryKey] =
                    repository.repositoryKey === message.seed.repositoryKey;
            });
            state.baseRefOverrides[message.seed.repositoryKey] = message.seed.baseRef;
        }
        var checked = checkedRepositories(state);
        if (!checked.some(function (repository) {
            return repository.repositoryKey === state.primaryRepositoryKey;
        })) {
            state.primaryRepositoryKey = checked.length
                ? checked[0].repositoryKey : '';
        }
        schedulePreview(message.projectId, 0);
        renderForm(message.projectId);
        return true;
    }

    function schedulePreview(projectId, debounceMs) {
        var state = getState(projectId);
        if (!state || !state.open) {
            return;
        }
        if (state.previewTimer) {
            clearTimeout(state.previewTimer);
        }
        state.previewDirty = true;
        state.previewTimer = setTimeout(function () {
            state.previewTimer = 0;
            sendPreviewRequest(projectId);
        }, debounceMs === undefined ? PREVIEW_DEBOUNCE_MS : debounceMs);
        // Never rebuild the form on a keystroke: innerHTML replacement
        // destroys the focused input mid-typing. Patch only the actions row.
        syncActionsDom(projectId);
    }

    function sendPreviewRequest(projectId) {
        var state = getState(projectId);
        if (!state || !state.open) {
            return;
        }
        var requestId = nextRequestId('group-preview');
        state.previewRequestId = requestId;
        window.vscode.postMessage({
            type: 'preview-worktree-group',
            version: 1,
            requestId: requestId,
            projectId: projectId,
            displayName: state.name,
            ...(state.derive ? { sourceGroupId: state.derive.sourceGroupId } : {}),
            ...(state.addRepo ? { targetGroupId: state.addRepo.groupId } : {}),
            selections: checkedRepositories(state).map(function (repository) {
                var override = state.baseRefOverrides[repository.repositoryKey];
                return override
                    ? { repositoryKey: repository.repositoryKey, baseRef: override }
                    : { repositoryKey: repository.repositoryKey };
            }),
        });
    }

    function applyPreview(message) {
        if (!message || message.type !== 'worktree-group-preview'
            || message.version !== 1 || typeof message.requestId !== 'string'
            || typeof message.previewId !== 'string'
            || typeof message.projectId !== 'string'
            || !Array.isArray(message.members)) {
            return false;
        }
        var state = statesByProject.get(message.projectId || '');
        // Stale responses must never overwrite a newer form state (PRD §6.1
        // preview engineering contract).
        if (!state || !state.open || message.requestId !== state.previewRequestId) {
            return true;
        }
        state.preview = {
            slug: typeof message.slug === 'string' ? message.slug : '',
            formError: message.formError === 'invalid-task' ? 'invalid-task' : '',
            members: message.members,
        };
        state.previewId = message.previewId;
        state.previewDirty = false;
        renderForm(message.projectId);
        return true;
    }

    function previewMemberFor(state, repositoryKey) {
        if (!state.preview) {
            return null;
        }
        for (var index = 0; index < state.preview.members.length; index++) {
            if (state.preview.members[index].repositoryKey === repositoryKey) {
                return state.preview.members[index];
            }
        }
        return null;
    }

    function availableMembers(state) {
        return checkedRepositories(state).filter(function (repository) {
            var member = previewMemberFor(state, repository.repositoryKey);
            return member && member.preflight === 'ok';
        });
    }

    function hasPreflightFailures(state) {
        return checkedRepositories(state).some(function (repository) {
            var member = previewMemberFor(state, repository.repositoryKey);
            return member && member.preflight !== 'ok';
        });
    }

    function confirmForm(projectId, availableOnly) {
        var state = getState(projectId);
        if (!state || !state.open || state.confirming || state.previewDirty
            || !state.preview || state.preview.formError || !state.previewId) {
            return;
        }
        var selected = availableOnly
            ? availableMembers(state)
            : checkedRepositories(state);
        if (!selected.length) {
            return;
        }
        if (!availableOnly && hasPreflightFailures(state)) {
            return;
        }
        var members = [];
        for (var index = 0; index < selected.length; index++) {
            var repository = selected[index];
            var preview = previewMemberFor(state, repository.repositoryKey);
            if (!preview || preview.preflight !== 'ok') {
                return;
            }
            members.push({
                repositoryKey: repository.repositoryKey,
                baseRef: preview.baseRef,
                branchName: preview.branchName,
                worktreePath: preview.worktreePath,
                // The host re-reads the configured command per repository;
                // the webview only carries the user's toggle.
                setupEnabled: !state.setupDisabled[repository.repositoryKey],
            });
        }
        var primaryAvailable = members.some(function (member) {
            return member.repositoryKey === state.primaryRepositoryKey;
        });
        state.confirming = true;
        state.confirmRequestId = nextRequestId('group-confirm');
        state.formError = '';
        var message = {
            type: 'confirm-worktree-group',
            version: 1,
            requestId: state.confirmRequestId,
            projectId: projectId,
            previewId: state.previewId,
            displayName: state.name,
            members: members,
        };
        if (state.addRepo) {
            message.targetGroupId = state.addRepo.groupId;
        }
        if (primaryAvailable) {
            message.primaryRepositoryKey = state.primaryRepositoryKey;
        }
        window.vscode.postMessage(message);
        renderForm(projectId);
    }

    function applyCreationSettlement(message) {
        if (!message || message.type !== 'worktree-group-creation-settlement'
            || message.version !== 1 || typeof message.requestId !== 'string'
            || ['accepted', 'created', 'failed'].indexOf(message.status) < 0) {
            return false;
        }
        var entries = statesByProject.entries();
        for (var step = entries.next(); !step.done; step = entries.next()) {
            var projectId = step.value[0];
            var state = step.value[1];
            if (state.confirmRequestId !== message.requestId) {
                continue;
            }
            if (message.status === 'accepted') {
                return true;
            }
            state.confirming = false;
            if (message.status === 'created') {
                state.pendingFocusGroupId = typeof message.groupId === 'string'
                    ? message.groupId : '';
                // Confirmed: the next open starts from a clean form, and
                // focus lands on the new group row once it renders.
                announce(projectId, 'Worktree group created.');
                closeForm(projectId, false);
                // The group row usually rendered before this settlement
                // arrived; try the focus immediately instead of waiting
                // for a replacement that may never come.
                reconcileDom();
            } else {
                state.formError = typeof message.errorCode === 'string'
                    ? message.errorCode : 'unexpected-error';
                announce(projectId, describeFormError(state.formError));
                renderForm(projectId);
                if (state.formError === 'preview-stale') {
                    // Recompute immediately so the refreshed preview shows
                    // the configuration that rejected the old confirm.
                    schedulePreview(projectId, 0);
                }
            }
            return true;
        }
        return true;
    }

    function submitMemberRequest(projectId, button, type) {
        var groupId = button.getAttribute('data-group-id');
        var memberId = button.getAttribute('data-member-id');
        if (!groupId || !memberId || button.disabled) {
            return;
        }
        var requestId = nextRequestId('group-member');
        button.disabled = true;
        button.setAttribute('aria-disabled', 'true');
        var state = ensureState(projectId);
        state.pendingMemberRequests[requestId] = {
            button: button, groupId: groupId, memberId: memberId,
        };
        window.vscode.postMessage({
            type: type,
            version: 1,
            requestId: requestId,
            projectId: projectId,
            groupId: groupId,
            memberId: memberId,
        });
    }

    function applyMemberSettlement(message) {
        if (!message || message.type !== 'worktree-group-member-settlement'
            || message.version !== 1 || typeof message.requestId !== 'string'
            || ['accepted', 'settled', 'failed'].indexOf(message.status) < 0) {
            return false;
        }
        var entries = statesByProject.entries();
        for (var step = entries.next(); !step.done; step = entries.next()) {
            var pending = step.value[1].pendingMemberRequests[message.requestId];
            if (!pending) {
                continue;
            }
            if (message.status === 'accepted') {
                return true;
            }
            delete step.value[1].pendingMemberRequests[message.requestId];
            if (pending.button && pending.button.isConnected) {
                pending.button.disabled = false;
                pending.button.removeAttribute('aria-disabled');
            }
            announce(step.value[0], message.status === 'settled'
                ? 'Member worktree ready.'
                : 'Member action failed'
                    + (typeof message.errorCode === 'string'
                        ? ': ' + describePreflight(message.errorCode) : '') + '.');
            return true;
        }
        return true;
    }

    function describePreflight(code) {
        switch (code) {
            case 'branch-conflict': return 'branch name already exists';
            case 'path-conflict': return 'path already exists';
            case 'repository-has-no-commits': return 'repository has no commits yet';
            case 'base-ref-unavailable': return 'base ref unavailable';
            case 'allocation-exhausted': return 'no free branch/path suffix';
            case 'repository-unavailable': return 'repository unavailable';
            case 'store-full': return 'too many dismissed worktrees pending cleanup; remove them from disk first';
            default: return code || 'unavailable';
        }
    }

    // PRD §8: 人话错误，不显示裸错误码.
    function describeFormError(code) {
        switch (code) {
            case 'invalid-task': return 'Enter a group name.';
            case 'invalid-members': return 'The member set is no longer valid; close and reopen the form.';
            case 'preview-stale': return 'The setup configuration changed; the preview has been refreshed — review and confirm again.';
            case 'workspace-unavailable': return 'The workspace is unavailable.';
            case 'manifest-unavailable': return 'The workspace changed during creation; try again.';
            case 'store-full': return 'Too many worktree groups; remove some first.';
            default: return 'Creation failed: ' + (code || 'unexpected error');
        }
    }

    function announce(projectId, text) {
        var projectDiv = getCurrentWorkspaceDiv
            ? getCurrentWorkspaceDiv(projectId) : null;
        var liveRegion = projectDiv
            && projectDiv.querySelector('[data-ai-session-live-region]');
        if (liveRegion) {
            liveRegion.textContent = text;
        }
    }

    // The single-instance rule must be visible: while the form is open the
    // new-worktree button is disabled (PRD §6.1).
    function syncCreateButton(projectId, formOpen) {
        var projectDiv = getCurrentWorkspaceDiv
            ? getCurrentWorkspaceDiv(projectId) : null;
        var button = projectDiv
            && projectDiv.querySelector('[data-action="create-isolated-session"]');
        if (button) {
            button.disabled = !!formOpen;
        }
    }

    function memberRowHtml(state, repository, index) {
        var key = repository.repositoryKey;
        var checked = !!state.checked[key];
        var preview = previewMemberFor(state, key);
        var seen = {};
        var refs = [];
        [repository.defaultBaseRef]
            .concat((repository.localBranches || []).map(function (branch) {
                return 'refs/heads/' + branch;
            }))
            .forEach(function (ref) {
                if (ref && !seen[ref]) {
                    seen[ref] = true;
                    refs.push(ref);
                }
            });
        var multiRepo = state.repositories.length > 1;
        var preflight = preview && preview.preflight !== 'ok'
            ? '<span class="ai-session-group-form-preflight" role="alert" id="group-form-preflight-'
                + index + '">' + escapeHtml(describePreflight(preview.preflight.code)) + '</span>'
            : '';
        var preflightId = preflight ? 'group-form-preflight-' + index : '';
        var selectedRef = state.baseRefOverrides[key] || repository.defaultBaseRef;
        var baseHtml = baseComboboxHtml(
            state, key, repository, refs, selectedRef, checked, preflightId);
        var plan = preview && preview.preflight === 'ok'
            ? '<span class="ai-session-group-form-plan">'
                + escapeHtml(preview.worktreePath) + ' \u2190 '
                + escapeHtml(preview.branchName) + '</span>'
            : '';
        // Display the setup command from the authoritative preview (config
        // is re-resolved per preview); the bootstrap value is only a
        // pre-first-preview placeholder. An empty array is authoritative
        // too: a config change to empty must not resurrect the old command.
        var setupCommand = preview && Array.isArray(preview.setupCommand)
            ? preview.setupCommand
            : repository.setupCommand;
        var setup = setupCommand && setupCommand.length
            ? '<label class="ai-session-group-form-setup">'
                + '<input type="checkbox" data-group-form-setup="' + escapeHtml(key) + '"'
                + (state.setupDisabled[key] ? '' : ' checked') + (checked ? '' : ' disabled') + '>'
                + '<span>' + (state.setupDisabled[key]
                    ? 'setup disabled for this repository'
                    : 'setup: ' + escapeHtml(setupCommand.join(' '))) + '</span></label>'
            : '<span class="ai-session-group-form-setup ai-session-group-form-setup-none">no setup configured</span>';
        var primary = checked
            ? '<label class="ai-session-group-form-primary" data-tooltip="Primary worktree for new sessions">'
                + '<input type="radio" name="group-form-primary" data-group-form-primary="'
                + escapeHtml(key) + '"'
                + (state.primaryRepositoryKey === key ? ' checked' : '') + '>primary</label>'
            : '';
        return '<div class="ai-session-group-form-member"'
            + ' data-group-form-member="' + escapeHtml(key) + '"'
            + (checked ? '' : ' data-unchecked') + '>'
            + (multiRepo
                ? '<label class="ai-session-group-form-check">'
                    + '<input type="checkbox" data-group-form-check="' + escapeHtml(key) + '"'
                    + (checked ? ' checked' : '')
                    + (preflightId ? ' aria-describedby="' + preflightId + '"' : '') + '>'
                    + '<span>' + escapeHtml(repository.label) + '</span></label>'
                : '<span class="ai-session-group-form-check ai-session-group-form-single">'
                    + escapeHtml(repository.label) + '</span>')
            + baseHtml
            + primary + setup + plan + preflight
            + '</div>';
    }

    // Searchable base-branch combobox (PRD §6.1): a text input filters the
    // local branch list; ArrowUp/Down + Enter choose, Esc closes.
    function baseComboboxHtml(state, key, repository, refs, selectedRef, checked, preflightId) {
        var label = repository.label;
        var open = state.baseDropdown && state.baseDropdown.repositoryKey === key;
        if (!open) {
            return '<button type="button" class="ai-session-group-form-base"'
                + ' data-group-form-base="' + escapeHtml(key) + '"'
                + ' role="combobox" aria-expanded="false"'
                + ' aria-label="Base branch for ' + escapeHtml(label) + '"'
                + (preflightId
                    ? ' aria-invalid="true" aria-errormessage="' + preflightId + '"'
                        + ' aria-describedby="' + preflightId + '"'
                    : '')
                + (checked ? '' : ' disabled') + '>'
                + escapeHtml(shortRefName(selectedRef)) + ' \u25be</button>';
        }
        var filter = state.baseDropdown.filter || '';
        var filtered = refs.filter(function (ref) {
            return shortRefName(ref).toLowerCase().indexOf(filter.toLowerCase()) >= 0;
        });
        var activeIndex = Math.min(state.baseDropdown.activeIndex, filtered.length - 1);
        var optionsHtml = filtered.map(function (ref, position) {
            return '<li role="option" id="group-form-base-option-' + position + '"'
                + ' data-group-form-base-option="' + escapeHtml(ref) + '"'
                + ' aria-selected="' + (ref === selectedRef) + '"'
                + (position === activeIndex ? ' data-active' : '') + '>'
                + escapeHtml(shortRefName(ref)) + '</li>';
        }).join('');
        return '<span class="ai-session-group-form-base-combobox">'
            + '<input type="text" class="ai-session-group-form-base-filter"'
            + ' data-group-form-base-filter="' + escapeHtml(key) + '"'
            + ' role="combobox" aria-expanded="true"'
            + ' aria-controls="group-form-base-listbox"'
            + (preflightId
                ? ' aria-invalid="true" aria-errormessage="' + preflightId + '"'
                    + ' aria-describedby="' + preflightId + '"'
                : '')
            + (activeIndex >= 0
                ? ' aria-activedescendant="group-form-base-option-' + activeIndex + '"'
                : '')
            + ' aria-label="Search base branch for ' + escapeHtml(label) + '"'
            + ' value="' + escapeHtml(filter) + '">'
            + '<ul role="listbox" id="group-form-base-listbox"'
            + ' class="ai-session-group-form-base-listbox">'
            + (optionsHtml || '<li class="ai-session-group-form-base-empty">no matching branch</li>')
            + '</ul></span>';
    }

    function formSlot(projectId) {
        var projectDiv = getCurrentWorkspaceDiv
            ? getCurrentWorkspaceDiv(projectId) : null;
        return projectDiv && projectDiv.querySelector('[data-worktree-group-form-slot]');
    }

    function actionsHtml(state) {
        var checked = checkedRepositories(state);
        var failures = hasPreflightFailures(state);
        var availableCount = availableMembers(state).length;
        var hasName = !!state.name.trim();
        var canConfirm = !state.confirming && !state.previewDirty
            && !!state.preview && !state.preview.formError
            && checked.length > 0 && !failures && hasName;
        var canConfirmAvailable = !state.confirming && !state.previewDirty
            && !!state.preview && failures && availableCount > 0 && hasName;
        var availableButton = failures
            ? '<button type="button" class="ai-session-group-form-available"'
                + ' data-group-form-action="confirm-available"'
                + (canConfirmAvailable ? '' : ' disabled')
                + '>Create only the available ' + availableCount + '/'
                + checked.length + ' members</button>'
            : '';
        return '<button type="button" class="ai-session-group-form-confirm"'
            + ' data-group-form-action="confirm"' + (canConfirm ? '' : ' disabled')
            + '>Create worktree group</button>'
            + availableButton
            + (state.previewDirty && hasName
                ? '<span class="ai-session-group-form-pending">previewing\u2026</span>'
                : '');
    }

    // Light patch for keystroke-driven state changes: the confirm button
    // and the pending indicator follow the dirty flag without touching the
    // rest of the form (a full rebuild would drop input focus).
    function syncActionsDom(projectId) {
        var state = getState(projectId);
        var slot = formSlot(projectId);
        var actions = slot && slot.querySelector('.ai-session-group-form-actions');
        if (!state || !state.open || !actions) {
            return;
        }
        actions.innerHTML = actionsHtml(state);
    }

    function captureFormFocus(slot) {
        var active = document.activeElement;
        if (!active || !slot.contains(active)) {
            return null;
        }
        var attributes = [
            'data-group-form-name',
            'data-group-form-base-filter',
            'data-group-form-base',
            'data-group-form-check',
            'data-group-form-setup',
            'data-group-form-primary',
            'data-group-form-action',
        ];
        for (var index = 0; index < attributes.length; index++) {
            var attribute = attributes[index];
            var value = active.getAttribute && active.getAttribute(attribute);
            if (value !== null && value !== undefined) {
                var isTextInput = attribute === 'data-group-form-name'
                    || attribute === 'data-group-form-base-filter';
                return {
                    selector: '[' + attribute + (value ? '="' + CSS.escape(value) + '"' : '') + ']',
                    selectionStart: isTextInput
                        ? active.selectionStart : null,
                    selectionEnd: isTextInput
                        ? active.selectionEnd : null,
                };
            }
        }
        return null;
    }

    function restoreFormFocus(slot, capture) {
        if (!capture) {
            return;
        }
        var element = slot.querySelector(capture.selector);
        if (!element) {
            return;
        }
        element.focus();
        if (capture.selectionStart !== null && element.setSelectionRange) {
            element.setSelectionRange(capture.selectionStart, capture.selectionEnd);
        }
    }

    // Called by the authoritative update paths while the old DOM is still
    // mounted (focus is global, so at most one open form holds it).
    function captureFocus() {
        var entries = statesByProject.entries();
        for (var step = entries.next(); !step.done; step = entries.next()) {
            var projectId = step.value[0];
            var state = step.value[1];
            if (!state.open) {
                continue;
            }
            var slot = formSlot(projectId);
            var focus = slot && captureFormFocus(slot);
            if (focus) {
                replacementFocusByProject.set(projectId, focus);
            }
        }
    }

    function renderForm(projectId) {
        var state = getState(projectId);
        var slot = formSlot(projectId);
        if (!slot) {
            return;
        }
        if (!state || !state.open) {
            replacementFocusByProject.delete(projectId);
            slot.hidden = true;
            slot.innerHTML = '';
            syncCreateButton(projectId, false);
            return;
        }
        var focus = replacementFocusByProject.get(projectId) || null;
        replacementFocusByProject.delete(projectId);
        if (!focus) {
            focus = captureFormFocus(slot);
        }
        var membersHtml = state.bootstrapping
            ? '<div class="ai-session-group-form-loading">Loading repositories\u2026</div>'
            : (state.repositories.length
                ? state.repositories.map(function (repository, index) {
                    return memberRowHtml(state, repository, index);
                }).join('')
                : '<div class="ai-session-group-form-loading">No git repository found in this workspace.</div>');
        var selectionTools = state.repositories.length > 1
            ? '<div class="ai-session-group-form-tools">'
                + '<button type="button" data-group-form-action="select-all">Select all</button>'
                + '<button type="button" data-group-form-action="select-none">Clear</button>'
                + '</div>'
            : '';
        slot.innerHTML = '<div class="ai-session-group-form" data-worktree-group-form'
            + ' data-project-id="' + escapeHtml(projectId) + '">'
            + '<div class="ai-session-group-form-title">'
            + (state.addRepo
                ? 'Add repositories to ' + escapeHtml(state.addRepo.displayName)
                : state.derive
                    ? 'Derive from ' + escapeHtml(state.derive.sourceName || 'group')
                    : 'New worktree group')
            + '</div>'
            + (state.derive && state.derive.skipped.length
                ? '<div class="ai-session-group-form-derive-skipped" role="note">'
                    + 'Skipped: ' + state.derive.skipped.map(function (entry) {
                        return escapeHtml(entry.repositoryLabel)
                            + ' (' + escapeHtml(entry.reason) + ')';
                    }).join('; ')
                    + '</div>'
                : '')
            + '<div class="ai-session-group-form-header">'
            + '<input type="text" class="ai-session-group-form-name"'
            + ' data-group-form-name placeholder="Worktree group name"'
            + ' aria-label="Worktree group name" value="' + escapeHtml(state.name) + '"'
            // Add-repo mode locks the group name (PRD §6.3: slug 锁定).
            + (state.addRepo ? ' readonly aria-readonly="true"' : '')
            + ((state.preview && state.preview.formError === 'invalid-task') || state.formError
                ? ' aria-invalid="true" aria-describedby="group-form-name-error group-form-error"'
                : '') + '>'
            + '<button type="button" class="ai-session-group-form-close"'
            + ' data-group-form-action="close" aria-label="Close creation form"'
            + ' data-tooltip="Close (Esc)">\u00d7</button>'
            + '</div>'
            + (state.preview && state.preview.formError === 'invalid-task'
                ? '<div class="ai-session-group-form-error" id="group-form-name-error" role="alert">Enter a group name.</div>'
                : '')
            + (state.formError
                ? '<div class="ai-session-group-form-error" id="group-form-error" role="alert">'
                    + escapeHtml(describeFormError(state.formError)) + '</div>'
                : '')
            + selectionTools
            + '<div class="ai-session-group-form-members">' + membersHtml + '</div>'
            + '<div class="ai-session-group-form-actions">' + actionsHtml(state) + '</div>'
            + '</div>';
        slot.hidden = false;
        restoreFormFocus(slot, focus);
        syncCreateButton(projectId, true);
    }

    function focusNameInput(projectId) {
        var projectDiv = getCurrentWorkspaceDiv
            ? getCurrentWorkspaceDiv(projectId) : null;
        var input = projectDiv && projectDiv.querySelector('[data-group-form-name]');
        if (input) {
            input.focus();
        }
    }

    // Re-render after authoritative workspace updates replaced the DOM, and
    // move focus to a freshly created group row exactly once.
    function reconcileDom() {
        var entries = statesByProject.entries();
        for (var step = entries.next(); !step.done; step = entries.next()) {
            var projectId = step.value[0];
            var state = step.value[1];
            if (state.open) {
                renderForm(projectId);
            }
            if (state.pendingFocusGroupId) {
                var projectDiv = getCurrentWorkspaceDiv
                    ? getCurrentWorkspaceDiv(projectId) : null;
                var header = projectDiv && projectDiv.querySelector(
                    '.ai-session-worktree-task-group[data-group-id="'
                    + CSS.escape(state.pendingFocusGroupId)
                    + '"] .ai-session-worktree-header');
                if (header) {
                    state.pendingFocusGroupId = '';
                    header.focus();
                }
            }
        }
    }

    function onClick(target, projectDiv, projectId) {
        var state = getState(projectId);
        var baseToggle = target.closest
            ? target.closest('[data-group-form-base]') : null;
        if (baseToggle) {
            if (state) {
                var toggleKey = baseToggle.getAttribute('data-group-form-base');
                state.baseDropdown = state.baseDropdown
                    && state.baseDropdown.repositoryKey === toggleKey
                    ? null
                    : { repositoryKey: toggleKey, filter: '', activeIndex: 0 };
                renderForm(projectId);
                if (state.baseDropdown) {
                    var filterInput = formSlot(projectId)
                        && formSlot(projectId).querySelector('[data-group-form-base-filter]');
                    if (filterInput) {
                        filterInput.focus();
                    }
                }
            }
            return true;
        }
        var baseOption = target.closest
            ? target.closest('[data-group-form-base-option]') : null;
        if (baseOption) {
            if (state && state.baseDropdown) {
                state.baseRefOverrides[state.baseDropdown.repositoryKey] =
                    baseOption.getAttribute('data-group-form-base-option');
                state.baseDropdown = null;
                schedulePreview(projectId, 0);
                renderForm(projectId);
            }
            return true;
        }
        if (state && state.baseDropdown
            && !(target.closest && target.closest('.ai-session-group-form-base-combobox'))) {
            state.baseDropdown = null;
            renderForm(projectId);
            // Fall through: the click may still hit another form control.
        }
        var formAction = target.closest
            ? target.closest('[data-group-form-action]') : null;
        if (formAction) {
            var action = formAction.getAttribute('data-group-form-action');
            if (action === 'close') {
                closeForm(projectId, true);
            } else if (action === 'confirm') {
                confirmForm(projectId, false);
            } else if (action === 'confirm-available') {
                confirmForm(projectId, true);
            } else if (action === 'select-all' || action === 'select-none') {
                if (state) {
                    var checkAll = action === 'select-all';
                    state.repositories.forEach(function (repository) {
                        state.checked[repository.repositoryKey] = checkAll;
                    });
                    var remaining = checkedRepositories(state);
                    if (!remaining.some(function (repository) {
                        return repository.repositoryKey === state.primaryRepositoryKey;
                    })) {
                        state.primaryRepositoryKey = remaining.length
                            ? remaining[0].repositoryKey : '';
                    }
                    schedulePreview(projectId, 0);
                    // Bulk selection changes every checkbox: the light
                    // actions patch is not enough here.
                    renderForm(projectId);
                }
            }
            return true;
        }
        var memberAction = target.closest
            ? target.closest('[data-action="retry-group-member"],'
                + '[data-action="dismiss-group-member"]') : null;
        if (memberAction) {
            submitMemberRequest(
                projectId, memberAction,
                memberAction.getAttribute('data-action') === 'retry-group-member'
                    ? 'retry-worktree-group-member'
                    : 'dismiss-worktree-group-member');
            return true;
        }
        return false;
    }

    function onInput(target) {
        var filterInput = target.closest
            ? target.closest('[data-group-form-base-filter]') : null;
        if (filterInput) {
            var filterForm = filterInput.closest('[data-worktree-group-form]');
            var filterProjectId = filterForm && filterForm.getAttribute('data-project-id');
            var filterState = filterProjectId && getState(filterProjectId);
            if (filterState && filterState.baseDropdown) {
                filterState.baseDropdown.filter = filterInput.value;
                filterState.baseDropdown.activeIndex = 0;
                renderForm(filterProjectId);
            }
            return true;
        }
        var nameInput = target.closest
            ? target.closest('[data-group-form-name]') : null;
        if (!nameInput) {
            return false;
        }
        var form = nameInput.closest('[data-worktree-group-form]');
        var projectId = form && form.getAttribute('data-project-id');
        var state = projectId && getState(projectId);
        if (!state) {
            return true;
        }
        state.name = nameInput.value;
        schedulePreview(projectId);
        return true;
    }

    function onChange(target) {
        var form = target.closest
            ? target.closest('[data-worktree-group-form]') : null;
        if (!form) {
            return false;
        }
        var projectId = form.getAttribute('data-project-id');
        var state = projectId && getState(projectId);
        if (!state) {
            return true;
        }
        var check = target.closest('[data-group-form-check]');
        if (check) {
            var key = check.getAttribute('data-group-form-check');
            state.checked[key] = !!check.checked;
            if (state.checked[key] && !state.primaryRepositoryKey) {
                state.primaryRepositoryKey = key;
            }
            if (!state.checked[key] && state.primaryRepositoryKey === key) {
                var remaining = checkedRepositories(state);
                state.primaryRepositoryKey = remaining.length
                    ? remaining[0].repositoryKey : '';
            }
            schedulePreview(projectId, 0);
            return true;
        }
        var setup = target.closest('[data-group-form-setup]');
        if (setup) {
            state.setupDisabled[setup.getAttribute('data-group-form-setup')] =
                !setup.checked;
            renderForm(projectId);
            return true;
        }
        var primary = target.closest('[data-group-form-primary]');
        if (primary) {
            state.primaryRepositoryKey =
                primary.getAttribute('data-group-form-primary');
            renderForm(projectId);
            return true;
        }
        return false;
    }

    function onKeydown(event) {
        var form = event.target && event.target.closest
            ? event.target.closest('[data-worktree-group-form]') : null;
        if (!form) {
            return false;
        }
        var projectId = form.getAttribute('data-project-id');
        var state = projectId && getState(projectId);
        if (state && state.baseDropdown
            && event.target.hasAttribute('data-group-form-base-filter')) {
            var dropdown = state.baseDropdown;
            if (event.key === 'Escape') {
                state.baseDropdown = null;
                renderForm(projectId);
                return true;
            }
            if (event.key === 'ArrowDown' || event.key === 'ArrowUp'
                || event.key === 'Enter') {
                var repository = state.repositories.find(function (candidate) {
                    return candidate.repositoryKey === dropdown.repositoryKey;
                });
                var refs = repository
                    ? [repository.defaultBaseRef]
                        .concat((repository.localBranches || []).map(function (branch) {
                            return 'refs/heads/' + branch;
                        }))
                        .filter(function (ref, position, all) {
                            return ref && all.indexOf(ref) === position;
                        })
                    : [];
                var filtered = refs.filter(function (ref) {
                    return shortRefName(ref).toLowerCase()
                        .indexOf((dropdown.filter || '').toLowerCase()) >= 0;
                });
                if (event.key === 'Enter') {
                    var chosen = filtered[Math.min(dropdown.activeIndex, filtered.length - 1)];
                    if (chosen) {
                        state.baseRefOverrides[dropdown.repositoryKey] = chosen;
                    }
                    state.baseDropdown = null;
                    schedulePreview(projectId, 0);
                    renderForm(projectId);
                } else {
                    var delta = event.key === 'ArrowDown' ? 1 : -1;
                    dropdown.activeIndex = Math.max(0, Math.min(
                        filtered.length - 1, dropdown.activeIndex + delta));
                    renderForm(projectId);
                }
                event.preventDefault();
                return true;
            }
        }
        if (event.key === 'Escape') {
            closeForm(projectId, true);
            return true;
        }
        if (event.key === 'Enter' && event.target.matches('[data-group-form-name]')) {
            // Single-repo degradation keeps the old one-shot flow: Enter
            // submits when the form is confirmable (PRD §7).
            confirmForm(projectId, false);
            return true;
        }
        return false;
    }

    document.addEventListener('input', function (event) {
        onInput(event.target);
    });
    document.addEventListener('change', function (event) {
        onChange(event.target);
    });
    document.addEventListener('keydown', function (event) {
        onKeydown(event);
    });

    return {
        openForm: openForm,
        closeForm: closeForm,
        isOpen: function (projectId) {
            var state = getState(projectId);
            return !!state && state.open;
        },
        onClick: onClick,
        reconcileDom: reconcileDom,
        captureFocus: captureFocus,
        applyFormState: applyFormState,
        applyPreview: applyPreview,
        applyCreationSettlement: applyCreationSettlement,
        applyMemberSettlement: applyMemberSettlement,
    };
}

/* src/webview/webviewProjectAiSessionControlsScripts.js */
function initProjectAiSessionControls(options) {
    'use strict';

    options = options || {};
    var getAiSessionsUpdate = options.getAiSessionsUpdate;
    var getAiSessionPresentationStateStore = options.getAiSessionPresentationStateStore;
    var updateStickyGroupHeaderOffset = options.updateStickyGroupHeaderOffset;

    // Native title tooltips take over a second to appear; icon-only buttons
    // get a shared fast tooltip instead (150ms), driven by data-tooltip.
    var fastTooltip = null;
    var fastTooltipTimer = null;
    var fastTooltipTarget = null;

    function hideFastTooltip() {
        if (fastTooltipTimer) {
            clearTimeout(fastTooltipTimer);
            fastTooltipTimer = null;
        }
        fastTooltipTarget = null;
        if (fastTooltip) {
            fastTooltip.remove();
            fastTooltip = null;
        }
    }

    function showFastTooltip(target) {
        var label = target.getAttribute('data-tooltip');
        if (!label || !target.isConnected) return;
        hideFastTooltip();
        fastTooltipTarget = target;
        fastTooltipTimer = setTimeout(() => {
            if (fastTooltipTarget !== target || !target.isConnected) return;
            fastTooltip = document.createElement('div');
            fastTooltip.className = 'ai-session-fast-tooltip';
            fastTooltip.setAttribute('role', 'tooltip');
            fastTooltip.textContent = label;
            document.body.appendChild(fastTooltip);
            var rect = target.getBoundingClientRect();
            var tipRect = fastTooltip.getBoundingClientRect();
            var left = Math.max(4, Math.min(
                rect.right - tipRect.width,
                window.innerWidth - tipRect.width - 4
            ));
            var top = rect.top - tipRect.height - 5;
            if (top < 4) {
                top = rect.bottom + 5;
            }
            fastTooltip.style.left = left + 'px';
            fastTooltip.style.top = top + 'px';
        }, 150);
    }

    document.addEventListener('mouseover', event => {
        var target = event.target && event.target.closest
            ? event.target.closest('[data-tooltip]') : null;
        if (target === fastTooltipTarget) return;
        hideFastTooltip();
        if (target) showFastTooltip(target);
    });
    document.addEventListener('pointerdown', hideFastTooltip, true);
    document.addEventListener('focusin', event => {
        var target = event.target && event.target.closest
            ? event.target.closest('[data-tooltip]') : null;
        hideFastTooltip();
        if (target) showFastTooltip(target);
    });
    document.addEventListener('focusout', hideFastTooltip);

    var batchAiSessionState = {
        projectId: null,
        selectedItems: new Map(),
        pending: false,
        requestId: null,
    };
    var nextAiSessionBatchArchiveRequestId = 0;
    var nextAiSessionProviderSelectionRequestId = 0;
    var nextAiSessionAttentionAcknowledgementRequestId = 0;
    var nextIsolatedSessionRequestId = 0;
    var pendingIsolatedSessionRequests = new Map();
    var nextManagedWorktreeRemovalRequestId = 0;
    var pendingManagedWorktreeRemovalRequests = new Map();
    var nextMergeWorktreeGroupsRequestId = 0;
    var pendingMergeWorktreeGroupsRequests = new Map();
    // A per-document nonce keeps merge request ids unique across webview
    // reloads (review R6): the host replay cache outlives the document, so
    // without it a reloaded document's `worktree-merge-1` would correlate
    // with the previous document's cached settlement and never execute.
    // Same pattern as rename/adopt/deletion.
    var worktreeMergeDocumentNonce = Math.random().toString(36).slice(2, 10);
    var nextSetGroupPrimaryRequestId = 0;
    var pendingSetGroupPrimaryRequests = new Map();
    var worktreeGroupForm = null;

    function setWorktreeGroupForm(form) {
        worktreeGroupForm = form;
    }
    var pendingAiSessionAttentionAcknowledgements = new Map();
    var pendingAiSessionProviderSelectionProjectId = null;
    var pendingAiSessionProviderSelectionRequestId = null;
    var pendingAiSessionProviderSelectionProviders = [];

    function getAiSessionBatchItemKey(provider, sessionId) {
        return JSON.stringify([provider, sessionId]);
    }

    function enter(projectId) {
        if (batchAiSessionState.pending)
            return;
        batchAiSessionState.projectId = projectId;
        batchAiSessionState.selectedItems = new Map();
        batchAiSessionState.pending = false;
        batchAiSessionState.requestId = null;
    }

    function toggle(provider, sessionId, active) {
        if (!isAiSessionProvider(provider) || !sessionId || active || batchAiSessionState.pending)
            return;
        var key = getAiSessionBatchItemKey(provider, sessionId);
        if (batchAiSessionState.selectedItems.has(key))
            batchAiSessionState.selectedItems.delete(key);
        else
            batchAiSessionState.selectedItems.set(key, { provider, sessionId });
    }

    function selectUnpinned(sessions) {
        if (batchAiSessionState.pending)
            return;
        sessions
            .filter(session => isAiSessionProvider(session.provider)
                && session.id && !session.pinned && !session.active)
            .forEach(session => {
                var item = { provider: session.provider, sessionId: session.id };
                batchAiSessionState.selectedItems.set(
                    getAiSessionBatchItemKey(item.provider, item.sessionId),
                    item
                );
            });
    }

    function clear() {
        if (!batchAiSessionState.pending)
            batchAiSessionState.selectedItems.clear();
    }

    function reconcile(projectId, remainingItems) {
        if (projectId !== batchAiSessionState.projectId) {
            exit();
            return;
        }
        let selectedItems = batchAiSessionState.selectedItems;
        batchAiSessionState.selectedItems = new Map(
            remainingItems
                .filter(item => item && isAiSessionProvider(item.provider) && item.sessionId)
                .map(item => {
                    var key = getAiSessionBatchItemKey(item.provider, item.sessionId);
                    return [key, selectedItems.get(key)];
                })
                .filter(entry => entry[1])
        );
    }

    function reconcileVisible(projectDiv) {
        if (!projectDiv)
            return;
        var projectId = projectDiv.getAttribute('data-id');
        var remainingItems = Array.from(
            projectDiv.querySelectorAll('.ai-session-history-panel .codex-session-row[data-session-id]')
        )
            .filter(row => isAiSessionProvider(row.getAttribute('data-session-provider') || 'codex')
                && row.getAttribute('data-session-id')
                && !row.hasAttribute('data-session-active'))
            .map(row => ({
                provider: row.getAttribute('data-session-provider') || 'codex',
                sessionId: row.getAttribute('data-session-id'),
            }));
        reconcile(projectId, remainingItems);
    }

    function submit() {
        if (batchAiSessionState.pending || !batchAiSessionState.selectedItems.size)
            return;
        nextAiSessionBatchArchiveRequestId = nextAiSessionBatchArchiveRequestId >= Number.MAX_SAFE_INTEGER
            ? 1
            : nextAiSessionBatchArchiveRequestId + 1;
        var requestId = nextAiSessionBatchArchiveRequestId;
        batchAiSessionState.pending = true;
        batchAiSessionState.requestId = requestId;
        window.vscode.postMessage({
            type: 'archive-ai-sessions',
            version: 1,
            requestId: requestId,
            projectId: batchAiSessionState.projectId,
            items: Array.from(batchAiSessionState.selectedItems.values()),
        });
    }

    function complete(message) {
        if (!message
            || message.type !== 'ai-session-batch-archive-completed'
            || message.version !== 1
            || !Number.isSafeInteger(message.requestId)
            || message.requestId < 1
            || typeof message.projectId !== 'string'
            || !['cancelled', 'rejected', 'finished'].includes(message.status)
            || !batchAiSessionState.pending
            || message.projectId !== batchAiSessionState.projectId
            || message.requestId !== batchAiSessionState.requestId) {
            return false;
        }
        if (message.status === 'finished') {
            exit();
            return true;
        }
        batchAiSessionState.pending = false;
        batchAiSessionState.requestId = null;
        return true;
    }

    function exit() {
        batchAiSessionState.projectId = null;
        batchAiSessionState.selectedItems = new Map();
        batchAiSessionState.pending = false;
        batchAiSessionState.requestId = null;
    }

    function snapshot() {
        return {
            projectId: batchAiSessionState.projectId,
            selectedItems: Array.from(batchAiSessionState.selectedItems.values()),
            pending: batchAiSessionState.pending,
        };
    }

    var batchAiSessionManager = {
        enter, toggle, selectUnpinned, clear, reconcile, reconcileVisible,
        submit, complete, exit, snapshot,
    };
    window.__agentPivotBatchAiSessions = batchAiSessionManager;

    function onTriggerAiSessionAction(target, projectId) {
        var projectDiv = target.closest('.project[data-id]');
        var managedWorktreeRemoveAction = target.closest(
            '[data-action="remove-managed-worktree"]'
        );
        if (managedWorktreeRemoveAction) {
            submitManagedWorktreeRemoval(
                projectId,
                managedWorktreeRemoveAction.closest(
                    '.ai-session-worktree-group[data-worktree-repository-key][data-worktree-path]'
                ),
                managedWorktreeRemoveAction
            );
            return true;
        }
        var isolatedRetryAction = target.closest(
            '[data-action="retry-isolated-session"][data-operation-id]'
        );
        if (isolatedRetryAction) {
            submitIsolatedSessionRequest(
                'retry-isolated-session', projectId,
                isolatedRetryAction.getAttribute('data-operation-id'), isolatedRetryAction
            );
            return true;
        }
        var isolatedDismissAction = target.closest(
            '[data-action="dismiss-isolated-session"][data-operation-id]'
        );
        if (isolatedDismissAction) {
            submitIsolatedSessionRequest(
                'dismiss-isolated-session', projectId,
                isolatedDismissAction.getAttribute('data-operation-id'), isolatedDismissAction
            );
            return true;
        }
        var isolatedCancelAction = target.closest(
            '[data-action="cancel-isolated-session"][data-operation-id]'
        );
        if (isolatedCancelAction) {
            submitIsolatedSessionRequest(
                'cancel-isolated-session', projectId,
                isolatedCancelAction.getAttribute('data-operation-id'), isolatedCancelAction
            );
            return true;
        }
        var worktreeCollapseAllAction = target.closest(
            '[data-action="toggle-all-ai-session-worktrees"]'
        );
        if (worktreeCollapseAllAction) {
            toggleAllAiSessionWorktrees(projectDiv);
            return true;
        }
        var worktreeMenuAction = target.closest('[data-action="ai-session-worktree-menu"]');
        if (worktreeMenuAction) {
            toggleAiSessionWorktreeMenu(worktreeMenuAction, projectId);
            return true;
        }
        var mergeGroupsAction = target.closest(
            '[data-action="merge-worktree-groups"][data-group-id]'
        );
        if (mergeGroupsAction) {
            submitMergeWorktreeGroups(
                projectId,
                mergeGroupsAction.getAttribute('data-group-id'),
                mergeGroupsAction);
            return true;
        }
        var setPrimaryAction = target.closest(
            '[data-action="set-group-primary"][data-group-id][data-member-id]'
        );
        if (setPrimaryAction) {
            submitSetGroupPrimaryRequest(projectId, setPrimaryAction);
            return true;
        }
        var viewConversationAction = target.closest(
            '[data-action="view-ai-session-conversation"]'
        );
        if (viewConversationAction) {
            var viewRow = viewConversationAction.closest('.codex-session-row[data-session-id]');
            if (viewRow) {
                window.vscode.postMessage({
                    type: 'open-active-ai-session-conversation',
                    version: 1,
                    projectId: projectId,
                    provider: viewRow.getAttribute('data-session-provider'),
                    sessionId: viewRow.getAttribute('data-session-id'),
                });
            }
            return true;
        }
        var worktreeToggle = target.closest('[data-action="toggle-ai-session-worktree"]');
        if (worktreeToggle) {
            setAiSessionWorktreeGroupExpanded(
                projectDiv,
                worktreeToggle.closest('.ai-session-worktree-group'),
                worktreeToggle.getAttribute('aria-expanded') !== 'true'
            );
            writeAiSessionWorktreeCollapseState(window.vscode, projectDiv);
            return true;
        }
        var memberDetailsToggle = target.closest('[data-action="toggle-group-member-details"]');
        if (memberDetailsToggle) {
            var memberDetailsSection = memberDetailsToggle.closest('.ai-session-worktree-group');
            if (memberDetailsSection
                && typeof setWorktreeGroupMemberDetailsExpanded === 'function') {
                setWorktreeGroupMemberDetailsExpanded(
                    memberDetailsSection,
                    memberDetailsToggle.getAttribute('aria-expanded') !== 'true'
                );
                writeAiSessionWorktreeCollapseState(window.vscode, projectDiv);
            }
            return true;
        }
        var memberRemoveAction = target.closest(
            '[data-action="preview-group-member-deletion"][data-group-id][data-member-id]'
        );
        if (memberRemoveAction) {
            startWorktreeGroupMemberDeletion(
                projectId,
                memberRemoveAction.getAttribute('data-group-id'),
                memberRemoveAction.getAttribute('data-member-id')
            );
            return true;
        }
        var deletionCancel = target.closest('[data-action="cancel-group-member-deletion"]');
        if (deletionCancel) {
            cancelWorktreeGroupDeletionCard(projectDiv);
            return true;
        }
        var deletionConfirm = target.closest('[data-action="confirm-group-member-deletion"]');
        if (deletionConfirm) {
            if (!deletionConfirm.disabled) {
                confirmWorktreeGroupMemberDeletion(
                    deletionConfirm.closest('.ai-session-worktree-deletion-card'));
            }
            return true;
        }
        var visibleOnlySwitch = target.closest('[data-action="preview-group-visible-deletion"]');
        if (visibleOnlySwitch) {
            var switchSection = visibleOnlySwitch.closest('.ai-session-worktree-group');
            var switchGroupId = switchSection && switchSection.getAttribute('data-group-id');
            if (switchGroupId) {
                startWorktreeGroupMemberDeletion(projectId, switchGroupId, '', {
                    mode: 'visible-only',
                });
            }
            return true;
        }
        var deletionRetry = target.closest(
            '[data-action="retry-group-deletion"][data-operation-id]'
        );
        if (deletionRetry) {
            submitWorktreeGroupDeletionOperation(deletionRetry, 'retry');
            return true;
        }
        var deletionAbandon = target.closest(
            '[data-action="abandon-group-deletion"][data-operation-id]'
        );
        if (deletionAbandon) {
            submitWorktreeGroupDeletionOperation(deletionAbandon, 'abandon');
            return true;
        }
        var claimDiscard = target.closest(
            '[data-action="discard-generation-claim"][data-claim-id]'
        );
        if (claimDiscard) {
            submitWorktreeGroupClaimDiscard(claimDiscard);
            return true;
        }
        var adoptCluster = target.closest('[data-action="adopt-worktree-cluster"]');
        if (adoptCluster) {
            startWorktreeAdopt(adoptCluster);
            return true;
        }
        var adoptCancel = target.closest('[data-action="cancel-worktree-adopt"]');
        if (adoptCancel) {
            cancelWorktreeAdoptCard(projectDiv);
            return true;
        }
        var adoptConfirm = target.closest('[data-action="confirm-worktree-adopt"]');
        if (adoptConfirm) {
            if (!adoptConfirm.disabled) {
                confirmWorktreeAdopt(adoptConfirm.closest('.ai-session-worktree-adopt-card'));
            }
            return true;
        }
        var surfaceAction = target.closest(
            '[data-action="select-ai-session-surface"][data-surface]'
        );
        if (surfaceAction) {
            var selectedSurface = normalizeAiSessionSurface(
                surfaceAction.getAttribute('data-surface')
            );
            selectAiSessionSurfaceDom(projectDiv, selectedSurface);
            writeAiSessionSurfaceState(window.vscode, projectId, selectedSurface);
            // The host renders future authoritative HTML with this selection,
            // so replacements never flip the visible surface.
            window.vscode.postMessage({
                type: 'select-ai-session-surface',
                version: 1,
                projectId: projectId,
                surface: selectedSurface,
            });
            if (selectedSurface === 'chats') {
                // M2 transition: entering the legacy CHATS surface maps the
                // current sub-tab onto the host-persisted window view tab.
                var currentSubTab = getSelectedAiSessionTab(projectDiv);
                window.vscode.postMessage({
                    type: 'select-ai-session-view-tab',
                    version: 1,
                    projectId: projectId,
                    tab: currentSubTab === 'sessions' ? 'all' : 'chats',
                });
            }
            return true;
        }
        var tabAction = target.closest('[data-action="select-ai-session-tab"][data-tab]');
        if (tabAction) {
            var selectedTab = normalizeAiSessionTab(tabAction.getAttribute('data-tab'));
            selectAiSessionTabDom(projectDiv, selectedTab);
            writeAiSessionTabState(window.vscode, projectId, selectedTab);
            // M2 transition: mirror the sub-tab selection into the
            // host-persisted window view state (ACTIVE → chats, ALL → all) so
            // the PR-D cutover reads live values instead of a migration.
            window.vscode.postMessage({
                type: 'select-ai-session-view-tab',
                version: 1,
                projectId: projectId,
                tab: selectedTab === 'active' ? 'chats' : 'all',
            });
            return true;
        }

        var providerMenuTrigger = target.closest('[data-ai-provider-menu-trigger]');
        if (providerMenuTrigger) {
            toggleAiSessionProviderMenu(projectDiv);
            return true;
        }

        var providerOption = target.closest('[data-ai-provider-option][data-provider]');
        if (providerOption) {
            activateAiSessionProviderOption(projectDiv, providerOption);
            return true;
        }

        var createAction = target.closest('[data-action="create-ai-session"]');
        if (createAction) {
            window.vscode.postMessage({
                type: 'create-ai-session',
                projectId,
            });

            return true;
        }

        var quickCreateAction = target.closest('[data-action="create-ai-session-quick"]');
        if (quickCreateAction) {
            var provider = quickCreateAction.getAttribute('data-provider');
            if (provider) {
                var message = {
                    type: 'create-ai-session-quick',
                    projectId,
                    provider: provider,
                };
                var worktreeGroup = quickCreateAction.closest(
                    '[data-worktree-repository-key][data-worktree-path]'
                );
                if (worktreeGroup) {
                    message.worktreeKey = {
                        repositoryKey: worktreeGroup.getAttribute('data-worktree-repository-key'),
                        canonicalWorktreePath: worktreeGroup.getAttribute('data-worktree-path'),
                    };
                }
                window.vscode.postMessage(message);
            }

            return true;
        }

        var dropdownAction = target.closest('[data-action="create-ai-session-dropdown"]');
        if (dropdownAction) {
            var dropdownMenu = document.getElementById('aiSessionCreateDropdown');
            if (dropdownMenu) {
                // Snapshot before closing: a second click on the arrow that
                // opened the menu toggles it closed.
                var wasOpenForProject = dropdownMenu.classList.contains('visible')
                    && (dropdownMenu.getAttribute('data-dropdown-project-id') || '') === projectId;
                // Close other menus first (this also resets every arrow's
                // aria-expanded via closeContextMenus).
                var contextMenus = window.__agentPivotContextMenus;
                if (contextMenus && typeof contextMenus.closeContextMenus === 'function') {
                    contextMenus.closeContextMenus();
                }
                if (wasOpenForProject) {
                    return true;
                }
                // Store the projectId on the menu element for menu item handlers
                dropdownMenu.setAttribute('data-dropdown-project-id', projectId);
                dropdownMenu.__originButton = dropdownAction;
                dropdownAction.setAttribute('aria-expanded', 'true');
                // Position and show the dropdown below the button
                var buttonRect = dropdownAction.getBoundingClientRect();
                dropdownMenu.style.visibility = 'hidden';
                dropdownMenu.style.left = '0px';
                dropdownMenu.style.top = '0px';
                dropdownMenu.classList.add('visible');
                var menuRect = dropdownMenu.getBoundingClientRect();
                var viewportPadding = 4;
                var left = Math.max(viewportPadding, Math.min(
                    buttonRect.left,
                    window.innerWidth - menuRect.width - viewportPadding
                ));
                var top = buttonRect.bottom + 2;
                if (top + menuRect.height > window.innerHeight - viewportPadding) {
                    top = buttonRect.top - menuRect.height - 2;
                }
                dropdownMenu.style.left = left + 'px';
                dropdownMenu.style.top = top + 'px';
                dropdownMenu.style.visibility = 'visible';
                var firstMenuItem = dropdownMenu.querySelector('[role="menuitem"]');
                if (firstMenuItem) {
                    firstMenuItem.focus();
                }
            }
            return true;
        }

        var manageAction = target.closest('[data-action="manage-ai-sessions"][data-provider]');
        if (manageAction) {
            if (batchAiSessionState.pending
                || pendingAiSessionProviderSelectionProjectId)
                return true;

            var manageProvider = manageAction.getAttribute("data-provider");
            if (projectDiv && isAiSessionProvider(manageProvider)) {
                if (isActiveAiSessionBatchScope(projectId, manageProvider)) {
                    exitAiSessionBatchManagement();
                } else {
                    batchAiSessionManager.enter(projectId);
                    syncAiSessionBatchManagementDom(projectDiv);
                }
            }

            return true;
        }

        var selectUnpinnedAction = target.closest('[data-action="select-unpinned-ai-sessions"]');
        if (selectUnpinnedAction) {
            if (isActiveAiSessionBatchScope(projectId, getProjectActiveAiSessionProvider(projectDiv))) {
                var sessions = Array.from(projectDiv.querySelectorAll('.ai-session-history-panel .codex-session-row[data-session-id]'))
                    .map(row => ({
                        provider: row.getAttribute("data-session-provider") || "codex",
                        id: row.getAttribute("data-session-id"),
                        pinned: row.hasAttribute("data-session-pinned"),
                        active: row.hasAttribute("data-session-active"),
                    }));
                batchAiSessionManager.selectUnpinned(sessions);
                syncAiSessionBatchManagementDom(projectDiv);
            }

            return true;
        }

        var clearSelectionAction = target.closest('[data-action="clear-ai-session-selection"]');
        if (clearSelectionAction) {
            if (isActiveAiSessionBatchScope(projectId, getProjectActiveAiSessionProvider(projectDiv))) {
                batchAiSessionManager.clear();
                syncAiSessionBatchManagementDom(projectDiv);
            }

            return true;
        }

        var archiveSelectedAction = target.closest('[data-action="archive-selected-ai-sessions"]');
        if (archiveSelectedAction) {
            if (isActiveAiSessionBatchScope(projectId, getProjectActiveAiSessionProvider(projectDiv))) {
                batchAiSessionManager.submit();
                syncAiSessionBatchManagementDom(projectDiv);
            }

            return true;
        }

        var terminalAction = target.closest('[data-action="close-ai-session-terminal"], [data-action="detach-ai-session-terminal"], [data-action="stop-ai-session-runtime"]');
        if (terminalAction) {
            var terminalRow = terminalAction.closest('.codex-session-row[data-session-provider][data-session-backend]');
            var terminalProvider = terminalRow && terminalRow.getAttribute('data-session-provider');
            var terminalBackend = terminalRow && terminalRow.getAttribute('data-session-backend');
            var requestedTerminalAction = terminalAction.getAttribute('data-action');
            var requestedDetach = requestedTerminalAction === 'detach-ai-session-terminal';
            var requestedStop = requestedTerminalAction === 'stop-ai-session-runtime';
            if (terminalRow && isAiSessionProvider(terminalProvider)
                && ((requestedDetach && terminalBackend === 'tmux')
                    || (requestedStop && terminalBackend === 'tmux')
                    || (!requestedDetach && !requestedStop && terminalBackend === 'vscode'))) {
                var terminalMessage = {
                    type: requestedDetach ? 'detach-ai-session-terminal'
                        : requestedStop ? 'stop-ai-session-runtime'
                            : 'close-ai-session-terminal',
                    projectId,
                    provider: terminalProvider,
                };
                if (terminalRow.hasAttribute('data-session-pending')) {
                    terminalMessage.pendingCreatedAt = terminalRow.getAttribute('data-pending-created-at');
                } else {
                    terminalMessage.sessionId = terminalRow.getAttribute('data-session-id');
                }
                window.vscode.postMessage(terminalMessage);
            }
            return true;
        }

        var managedSessionRow = target.closest('.codex-session-row[data-session-id]');
        if (managedSessionRow) {
            var managedSessionProvider = managedSessionRow.getAttribute("data-session-provider") || "codex";
            if (isActiveAiSessionBatchScope(projectId, managedSessionProvider)
                && !managedSessionRow.hasAttribute('data-session-active')) {
                batchAiSessionManager.toggle(
                    managedSessionProvider,
                    managedSessionRow.getAttribute("data-session-id"),
                    managedSessionRow.hasAttribute('data-session-active')
                );
                syncAiSessionBatchManagementDom(projectDiv);
                return true;
            }
        }

        var pinAction = target.closest('[data-action="toggle-ai-session-pin"]');
        if (pinAction) {
            var pinRow = pinAction.closest('.codex-session-row[data-session-id]');
            var pinSessionId = pinRow && pinRow.getAttribute("data-session-id");
            var pinProvider = pinRow && pinRow.getAttribute("data-session-provider") || "codex";
            if (pinSessionId) {
                window.vscode.postMessage({
                    type: 'toggle-ai-session-pin',
                    projectId,
                    provider: pinProvider,
                    sessionId: pinSessionId,
                });
            }

            return true;
        }

        var archiveAction = target.closest('[data-action="archive-codex-session"], [data-action="archive-kimi-session"], [data-action="archive-claude-session"]');
        if (archiveAction) {
            var archiveRow = archiveAction.closest('.codex-session-row[data-session-id]');
            var archiveSessionId = archiveRow && archiveRow.getAttribute("data-session-id");
            var archiveProvider = archiveRow && archiveRow.getAttribute("data-session-provider") || "codex";
            if (archiveSessionId && isAiSessionProvider(archiveProvider)) {
                acknowledgeAiSessionRow(archiveRow);
                window.vscode.postMessage({
                    type: getArchiveAiSessionMessageType(archiveProvider),
                    projectId,
                    sessionId: archiveSessionId,
                });
            }

            return true;
        }

        var activation = getAiSessionCardActivation(target, projectId);
        if (!activation.handled)
            return false;
        if (activation.sessionRow
            && !activation.sessionRow.hasAttribute('data-session-pending')
            && activation.sessionRow.getAttribute('data-session-id')) {
            acknowledgeAiSessionRow(activation.sessionRow);
        }
        if (activation.message) {
            window.vscode.postMessage(activation.message);
        }
        return true;
    }

    function submitIsolatedSessionRequest(type, projectId, operationId, button, sourceWorktree) {
        if (!projectId || !button || button.disabled)
            return;
        nextIsolatedSessionRequestId = nextIsolatedSessionRequestId >= Number.MAX_SAFE_INTEGER
            ? 1 : nextIsolatedSessionRequestId + 1;
        var requestId = 'isolated-' + nextIsolatedSessionRequestId.toString(36);
        var message = {
            type: type,
            version: 1,
            requestId: requestId,
            projectId: projectId,
        };
        if (operationId) message.operationId = operationId;
        if (sourceWorktree) message.sourceWorktree = sourceWorktree;
        button.disabled = true;
        button.setAttribute('aria-disabled', 'true');
        pendingIsolatedSessionRequests.set(requestId, {
            button: button,
            projectId: projectId,
            requestType: type,
            operationId: operationId || requestId,
        });
        window.vscode.postMessage(message);
    }

    function applyIsolatedSessionSettlement(message) {
        var expectedKeys = message && typeof message.errorCode === 'string'
            ? ['errorCode', 'operationId', 'requestId', 'status', 'type', 'version']
            : ['operationId', 'requestId', 'status', 'type', 'version'];
        if (!message || message.type !== 'isolated-session-settlement'
            || message.version !== 1
            || Object.keys(message).sort().some((key, index) => key !== expectedKeys[index])
            || Object.keys(message).length !== expectedKeys.length
            || typeof message.requestId !== 'string' || !message.requestId
            || typeof message.operationId !== 'string' || !message.operationId
            || (Object.prototype.hasOwnProperty.call(message, 'errorCode')
                && !/^[a-z0-9-]{1,64}$/.test(message.errorCode))
            || !['accepted', 'cancelled', 'rejected', 'succeeded', 'partial', 'failed']
                .includes(message.status)) {
            return false;
        }
        var pending = pendingIsolatedSessionRequests.get(message.requestId);
        if (!pending) return true;
        if (pending.operationId !== message.operationId) return true;
        if (message.status === 'accepted') return true;
        pendingIsolatedSessionRequests.delete(message.requestId);
        if (pending.button && pending.button.isConnected) {
            pending.button.disabled = false;
            pending.button.removeAttribute('aria-disabled');
        }
        var projectDiv = getAiSessionsUpdate().findCurrentWorkspaceDiv(pending.projectId);
        var liveRegion = projectDiv?.querySelector('[data-ai-session-live-region]');
        if (liveRegion) {
            liveRegion.textContent = message.status === 'succeeded'
                ? pending.requestType === 'cancel-isolated-session'
                    ? 'Worktree creation cancelled.'
                    : pending.requestType === 'dismiss-isolated-session'
                        ? 'Worktree creation dismissed.'
                        : 'Worktree created.'
                : message.status === 'cancelled'
                    ? 'Worktree creation cancelled.'
                    : `Worktree creation ${message.status}: ${describeProvisioningError(message.errorCode)}`;
        }
        return true;
    }

    // The per-worktree ⋯ menu is one shared body-level element; the context is
    // rebound from the clicked row every time it opens so a single menu can
    // serve quick create, per-provider create, branch-from-here, and removal.
    function toggleAiSessionWorktreeMenu(button, projectId) {
        var menu = document.getElementById('aiSessionWorktreeMenu');
        if (!menu || !button) return false;
        var wasOpen = menu.classList.contains('visible') && menu.__originButton === button;
        if (window.__agentPivotContextMenus
            && typeof window.__agentPivotContextMenus.closeContextMenus === 'function') {
            window.__agentPivotContextMenus.closeContextMenus();
        }
        if (wasOpen) return true;
        // Group rows always carry the menu (M3: group-level actions such as
        // rename must stay reachable even without a ready primary); the
        // worktree-targeted items below hide themselves when the row has no
        // usable primary worktree.
        var group = button.closest('.ai-session-worktree-group');
        if (!group) return false;
        menu.__context = {
            projectId: projectId,
            repositoryKey: group.getAttribute('data-worktree-repository-key') || '',
            worktreePath: group.getAttribute('data-worktree-path') || '',
            groupId: button.getAttribute('data-group-id')
                || group.getAttribute('data-group-id') || '',
            anchor: button.getAttribute('data-worktree-anchor') === 'true',
            quickProvider: button.getAttribute('data-quick-provider') || '',
            canResume: button.getAttribute('data-can-resume') === 'true',
            canRemove: button.getAttribute('data-can-remove') === 'true',
            canBranchCreate: button.getAttribute('data-can-branch-create') === 'true'
                && button.getAttribute('data-worktree-head-kind') === 'branch',
        };
        menu.__originButton = button;
        var hasWorktreeTarget = !!(menu.__context.repositoryKey && menu.__context.worktreePath);
        var quickItem = menu.querySelector('[data-action="worktree-quick-create"]');
        quickItem.textContent = button.getAttribute('data-quick-label')
            || ('New session in ' + (button.getAttribute('data-worktree-name') || 'worktree'));
        // Session creation works without a worktree target too: the Current
        // anchor launches plain main-checkout sessions from the same menu,
        // keeping single- and multi-root behavior identical.
        quickItem.hidden = !menu.__context.canResume;
        menu.querySelectorAll('[data-action="worktree-provider-create"]').forEach(item => {
            item.hidden = !menu.__context.canResume;
        });
        var optionsItem = menu.querySelector('[data-action="worktree-create-with-options"]');
        optionsItem.hidden = !menu.__context.canResume;
        var branchItem = menu.querySelector('[data-action="worktree-branch-create"]');
        branchItem.textContent = 'New worktree from '
            + (button.getAttribute('data-worktree-name') || 'this branch');
        branchItem.hidden = !menu.__context.canBranchCreate || !hasWorktreeTarget;
        // "New worktree…" opens the plain creation form: it replaces the
        // removed surface-level button, and covers multi-root anchors where
        // a single seeded branch makes no sense.
        var newWorktreeItem = menu.querySelector('[data-action="worktree-new"]');
        newWorktreeItem.hidden = !menu.__context.anchor || !branchItem.hidden;
        var renameItem = menu.querySelector('[data-action="worktree-group-rename"]');
        renameItem.hidden = !menu.__context.groupId;
        var deriveItem = menu.querySelector('[data-action="worktree-group-derive"]');
        deriveItem.hidden = !menu.__context.groupId;
        var addRepoItem = menu.querySelector('[data-action="worktree-group-add-repo"]');
        addRepoItem.hidden = !menu.__context.groupId;
        var groupDeleteItem = menu.querySelector('[data-action="worktree-group-delete"]');
        groupDeleteItem.hidden = !menu.__context.groupId;
        var sessionSeparator = menu.querySelector('[data-worktree-session-separator]');
        if (sessionSeparator) {
            sessionSeparator.hidden = quickItem.hidden && branchItem.hidden;
        }
        var removeItem = menu.querySelector('[data-action="worktree-remove"]');
        removeItem.hidden = !menu.__context.canRemove || !hasWorktreeTarget;
        var removeSeparator = menu.querySelector('[data-worktree-remove-separator]');
        if (removeSeparator) {
            removeSeparator.hidden = removeItem.hidden && renameItem.hidden;
        }

        button.setAttribute('aria-expanded', 'true');
        menu.style.visibility = 'hidden';
        menu.style.left = '0px';
        menu.style.top = '0px';
        menu.classList.add('visible');
        var buttonRect = button.getBoundingClientRect();
        var menuRect = menu.getBoundingClientRect();
        var viewportPadding = 4;
        var left = Math.max(viewportPadding, Math.min(
            buttonRect.right - menuRect.width,
            window.innerWidth - menuRect.width - viewportPadding
        ));
        var top = buttonRect.bottom + 2;
        if (top + menuRect.height > window.innerHeight - viewportPadding) {
            top = Math.max(viewportPadding, buttonRect.top - menuRect.height - 2);
        }
        menu.style.left = left + 'px';
        menu.style.top = top + 'px';
        menu.style.visibility = 'visible';
        var firstItem = menu.querySelector('[role="menuitem"]:not([hidden])');
        firstItem?.focus();
        return true;
    }

    function closeAiSessionWorktreeMenu() {
        var menu = document.getElementById('aiSessionWorktreeMenu');
        if (!menu) return;
        if (menu.__originButton) {
            menu.__originButton.setAttribute('aria-expanded', 'false');
        }
        menu.__originButton = null;
        menu.classList.remove('visible');
    }

    function activateAiSessionWorktreeMenuItem(item) {
        var menu = document.getElementById('aiSessionWorktreeMenu');
        var context = menu && menu.__context;
        var originButton = menu ? menu.__originButton : null;
        if (!menu || !context || !context.projectId) return;
        var action = item.getAttribute('data-action');
        // The Current anchor launches plain main-checkout sessions even
        // when it carries the main checkout's key for branch seeding.
        var worktreeKey = !context.anchor && context.repositoryKey && context.worktreePath
            ? {
                repositoryKey: context.repositoryKey,
                canonicalWorktreePath: context.worktreePath,
            }
            : null;
        if (action === 'worktree-quick-create' && context.canResume) {
            window.vscode.postMessage({
                type: 'create-ai-session-quick',
                projectId: context.projectId,
                provider: context.quickProvider,
                ...(worktreeKey ? { worktreeKey: worktreeKey } : {}),
            });
        } else if (action === 'worktree-provider-create') {
            var provider = item.getAttribute('data-provider');
            if (!provider) return;
            window.vscode.postMessage({
                type: 'create-ai-session-quick',
                projectId: context.projectId,
                provider: provider,
                ...(worktreeKey ? { worktreeKey: worktreeKey } : {}),
            });
        } else if (action === 'worktree-create-with-options' && context.canResume) {
            // The full creation flow: title, profile, and root pickers.
            window.vscode.postMessage({
                type: 'create-ai-session',
                projectId: context.projectId,
                ...(worktreeKey ? { worktreeKey: worktreeKey } : {}),
            });
        } else if (action === 'worktree-branch-create' && context.canBranchCreate) {
            // M2: absorbed by the inline creation form with a branch seed
            // (PRD §6.1 entry absorption).
            if (worktreeGroupForm) {
                worktreeGroupForm.openForm(context.projectId, {
                    repositoryKey: context.repositoryKey,
                    worktreePath: context.worktreePath,
                });
            }
        } else if (action === 'worktree-new' && context.anchor) {
            // Replaces the removed surface-level New-worktree button:
            // follow the form into the Worktree surface immediately.
            var projectDiv = getAiSessionsUpdate().findCurrentWorkspaceDiv(context.projectId);
            selectAiSessionSurfaceDom(projectDiv, 'worktree');
            writeAiSessionSurfaceState(window.vscode, context.projectId, 'worktree');
            window.vscode.postMessage({
                type: 'select-ai-session-surface',
                version: 1,
                projectId: context.projectId,
                surface: 'worktree',
            });
            if (worktreeGroupForm) {
                worktreeGroupForm.openForm(context.projectId, null);
            }
        } else if (action === 'worktree-group-rename' && context.groupId) {
            startWorktreeGroupRename(context.projectId, context.groupId);
        } else if (action === 'worktree-group-derive' && context.groupId) {
            if (worktreeGroupForm) {
                worktreeGroupForm.openForm(context.projectId, {
                    sourceGroupId: context.groupId,
                });
            }
        } else if (action === 'worktree-group-add-repo' && context.groupId) {
            if (worktreeGroupForm) {
                worktreeGroupForm.openForm(context.projectId, {
                    targetGroupId: context.groupId,
                });
            }
        } else if (action === 'worktree-group-delete' && context.groupId) {
            startWorktreeGroupMemberDeletion(context.projectId, context.groupId, '', {
                mode: 'group',
            });
        } else if (action === 'worktree-remove' && context.canRemove) {
            var projectDiv = document.querySelector(
                '.project[data-id="' + CSS.escape(context.projectId) + '"]'
            );
            var group = projectDiv && projectDiv.querySelector(
                '.ai-session-worktree-group[data-worktree-path="' + CSS.escape(context.worktreePath) + '"]'
            );
            if (!group || !originButton || !originButton.isConnected) return;
            submitManagedWorktreeRemoval(context.projectId, group, originButton);
        } else {
            return;
        }
        closeAiSessionWorktreeMenu();
    }

    function submitMergeWorktreeGroups(projectId, sourceGroupId, actionElement) {
        if (!projectId || !sourceGroupId || !actionElement) return;
        if (pendingMergeWorktreeGroupsRequests.size > 0) return;
        nextMergeWorktreeGroupsRequestId = nextMergeWorktreeGroupsRequestId
            >= Number.MAX_SAFE_INTEGER ? 1 : nextMergeWorktreeGroupsRequestId + 1;
        var requestId = 'worktree-merge-' + worktreeMergeDocumentNonce
            + '-' + nextMergeWorktreeGroupsRequestId.toString(36);
        actionElement.setAttribute('aria-disabled', 'true');
        pendingMergeWorktreeGroupsRequests.set(requestId, {
            actionElement: actionElement,
            projectId: projectId,
        });
        window.vscode.postMessage({
            type: 'merge-worktree-groups', version: 1,
            requestId: requestId, projectId: projectId,
            sourceGroupId: sourceGroupId,
        });
    }

    function applyWorktreeGroupMergeSettlement(message) {
        var expectedKeys = message && typeof message.errorCode === 'string'
            ? ['errorCode', 'requestId', 'status', 'type', 'version']
            : message && typeof message.groupId === 'string'
                ? ['groupId', 'requestId', 'status', 'type', 'version']
                : ['requestId', 'status', 'type', 'version'];
        if (!message || message.type !== 'worktree-group-merge-settlement'
            || message.version !== 1
            || Object.keys(message).length !== expectedKeys.length
            || Object.keys(message).sort().some((key, index) => key !== expectedKeys[index])
            || typeof message.requestId !== 'string' || !message.requestId
            || !['accepted', 'merged', 'cancelled', 'failed'].includes(message.status)
            || (Object.prototype.hasOwnProperty.call(message, 'errorCode')
                && !/^[a-z0-9-]{1,64}$/.test(message.errorCode))) return false;
        var pending = pendingMergeWorktreeGroupsRequests.get(message.requestId);
        if (!pending) return true;
        if (message.status === 'accepted') return true;
        pendingMergeWorktreeGroupsRequests.delete(message.requestId);
        if (pending.actionElement && pending.actionElement.isConnected) {
            pending.actionElement.removeAttribute('aria-disabled');
        }
        var projectDiv = getAiSessionsUpdate().findCurrentWorkspaceDiv(pending.projectId);
        var liveRegion = projectDiv?.querySelector('[data-ai-session-live-region]');
        if (liveRegion && message.status !== 'cancelled') {
            liveRegion.textContent = message.status === 'merged'
                ? 'Worktree groups merged.'
                : `Worktree group merge failed: ${message.errorCode || 'unknown'}`;
        }
        return true;
    }

    function submitManagedWorktreeRemoval(projectId, group, button) {
        if (!projectId || !group || !button || button.disabled) return;
        var repositoryKey = group.getAttribute('data-worktree-repository-key');
        var worktreePath = group.getAttribute('data-worktree-path');
        if (!repositoryKey || !worktreePath) return;
        nextManagedWorktreeRemovalRequestId = nextManagedWorktreeRemovalRequestId
            >= Number.MAX_SAFE_INTEGER ? 1 : nextManagedWorktreeRemovalRequestId + 1;
        var requestId = 'worktree-remove-' + nextManagedWorktreeRemovalRequestId.toString(36);
        button.disabled = true;
        button.setAttribute('aria-disabled', 'true');
        pendingManagedWorktreeRemovalRequests.set(requestId, {
            button: button,
            projectId: projectId,
        });
        window.vscode.postMessage({
            type: 'remove-managed-worktree', version: 1,
            requestId: requestId, projectId: projectId,
            repositoryKey: repositoryKey, worktreePath: worktreePath,
        });
    }

    function applyManagedWorktreeRemovalSettlement(message) {
        var expectedKeys = message && typeof message.errorCode === 'string'
            ? ['errorCode', 'requestId', 'status', 'type', 'version']
            : ['requestId', 'status', 'type', 'version'];
        if (!message || message.type !== 'managed-worktree-removal-settlement'
            || message.version !== 1
            || Object.keys(message).length !== expectedKeys.length
            || Object.keys(message).sort().some((key, index) => key !== expectedKeys[index])
            || typeof message.requestId !== 'string' || !message.requestId
            || !['accepted', 'cancelled', 'rejected', 'succeeded', 'partial', 'failed']
                .includes(message.status)
            || (Object.prototype.hasOwnProperty.call(message, 'errorCode')
                && !/^[a-z0-9-]{1,64}$/.test(message.errorCode))) return false;
        var pending = pendingManagedWorktreeRemovalRequests.get(message.requestId);
        if (!pending) return true;
        if (message.status === 'accepted') return true;
        pendingManagedWorktreeRemovalRequests.delete(message.requestId);
        if (pending.button && pending.button.isConnected) {
            pending.button.disabled = false;
            pending.button.removeAttribute('aria-disabled');
        }
        var projectDiv = getAiSessionsUpdate().findCurrentWorkspaceDiv(pending.projectId);
        var liveRegion = projectDiv?.querySelector('[data-ai-session-live-region]');
        if (liveRegion) {
            liveRegion.textContent = message.status === 'succeeded'
                ? 'Managed worktree removed; local branch kept.'
                : message.status === 'cancelled'
                    ? 'Worktree removal cancelled.'
                    : `Worktree removal ${message.status}: ${describeWorktreeRemovalError(message.errorCode)}`;
        }
        return true;
    }

    function submitSetGroupPrimaryRequest(projectId, button) {
        var groupId = button && button.getAttribute('data-group-id');
        var memberId = button && button.getAttribute('data-member-id');
        if (!projectId || !groupId || !memberId || button.disabled) return;
        nextSetGroupPrimaryRequestId = nextSetGroupPrimaryRequestId
            >= Number.MAX_SAFE_INTEGER ? 1 : nextSetGroupPrimaryRequestId + 1;
        var requestId = 'set-primary-' + nextSetGroupPrimaryRequestId.toString(36);
        // Transient pending state until the Host's terminal settlement (or
        // an authoritative refresh re-render) resolves it.
        button.disabled = true;
        button.setAttribute('aria-disabled', 'true');
        pendingSetGroupPrimaryRequests.set(requestId, {
            button: button,
            projectId: projectId,
            groupId: groupId,
            memberId: memberId,
        });
        window.vscode.postMessage({
            type: 'set-worktree-group-primary',
            version: 1,
            requestId: requestId,
            projectId: projectId,
            groupId: groupId,
            memberId: memberId,
        });
    }

    function applySetGroupPrimarySettlement(message) {
        var expectedKeys = message && typeof message.errorCode === 'string'
            ? ['errorCode', 'groupId', 'memberId', 'requestId', 'status', 'type', 'version']
            : ['groupId', 'memberId', 'requestId', 'status', 'type', 'version'];
        if (!message || message.type !== 'worktree-group-primary-settlement'
            || message.version !== 1
            || Object.keys(message).length !== expectedKeys.length
            || Object.keys(message).sort().some((key, index) => key !== expectedKeys[index])
            || typeof message.requestId !== 'string' || !message.requestId
            || typeof message.groupId !== 'string' || !message.groupId
            || typeof message.memberId !== 'string' || !message.memberId
            || !['accepted', 'settled', 'failed'].includes(message.status)
            || (Object.prototype.hasOwnProperty.call(message, 'errorCode')
                && !/^[a-z0-9-]{1,64}$/.test(message.errorCode))) return false;
        var pending = pendingSetGroupPrimaryRequests.get(message.requestId);
        if (!pending) return true;
        if (pending.groupId !== message.groupId
            || pending.memberId !== message.memberId) return true;
        if (message.status === 'accepted') return true;
        pendingSetGroupPrimaryRequests.delete(message.requestId);
        if (pending.button && pending.button.isConnected) {
            pending.button.disabled = false;
            pending.button.removeAttribute('aria-disabled');
        }
        if (message.status === 'failed') {
            var projectDiv = getAiSessionsUpdate().findCurrentWorkspaceDiv(pending.projectId);
            var liveRegion = projectDiv && projectDiv.querySelector('[data-ai-session-live-region]');
            if (liveRegion) {
                liveRegion.textContent = 'Could not set the primary worktree; try again.';
            }
        }
        return true;
    }

    // ---------- Worktree group rename (M3; PRD §5.2) ----------
    // The editor is local transient state: an unrelated authoritative
    // replacement captures and restores it (view-state script); a submitted
    // editor stays pending until the rename lands in the authoritative HTML
    // (the restored editor is skipped once the group's name changed), and a
    // failed settlement re-enables it in place — the host never refreshes on
    // failure because nothing authoritative changed.
    var pendingWorktreeGroupRenameRequests = new Map();
    var worktreeGroupRenameSerial = 0;
    // A per-document nonce keeps request ids unique across webview reloads:
    // a late settlement from a previous document can never correlate with a
    // request issued by this one.
    var worktreeGroupRenameDocumentNonce = Math.random().toString(36).slice(2, 10);

    function nextWorktreeGroupRenameRequestId() {
        worktreeGroupRenameSerial = worktreeGroupRenameSerial >= Number.MAX_SAFE_INTEGER
            ? 1 : worktreeGroupRenameSerial + 1;
        return 'group-rename-' + worktreeGroupRenameDocumentNonce
            + '-' + worktreeGroupRenameSerial.toString(36);
    }

    function findWorktreeGroupSection(projectDiv, groupId) {
        if (!projectDiv || typeof projectDiv.querySelectorAll !== 'function') return null;
        var sections = projectDiv.querySelectorAll('.ai-session-worktree-group[data-group-id]');
        for (var index = 0; index < sections.length; index++) {
            if (sections[index].getAttribute('data-group-id') === groupId) {
                return sections[index];
            }
        }
        return null;
    }

    function announceWorktreeGroupRename(projectId, text) {
        var projectDiv = getAiSessionsUpdate().findCurrentWorkspaceDiv(projectId);
        var liveRegion = projectDiv
            && projectDiv.querySelector('[data-ai-session-live-region]');
        if (liveRegion) {
            liveRegion.textContent = text;
        }
    }

    function cancelWorktreeGroupRename(projectDiv, options) {
        var editor = projectDiv
            && projectDiv.querySelector('.ai-session-worktree-rename-editor');
        if (!editor || editor.getAttribute('data-rename-pending') === 'true') return false;
        var section = editor.closest('.ai-session-worktree-group');
        var toolbar = section && section.querySelector('.ai-session-worktree-toolbar');
        editor.remove();
        if (toolbar) toolbar.hidden = false;
        if (section && !(options && options.keepFocus)) {
            var header = section.querySelector('.ai-session-worktree-header');
            if (header && typeof header.focus === 'function') {
                header.focus({ preventScroll: true });
            }
        }
        return true;
    }

    function buildWorktreeGroupRenameEditor(section, initialValue, options) {
        var toolbar = section.querySelector('.ai-session-worktree-toolbar');
        var title = section.querySelector('.ai-session-worktree-title');
        if (!toolbar || !title) return null;
        var groupId = section.getAttribute('data-group-id') || '';
        var editor = document.createElement('div');
        editor.className = 'ai-session-worktree-rename-editor';
        editor.setAttribute('data-rename-original-name', title.textContent || '');
        // Freeze the base revision when the editor opens: a replacement
        // that advances the group meanwhile must not let this edit post a
        // newer revision than the user ever saw — the host rejects stale
        // bases with group-changed.
        var baseRevision = options && options.baseRevision !== undefined
            ? options.baseRevision
            : parseInt(section.getAttribute('data-group-revision') || '', 10);
        editor.setAttribute('data-rename-base-revision', String(baseRevision));
        if (options && options.pending) {
            editor.setAttribute('data-rename-pending', 'true');
        }
        var input = document.createElement('input');
        input.className = 'ai-session-worktree-rename-input';
        input.type = 'text';
        input.maxLength = 200;
        input.value = initialValue;
        input.setAttribute('aria-label', 'Rename worktree group');
        input.setAttribute('aria-describedby', 'ai-session-worktree-rename-hint');
        if (options && options.pending) {
            input.readOnly = true;
            input.setAttribute('aria-disabled', 'true');
            editor.setAttribute('aria-busy', 'true');
        }
        var hint = document.createElement('span');
        hint.className = 'ai-session-worktree-rename-hint';
        hint.id = 'ai-session-worktree-rename-hint';
        hint.textContent = 'Enter to rename · Esc to cancel';
        editor.appendChild(input);
        editor.appendChild(hint);
        toolbar.hidden = true;
        section.insertBefore(editor, toolbar.nextSibling);
        input.addEventListener('keydown', event => {
            if (event.key === 'Enter') {
                event.preventDefault();
                event.stopPropagation();
                submitWorktreeGroupRenameEditor(section, editor, input);
            } else if (event.key === 'Escape') {
                event.preventDefault();
                event.stopPropagation();
                cancelWorktreeGroupRename(section.closest('.project'));
            }
        });
        if (!options || !options.skipFocus) {
            input.focus({ preventScroll: true });
            if (typeof input.select === 'function' && !(options && options.pending)) {
                input.select();
            }
        }
        return editor;
    }

    function startWorktreeGroupRename(projectId, groupId) {
        var projectDiv = getAiSessionsUpdate().findCurrentWorkspaceDiv(projectId);
        var section = findWorktreeGroupSection(projectDiv, groupId);
        if (!section) return;
        // One editor per workspace card: a fresh rename supersedes an
        // unsubmitted editor; a submitted one keeps ownership until settled.
        var existing = projectDiv.querySelector('.ai-session-worktree-rename-editor');
        if (existing) {
            if (existing.getAttribute('data-rename-pending') === 'true') return;
            cancelWorktreeGroupRename(projectDiv, { keepFocus: true });
        }
        var title = section.querySelector('.ai-session-worktree-title');
        buildWorktreeGroupRenameEditor(section, title ? title.textContent || '' : '');
    }

    function submitWorktreeGroupRenameEditor(section, editor, input) {
        if (editor.getAttribute('data-rename-pending') === 'true') return;
        var projectDiv = section.closest('.project');
        var projectId = projectDiv && projectDiv.getAttribute('data-id');
        var groupId = section.getAttribute('data-group-id') || '';
        var baseRevision = parseInt(
            editor.getAttribute('data-rename-base-revision') || '', 10);
        var value = (input.value || '').trim();
        if (!projectId || !groupId || !Number.isSafeInteger(baseRevision) || baseRevision < 1) {
            return;
        }
        if (!value) {
            announceWorktreeGroupRename(projectId, 'The group name cannot be empty.');
            input.focus({ preventScroll: true });
            return;
        }
        if (value === editor.getAttribute('data-rename-original-name')) {
            cancelWorktreeGroupRename(projectDiv);
            return;
        }
        var requestId = nextWorktreeGroupRenameRequestId();
        pendingWorktreeGroupRenameRequests.set(requestId, {
            projectId: projectId,
            groupId: groupId,
            awaitingReplacement: false,
        });
        editor.setAttribute('data-rename-pending', 'true');
        editor.setAttribute('data-rename-request-id', requestId);
        // readonly (not disabled) keeps focus stable: disabling the focused
        // input drops focus to <body> until the replacement arrives.
        input.readOnly = true;
        input.setAttribute('aria-disabled', 'true');
        editor.setAttribute('aria-busy', 'true');
        window.vscode.postMessage({
            type: 'rename-worktree-group',
            version: 1,
            requestId: requestId,
            projectId: projectId,
            groupId: groupId,
            displayName: value,
            baseRevision: baseRevision,
        });
    }

    function applyWorktreeGroupRenameSettlement(message) {
        var expectedKeys = message && typeof message.errorCode === 'string'
            ? ['errorCode', 'groupId', 'projectId', 'requestId', 'status', 'type', 'version']
            : ['groupId', 'projectId', 'requestId', 'status', 'type', 'version'];
        if (!message || message.type !== 'worktree-group-rename-settlement'
            || message.version !== 1
            || Object.keys(message).length !== expectedKeys.length
            || Object.keys(message).sort().some((key, index) => key !== expectedKeys[index])
            || typeof message.requestId !== 'string' || !message.requestId
            || typeof message.projectId !== 'string' || !message.projectId
            || typeof message.groupId !== 'string' || !message.groupId
            || !['accepted', 'settled', 'failed'].includes(message.status)
            || (Object.prototype.hasOwnProperty.call(message, 'errorCode')
                && !/^[a-z0-9-]{1,64}$/.test(message.errorCode))) return false;
        var pending = pendingWorktreeGroupRenameRequests.get(message.requestId);
        if (!pending || pending.groupId !== message.groupId
            || pending.projectId !== message.projectId) return true;
        if (message.status === 'accepted') return true;
        if (pending.awaitingReplacement) {
            // The terminal settled settlement already arrived; any later
            // settlement for this request is out of order — ignore it.
            return true;
        }
        if (message.status === 'settled') {
            // Keep the correlation until the authoritative replacement
            // actually applies: the restore hook below retires it when the
            // renamed row lands, and a lost publication is covered by the
            // host's full-refresh fallback.
            pending.awaitingReplacement = true;
            return true;
        }
        pendingWorktreeGroupRenameRequests.delete(message.requestId);
        var projectDiv = getAiSessionsUpdate().findCurrentWorkspaceDiv(pending.projectId);
        var section = findWorktreeGroupSection(projectDiv, pending.groupId);
        var editor = section
            && section.querySelector('.ai-session-worktree-rename-editor');
        var input = editor
            && editor.querySelector('.ai-session-worktree-rename-input');
        if (editor && input && editor.isConnected) {
            editor.removeAttribute('data-rename-pending');
            editor.removeAttribute('aria-busy');
            input.readOnly = false;
            input.removeAttribute('aria-disabled');
            input.focus({ preventScroll: true });
        }
        announceWorktreeGroupRename(
            pending.projectId,
            'Could not rename the worktree group; try again.'
        );
        return true;
    }

    // View-state hooks: an unsubmitted editor survives authoritative
    // replacements; a submitted one is restored only while the authoritative
    // name still equals the original (i.e. the rename has not landed yet).
    function captureWorktreeGroupRenameEditor(projectDiv) {
        if (!projectDiv || typeof projectDiv.querySelector !== 'function') return null;
        var editor = projectDiv.querySelector('.ai-session-worktree-rename-editor');
        if (!editor) return null;
        var section = editor.closest('.ai-session-worktree-group');
        var groupId = section && section.getAttribute('data-group-id');
        var input = editor.querySelector('.ai-session-worktree-rename-input');
        if (!groupId || !input) return null;
        return {
            groupId: groupId,
            value: input.value || '',
            originalName: editor.getAttribute('data-rename-original-name') || '',
            pending: editor.getAttribute('data-rename-pending') === 'true',
            requestId: editor.getAttribute('data-rename-request-id') || '',
            baseRevision: editor.getAttribute('data-rename-base-revision') || '',
        };
    }

    function restoreWorktreeGroupRenameEditor(projectDiv, state) {
        if (!projectDiv || !state || !state.groupId) return;
        var section = findWorktreeGroupSection(projectDiv, state.groupId);
        if (!section) return;
        // The replacement pipeline restores view state in two passes;
        // building the editor must be idempotent.
        if (section.querySelector('.ai-session-worktree-rename-editor')) return;
        var title = section.querySelector('.ai-session-worktree-title');
        var currentName = title ? title.textContent || '' : '';
        if (state.pending && currentName !== state.originalName) {
            // The rename landed: the authoritative row already shows it.
            // Retire the correlation — exactly by request id when known, so
            // even a replacement that races ahead of the settled settlement
            // cannot leak the pending entry — and park focus on the renamed
            // group's header.
            if (state.requestId) {
                pendingWorktreeGroupRenameRequests.delete(state.requestId);
            }
            pendingWorktreeGroupRenameRequests.forEach((pending, requestId) => {
                if (pending.awaitingReplacement && pending.groupId === state.groupId) {
                    pendingWorktreeGroupRenameRequests.delete(requestId);
                }
            });
            var header = section.querySelector('.ai-session-worktree-header');
            if (header && typeof header.focus === 'function') {
                header.focus({ preventScroll: true });
            }
            return;
        }
        var editor = buildWorktreeGroupRenameEditor(
            section,
            state.value,
            {
                pending: state.pending,
                skipFocus: true,
                baseRevision: state.baseRevision,
            }
        );
        if (editor && state.pending && state.requestId) {
            editor.setAttribute('data-rename-request-id', state.requestId);
        }
        if (editor && !state.pending) {
            var input = editor.querySelector('.ai-session-worktree-rename-input');
            if (input) {
                input.focus({ preventScroll: true });
                if (typeof input.setSelectionRange === 'function') {
                    input.setSelectionRange(input.value.length, input.value.length);
                }
            }
        }
    }

    window.__agentPivotWorktreeGroupRename = {
        capture: captureWorktreeGroupRenameEditor,
        restore: restoreWorktreeGroupRenameEditor,
    };

    // ---------- Worktree group member deletion (M3 batch 4; PRD §6.4) ----------
    // The confirmation card is local transient state, like the rename
    // editor: an unsubmitted card is captured/restored across authoritative
    // replacements (re-previewing so its data can never go stale), and a
    // submitted card stays pending until the correlated settlement plus
    // the authoritative replacement retires it — a settled deletion
    // removes the member row, a partial one replaces it with the
    // Retry/abandon banner, both observed in the replacement DOM.
    var pendingWorktreeGroupDeletionRequests = new Map();
    var pendingWorktreeGroupDeletionPreviews = new Map();
    var worktreeGroupDeletionSerial = 0;
    var worktreeGroupDeletionDocumentNonce = Math.random().toString(36).slice(2, 10);

    function nextWorktreeGroupDeletionRequestId(prefix) {
        worktreeGroupDeletionSerial = worktreeGroupDeletionSerial >= Number.MAX_SAFE_INTEGER
            ? 1 : worktreeGroupDeletionSerial + 1;
        return prefix + '-' + worktreeGroupDeletionDocumentNonce
            + '-' + worktreeGroupDeletionSerial.toString(36);
    }

    function findWorktreeGroupDeletionCard(projectDiv) {
        if (!projectDiv || typeof projectDiv.querySelector !== 'function') return null;
        return projectDiv.querySelector('.ai-session-worktree-deletion-card');
    }

    function announceWorktreeGroupDeletion(projectId, text) {
        var projectDiv = getAiSessionsUpdate().findCurrentWorkspaceDiv(projectId);
        var liveRegion = projectDiv
            && projectDiv.querySelector('[data-ai-session-live-region]');
        if (liveRegion) {
            liveRegion.textContent = text;
        }
    }

    function cancelWorktreeGroupDeletionCard(projectDiv, options) {
        var card = findWorktreeGroupDeletionCard(projectDiv);
        if (!card || card.getAttribute('data-deletion-pending') === 'true') return false;
        var section = card.closest('.ai-session-worktree-group');
        var memberId = card.getAttribute('data-member-id') || '';
        card.remove();
        if (!(options && options.keepFocus) && section) {
            var origin = memberId
                && section.querySelector('[data-action="preview-group-member-deletion"]'
                    + '[data-member-id="' + CSS.escape(memberId) + '"]');
            var focusTarget = origin
                || section.querySelector('.ai-session-worktree-header');
            if (focusTarget && typeof focusTarget.focus === 'function') {
                focusTarget.focus({ preventScroll: true });
            }
        }
        return true;
    }

    function buildWorktreeGroupDeletionCardShell(section, memberId) {
        var card = document.createElement('div');
        card.className = 'ai-session-worktree-deletion-card';
        card.setAttribute('data-member-id', memberId);
        card.setAttribute('role', 'group');
        card.setAttribute('aria-label', 'Confirm worktree removal');
        card.tabIndex = -1;
        var list = section.querySelector('.ai-session-worktree-session-list');
        (list || section).appendChild(card);
        card.addEventListener('keydown', event => {
            if (event.key === 'Escape') {
                event.preventDefault();
                event.stopPropagation();
                cancelWorktreeGroupDeletionCard(section.closest('.project'));
            }
        });
        return card;
    }

    function renderWorktreeGroupDeletionCardLoading(section, memberId) {
        var card = buildWorktreeGroupDeletionCardShell(section, memberId);
        card.setAttribute('data-deletion-phase', 'loading');
        var text = document.createElement('div');
        text.className = 'ai-session-worktree-deletion-card-text';
        text.textContent = 'Checking the worktree…';
        card.appendChild(text);
        return card;
    }

    function describeDeletionBlocker(errorCode) {
        switch (errorCode) {
            case 'worktree-active': return 'an AI session is running in this worktree';
            case 'worktree-open': return 'the worktree is open in a workspace window';
            case 'worktree-provisioning': return 'the worktree is still being created';
            case 'worktree-not-removable': return 'the worktree is not in a removable state';
            case 'worktree-status-failed': return 'the worktree state could not be verified';
            case 'worktree-identity-changed': return 'the worktree branch changed unexpectedly';
            case 'uncommitted-changes': return 'the worktree has uncommitted changes';
            case 'deletion-blocked': return 'a session is being created in this worktree';
            case 'group-leased': return 'another deletion is in progress for this group';
            case 'group-changed': return 'the group changed; review the deletion again';
            case 'member-not-ready': return 'the member is not in a removable state';
            case 'store-full': return 'the local store is full';
            case 'store-corrupt': return 'the local store needs attention';
            default: return errorCode;
        }
    }

    function updateWorktreeGroupDeletionConfirmState(card) {
        var confirm = card.querySelector('[data-action="confirm-group-member-deletion"]');
        if (!confirm) return;
        var blocked = card.getAttribute('data-deletion-blocked') === 'true';
        var needsReplacement = card.getAttribute('data-replacement-required') === 'true';
        var chosen = needsReplacement
            ? !!card.querySelector('.ai-session-worktree-deletion-replacement:checked')
            : true;
        confirm.disabled = blocked || !chosen;
    }

    function renderWorktreeGroupDeletionCard(section, preview) {
        var memberId = preview.member && preview.member.memberId || '';
        var card = buildWorktreeGroupDeletionCardShell(section, memberId);
        card.setAttribute('data-deletion-phase', 'ready');
        card.setAttribute('data-base-revision', String(preview.groupRevision || 0));
        var mode = preview.mode || 'member';
        card.setAttribute('data-deletion-mode', mode);
        if (mode !== 'member') {
            return renderWorktreeGroupDeletionCardGroupMode(card, preview);
        }
        var member = preview.member;
        var lines = document.createElement('div');
        lines.className = 'ai-session-worktree-deletion-card-text';
        var title = document.createElement('div');
        title.className = 'ai-session-worktree-deletion-card-title';
        title.textContent = 'Remove ' + (member.repositoryLabel || 'worktree')
            + ' (' + member.branchName + ') from this group?';
        lines.appendChild(title);
        var pathLine = document.createElement('div');
        pathLine.className = 'ai-session-worktree-deletion-card-path';
        pathLine.textContent = member.path;
        lines.appendChild(pathLine);
        var detail = document.createElement('div');
        detail.className = 'ai-session-worktree-deletion-card-detail';
        detail.textContent = 'Only the worktree directory is deleted; the local branch is kept.'
            + (member.historyCount > 0
                ? ' ' + member.historyCount + ' past session'
                    + (member.historyCount === 1 ? '' : 's')
                    + ' will stay in Chats but cannot be resumed.'
                : '');
        lines.appendChild(detail);
        card.appendChild(lines);
        if (member.blocker) {
            card.setAttribute('data-deletion-blocked', 'true');
            var blockerLine = document.createElement('div');
            blockerLine.className = 'ai-session-worktree-deletion-card-error';
            blockerLine.setAttribute('role', 'alert');
            blockerLine.textContent = 'Cannot remove: '
                + describeDeletionBlocker(member.blocker) + '.';
            card.appendChild(blockerLine);
        }
        if (preview.replacementRequired
            && Array.isArray(preview.replacementCandidates)
            && preview.replacementCandidates.length) {
            card.setAttribute('data-replacement-required', 'true');
            var picker = document.createElement('div');
            picker.className = 'ai-session-worktree-deletion-replacements';
            picker.setAttribute('role', 'radiogroup');
            picker.setAttribute('aria-label', 'Choose the new primary worktree');
            var pickerHint = document.createElement('div');
            pickerHint.className = 'ai-session-worktree-deletion-card-detail';
            pickerHint.textContent = 'This is the primary worktree — choose its replacement:';
            picker.appendChild(pickerHint);
            preview.replacementCandidates.forEach(candidate => {
                var option = document.createElement('label');
                option.className = 'ai-session-worktree-deletion-replacement-option';
                var radio = document.createElement('input');
                radio.type = 'radio';
                radio.className = 'ai-session-worktree-deletion-replacement';
                radio.name = 'deletion-primary-replacement';
                radio.value = candidate.memberId;
                radio.addEventListener('change', () =>
                    updateWorktreeGroupDeletionConfirmState(card));
                option.appendChild(radio);
                option.appendChild(document.createTextNode(candidate.repositoryLabel));
                picker.appendChild(option);
            });
            card.appendChild(picker);
        }
        if (Array.isArray(preview.blockingClaims) && preview.blockingClaims.length) {
            card.setAttribute('data-deletion-blocked', 'true');
            var claimsBox = document.createElement('div');
            claimsBox.className = 'ai-session-worktree-deletion-claims';
            var claimsText = document.createElement('div');
            claimsText.className = 'ai-session-worktree-deletion-card-error';
            claimsText.setAttribute('role', 'alert');
            claimsText.textContent = 'A session start on this worktree never completed.'
                + ' Discard the unfinished start to allow the deletion.';
            claimsBox.appendChild(claimsText);
            preview.blockingClaims.forEach(claim => {
                var discard = document.createElement('button');
                discard.type = 'button';
                discard.className = 'ai-session-worktree-deletion-discard-claim';
                discard.setAttribute('data-action', 'discard-generation-claim');
                discard.setAttribute('data-claim-id', claim.claimId);
                discard.textContent = 'Discard unfinished '
                    + (claim.provider || 'session') + ' start';
                claimsBox.appendChild(discard);
            });
            card.appendChild(claimsBox);
        }
        var actions = document.createElement('div');
        actions.className = 'ai-session-worktree-deletion-card-actions';
        var cancel = document.createElement('button');
        cancel.type = 'button';
        cancel.className = 'ai-session-worktree-deletion-cancel';
        cancel.setAttribute('data-action', 'cancel-group-member-deletion');
        cancel.textContent = 'Cancel';
        var confirm = document.createElement('button');
        confirm.type = 'button';
        confirm.className = 'ai-session-worktree-deletion-confirm';
        confirm.setAttribute('data-action', 'confirm-group-member-deletion');
        confirm.textContent = 'Remove worktree';
        actions.appendChild(cancel);
        actions.appendChild(confirm);
        card.appendChild(actions);
        updateWorktreeGroupDeletionConfirmState(card);
        return card;
    }

    function renderWorktreeGroupDeletionCardGroupMode(card, preview) {
        var members = Array.isArray(preview.members) ? preview.members : [];
        var totalHistory = members.reduce((sum, member) => sum + (member.historyCount || 0), 0);
        var visibleOnly = preview.mode === 'visible-only';
        var lines = document.createElement('div');
        lines.className = 'ai-session-worktree-deletion-card-text';
        var title = document.createElement('div');
        title.className = 'ai-session-worktree-deletion-card-title';
        title.textContent = visibleOnly
            ? 'Remove the ' + members.length + ' visible worktree'
                + (members.length === 1 ? '' : 's') + ' of this group?'
            : 'Remove all ' + members.length + ' worktrees of this group?';
        lines.appendChild(title);
        var detail = document.createElement('div');
        detail.className = 'ai-session-worktree-deletion-card-detail';
        detail.textContent = 'Only the worktree directories are deleted; the local branches are kept.'
            + (totalHistory > 0
                ? ' ' + totalHistory + ' past session' + (totalHistory === 1 ? '' : 's')
                    + ' will stay in Chats but cannot be resumed.'
                : '');
        lines.appendChild(detail);
        card.appendChild(lines);
        var anyBlocked = false;
        members.forEach(member => {
            var row = document.createElement('div');
            row.className = 'ai-session-worktree-deletion-member';
            var label = document.createElement('span');
            label.className = 'ai-session-worktree-deletion-member-label';
            label.textContent = member.repositoryLabel + ' (' + member.branchName + ')';
            row.appendChild(label);
            var state = document.createElement('span');
            state.className = 'ai-session-worktree-deletion-member-state';
            if (member.blocker) {
                anyBlocked = true;
                state.textContent = describeDeletionBlocker(member.blocker);
                row.setAttribute('data-deletion-member-blocked', 'true');
            } else {
                state.textContent = 'ready';
            }
            row.appendChild(state);
            card.appendChild(row);
        });
        if (anyBlocked) {
            card.setAttribute('data-deletion-blocked', 'true');
            var blockedNote = document.createElement('div');
            blockedNote.className = 'ai-session-worktree-deletion-card-error';
            blockedNote.setAttribute('role', 'alert');
            blockedNote.textContent = 'Resolve the blocked worktrees, then review the deletion again.';
            card.appendChild(blockedNote);
        }
        if (preview.wholeGroupBlocked) {
            card.setAttribute('data-deletion-blocked', 'true');
            var detachedNote = document.createElement('div');
            detachedNote.className = 'ai-session-worktree-deletion-card-error';
            detachedNote.setAttribute('role', 'alert');
            detachedNote.textContent = (preview.detachedCount || 0) + ' worktree'
                + (preview.detachedCount === 1 ? '' : 's')
                + ' in this group belong to repositories outside the workspace and'
                + ' cannot be deleted. Restore the repositories to delete the whole'
                + ' group, or remove only the visible worktrees.';
            card.appendChild(detachedNote);
            var visibleSwitch = document.createElement('button');
            visibleSwitch.type = 'button';
            visibleSwitch.className = 'ai-session-worktree-deletion-visible-only';
            visibleSwitch.setAttribute('data-action', 'preview-group-visible-deletion');
            visibleSwitch.textContent = 'Remove visible worktrees instead';
            card.appendChild(visibleSwitch);
        }
        if (Array.isArray(preview.blockingClaims) && preview.blockingClaims.length) {
            card.setAttribute('data-deletion-blocked', 'true');
            var claimsBox = document.createElement('div');
            claimsBox.className = 'ai-session-worktree-deletion-claims';
            var claimsText = document.createElement('div');
            claimsText.className = 'ai-session-worktree-deletion-card-error';
            claimsText.setAttribute('role', 'alert');
            claimsText.textContent = 'A session start on one of these worktrees never'
                + ' completed. Discard the unfinished start to allow the deletion.';
            claimsBox.appendChild(claimsText);
            preview.blockingClaims.forEach(claim => {
                var discard = document.createElement('button');
                discard.type = 'button';
                discard.className = 'ai-session-worktree-deletion-discard-claim';
                discard.setAttribute('data-action', 'discard-generation-claim');
                discard.setAttribute('data-claim-id', claim.claimId);
                discard.textContent = 'Discard unfinished '
                    + (claim.provider || 'session') + ' start';
                claimsBox.appendChild(discard);
            });
            card.appendChild(claimsBox);
        }
        var actions = document.createElement('div');
        actions.className = 'ai-session-worktree-deletion-card-actions';
        var cancel = document.createElement('button');
        cancel.type = 'button';
        cancel.className = 'ai-session-worktree-deletion-cancel';
        cancel.setAttribute('data-action', 'cancel-group-member-deletion');
        cancel.textContent = 'Cancel';
        var confirm = document.createElement('button');
        confirm.type = 'button';
        confirm.className = 'ai-session-worktree-deletion-confirm';
        confirm.setAttribute('data-action', 'confirm-group-member-deletion');
        confirm.textContent = visibleOnly
            ? 'Remove visible worktrees'
            : 'Remove ' + members.length + ' worktree' + (members.length === 1 ? '' : 's');
        actions.appendChild(cancel);
        actions.appendChild(confirm);
        card.appendChild(actions);
        updateWorktreeGroupDeletionConfirmState(card);
        return card;
    }

    function startWorktreeGroupMemberDeletion(projectId, groupId, memberId, options) {
        var mode = options && options.mode || 'member';
        var projectDiv = getAiSessionsUpdate().findCurrentWorkspaceDiv(projectId);
        var section = findWorktreeGroupSection(projectDiv, groupId);
        if (!section || (mode === 'member' && !memberId)) return;
        var existing = findWorktreeGroupDeletionCard(projectDiv);
        if (existing) {
            if (existing.getAttribute('data-deletion-pending') === 'true') return;
            cancelWorktreeGroupDeletionCard(projectDiv, { keepFocus: true });
        }
        var requestId = nextWorktreeGroupDeletionRequestId('group-delete-preview');
        pendingWorktreeGroupDeletionPreviews.set(requestId, {
            projectId: projectId, groupId: groupId, memberId: memberId, mode: mode,
        });
        var loading = renderWorktreeGroupDeletionCardLoading(section, memberId);
        loading.setAttribute('data-deletion-mode', mode);
        window.vscode.postMessage({
            type: 'preview-worktree-group-deletion',
            version: 1,
            requestId: requestId,
            projectId: projectId,
            groupId: groupId,
            mode: mode,
            ...(mode === 'member' ? { memberId: memberId } : {}),
        });
    }

    function applyWorktreeGroupDeletionPreview(message) {
        if (!message || message.type !== 'worktree-group-deletion-preview'
            || message.version !== 1
            || typeof message.requestId !== 'string' || !message.requestId
            || typeof message.projectId !== 'string' || !message.projectId
            || typeof message.groupId !== 'string' || !message.groupId
            || (message.status !== 'ready' && message.status !== 'failed')) return false;
        var pending = pendingWorktreeGroupDeletionPreviews.get(message.requestId);
        if (!pending || pending.groupId !== message.groupId
            || pending.projectId !== message.projectId) return true;
        pendingWorktreeGroupDeletionPreviews.delete(message.requestId);
        var projectDiv = getAiSessionsUpdate().findCurrentWorkspaceDiv(pending.projectId);
        var section = findWorktreeGroupSection(projectDiv, pending.groupId);
        var card = findWorktreeGroupDeletionCard(projectDiv);
        if (!section || !card
            || card.getAttribute('data-member-id') !== pending.memberId
            || card.getAttribute('data-deletion-phase') !== 'loading'
            || card.getAttribute('data-deletion-pending') === 'true') return true;
        card.remove();
        if (message.status !== 'ready'
            || ((message.mode || 'member') === 'member' && !message.member)
            || ((message.mode || 'member') !== 'member' && !Array.isArray(message.members))) {
            announceWorktreeGroupDeletion(pending.projectId,
                'Could not prepare the deletion: '
                + describeDeletionBlocker(message.errorCode || 'deletion-failed') + '.');
            return true;
        }
        renderWorktreeGroupDeletionCard(section, message);
        var cardNow = findWorktreeGroupDeletionCard(projectDiv);
        if (cardNow) {
            cardNow.focus({ preventScroll: true });
        }
        return true;
    }

    function confirmWorktreeGroupMemberDeletion(card) {
        if (!card || card.getAttribute('data-deletion-pending') === 'true') return;
        var section = card.closest('.ai-session-worktree-group');
        var projectDiv = card.closest('.project');
        var projectId = projectDiv && projectDiv.getAttribute('data-id');
        var groupId = section && section.getAttribute('data-group-id');
        var memberId = card.getAttribute('data-member-id') || '';
        var mode = card.getAttribute('data-deletion-mode') || 'member';
        var baseRevision = parseInt(card.getAttribute('data-base-revision') || '', 10);
        if (!projectId || !groupId || (mode === 'member' && !memberId)
            || !Number.isSafeInteger(baseRevision) || baseRevision < 1) return;
        var replacement = card.querySelector(
            '.ai-session-worktree-deletion-replacement:checked');
        var requestId = nextWorktreeGroupDeletionRequestId('group-delete');
        pendingWorktreeGroupDeletionRequests.set(requestId, {
            projectId: projectId,
            groupId: groupId,
            memberId: memberId,
            awaitingReplacement: false,
        });
        card.setAttribute('data-deletion-pending', 'true');
        card.setAttribute('data-deletion-request-id', requestId);
        card.setAttribute('aria-busy', 'true');
        card.querySelectorAll('button, input').forEach(control => {
            control.disabled = true;
        });
        card.focus({ preventScroll: true });
        window.vscode.postMessage({
            type: 'delete-worktree-group-member',
            version: 1,
            requestId: requestId,
            projectId: projectId,
            groupId: groupId,
            mode: mode,
            ...(mode === 'member' ? { memberId: memberId } : {}),
            baseRevision: baseRevision,
            ...(replacement ? { replacementPrimaryMemberId: replacement.value } : {}),
        });
    }

    function setWorktreeGroupDeletionBannerPending(banner, pending) {
        if (!banner) return;
        if (pending) {
            banner.setAttribute('aria-busy', 'true');
            banner.querySelectorAll('button').forEach(button => {
                button.disabled = true;
            });
        } else {
            banner.removeAttribute('aria-busy');
            banner.querySelectorAll('button').forEach(button => {
                button.disabled = false;
            });
        }
    }

    function submitWorktreeGroupDeletionOperation(button, kind) {
        var banner = button && button.closest('.ai-session-worktree-deletion');
        var section = button && button.closest('.ai-session-worktree-group');
        var projectDiv = button && button.closest('.project');
        var projectId = projectDiv && projectDiv.getAttribute('data-id');
        var groupId = button.getAttribute('data-group-id') || '';
        var operationId = button.getAttribute('data-operation-id') || '';
        if (!projectId || !groupId || !operationId || button.disabled) return;
        var requestId = nextWorktreeGroupDeletionRequestId('group-delete-' + kind);
        pendingWorktreeGroupDeletionRequests.set(requestId, {
            projectId: projectId,
            groupId: groupId,
            memberId: '',
            banner: true,
            awaitingReplacement: false,
        });
        if (banner) {
            banner.setAttribute('data-deletion-request-id', requestId);
        }
        setWorktreeGroupDeletionBannerPending(banner, true);
        window.vscode.postMessage({
            type: kind === 'retry'
                ? 'retry-worktree-group-deletion'
                : 'abandon-worktree-group-deletion',
            version: 1,
            requestId: requestId,
            projectId: projectId,
            groupId: groupId,
            operationId: operationId,
        });
    }

    function submitWorktreeGroupClaimDiscard(button) {
        var card = button && button.closest('.ai-session-worktree-deletion-card');
        var section = button && button.closest('.ai-session-worktree-group');
        var projectDiv = button && button.closest('.project');
        var projectId = projectDiv && projectDiv.getAttribute('data-id');
        var groupId = section && section.getAttribute('data-group-id') || '';
        var claimId = button.getAttribute('data-claim-id') || '';
        var memberId = card && card.getAttribute('data-member-id') || '';
        if (!projectId || !groupId || !claimId || button.disabled) return;
        var requestId = nextWorktreeGroupDeletionRequestId('group-claim-discard');
        pendingWorktreeGroupDeletionRequests.set(requestId, {
            projectId: projectId,
            groupId: groupId,
            memberId: memberId,
            claimDiscard: true,
            awaitingReplacement: false,
        });
        button.disabled = true;
        window.vscode.postMessage({
            type: 'discard-worktree-generation-claim',
            version: 1,
            requestId: requestId,
            projectId: projectId,
            groupId: groupId,
            claimId: claimId,
        });
    }

    function applyWorktreeGroupDeletionSettlement(message) {
        var baseKeys = ['groupId', 'projectId', 'requestId', 'status', 'type', 'version'];
        var withError = baseKeys.concat(['errorCode']);
        var withRevision = baseKeys.concat(['minimumAggregateRevision']);
        var withBoth = baseKeys.concat(['errorCode', 'minimumAggregateRevision']);
        var keys = message && typeof message === 'object'
            ? Object.keys(message).sort() : [];
        var matchesShape = [baseKeys, withError, withRevision, withBoth]
            .some(expected => {
                var sorted = expected.slice().sort();
                return keys.length === sorted.length
                    && keys.every((key, index) => key === sorted[index]);
            });
        if (!message || message.type !== 'worktree-group-deletion-settlement'
            || message.version !== 1 || !matchesShape
            || typeof message.requestId !== 'string' || !message.requestId
            || typeof message.projectId !== 'string' || !message.projectId
            || typeof message.groupId !== 'string' || !message.groupId
            || !['accepted', 'settled', 'partial', 'failed'].includes(message.status)
            || (Object.prototype.hasOwnProperty.call(message, 'errorCode')
                && !/^[a-z0-9-]{1,64}$/.test(message.errorCode))
            || (Object.prototype.hasOwnProperty.call(message, 'minimumAggregateRevision')
                && (!Number.isSafeInteger(message.minimumAggregateRevision)
                    || message.minimumAggregateRevision < 0))) return false;
        var pending = pendingWorktreeGroupDeletionRequests.get(message.requestId);
        if (!pending || pending.groupId !== message.groupId
            || pending.projectId !== message.projectId) return true;
        if (message.status === 'accepted') return true;
        if (pending.awaitingReplacement) {
            return true;
        }
        var projectDiv = getAiSessionsUpdate().findCurrentWorkspaceDiv(pending.projectId);
        if (message.status === 'failed') {
            pendingWorktreeGroupDeletionRequests.delete(message.requestId);
            if (pending.banner) {
                var section = findWorktreeGroupSection(projectDiv, pending.groupId);
                setWorktreeGroupDeletionBannerPending(section
                    && section.querySelector('.ai-session-worktree-deletion'), false);
            } else if (pending.claimDiscard) {
                var card = findWorktreeGroupDeletionCard(projectDiv);
                var discardButton = card && card.querySelector(
                    '[data-action="discard-generation-claim"]');
                if (discardButton) {
                    discardButton.disabled = false;
                }
            } else {
                var card = findWorktreeGroupDeletionCard(projectDiv);
                if (card && card.isConnected) {
                    card.removeAttribute('data-deletion-pending');
                    card.removeAttribute('aria-busy');
                    card.querySelectorAll('button, input').forEach(control => {
                        control.disabled = false;
                    });
                    updateWorktreeGroupDeletionConfirmState(card);
                }
            }
            announceWorktreeGroupDeletion(pending.projectId,
                'Deletion failed: '
                + describeDeletionBlocker(message.errorCode || 'deletion-failed') + '.');
            return true;
        }
        if (pending.claimDiscard) {
            // The claim is gone: re-run the preview so the card reflects
            // the now-unblocked deletion instead of trusting local edits.
            pendingWorktreeGroupDeletionRequests.delete(message.requestId);
            if (pending.memberId) {
                startWorktreeGroupMemberDeletion(
                    pending.projectId, pending.groupId, pending.memberId);
            }
            return true;
        }
        // settled / partial: keep the correlation until the authoritative
        // replacement lands (member row gone, or the Retry/abandon banner
        // visible) — the restore hook retires it.
        pending.awaitingReplacement = true;
        if (typeof message.minimumAggregateRevision === 'number') {
            // Decision J: the pending UI may only clear once a rendered
            // presentation at or beyond this aggregate revision applied.
            pending.minimumAggregateRevision = message.minimumAggregateRevision;
        }
        return true;
    }

    function worktreeGroupAggregateRevisionReached(minimum) {
        if (typeof minimum !== 'number') {
            return true;
        }
        var applied = window.__agentPivotWorktreeGroupAggregateRevision;
        return !!applied && applied.revision >= minimum;
    }

    function captureWorktreeGroupDeletionCard(projectDiv) {
        var card = findWorktreeGroupDeletionCard(projectDiv);
        if (!card) return null;
        var section = card.closest('.ai-session-worktree-group');
        var groupId = section && section.getAttribute('data-group-id');
        if (!groupId) return null;
        return {
            groupId: groupId,
            memberId: card.getAttribute('data-member-id') || '',
            mode: card.getAttribute('data-deletion-mode') || 'member',
            phase: card.getAttribute('data-deletion-phase') || 'loading',
            pending: card.getAttribute('data-deletion-pending') === 'true',
            requestId: card.getAttribute('data-deletion-request-id') || '',
        };
    }

    function restoreWorktreeGroupDeletionCard(projectDiv, state) {
        if (!projectDiv || !state || !state.groupId) return;
        var section = findWorktreeGroupSection(projectDiv, state.groupId);
        if (state.pending) {
            // Retire the pending correlation from the authoritative DOM:
            // the member row is gone (settled) or the deletion banner
            // took over (partial) — or the whole group disappeared.
            var memberGone = !section || !section.querySelector(
                '.ai-session-worktree-member-detail[data-member-id="'
                + CSS.escape(state.memberId) + '"]');
            var banner = section && section.querySelector('.ai-session-worktree-deletion');
            var pendingEntry = state.requestId
                ? pendingWorktreeGroupDeletionRequests.get(state.requestId)
                : null;
            var revisionPending = pendingEntry
                && !worktreeGroupAggregateRevisionReached(
                    pendingEntry.minimumAggregateRevision);
            if ((memberGone || banner) && !revisionPending) {
                if (state.requestId) {
                    pendingWorktreeGroupDeletionRequests.delete(state.requestId);
                }
                pendingWorktreeGroupDeletionRequests.forEach((entry, requestId) => {
                    if (entry.awaitingReplacement && entry.groupId === state.groupId
                        && worktreeGroupAggregateRevisionReached(
                            entry.minimumAggregateRevision)) {
                        pendingWorktreeGroupDeletionRequests.delete(requestId);
                    }
                });
                if (!section) {
                    // The whole group left with its last member: park
                    // focus on the next group header, else the Current
                    // anchor (PRD §6.4 focus rule).
                    var nextHeader = projectDiv.querySelector(
                        '.ai-session-worktree-group .ai-session-worktree-header');
                    var anchor = projectDiv.querySelector(
                        '.ai-session-worktree-anchor .ai-session-worktree-header');
                    var focusTarget = nextHeader || anchor;
                    if (focusTarget && typeof focusTarget.focus === 'function') {
                        focusTarget.focus({ preventScroll: true });
                    }
                } else {
                    var header = section.querySelector('.ai-session-worktree-header');
                    if (header && typeof header.focus === 'function' && !banner) {
                        header.focus({ preventScroll: true });
                    } else if (banner && typeof banner.focus === 'function') {
                        banner.tabIndex = -1;
                        banner.focus({ preventScroll: true });
                    }
                }
                return;
            }
            // Still executing: keep the pending card visible.
            if (section
                && !section.querySelector('.ai-session-worktree-deletion-card')) {
                var card = renderWorktreeGroupDeletionCardLoading(section, state.memberId);
                card.setAttribute('data-deletion-mode', state.mode || 'member');
                card.setAttribute('data-deletion-pending', 'true');
                card.setAttribute('aria-busy', 'true');
                if (state.requestId) {
                    card.setAttribute('data-deletion-request-id', state.requestId);
                }
                var text = card.querySelector('.ai-session-worktree-deletion-card-text');
                if (text) {
                    text.textContent = 'Removing the worktree…';
                }
            }
            return;
        }
        // Unsubmitted card: re-preview so the card never acts on stale
        // preview data after an authoritative replacement.
        startWorktreeGroupMemberDeletion(
            projectDiv.getAttribute('data-id'), state.groupId, state.memberId, {
                mode: state.mode || 'member',
            });
    }

    window.__agentPivotWorktreeGroupDeletion = {
        capture: captureWorktreeGroupDeletionCard,
        restore: restoreWorktreeGroupDeletionCard,
    };

    // ---------- Worktree adopt (M3 batch 8; PRD §6.5) ----------
    // The adopt card is local transient state like the deletion card: the
    // host re-validates every selected key against the live snapshot and
    // manifest, so stale card data can never adopt a claimed or vanished
    // worktree. A submitted card stays pending until the settlement and
    // the authoritative replacement (suggestion bar gone) retire it.
    var pendingWorktreeAdoptRequests = new Map();
    var worktreeAdoptSerial = 0;
    var worktreeAdoptDocumentNonce = Math.random().toString(36).slice(2, 10);

    function nextWorktreeAdoptRequestId() {
        worktreeAdoptSerial = worktreeAdoptSerial >= Number.MAX_SAFE_INTEGER
            ? 1 : worktreeAdoptSerial + 1;
        return 'adopt-' + worktreeAdoptDocumentNonce
            + '-' + worktreeAdoptSerial.toString(36);
    }

    function findWorktreeAdoptCard(projectDiv) {
        if (!projectDiv || typeof projectDiv.querySelector !== 'function') return null;
        return projectDiv.querySelector('.ai-session-worktree-adopt-card');
    }

    function cancelWorktreeAdoptCard(projectDiv) {
        var card = findWorktreeAdoptCard(projectDiv);
        if (!card || card.getAttribute('data-adopt-pending') === 'true') return false;
        var slug = card.getAttribute('data-adopt-slug') || '';
        card.remove();
        var origin = projectDiv && projectDiv.querySelector(
            '[data-action="adopt-worktree-cluster"][data-adopt-slug="' + CSS.escape(slug) + '"]');
        if (origin && typeof origin.focus === 'function') {
            origin.focus({ preventScroll: true });
        }
        return true;
    }

    function startWorktreeAdopt(button) {
        var suggestion = button.closest('.ai-session-worktree-adopt-suggestion');
        var projectDiv = button.closest('.project');
        if (!suggestion || !projectDiv) return;
        var existing = findWorktreeAdoptCard(projectDiv);
        if (existing) {
            if (existing.getAttribute('data-adopt-pending') === 'true') return;
            cancelWorktreeAdoptCard(projectDiv);
        }
        var members = [];
        try {
            members = JSON.parse(suggestion.getAttribute('data-adopt-members') || '[]');
        } catch (_error) {
            return;
        }
        if (!Array.isArray(members) || !members.length) return;
        var slug = suggestion.getAttribute('data-adopt-slug') || '';
        var card = document.createElement('div');
        card.className = 'ai-session-worktree-adopt-card ai-session-worktree-deletion-card';
        card.setAttribute('data-adopt-slug', slug);
        card.setAttribute('role', 'group');
        card.setAttribute('aria-label', 'Adopt worktrees as a group');
        card.tabIndex = -1;
        var title = document.createElement('div');
        title.className = 'ai-session-worktree-deletion-card-title';
        title.textContent = 'Adopt ' + members.length + ' worktree'
            + (members.length === 1 ? '' : 's') + ' as a group';
        card.appendChild(title);
        members.forEach(member => {
            var option = document.createElement('label');
            option.className = 'ai-session-worktree-adopt-member';
            var check = document.createElement('input');
            check.type = 'checkbox';
            check.className = 'ai-session-worktree-adopt-member-check';
            check.checked = true;
            check.setAttribute('data-repository-key', member.repositoryKey);
            check.setAttribute('data-worktree-path', member.canonicalWorktreePath);
            option.appendChild(check);
            option.appendChild(document.createTextNode(
                member.repositoryLabel + ' (' + member.branchName + ')'));
            card.appendChild(option);
        });
        var nameInput = document.createElement('input');
        nameInput.type = 'text';
        nameInput.className = 'ai-session-worktree-adopt-name';
        nameInput.maxLength = 200;
        nameInput.value = slug;
        nameInput.setAttribute('aria-label', 'Group name');
        card.appendChild(nameInput);
        var select = document.createElement('select');
        select.className = 'ai-session-worktree-adopt-target';
        select.setAttribute('aria-label', 'Adopt into');
        var newOption = document.createElement('option');
        newOption.value = '';
        newOption.textContent = 'New group';
        select.appendChild(newOption);
        projectDiv.querySelectorAll('.ai-session-worktree-task-group').forEach(section => {
            var groupId = section.getAttribute('data-group-id');
            var name = section.querySelector('.ai-session-worktree-title');
            if (!groupId) return;
            var option = document.createElement('option');
            option.value = groupId;
            option.textContent = 'Add to: ' + (name ? name.textContent : groupId);
            select.appendChild(option);
        });
        card.appendChild(select);
        var actions = document.createElement('div');
        actions.className = 'ai-session-worktree-deletion-card-actions';
        var cancel = document.createElement('button');
        cancel.type = 'button';
        cancel.setAttribute('data-action', 'cancel-worktree-adopt');
        cancel.className = 'ai-session-worktree-deletion-cancel';
        cancel.textContent = 'Cancel';
        var confirm = document.createElement('button');
        confirm.type = 'button';
        confirm.setAttribute('data-action', 'confirm-worktree-adopt');
        confirm.className = 'ai-session-worktree-deletion-confirm';
        confirm.textContent = 'Adopt';
        actions.appendChild(cancel);
        actions.appendChild(confirm);
        card.appendChild(actions);
        card.addEventListener('keydown', event => {
            if (event.key === 'Escape') {
                event.preventDefault();
                event.stopPropagation();
                cancelWorktreeAdoptCard(projectDiv);
            }
        });
        suggestion.insertAdjacentElement('afterend', card);
        nameInput.focus({ preventScroll: true });
        if (typeof nameInput.select === 'function') {
            nameInput.select();
        }
    }

    function confirmWorktreeAdopt(card) {
        if (!card || card.getAttribute('data-adopt-pending') === 'true') return;
        var projectDiv = card.closest('.project');
        var projectId = projectDiv && projectDiv.getAttribute('data-id');
        if (!projectId) return;
        var members = [];
        card.querySelectorAll('.ai-session-worktree-adopt-member-check:checked')
            .forEach(check => {
                members.push({
                    repositoryKey: check.getAttribute('data-repository-key'),
                    canonicalWorktreePath: check.getAttribute('data-worktree-path'),
                });
            });
        if (!members.length) return;
        var target = card.querySelector('.ai-session-worktree-adopt-target');
        var nameInput = card.querySelector('.ai-session-worktree-adopt-name');
        var targetGroupId = target && target.value || '';
        var displayName = nameInput && nameInput.value.trim() || '';
        if (!targetGroupId && !displayName) return;
        var requestId = nextWorktreeAdoptRequestId();
        pendingWorktreeAdoptRequests.set(requestId, {
            projectId: projectId,
            slug: card.getAttribute('data-adopt-slug') || '',
            awaitingReplacement: false,
        });
        card.setAttribute('data-adopt-pending', 'true');
        card.setAttribute('data-adopt-request-id', requestId);
        card.setAttribute('aria-busy', 'true');
        card.querySelectorAll('button, input, select').forEach(control => {
            control.disabled = true;
        });
        window.vscode.postMessage({
            type: 'adopt-worktrees',
            version: 1,
            requestId: requestId,
            projectId: projectId,
            members: members,
            ...(targetGroupId
                ? { targetGroupId: targetGroupId }
                : { displayName: displayName }),
        });
    }

    function applyWorktreeAdoptSettlement(message) {
        var baseKeys = ['projectId', 'requestId', 'status', 'type', 'version'];
        var withError = baseKeys.concat(['errorCode']);
        var withGroup = baseKeys.concat(['groupId']);
        var keys = message && typeof message === 'object'
            ? Object.keys(message).sort() : [];
        var matchesShape = [baseKeys, withError, withGroup]
            .map(expected => expected.slice().sort())
            .some(expected => keys.length === expected.length
                && keys.every((key, index) => key === expected[index]));
        if (!message || message.type !== 'worktree-adopt-settlement'
            || message.version !== 1 || !matchesShape
            || typeof message.requestId !== 'string' || !message.requestId
            || typeof message.projectId !== 'string' || !message.projectId
            || !['accepted', 'settled', 'failed'].includes(message.status)
            || (Object.prototype.hasOwnProperty.call(message, 'errorCode')
                && !/^[a-z0-9-]{1,64}$/.test(message.errorCode))) return false;
        var pending = pendingWorktreeAdoptRequests.get(message.requestId);
        if (!pending || pending.projectId !== message.projectId) return true;
        if (message.status === 'accepted') return true;
        if (pending.awaitingReplacement) return true;
        var projectDiv = getAiSessionsUpdate().findCurrentWorkspaceDiv(pending.projectId);
        if (message.status === 'failed') {
            pendingWorktreeAdoptRequests.delete(message.requestId);
            var card = findWorktreeAdoptCard(projectDiv);
            if (card && card.isConnected) {
                card.removeAttribute('data-adopt-pending');
                card.removeAttribute('aria-busy');
                card.querySelectorAll('button, input, select').forEach(control => {
                    control.disabled = false;
                });
            }
            announceWorktreeGroupDeletion(pending.projectId,
                'Could not adopt the worktrees: '
                + describeDeletionBlocker(message.errorCode || 'adopt-failed') + '.');
            return true;
        }
        pending.awaitingReplacement = true;
        return true;
    }

    function captureWorktreeAdoptCard(projectDiv) {
        var card = findWorktreeAdoptCard(projectDiv);
        if (!card) return null;
        return {
            slug: card.getAttribute('data-adopt-slug') || '',
            pending: card.getAttribute('data-adopt-pending') === 'true',
            requestId: card.getAttribute('data-adopt-request-id') || '',
        };
    }

    function restoreWorktreeAdoptCard(projectDiv, state) {
        if (!projectDiv || !state || !state.slug) return;
        var bar = projectDiv.querySelector(
            '.ai-session-worktree-adopt-suggestion[data-adopt-slug="'
            + CSS.escape(state.slug) + '"]');
        if (state.pending) {
            if (!bar) {
                // The suggestion is gone: the adoption landed. Retire the
                // correlation and park focus on the group list.
                if (state.requestId) {
                    pendingWorktreeAdoptRequests.delete(state.requestId);
                }
                pendingWorktreeAdoptRequests.forEach((entry, requestId) => {
                    if (entry.awaitingReplacement) {
                        pendingWorktreeAdoptRequests.delete(requestId);
                    }
                });
                var header = projectDiv.querySelector(
                    '.ai-session-worktree-task-group .ai-session-worktree-header');
                if (header && typeof header.focus === 'function') {
                    header.focus({ preventScroll: true });
                }
                return;
            }
            if (!findWorktreeAdoptCard(projectDiv)) {
                var button = bar.querySelector('[data-action="adopt-worktree-cluster"]');
                if (button) {
                    startWorktreeAdopt(button);
                    var card = findWorktreeAdoptCard(projectDiv);
                    if (card) {
                        card.setAttribute('data-adopt-pending', 'true');
                        card.setAttribute('aria-busy', 'true');
                        if (state.requestId) {
                            card.setAttribute('data-adopt-request-id', state.requestId);
                        }
                        card.querySelectorAll('button, input, select').forEach(control => {
                            control.disabled = true;
                        });
                    }
                }
            }
            return;
        }
        if (bar && !findWorktreeAdoptCard(projectDiv)) {
            var origin = bar.querySelector('[data-action="adopt-worktree-cluster"]');
            if (origin) {
                startWorktreeAdopt(origin);
            }
        }
    }

    window.__agentPivotWorktreeAdopt = {
        capture: captureWorktreeAdoptCard,
        restore: restoreWorktreeAdoptCard,
    };

    function describeProvisioningError(errorCode) {
        switch (errorCode) {
            case 'repository-has-no-commits':
                return 'the repository has no commits yet; make an initial commit first';
            case 'invalid-plan':
                return 'the saved creation plan is no longer valid; dismiss and recreate';
            case 'interrupted':
                return 'interrupted by a reload; retry or dismiss';
            case 'snapshot-unavailable':
                return 'worktree discovery is not ready yet; try again';
            case 'workspace-untrusted':
                return 'the workspace is not trusted';
            case 'repository-unavailable':
                return 'no usable repository found in this workspace';
            case 'base-ref-unavailable':
                return 'that worktree has no branch to base on';
            case 'duplicate-operation':
            case 'operation-running':
                return 'another creation is already in progress';
            case 'invalid-task':
                return 'enter a task name';
            case 'setup-failed':
                return 'the setup command failed';
            case 'worktree-create-failed':
                return 'Git could not create the worktree';
            case 'git-timeout':
                return 'Git timed out';
            default:
                return (errorCode || 'try again') + '';
        }
    }

    function describeWorktreeRemovalError(errorCode) {
        switch (errorCode) {
            case 'worktree-dirty':
                return 'the worktree has uncommitted changes';
            case 'worktree-not-removable':
                return 'it is not a removable Agent Pivot worktree';
            case 'worktree-active':
                return 'a session is still running in it';
            case 'worktree-open':
                return 'it is open as a workspace';
            case 'worktree-provisioning':
                return 'it is still being created';
            case 'operation-running':
                return 'another removal is already in progress';
            default:
                return (errorCode || 'try again') + '';
        }
    }

    function acknowledgeAiSessionRow(sessionRow) {
        if (!sessionRow || !sessionRow.hasAttribute('data-ai-session-attention')) return;
        var provider = sessionRow.getAttribute('data-session-provider') || 'codex';
        var sessionId = sessionRow.getAttribute('data-session-id') || '';
        var fallback = sessionRow.getAttribute('data-session-event-id') || sessionRow.getAttribute('data-ai-session-event-id');
        acknowledgeAiSession(provider, sessionId, fallback);
    }

    function acknowledgeAiSession(provider, sessionId, fallbackEventId) {
        var sessionKey = provider + ':' + sessionId;
        var stateStore = typeof getAiSessionPresentationStateStore === 'function'
            ? getAiSessionPresentationStateStore() : null;
        var eventIds = stateStore
            ? stateStore.getAttentionEventIds(provider, sessionId) : [];
        if (!eventIds.length && fallbackEventId) {
            eventIds = [fallbackEventId];
        }
        eventIds = Array.from(new Set(eventIds.filter(eventId => typeof eventId === 'string' && !!eventId)));
        if (eventIds.length) {
            var presentation = stateStore ? stateStore.getCurrent() : null;
            if (!presentation
                || presentation.type !== 'ai-session-presentation-state'
                || presentation.version !== 1
                || !Number.isSafeInteger(presentation.projectionRevision)
                || presentation.projectionRevision < 1
                || typeof presentation.workspaceScopeIdentity !== 'string'
                || !presentation.workspaceScopeIdentity) {
                window.vscode.postMessage({ type: 'acknowledge-ai-session-attention', eventIds: eventIds });
                return;
            }
            var pendingKey = presentation.workspaceScopeIdentity + '|' + sessionKey;
            if (pendingAiSessionAttentionAcknowledgements.has(pendingKey)) return;
            nextAiSessionAttentionAcknowledgementRequestId =
                nextAiSessionAttentionAcknowledgementRequestId >= Number.MAX_SAFE_INTEGER
                    ? 1 : nextAiSessionAttentionAcknowledgementRequestId + 1;
            var pending = {
                requestId: nextAiSessionAttentionAcknowledgementRequestId,
                provider: provider,
                sessionId: sessionId,
                workspaceScopeIdentity: presentation.workspaceScopeIdentity,
                projectionRevision: presentation.projectionRevision,
                eventIds: eventIds.slice(),
                committed: false,
                timeoutHandle: null,
            };
            if (typeof window.setTimeout === 'function') {
                pending.timeoutHandle = window.setTimeout(() => {
                    if (pendingAiSessionAttentionAcknowledgements.get(pendingKey) !== pending) return;
                    var currentPresentation = stateStore ? stateStore.getCurrent() : null;
                    if (!currentPresentation
                        || currentPresentation.workspaceScopeIdentity
                            !== pending.workspaceScopeIdentity) {
                        clearAiSessionAttentionAcknowledgement(pendingKey, pending);
                        return;
                    }
                    clearAiSessionAttentionAcknowledgement(pendingKey, pending);
                    announceAiSessionAttentionAcknowledgement(
                        pending,
                        'Attention update timed out. Refreshing…'
                    );
                    getAiSessionsUpdate().requestFullRefresh('ai-session-attention-acknowledgement-timeout');
                }, Number.isSafeInteger(window.__agentPivotAttentionAcknowledgementTimeoutMs)
                    && window.__agentPivotAttentionAcknowledgementTimeoutMs > 0
                    ? window.__agentPivotAttentionAcknowledgementTimeoutMs : 15_000);
            }
            pendingAiSessionAttentionAcknowledgements.set(pendingKey, pending);
            syncAiSessionAttentionAcknowledgementDom();
            window.vscode.postMessage({
                type: 'acknowledge-ai-session-attention',
                version: 1,
                requestId: pending.requestId,
                provider: provider,
                sessionId: sessionId,
                workspaceScopeIdentity: pending.workspaceScopeIdentity,
                projectionRevision: pending.projectionRevision,
                eventIds: pending.eventIds,
            });
        }
    }

    function clearAiSessionAttentionAcknowledgement(sessionKey, pending) {
        if (pendingAiSessionAttentionAcknowledgements.get(sessionKey) !== pending) return;
        if (pending.timeoutHandle !== null && typeof window.clearTimeout === 'function') {
            window.clearTimeout(pending.timeoutHandle);
        }
        pendingAiSessionAttentionAcknowledgements.delete(sessionKey);
        syncAiSessionAttentionAcknowledgementDom();
    }

    function announceAiSessionAttentionAcknowledgement(pending, message) {
        var stateStore = typeof getAiSessionPresentationStateStore === 'function'
            ? getAiSessionPresentationStateStore() : null;
        var presentation = stateStore ? stateStore.getCurrent() : null;
        if (!presentation
            || presentation.workspaceScopeIdentity !== pending.workspaceScopeIdentity) return;
        var row = document.querySelector(
            '.codex-session-row[data-session-provider="' + pending.provider
                + '"][data-session-id="' + CSS.escape(pending.sessionId) + '"]'
        );
        var project = row && row.closest('.workspace-card[data-current-workspace]');
        var liveRegion = project && project.querySelector('[data-ai-session-live-region]');
        if (liveRegion) liveRegion.textContent = message;
    }

    function syncAiSessionAttentionAcknowledgementDom() {
        document.querySelectorAll('.codex-session-row[data-attention-acknowledgement-pending]')
            .forEach(row => row.removeAttribute('data-attention-acknowledgement-pending'));
        var stateStore = typeof getAiSessionPresentationStateStore === 'function'
            ? getAiSessionPresentationStateStore() : null;
        var presentation = stateStore ? stateStore.getCurrent() : null;
        pendingAiSessionAttentionAcknowledgements.forEach(pending => {
            if (!presentation
                || presentation.workspaceScopeIdentity !== pending.workspaceScopeIdentity) return;
            document.querySelectorAll('.codex-session-row[data-session-provider][data-session-id]')
                .forEach(row => {
                    if (row.getAttribute('data-session-provider') === pending.provider
                        && row.getAttribute('data-session-id') === pending.sessionId) {
                        row.setAttribute('data-attention-acknowledgement-pending', '');
                    }
                });
        });
    }

    function reconcileAiSessionAttentionAcknowledgements() {
        var stateStore = typeof getAiSessionPresentationStateStore === 'function'
            ? getAiSessionPresentationStateStore() : null;
        var presentation = stateStore ? stateStore.getCurrent() : null;
        if (!presentation || presentation.type !== 'ai-session-presentation-state') return;
        pendingAiSessionAttentionAcknowledgements.forEach((pending, pendingKey) => {
            if (presentation.workspaceScopeIdentity !== pending.workspaceScopeIdentity) {
                clearAiSessionAttentionAcknowledgement(pendingKey, pending);
                return;
            }
            if (!pending.committed
                || presentation.projectionRevision < pending.projectionRevision) return;
            var currentEventIds = stateStore.getAttentionEventIds(
                pending.provider,
                pending.sessionId
            );
            if (pending.eventIds.some(eventId => currentEventIds.includes(eventId))) return;
            clearAiSessionAttentionAcknowledgement(pendingKey, pending);
        });
        syncAiSessionAttentionAcknowledgementDom();
    }

    function applyAiSessionAttentionAcknowledgementResult(message) {
        if (!message
            || Object.keys(message).sort().join('\n') !== [
                'outcome', 'projectionRevision', 'provider', 'requestId', 'sessionId',
                'type', 'version', 'workspaceScopeIdentity',
            ].sort().join('\n')
            || message.type !== 'ai-session-attention-acknowledgement-result'
            || message.version !== 1
            || !Number.isSafeInteger(message.requestId) || message.requestId < 1
            || !isAiSessionProvider(message.provider)
            || typeof message.sessionId !== 'string' || !message.sessionId
            || typeof message.workspaceScopeIdentity !== 'string' || !message.workspaceScopeIdentity
            || !Number.isSafeInteger(message.projectionRevision) || message.projectionRevision < 1
            || !['committed', 'degraded-local', 'rejected'].includes(message.outcome)) {
            return false;
        }
        var pendingKey = message.workspaceScopeIdentity + '|'
            + message.provider + ':' + message.sessionId;
        var pending = pendingAiSessionAttentionAcknowledgements.get(pendingKey);
        if (!pending
            || pending.requestId !== message.requestId
            || pending.workspaceScopeIdentity !== message.workspaceScopeIdentity
            || pending.projectionRevision !== message.projectionRevision) return true;
        if (message.outcome === 'committed') {
            pending.committed = true;
            reconcileAiSessionAttentionAcknowledgements();
            return true;
        }
        clearAiSessionAttentionAcknowledgement(pendingKey, pending);
        announceAiSessionAttentionAcknowledgement(
            pending,
            message.outcome === 'degraded-local'
                ? 'Attention cleared in this window, but cross-window sync could not be confirmed.'
                : 'Could not clear session attention. Try again.'
        );
        return true;
    }

    window.__agentPivotAcknowledgeSession = (provider, sessionId) => {
        if (isAiSessionProvider(provider) && sessionId) {
            acknowledgeAiSession(provider, sessionId);
        }
    };

    function getSelectedAiSessionProviders(projectDiv) {
        var region = projectDiv && projectDiv.querySelector('[data-ai-session-region]');
        return (region && region.getAttribute('data-selected-ai-session-providers') || '')
            .split(',')
            .filter(isAiSessionProvider);
    }

    function submitAiSessionProviderSelection(projectDiv, providers) {
        var projectId = projectDiv && projectDiv.getAttribute('data-id');
        if (!projectId || !providers.length || batchAiSessionState.pending
            || pendingAiSessionProviderSelectionProjectId)
            return;

        exitAiSessionBatchManagement();
        nextAiSessionProviderSelectionRequestId += 1;
        var requestId = nextAiSessionProviderSelectionRequestId;
        pendingAiSessionProviderSelectionProjectId = projectId;
        pendingAiSessionProviderSelectionRequestId = requestId;
        pendingAiSessionProviderSelectionProviders = providers.slice();
        syncAiSessionProviderMenuDisabledDom(projectDiv, true);
        window.vscode.postMessage({
            type: 'select-ai-session-providers',
            version: 1,
            requestId: requestId,
            projectId,
            selectedProviders: providers,
        });
    }

    function setAiSessionProviderMenuOpen(projectDiv, open) {
        var trigger = projectDiv && projectDiv.querySelector('[data-ai-provider-menu-trigger]');
        var menu = projectDiv && projectDiv.querySelector('[data-ai-provider-menu]');
        if (!trigger || !menu)
            return;
        if (open && (batchAiSessionState.pending
            || pendingAiSessionProviderSelectionProjectId))
            return;

        trigger.setAttribute('aria-expanded', open ? 'true' : 'false');
        menu.hidden = !open;
    }

    function closeAiSessionProviderMenus(exceptProjectDiv) {
        document.querySelectorAll('.project[data-id]').forEach(projectDiv => {
            if (projectDiv !== exceptProjectDiv) {
                setAiSessionProviderMenuOpen(projectDiv, false);
            }
        });
    }

    function closeAiSessionProviderMenu(projectDiv, restoreFocus) {
        setAiSessionProviderMenuOpen(projectDiv, false);
        if (restoreFocus) {
            projectDiv?.querySelector('[data-ai-provider-menu-trigger]')?.focus();
        }
    }

    function toggleAiSessionProviderMenu(projectDiv) {
        if (!projectDiv || batchAiSessionState.pending
            || pendingAiSessionProviderSelectionProjectId)
            return;
        var trigger = projectDiv.querySelector('[data-ai-provider-menu-trigger]');
        var open = trigger?.getAttribute('aria-expanded') !== 'true';
        closeAiSessionProviderMenus(projectDiv);
        setAiSessionProviderMenuOpen(projectDiv, open);
    }

    function activateAiSessionProviderOption(projectDiv, option) {
        if (!projectDiv || !option || batchAiSessionState.pending
            || pendingAiSessionProviderSelectionProjectId)
            return;
        var provider = option.getAttribute('data-provider');
        if (!isAiSessionProvider(provider))
            return;
        var selectedProviders = getSelectedAiSessionProviders(projectDiv);
        var selected = selectedProviders.includes(provider);
        if (selected && selectedProviders.length === 1)
            return;
        submitAiSessionProviderSelection(
            projectDiv,
            selected
                ? selectedProviders.filter(candidate => candidate !== provider)
                : selectedProviders.concat(provider)
        );
    }

    function getAiSessionProviderOptions(projectDiv) {
        return projectDiv
            ? Array.from(projectDiv.querySelectorAll('[data-ai-provider-option][data-provider]'))
            : [];
    }

    function isAiSessionProvider(provider) {
        return provider === "codex" || provider === "kimi" || provider === "claude";
    }

    function getResumeAiSessionMessageType(provider) {
        if (provider === "kimi")
            return 'resume-kimi-session';
        if (provider === "claude")
            return 'resume-claude-session';

        return 'resume-codex-session';
    }

    function getArchiveAiSessionMessageType(provider) {
        if (provider === "kimi")
            return 'archive-kimi-session';
        if (provider === "claude")
            return 'archive-claude-session';

        return 'archive-codex-session';
    }

    function toggleCodexSessions(projectDiv, projectId) {
        var expanded = !projectDiv.hasAttribute("data-codex-expanded");
        if (!expanded && batchAiSessionState.projectId === projectId) {
            exitAiSessionBatchManagement();
        }
        projectDiv.toggleAttribute("data-codex-expanded", expanded);
        // Keep the CURRENT WINDOW group class in sync so the open-tab fit
        // layout (no :has(), for older webview Chromium) reacts immediately;
        // authoritative group re-renders replay the same class afterwards.
        var currentWorkspaceGroup = projectDiv.closest(".open-current-workspace-group");
        if (currentWorkspaceGroup) {
            currentWorkspaceGroup.classList.toggle("current-card-expanded", expanded);
        }
        updateStickyGroupHeaderOffset();

        window.vscode.postMessage({
            type: 'toggle-codex-sessions',
            projectId,
            expanded,
        });
    }

    function isActiveAiSessionBatchScope(projectId) {
        return projectId === batchAiSessionState.projectId;
    }

    function getProjectActiveAiSessionProvider(projectDiv) {
        if (!projectDiv)
            return null;

        var region = projectDiv.querySelector('[data-ai-session-region]');
        var activeProvider = region && region.getAttribute('data-active-ai-session-provider');
        if (isAiSessionProvider(activeProvider))
            return activeProvider;

        var selectedProviders = region && region.getAttribute('data-selected-ai-session-providers') || '';
        return selectedProviders.split(',').find(isAiSessionProvider) || null;
    }

    function syncAiSessionBatchManagementDom(projectDiv) {
        var snapshot = batchAiSessionManager.snapshot();
        document.querySelectorAll('.project[data-ai-session-managing], .project[data-ai-session-pending]').forEach(project => {
            if (project !== projectDiv || project.getAttribute("data-id") !== snapshot.projectId) {
                project.removeAttribute("data-ai-session-managing");
                project.removeAttribute("data-ai-session-pending");
                syncAiSessionProviderMenuDisabledDom(project, false);
                var inactiveManageButton = project.querySelector('[data-action="manage-ai-sessions"]');
                if (inactiveManageButton) {
                    inactiveManageButton.setAttribute('aria-pressed', 'false');
                    inactiveManageButton.disabled = false;
                }
            }
        });

        if (!projectDiv)
            return;

        var projectId = projectDiv.getAttribute("data-id");
        var isScoped = projectId === snapshot.projectId;
        projectDiv.toggleAttribute("data-ai-session-managing", isScoped);
        projectDiv.toggleAttribute("data-ai-session-pending", isScoped && snapshot.pending);
        syncAiSessionProviderMenuDisabledDom(projectDiv, isScoped && snapshot.pending);
        var manageButton = projectDiv.querySelector('[data-action="manage-ai-sessions"]');
        if (manageButton) {
            manageButton.setAttribute('aria-pressed', isScoped ? 'true' : 'false');
            manageButton.disabled = isScoped && snapshot.pending;
        }

        var selectedItems = new Set(snapshot.selectedItems.map(item =>
            getAiSessionBatchItemKey(item.provider, item.sessionId)
        ));
        projectDiv.querySelectorAll('.ai-session-history-panel .codex-session-row[data-session-id]').forEach(row => {
            var rowProvider = row.getAttribute("data-session-provider") || "codex";
            var isActive = row.hasAttribute('data-session-active');
            var isSelected = isScoped
                && !isActive
                && selectedItems.has(getAiSessionBatchItemKey(
                    rowProvider,
                    row.getAttribute("data-session-id")
                ));
            row.toggleAttribute("data-ai-session-selected", isSelected);
            var checkbox = row.querySelector('.ai-session-batch-checkbox');
            if (checkbox) {
                checkbox.checked = isSelected;
                checkbox.disabled = isActive || (isScoped && snapshot.pending);
            }
        });

        var count = isScoped ? snapshot.selectedItems.length : 0;
        var countElement = projectDiv.querySelector('.ai-session-batch-count');
        if (countElement) {
            countElement.textContent = count + ' selected';
        }
        projectDiv.querySelectorAll('.ai-session-batch-actions button').forEach(button => {
            button.disabled = isScoped && snapshot.pending;
        });
        var archiveButton = projectDiv.querySelector('[data-action="archive-selected-ai-sessions"]');
        if (archiveButton) {
            archiveButton.disabled = !isScoped || snapshot.pending || count === 0;
        }
    }

    function syncAiSessionProviderMenuDisabledDom(projectDiv, batchPending) {
        var projectId = projectDiv?.getAttribute('data-id');
        var providerSelectionPending = projectId
            === pendingAiSessionProviderSelectionProjectId;
        var pending = Boolean(
            batchPending || batchAiSessionState.pending || providerSelectionPending
        );
        var trigger = projectDiv && projectDiv.querySelector('[data-ai-provider-menu-trigger]');
        if (trigger) {
            trigger.disabled = pending;
            trigger.setAttribute('aria-disabled', pending ? 'true' : 'false');
        }
        var selectedProviders = getSelectedAiSessionProviders(projectDiv);
        getAiSessionProviderOptions(projectDiv).forEach(option => {
            var provider = option.getAttribute('data-provider');
            var lastSelectedProvider = selectedProviders.length === 1
                && selectedProviders[0] === provider;
            option.disabled = pending;
            option.setAttribute(
                'aria-disabled',
                pending || lastSelectedProvider ? 'true' : 'false'
            );
        });
        if (pending) {
            closeAiSessionProviderMenu(projectDiv, false);
        }
    }

    function clearPendingAiSessionProviderSelection() {
        pendingAiSessionProviderSelectionProjectId = null;
        pendingAiSessionProviderSelectionRequestId = null;
        pendingAiSessionProviderSelectionProviders = [];
    }

    function selectedAiSessionProvidersMatch(projectDiv, expectedProviders) {
        var selectedProviders = getSelectedAiSessionProviders(projectDiv);
        return selectedProviders.length === expectedProviders.length
            && selectedProviders.every(provider =>
                expectedProviders.includes(provider)
            );
    }

    function reconcilePendingAiSessionProviderSelectionDom() {
        if (!pendingAiSessionProviderSelectionProjectId)
            return;
        var projectDiv = getAiSessionsUpdate().findCurrentWorkspaceDiv(
            pendingAiSessionProviderSelectionProjectId
        );
        if (!projectDiv)
            return;
        if (selectedAiSessionProvidersMatch(
            projectDiv,
            pendingAiSessionProviderSelectionProviders
        )) {
            clearPendingAiSessionProviderSelection();
        }
        syncAiSessionProviderMenuDisabledDom(projectDiv, false);
    }

    function applyAiSessionProviderSelectionResult(message) {
        if (!message
            || message.type !== 'ai-session-provider-selection-result'
            || message.version !== 1
            || !Number.isSafeInteger(message.requestId)
            || message.requestId < 1
            || typeof message.projectId !== 'string'
            || typeof message.success !== 'boolean'
            || message.projectId !== pendingAiSessionProviderSelectionProjectId
            || message.requestId !== pendingAiSessionProviderSelectionRequestId) {
            return false;
        }
        if (message.success) {
            return true;
        }

        var projectDiv = getAiSessionsUpdate().findCurrentWorkspaceDiv(message.projectId);
        clearPendingAiSessionProviderSelection();
        syncAiSessionProviderMenuDisabledDom(projectDiv, false);
        var liveRegion = projectDiv?.querySelector('[data-ai-session-live-region]');
        if (liveRegion) {
            liveRegion.textContent = 'Could not update AI session providers. Try again.';
        }
        return true;
    }

    function exitAiSessionBatchManagement() {
        var projectId = batchAiSessionState.projectId;
        batchAiSessionManager.exit();
        syncAiSessionBatchManagementDom(getAiSessionsUpdate().findCurrentWorkspaceDiv(projectId));
    }

    function getPendingAiSessionProviderSelectionProjectId() {
        return pendingAiSessionProviderSelectionProjectId;
    }

    return {
        batchAiSessionManager: batchAiSessionManager,
        batchAiSessionState: batchAiSessionState,
        applyAiSessionAttentionAcknowledgementResult: applyAiSessionAttentionAcknowledgementResult,
        applyIsolatedSessionSettlement: applyIsolatedSessionSettlement,
        applyManagedWorktreeRemovalSettlement: applyManagedWorktreeRemovalSettlement,
        applySetGroupPrimarySettlement: applySetGroupPrimarySettlement,
        applyWorktreeGroupMergeSettlement: applyWorktreeGroupMergeSettlement,
        applyWorktreeGroupRenameSettlement: applyWorktreeGroupRenameSettlement,
        applyWorktreeGroupDeletionPreview: applyWorktreeGroupDeletionPreview,
        applyWorktreeGroupDeletionSettlement: applyWorktreeGroupDeletionSettlement,
        applyWorktreeAdoptSettlement: applyWorktreeAdoptSettlement,
        setWorktreeGroupForm: setWorktreeGroupForm,
        getPendingAiSessionProviderSelectionProjectId: getPendingAiSessionProviderSelectionProjectId,
        activateAiSessionProviderOption: activateAiSessionProviderOption,
        activateAiSessionWorktreeMenuItem: activateAiSessionWorktreeMenuItem,
        applyAiSessionProviderSelectionResult: applyAiSessionProviderSelectionResult,
        closeAiSessionProviderMenu: closeAiSessionProviderMenu,
        closeAiSessionProviderMenus: closeAiSessionProviderMenus,
        closeAiSessionWorktreeMenu: closeAiSessionWorktreeMenu,
        toggleAiSessionWorktreeMenu: toggleAiSessionWorktreeMenu,
        exitAiSessionBatchManagement: exitAiSessionBatchManagement,
        getAiSessionProviderOptions: getAiSessionProviderOptions,
        getArchiveAiSessionMessageType: getArchiveAiSessionMessageType,
        getResumeAiSessionMessageType: getResumeAiSessionMessageType,
        getSelectedAiSessionProviders: getSelectedAiSessionProviders,
        isAiSessionProvider: isAiSessionProvider,
        onTriggerAiSessionAction: onTriggerAiSessionAction,
        reconcilePendingAiSessionProviderSelectionDom: reconcilePendingAiSessionProviderSelectionDom,
        reconcileAiSessionAttentionAcknowledgements: reconcileAiSessionAttentionAcknowledgements,
        setAiSessionProviderMenuOpen: setAiSessionProviderMenuOpen,
        submitAiSessionProviderSelection: submitAiSessionProviderSelection,
        syncAiSessionBatchManagementDom: syncAiSessionBatchManagementDom,
        toggleAiSessionProviderMenu: toggleAiSessionProviderMenu,
        toggleCodexSessions: toggleCodexSessions,
    };
}

/* src/webview/webviewProjectScripts.js */
function getAiSessionCardActivation(target, projectId) {
    if (!target || typeof target.closest !== 'function') {
        return { handled: false, sessionRow: null, message: null };
    }
    var primarySessionAction = target.closest('[data-action="activate-ai-session"]');
    var interactiveSessionChild = target.closest(
        'button, input, select, textarea, a[href], [data-action]'
    );
    var activationSessionRow = primarySessionAction
        ? primarySessionAction.closest('.codex-session-row')
        : (!interactiveSessionChild ? target.closest('.codex-session-row') : null);
    if (!activationSessionRow) {
        return {
            handled: !!target.closest('.codex-session-row'),
            sessionRow: null,
            message: null,
        };
    }

    var provider = activationSessionRow.getAttribute('data-session-provider') || 'codex';
    var supportedProvider = provider === 'codex' || provider === 'kimi' || provider === 'claude';
    if (activationSessionRow.hasAttribute('data-session-pending')) {
        var createdAt = activationSessionRow.getAttribute('data-pending-created-at');
        return {
            handled: true,
            sessionRow: activationSessionRow,
            message: supportedProvider && createdAt ? {
                type: 'focus-pending-ai-session',
                projectId: projectId,
                provider: provider,
                createdAt: createdAt,
            } : null,
        };
    }

    var sessionId = activationSessionRow.getAttribute('data-session-id');
    if (!sessionId || !supportedProvider) {
        return { handled: true, sessionRow: activationSessionRow, message: null };
    }
    if (activationSessionRow.hasAttribute('data-session-active')) {
        if (activationSessionRow.hasAttribute('data-session-focused')) {
            return {
                handled: true,
                sessionRow: activationSessionRow,
                message: {
                    type: 'open-active-ai-session-conversation',
                    version: 1,
                    projectId: projectId,
                    provider: provider,
                    sessionId: sessionId,
                },
            };
        }
        return {
            handled: true,
            sessionRow: activationSessionRow,
            message: {
                type: 'focus-ai-session-terminal',
                projectId: projectId,
                provider: provider,
                sessionId: sessionId,
            },
        };
    }
    return {
        handled: true,
        sessionRow: activationSessionRow,
        message: {
            type: provider === 'kimi'
                ? 'resume-kimi-session'
                : provider === 'claude'
                    ? 'resume-claude-session'
                    : 'resume-codex-session',
            projectId: projectId,
            sessionId: sessionId,
        },
    };
}

var MAX_AI_SESSION_BATCH_ARCHIVE_RESULT_COUNT = 100;

function getBoundedAiSessionBatchArchiveResultCounts(result) {
    if (!result || typeof result !== 'object' || Array.isArray(result)) {
        return null;
    }
    var arrayFields = ['archived', 'running', 'missing', 'rejected', 'failed'];
    if (arrayFields.some(field =>
        !Array.isArray(result[field])
        || result[field].length > MAX_AI_SESSION_BATCH_ARCHIVE_RESULT_COUNT
    )) {
        return null;
    }
    if (!Number.isSafeInteger(result.rejectedCount)
        || result.rejectedCount < result.rejected.length
        || !Number.isSafeInteger(result.malformedCount)
        || result.rejectedCount < 0
        || result.malformedCount < 0) {
        return null;
    }
    var counts = {
        archived: result.archived.length,
        running: result.running.length,
        missing: result.missing.length,
        rejected: result.rejectedCount + result.malformedCount,
        failed: result.failed.length,
    };
    var total = Object.values(counts).reduce((sum, count) => sum + count, 0);
    if (!Number.isSafeInteger(total)
        || total > MAX_AI_SESSION_BATCH_ARCHIVE_RESULT_COUNT) {
        return null;
    }
    return counts;
}

function formatAiSessionBatchArchiveCount(count, singular, plural) {
    return count + ' ' + (count === 1 ? singular : plural);
}

function getAiSessionBatchArchiveAnnouncement(message) {
    if (message.status === 'cancelled') {
        return 'Archive cancelled. No sessions were archived.';
    }
    if (message.status === 'rejected') {
        return 'Archive request was rejected. No sessions were archived.';
    }
    var counts = getBoundedAiSessionBatchArchiveResultCounts(message.result);
    if (!counts) {
        return 'Archive completed, but its result summary was unavailable.';
    }
    var parts = [
        'Archived ' + formatAiSessionBatchArchiveCount(
            counts.archived,
            'AI session',
            'AI sessions'
        ),
    ];
    if (counts.running) {
        parts.push('skipped ' + formatAiSessionBatchArchiveCount(
            counts.running,
            'running session',
            'running sessions'
        ));
    }
    if (counts.missing) {
        parts.push(formatAiSessionBatchArchiveCount(
            counts.missing,
            'session was',
            'sessions were'
        ) + ' no longer available');
    }
    if (counts.rejected) {
        parts.push(formatAiSessionBatchArchiveCount(
            counts.rejected,
            'invalid or out-of-scope selection was rejected',
            'invalid or out-of-scope selections were rejected'
        ));
    }
    if (counts.failed) {
        parts.push(formatAiSessionBatchArchiveCount(
            counts.failed,
            'session failed',
            'sessions failed'
        ));
    }
    return parts.join('; ') + '.';
}

function initProjects() {

    const ProjectOpenType = {
        Default: 0,
        NewWindow: 1,
        AddToWorkspace: 2,
        CurrentWindow: 3,
    };

    function openProject(projectId, projectOpenType) {
        window.vscode.postMessage({
            type: 'selected-project',
            projectId,
            projectOpenType,
        });
    }

    function onAddProjectClicked(e) {
        if (!e.target)
            return;

        var projectDiv = e.target.closest('.project');
        if (!projectDiv)
            return;

        var groupId = projectDiv.getAttribute("data-group-id");

        window.vscode.postMessage({
            type: 'add-project',
            groupId,
        });
    }

    function onImportFromOtherStorageClicked(e) {
        if (!e.target)
            return;

        window.vscode.postMessage({
            type: 'import-from-other-storage',
        });
    }

    function onInsideOpenWindowRowClick(e, row) {
        // PRD 单击语义：非当前行 = 聚焦该 OS 窗口（走导航请求协议）；当前行 =
        // 空操作；双击/中键 = 无行为。★/⋯/重试按钮在各行内单独处理，不触发行点击。
        if (e.button !== 0 || e.detail > 1) {
            return;
        }
        var pinButton = e.target.closest('[data-action="toggle-open-workspace-pin"]');
        if (pinButton) {
            e.preventDefault();
            e.stopPropagation();
            if (typeof requestOpenWorkspacePin === 'function') {
                requestOpenWorkspacePin(pinButton, row.getAttribute('data-id'));
            }
            return;
        }
        var menuButton = e.target.closest('[data-action="open-window-menu"]');
        if (menuButton) {
            e.preventDefault();
            e.stopPropagation();
            if (window.__agentPivotOpenWindowNavigation) {
                window.__agentPivotOpenWindowNavigation.toggleMenu(menuButton);
            }
            return;
        }
        if (e.target.closest('[data-action="retry-open-window-navigation"]')) {
            e.preventDefault();
            e.stopPropagation();
            if (window.__agentPivotOpenWindowNavigation) {
                window.__agentPivotOpenWindowNavigation.retry(row.getAttribute('data-id'));
            }
            return;
        }
        var focusButton = e.target.closest('[data-action="focus-open-window"]');
        if (!focusButton || !row.contains(focusButton)) {
            return;
        }
        if (focusButton.getAttribute('aria-disabled') === 'true') {
            return;
        }
        e.preventDefault();
        e.stopPropagation();
        if (window.__agentPivotOpenWindowNavigation) {
            window.__agentPivotOpenWindowNavigation.request(row.getAttribute('data-id'));
        }
    }

    function onInsideProjectClick(e, projectDiv) {
        projectDiv = projectDiv || e.target.closest(".project");
        var dataId = projectDiv && projectDiv.getAttribute("data-id");
        if (dataId == null)
            return;

        if (worktreeGroupForm.onClick(e.target, projectDiv, dataId))
            return;

        if (aiSessionControls.onTriggerAiSessionAction(e.target, dataId))
            return;

        if (contextMenus.onTriggerProjectAction(e.target, dataId))
            return;

        if (projectDiv.hasAttribute("data-current-workspace")) {
            if (e.target.closest('[data-ai-session-region]'))
                return;

            aiSessionControls.toggleCodexSessions(projectDiv, dataId);
            return;
        }

        var currentWindow = e.ctrlKey || e.metaKey;
        var newWindow = e.button === 1;
        openProject(dataId, currentWindow ? ProjectOpenType.CurrentWindow : newWindow ? ProjectOpenType.NewWindow : ProjectOpenType.Default);

    }


    var groupCollapse = initProjectGroupCollapse();
    var todoControls = initProjectTodoControls({
        syncCollapseButton: () => groupCollapse.syncCollapseButton(),
    });
    var aiSessionPresentationStateStore = null;
    var aiSessionControls = initProjectAiSessionControls({
        getAiSessionsUpdate: () => aiSessionsUpdate,
        getAiSessionPresentationStateStore: () => aiSessionPresentationStateStore,
        updateStickyGroupHeaderOffset: updateStickyGroupHeaderOffset,
    });
    window.__agentPivotContextMenus = null;
    var contextMenus = initProjectContextMenus({
        openProject: openProject,
        ProjectOpenType: ProjectOpenType,
        getResumeAiSessionMessageType: aiSessionControls.getResumeAiSessionMessageType,
        getArchiveAiSessionMessageType: aiSessionControls.getArchiveAiSessionMessageType,
        isAiSessionProvider: aiSessionControls.isAiSessionProvider,
    });
    window.__agentPivotContextMenus = contextMenus;
    aiSessionPresentationStateStore = initAiSessionPresentationStateStore({
        isAiSessionProvider: aiSessionControls.isAiSessionProvider,
    });
    var aiSessionPresentationDom = initAiSessionPresentationDom({
        presentationStateStore: aiSessionPresentationStateStore,
    });
    var presentationTransactions = initAiSessionPresentationTransactions({
        isValidAiSessionPresentationState: aiSessionPresentationStateStore.isValid,
        canApplyAiSessionPresentationState: aiSessionPresentationDom.canApply,
        applyValidatedAiSessionPresentationState: applyValidatedAiSessionPresentationState,
    });
    var aiSessionsUpdate = initProjectAiSessionsUpdate({
        batchAiSessionState: aiSessionControls.batchAiSessionState,
        batchAiSessionManager: aiSessionControls.batchAiSessionManager,
        getPendingAiSessionProviderSelectionProjectId: () => aiSessionControls.getPendingAiSessionProviderSelectionProjectId(),
        getSelectedAiSessionProviders: aiSessionControls.getSelectedAiSessionProviders,
        syncAiSessionBatchManagementDom: aiSessionControls.syncAiSessionBatchManagementDom,
        reconcilePendingAiSessionProviderSelectionDom: aiSessionControls.reconcilePendingAiSessionProviderSelectionDom,
        reconcileWorktreeGroupFormDom: () => worktreeGroupForm.reconcileDom(),
        submitAiSessionProviderSelection: aiSessionControls.submitAiSessionProviderSelection,
        toggleCodexSessions: aiSessionControls.toggleCodexSessions,
        exitAiSessionBatchManagement: aiSessionControls.exitAiSessionBatchManagement,
        isAiSessionProvider: aiSessionControls.isAiSessionProvider,
        updateStickyGroupHeaderOffset: updateStickyGroupHeaderOffset,
        presentationTransactions: presentationTransactions,
    });
    var worktreeGroupForm = initWorktreeGroupForm({
        findCurrentWorkspaceDiv: projectId =>
            aiSessionsUpdate.findCurrentWorkspaceDiv(projectId),
    });
    aiSessionControls.setWorktreeGroupForm(worktreeGroupForm);
    // The authoritative update paths capture the open form's focus through
    // this global before replacing the DOM (same convention as
    // window.__agentPivotWorktreeGroupRename).
    window.__agentPivotWorktreeGroupForm = worktreeGroupForm;

    function applyValidatedAiSessionPresentationState(message) {
        if (!aiSessionPresentationStateStore.adopt(message)) return;
        aiSessionPresentationDom.apply(message);
        aiSessionControls.reconcileAiSessionAttentionAcknowledgements();
        // Track the worktree-group aggregate revision the webview has
        // actually rendered (PRD §6.4 decision J): deletion settlements
        // bind a minimum revision, and pending UI may only clear once a
        // presentation at or beyond it has been applied.
        if (typeof message.worktreeGroupsAggregateRevision === 'number'
            && message.workspaceNavigationIdentity) {
            var applied = window.__agentPivotWorktreeGroupAggregateRevision
                || { identity: '', revision: 0 };
            if (applied.identity !== message.workspaceNavigationIdentity
                || message.worktreeGroupsAggregateRevision > applied.revision) {
                window.__agentPivotWorktreeGroupAggregateRevision = {
                    identity: message.workspaceNavigationIdentity,
                    revision: message.worktreeGroupsAggregateRevision,
                };
            }
        }
    }

    function readInitialAiSessionPresentationState() {
        var element = document.getElementById('dashboard-ai-session-presentation');
        if (!element) return null;
        try {
            return JSON.parse(element.textContent || '');
        } catch (_error) {
            return {};
        }
    }

    var initialAiSessionPresentationState = readInitialAiSessionPresentationState();
    if (initialAiSessionPresentationState) {
        presentationTransactions.applyInitialPresentation(
            initialAiSessionPresentationState
        );
    }

    function activateAiSessionCreateDropdownItem(menuItem) {
        var action = menuItem.getAttribute("data-action");
        var dropdownMenu = document.getElementById('aiSessionCreateDropdown');
        var projectId = dropdownMenu
            ? dropdownMenu.getAttribute('data-dropdown-project-id') || ''
            : '';
        if (action === "create-ai-session-quick") {
            var provider = menuItem.getAttribute("data-provider");
            if (provider) {
                window.vscode.postMessage({
                    type: "create-ai-session-quick",
                    projectId: projectId,
                    provider: provider,
                });
            }
        } else if (action === "create-ai-session") {
            window.vscode.postMessage({
                type: "create-ai-session",
                projectId: projectId,
            });
        }
        contextMenus.closeContextMenus();
    }

    function onMouseEvent(e) {
        if (!e.target || e.target.closest(".disabled"))
            return;
        if (todoControls.isDedicatedTodoTarget(e.target))
            return;

        var contextMenuElement = e.target.closest("#projectContextMenu [data-action]");
        if (contextMenuElement) {
            contextMenus.onProjectContextMenuActionClicked(contextMenuElement);
            return;
        }

        contextMenuElement = e.target.closest("#aiSessionContextMenu [data-action]");
        if (contextMenuElement) {
            contextMenus.onAiSessionContextMenuActionClicked(contextMenuElement);
            return;
        }

        contextMenuElement = e.target.closest("#aiSessionCreateDropdown [data-action]");
        if (contextMenuElement) {
            activateAiSessionCreateDropdownItem(contextMenuElement);
            return;
        }

        contextMenuElement = e.target.closest("#aiSessionWorktreeMenu [data-action]");
        if (contextMenuElement) {
            aiSessionControls.activateAiSessionWorktreeMenuItem(contextMenuElement);
            return;
        }

        contextMenuElement = e.target.closest("#groupContextMenu [data-action]");
        if (contextMenuElement) {
            contextMenus.onGroupContextMenuActionClicked(contextMenuElement);
            return;
        }

        // The create-dropdown arrow owns its toggle: the generic close would
        // hide the menu before the arrow handler can see it was open.
        if (!e.target.closest('[data-action="create-ai-session-dropdown"]')
            && !e.target.closest('[data-action="ai-session-worktree-menu"]')) {
            contextMenus.closeContextMenus();
        }
        if (!e.target.closest('.ai-session-provider-menu-wrapper')) {
            aiSessionControls.closeAiSessionProviderMenus();
        }

        if (e.target.closest('[data-action="toggle-all-groups"]')) {
            groupCollapse.toggleAllGroups();
            return;
        }

        if (e.target.closest('[data-action="sponsor"]')) {
            window.vscode.postMessage({
                type: 'sponsor'
            });
            return;
        }

        if (e.target.closest('[data-action="open-settings"]')) {
            window.vscode.postMessage({
                type: 'open-settings'
            });
            return;
        }

        if (e.target.closest('[data-action="open-bridge-extension"]')) {
            window.vscode.postMessage({
                type: 'open-bridge-extension'
            });
            return;
        }

        if (e.target.closest('[data-action="add-group"]')) {
            window.vscode.postMessage({
                type: 'add-group'
            });
            return;
        }

        if (e.target.closest('[data-action="add-project"]')) {
            onAddProjectClicked(e);
            return;
        }

        if (e.target.closest('[data-action="import-from-other-storage"]')) {
            onImportFromOtherStorageClicked(e);
            return;
        }

        if (todoControls.onTodoAction(e)) {
            return;
        }

        var todoItem = e.target.closest('.todo-item[data-todo-id]');
        if (todoItem && !todoItem.classList.contains('editing') && !todoControls.isTodoInteractiveTarget(e.target)) {
            todoControls.toggleTodoItemExpanded(todoItem);
            return;
        }

        var projectDiv = e.target.closest('.project');
        if (projectDiv) {
            onInsideProjectClick(e, projectDiv);
            return;
        }

        var openWindowRow = e.target.closest
            ? e.target.closest('[data-open-window-row]')
            : null;
        if (openWindowRow) {
            onInsideOpenWindowRowClick(e, openWindowRow);
            return;
        }

        var groupDiv = e.target.closest('.group');
        if (groupDiv) {
            todoControls.onInsideGroupClick(e, groupDiv);
            return;
        }
    }

    function onChangeEvent(e) {
        if (!e.target)
            return;
        if (todoControls.isDedicatedTodoTarget(e.target))
            return;

        var todoPriorityInput = e.target.closest('.todo-priority-choice input[name="priority"]');
        if (todoPriorityInput) {
            todoControls.syncTodoPrioritySegment(todoPriorityInput.closest('.todo-priority-segment'));
            return;
        }

    }

    function updateStickyGroupHeaderOffset() {
        window.requestAnimationFrame(() => {
            var stickyHeader = document.querySelector('.steward-sticky-header');
            var offset = stickyHeader ? Math.ceil(stickyHeader.getBoundingClientRect().height) : 0;
            document.body.style.setProperty('--steward-sticky-header-height', offset + 'px');
        });
    }

    function onWindowMessage(e) {
        var message = e && e.data;
        if (message
            && message.type === 'focus-ai-session-conversation-origin') {
            focusAiSessionConversationOrigin(message);
            return;
        }
        if (message
            && message.type === 'reveal-ai-session-requested') {
            revealAiSessionInWorkspace(message);
            return;
        }
        if (message && message.type === 'todo-mutation-result') {
            applyTodoMutationResult(message, document);
            return;
        }
        if (message && message.type === 'ai-session-provider-selection-result') {
            aiSessionControls.applyAiSessionProviderSelectionResult(message);
            return;
        }
        if (message && message.type === 'ai-session-attention-acknowledgement-result') {
            aiSessionControls.applyAiSessionAttentionAcknowledgementResult(message);
            return;
        }
        if (message && (message.type === 'todo-panel-content' || message.type === 'todo-panel-updated')) {
            window.setTimeout(() => {
                var todoRoot = document.querySelector('#dashboard-tab-todo');
                if (todoRoot && typeof initDnD === 'function' && typeof disposeDnD === 'function') {
                    disposeDnD(todoRoot);
                    initDnD(todoRoot);
                    groupCollapse.syncCollapseButton();
                }
            }, 0);
        }
        if (message && message.type === 'open-workspaces-updated') {
            if (message.version !== 4) {
                aiSessionsUpdate.requestFullRefresh(
                    'unsupported-open-workspaces-message'
                );
                return;
            }
            if (!presentationTransactions.applyAtomicEnvelope({
                message: message,
                invalidPresentationReason: 'invalid-open-workspaces-presentation-envelope',
                invalidReplacementReason: 'invalid-open-workspaces-update',
                replaceContent: validateReplacement => applyOpenWorkspacesUpdate(
                    message,
                    { validateReplacement: validateReplacement }
                ),
            })) {
                return;
            }
            // applyOpenWorkspacesUpdate replaces the whole wrapper,
            // including the form slot: re-render any open creation form.
            worktreeGroupForm.reconcileDom();
            updateStickyGroupHeaderOffset();
            if (window.__agentPivotOpenWindowNavigation) {
                window.__agentPivotOpenWindowNavigation.reconcile(document);
            }
            var renderedOpenWorkspaceState = getOpenWorkspacesUpdateDomState();
            window.vscode.postMessage({
                type: 'open-workspaces-rendered',
                version: 3,
                semanticRevision: message.semanticRevision,
                windowRowCount: renderedOpenWorkspaceState.windowRowCount,
                currentWindowRowCount: renderedOpenWorkspaceState.currentWindowRowCount,
                navigationWindowRowCount: renderedOpenWorkspaceState.navigationWindowRowCount,
                currentDetailCount: renderedOpenWorkspaceState.currentDetailCount,
                hasWindowSwitcher: renderedOpenWorkspaceState.hasWindowSwitcher,
                otherWindowsStatus: renderedOpenWorkspaceState.otherWindowsStatus,
            });
            return;
        }
        if (message && message.type === 'open-workspace-pin-result') {
            completeOpenWorkspacePin(message);
            return;
        }
        if (message && message.type === 'open-window-navigation-result') {
            if (window.__agentPivotOpenWindowNavigation) {
                window.__agentPivotOpenWindowNavigation.complete(message);
            }
            return;
        }
        if (message && message.type === 'ai-session-tab-selection-requested') {
            var requestedProject = aiSessionsUpdate.findCurrentWorkspaceDiv(message.projectId);
            if (requestedProject && (message.tab === 'active' || message.tab === 'sessions')) {
                selectAiSessionTabDom(requestedProject, message.tab);
                writeAiSessionTabState(window.vscode, message.projectId, message.tab);
            }
            return;
        }

        if (message && message.type === 'ai-session-status-announcement') {
            var announcementProject = aiSessionsUpdate.findCurrentWorkspaceDiv(message.projectId);
            var announcement = typeof message.message === 'string' ? message.message.trim().slice(0, 256) : '';
            var announcementRegion = announcementProject && announcementProject.querySelector('[data-ai-session-live-region]');
            if (announcementRegion && announcement) announcementRegion.textContent = announcement;
            return;
        }

        if (message && message.type === 'ai-session-presentation-state') {
            presentationTransactions.applyDirectPresentation(message);
            return;
        }

        if (message && message.type === 'ai-session-batch-archive-completed') {
            if (aiSessionControls.batchAiSessionManager.complete(message)) {
                var completedProject = aiSessionsUpdate.findCurrentWorkspaceDiv(message.projectId);
                aiSessionControls.syncAiSessionBatchManagementDom(completedProject);
                var archiveLiveRegion = completedProject
                    && completedProject.querySelector('[data-ai-session-live-region]');
                if (archiveLiveRegion) {
                    archiveLiveRegion.textContent =
                        getAiSessionBatchArchiveAnnouncement(message);
                }
            }
            return;
        }

        if (message && message.type === 'isolated-session-settlement') {
            aiSessionControls.applyIsolatedSessionSettlement(message);
            return;
        }

        if (message && message.type === 'managed-worktree-removal-settlement') {
            aiSessionControls.applyManagedWorktreeRemovalSettlement(message);
            return;
        }

        if (message && message.type === 'worktree-group-merge-settlement') {
            aiSessionControls.applyWorktreeGroupMergeSettlement(message);
            return;
        }

        if (message && message.type === 'worktree-group-primary-settlement') {
            aiSessionControls.applySetGroupPrimarySettlement(message);
            return;
        }

        if (message && message.type === 'worktree-group-rename-settlement') {
            aiSessionControls.applyWorktreeGroupRenameSettlement(message);
            return;
        }

        if (message && message.type === 'worktree-group-deletion-preview') {
            aiSessionControls.applyWorktreeGroupDeletionPreview(message);
            return;
        }

        if (message && message.type === 'worktree-group-deletion-settlement') {
            aiSessionControls.applyWorktreeGroupDeletionSettlement(message);
            return;
        }

        if (message && message.type === 'worktree-adopt-settlement') {
            aiSessionControls.applyWorktreeAdoptSettlement(message);
            return;
        }

        if (message && message.type === 'worktree-group-form-state') {
            worktreeGroupForm.applyFormState(message);
            return;
        }

        if (message && message.type === 'worktree-group-preview') {
            worktreeGroupForm.applyPreview(message);
            return;
        }

        if (message && message.type === 'worktree-group-creation-settlement') {
            worktreeGroupForm.applyCreationSettlement(message);
            return;
        }

        if (message && message.type === 'worktree-group-member-settlement') {
            worktreeGroupForm.applyMemberSettlement(message);
            return;
        }

        if (!message || message.type !== 'ai-sessions-updated') {
            return;
        }

        aiSessionsUpdate.applyAiSessionsUpdate(message);
    }

    function observeStickyGroupHeaderOffset() {
        updateStickyGroupHeaderOffset();
        window.addEventListener('resize', updateStickyGroupHeaderOffset);

        var stickyHeader = document.querySelector('.steward-sticky-header');
        if (stickyHeader && typeof ResizeObserver !== 'undefined') {
            var observer = new ResizeObserver(updateStickyGroupHeaderOffset);
            observer.observe(stickyHeader);
            window.__stewardStickyHeaderObserver = observer;
        }
    }

    // Middle mouse button requires mousedown, as it does not fire click event when scroll option is available.
    document.addEventListener('click', (e) => {
        if (e.button !== 1) {
            onMouseEvent(e);
        }
    });

    // VS Code forwards no outside clicks into the webview: dismiss open
    // menus when the sidebar loses focus instead (e.g. editor clicks).
    window.addEventListener('blur', () => {
        contextMenus.closeContextMenus();
        aiSessionControls.closeAiSessionWorktreeMenu();
    });

    document.addEventListener('change', onChangeEvent);
    document.addEventListener('submit', e => todoControls.onTodoFormSubmit(e));

    document.addEventListener('mousedown', (e) => {
        if (e.target.closest('.codex-session-row')) {
            return;
        }

        if (e.button === 1) {
            onMouseEvent(e);
        }
    });

    document.addEventListener('contextmenu', (e) => {
        if (!e.target)
            return;

        contextMenus.onContextMenu(e);
    });

    document.addEventListener("keydown", e => {
        var worktreeHeader = e.target && e.target.closest
            ? e.target.closest('.ai-session-worktree-header')
            : null;
        if (worktreeHeader
            && (e.key === 'ArrowDown' || e.key === 'ArrowUp'
                || e.key === 'Home' || e.key === 'End')) {
            var worktreePanel = worktreeHeader.closest('[data-ai-session-panel]');
            var worktreeHeaders = worktreePanel
                ? Array.from(worktreePanel.querySelectorAll('.ai-session-worktree-header'))
                : [];
            var worktreeHeaderIndex = worktreeHeaders.indexOf(worktreeHeader);
            if (worktreeHeaderIndex >= 0 && worktreeHeaders.length) {
                e.preventDefault();
                var nextWorktreeHeaderIndex = e.key === 'Home' ? 0
                    : e.key === 'End' ? worktreeHeaders.length - 1
                        : (worktreeHeaderIndex + (e.key === 'ArrowDown' ? 1 : -1)
                            + worktreeHeaders.length) % worktreeHeaders.length;
                worktreeHeaders[nextWorktreeHeaderIndex]?.focus();
            }
            return;
        }
        var aiSessionProviderTrigger = e.target && e.target.closest
            ? e.target.closest('[data-ai-provider-menu-trigger]')
            : null;
        if (aiSessionProviderTrigger
            && (e.key === 'ArrowDown' || e.key === 'ArrowUp'
                || e.key === 'Home' || e.key === 'End')) {
            e.preventDefault();
            var triggerProject = aiSessionProviderTrigger.closest('.project[data-id]');
            aiSessionControls.closeAiSessionProviderMenus(triggerProject);
            aiSessionControls.setAiSessionProviderMenuOpen(triggerProject, true);
            var triggerOptions = aiSessionControls.getAiSessionProviderOptions(triggerProject);
            var triggerOptionIndex = e.key === 'ArrowUp' || e.key === 'End'
                ? triggerOptions.length - 1
                : 0;
            triggerOptions[triggerOptionIndex]?.focus();
            return;
        }
        if (aiSessionProviderTrigger && e.key === 'Escape') {
            e.preventDefault();
            aiSessionControls.closeAiSessionProviderMenu(
                aiSessionProviderTrigger.closest('.project[data-id]'),
                true
            );
            return;
        }

        var aiSessionProviderOption = e.target && e.target.closest
            ? e.target.closest('[data-ai-provider-option][data-provider]')
            : null;
        if (aiSessionProviderOption) {
            var providerProject = aiSessionProviderOption.closest('.project[data-id]');
            var providerOptions = aiSessionControls.getAiSessionProviderOptions(providerProject);
            var providerOptionIndex = providerOptions.indexOf(aiSessionProviderOption);
            if (e.key === 'ArrowDown' || e.key === 'ArrowUp'
                || e.key === 'Home' || e.key === 'End') {
                e.preventDefault();
                var nextProviderOptionIndex = e.key === 'Home' ? 0
                    : e.key === 'End' ? providerOptions.length - 1
                        : (providerOptionIndex + (e.key === 'ArrowDown' ? 1 : -1)
                            + providerOptions.length) % providerOptions.length;
                providerOptions[nextProviderOptionIndex]?.focus();
                return;
            }
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                aiSessionControls.activateAiSessionProviderOption(providerProject, aiSessionProviderOption);
                return;
            }
            if (e.key === 'Escape') {
                e.preventDefault();
                aiSessionControls.closeAiSessionProviderMenu(providerProject, true);
                return;
            }
            if (e.key === 'Tab') {
                aiSessionControls.closeAiSessionProviderMenu(providerProject, false);
            }
        }

        var aiSessionMenuItem = e.target && e.target.closest
            ? e.target.closest('#aiSessionContextMenu [role="menuitem"]')
            : null;
        if (aiSessionMenuItem) {
            var aiSessionMenu = aiSessionMenuItem.closest('#aiSessionContextMenu');
            var enabledMenuItems = Array.from(aiSessionMenu.querySelectorAll('[role="menuitem"]'))
                .filter(item => !item.classList.contains('disabled'));
            var currentMenuIndex = enabledMenuItems.indexOf(aiSessionMenuItem);
            if (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'Home' || e.key === 'End') {
                e.preventDefault();
                var nextMenuIndex = e.key === 'Home' ? 0
                    : e.key === 'End' ? enabledMenuItems.length - 1
                        : (currentMenuIndex + (e.key === 'ArrowDown' ? 1 : -1) + enabledMenuItems.length)
                            % enabledMenuItems.length;
                enabledMenuItems[nextMenuIndex]?.focus();
                return;
            }
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                contextMenus.onAiSessionContextMenuActionClicked(aiSessionMenuItem);
                return;
            }
            if (e.key === 'Escape') {
                e.preventDefault();
                var menuOrigin = contextMenus.getAiSessionContextMenuOrigin();
                contextMenus.closeContextMenus();
                menuOrigin?.focus();
                return;
            }
            if (e.key === 'Tab') {
                contextMenus.closeContextMenus();
            }
        }

        var aiSessionCreateItem = e.target && e.target.closest
            ? e.target.closest('#aiSessionCreateDropdown [role="menuitem"]')
            : null;
        if (aiSessionCreateItem) {
            var createMenu = aiSessionCreateItem.closest('#aiSessionCreateDropdown');
            var createItems = Array.from(createMenu.querySelectorAll('[role="menuitem"]'));
            var createIndex = createItems.indexOf(aiSessionCreateItem);
            if (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'Home' || e.key === 'End') {
                e.preventDefault();
                var nextCreateIndex = e.key === 'Home' ? 0
                    : e.key === 'End' ? createItems.length - 1
                        : (createIndex + (e.key === 'ArrowDown' ? 1 : -1) + createItems.length)
                            % createItems.length;
                createItems[nextCreateIndex]?.focus();
                return;
            }
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                activateAiSessionCreateDropdownItem(aiSessionCreateItem);
                return;
            }
            if (e.key === 'Escape') {
                e.preventDefault();
                var createOrigin = createMenu.__originButton || null;
                createMenu.__originButton = null;
                contextMenus.closeContextMenus();
                createOrigin?.focus();
                return;
            }
            if (e.key === 'Tab') {
                contextMenus.closeContextMenus();
            }
        }

        var worktreeMenuItem = e.target && e.target.closest
            ? e.target.closest('#aiSessionWorktreeMenu [role="menuitem"]')
            : null;
        if (worktreeMenuItem) {
            var worktreeMenu = worktreeMenuItem.closest('#aiSessionWorktreeMenu');
            var worktreeItems = Array.from(
                worktreeMenu.querySelectorAll('[role="menuitem"]:not([hidden])')
            );
            var worktreeIndex = worktreeItems.indexOf(worktreeMenuItem);
            if (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'Home' || e.key === 'End') {
                e.preventDefault();
                var nextWorktreeIndex = e.key === 'Home' ? 0
                    : e.key === 'End' ? worktreeItems.length - 1
                        : (worktreeIndex + (e.key === 'ArrowDown' ? 1 : -1) + worktreeItems.length)
                            % worktreeItems.length;
                worktreeItems[nextWorktreeIndex]?.focus();
                return;
            }
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                aiSessionControls.activateAiSessionWorktreeMenuItem(worktreeMenuItem);
                return;
            }
            if (e.key === 'Escape') {
                e.preventDefault();
                var worktreeOrigin = worktreeMenu.__originButton || null;
                aiSessionControls.closeAiSessionWorktreeMenu();
                worktreeOrigin?.focus();
                return;
            }
            if (e.key === 'Tab') {
                aiSessionControls.closeAiSessionWorktreeMenu();
            }
        }

        var surfaceTab = e.target && e.target.closest
            ? e.target.closest('[data-ai-session-surface-tab]')
            : null;
        if (surfaceTab && ['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(e.key)) {
            e.preventDefault();
            var nextSurfaceId = getAdjacentAiSessionSurface(
                surfaceTab.getAttribute('data-ai-session-surface-tab'),
                e.key
            );
            var surfaceProject = surfaceTab.closest('.project[data-id]');
            var nextSurface = surfaceProject
                && Array.from(surfaceProject.querySelectorAll('[data-ai-session-surface-tab]'))
                    .find(candidate =>
                        candidate.getAttribute('data-ai-session-surface-tab') === nextSurfaceId
                    );
            nextSurface?.focus();
            return;
        }
        if (surfaceTab && (e.key === 'Enter' || e.key === ' ')) {
            e.preventDefault();
            var surfaceTabProject = surfaceTab.closest('.project[data-id]');
            var surfaceTabProjectId = surfaceTabProject
                && surfaceTabProject.getAttribute('data-id');
            if (surfaceTabProjectId) {
                aiSessionControls.onTriggerAiSessionAction(surfaceTab, surfaceTabProjectId);
            }
            return;
        }

        var tab = e.target && e.target.closest ? e.target.closest('[data-ai-session-tab]') : null;
        if (tab && ['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(e.key)) {
            e.preventDefault();
            var nextTabId = getAdjacentAiSessionTab(tab.getAttribute('data-ai-session-tab'), e.key);
            var projectDiv = tab.closest('.project[data-id]');
            var nextTab = projectDiv && Array.from(projectDiv.querySelectorAll('[data-ai-session-tab]'))
                .find(candidate => candidate.getAttribute('data-ai-session-tab') === nextTabId);
            nextTab?.focus();
            return;
        }
        if (tab && (e.key === 'Enter' || e.key === ' ')) {
            e.preventDefault();
            var tabProject = tab.closest('.project[data-id]');
            var tabProjectId = tabProject && tabProject.getAttribute('data-id');
            if (tabProjectId) aiSessionControls.onTriggerAiSessionAction(tab, tabProjectId);
            return;
        }

        var sessionRow = e.target && e.target.closest ? e.target.closest('.codex-session-row') : null;
        var interactiveChild = e.target && e.target.closest
            ? e.target.closest('button, input, select, textarea, a[href]')
            : null;
        var primarySessionAction = e.target && e.target.closest
            ? e.target.closest('.ai-session-primary-action') : null;
        if (sessionRow && (!interactiveChild || primarySessionAction)
            && (e.key === 'ContextMenu' || (e.key === 'F10' && e.shiftKey))) {
            e.preventDefault();
            var sessionRowRect = sessionRow.getBoundingClientRect();
            contextMenus.onContextMenu({
                target: primarySessionAction || sessionRow,
                preventDefault: () => {},
                clientX: sessionRowRect.left + 8,
                clientY: sessionRowRect.top + 8,
                keyboardTrigger: true,
            });
            return;
        }
        if (e.key === "Escape") {
            var editForm = e.target && e.target.closest ? e.target.closest('.todo-edit-form') : null;
            if (editForm) {
                e.preventDefault();
                todoControls.setTodoEditing(editForm.getAttribute('data-todo-id'), false);
                return;
            }
            contextMenus.closeContextMenus();
            if (aiSessionControls.batchAiSessionState.projectId && !aiSessionControls.batchAiSessionState.pending) {
                aiSessionControls.exitAiSessionBatchManagement();
            }
        }
    });

    window.addEventListener('message', onWindowMessage);
    window.vscode.postMessage({
        type: 'open-workspaces-renderer-ready',
        version: 1,
        documentGeneration: window.__agentPivotReadyDocumentGeneration,
    });
    restoreAiSessionTabsFromState(document, window.vscode);
    // M2 transition: import the legacy webview-held sub-tab selection into the
    // host-persisted window view state once per boot (first-writer-wins host
    // side), right after the in-session restore above consumed the same map.
    maybeImportLegacyAiSessionViewState(window.vscode, document);
    window.vscode.postMessage({ type: 'request-active-ai-session-terminal' });

    observeStickyGroupHeaderOffset();
}

/* src/webview/webviewSkillPanelScripts.js */
function initSkillPanel(options) {
    options = options || {};

    function getSkillRowDetail(row) {
        var holder = row && row.closest ? row.closest('.skill-row-holder') : null;
        return holder && holder.querySelector
            ? holder.querySelector(':scope > .skill-detail')
            : null;
    }

    function revealSkillCard(dirPath) {
        if (!options.aiPanel || typeof options.aiPanel.querySelector !== 'function') {
            return false;
        }
        var skillsTab = options.aiPanel.querySelector('#ai-tab-skills');
        if (skillsTab && skillsTab.getAttribute('aria-selected') !== 'true' && typeof skillsTab.click === 'function') {
            skillsTab.click();
        }
        var cards = options.aiPanel.querySelectorAll('.skill-row[data-skill-dir]');
        for (var i = 0; i < cards.length; i++) {
            if (cards[i].getAttribute('data-skill-dir') !== dirPath) {
                continue;
            }
            var detail = getSkillRowDetail(cards[i]);
            if (detail) {
                detail.hidden = false;
                cards[i].classList.add('skill-detail-open');
            }
            if (typeof cards[i].scrollIntoView === 'function') {
                cards[i].scrollIntoView({ block: 'center' });
            }
            return true;
        }
        return false;
    }

    var skillAgentFilter = 'all';
    var skillScopeActionSequence = 0;
    var skillScopeActionPending = {};

    function nextSkillScopeActionRequestId() {
        skillScopeActionSequence += 1;
        return 'skill-scope-' + Date.now().toString(36) + '-' + skillScopeActionSequence.toString(36);
    }

    function findSkillScopeActionButton(dirPath, operation) {
        var buttons = document.querySelectorAll
            ? document.querySelectorAll('[data-skill-scope-action]')
            : [];
        for (var i = 0; i < buttons.length; i++) {
            if (buttons[i].getAttribute('data-skill-scope-action') === dirPath
                && buttons[i].getAttribute('data-skill-scope-operation') === operation) {
                return buttons[i];
            }
        }
        return null;
    }

    function markSkillScopeActionPending(button, pending) {
        if (!button || !pending) {
            return;
        }
        button.setAttribute('aria-disabled', 'true');
        button.classList.add('pending');
        button.textContent = pending.operation === 'move-to-global' ? 'Moving…' : 'Applying…';
    }

    function restorePendingSkillScopeActions() {
        Object.keys(skillScopeActionPending).forEach(function (requestId) {
            var pending = skillScopeActionPending[requestId];
            markSkillScopeActionPending(
                findSkillScopeActionButton(pending.dirPath, pending.operation),
                pending
            );
        });
    }

    function isMatchingSkillScopeSettlement(settlement, pending) {
        return Boolean(settlement && settlement.version === 1
            && settlement.requestId === pending.requestId
            && settlement.dirPath === pending.dirPath
            && settlement.operation === pending.operation
            && typeof settlement.ok === 'boolean');
    }

    function announceSkillScopeSettlement(settlement, pending) {
        var status = document.querySelector ? document.querySelector('[data-skill-scope-status]') : null;
        if (!status || !settlement || !pending) {
            return;
        }
        status.textContent = settlement.ok
            ? (pending.operation === 'move-to-global'
                ? 'Skill moved to Global management.'
                : 'Project skill access updated.')
            : (settlement.code === 'cancelled' ? 'Skill action cancelled.' : 'Skill action failed.');
    }

    // Scroll anchors keep each pane's list at its scrolled card/folder across
    // authoritative HTML replacements (window.__agentPivotScrollState is
    // optional: fall back to a clamped scrollTop when it is not loaded).
    var SKILLS_SCROLL_ITEM_SELECTOR = '.skill-row[data-skill-dir], .skill-folder[data-skill-folder]';

    function getSkillsScrollItemKey(el) {
        var dir = el.getAttribute('data-skill-dir');
        if (dir) {
            return 'card:' + dir;
        }
        return 'folder:' + (el.getAttribute('data-skill-store') || '')
            + '|' + (el.getAttribute('data-skill-folder') || '');
    }

    function getSkillsPaneList(pane) {
        return pane && pane.querySelector
            ? pane.querySelector(':scope > .group.steward-section > .group-list')
            : null;
    }

    function captureSkillsListScroll(wrapper) {
        var state = {};
        if (!wrapper || !wrapper.querySelectorAll) {
            return state;
        }
        var panes = wrapper.querySelectorAll('[data-skills-pane]');
        for (var i = 0; i < panes.length; i++) {
            var scope = panes[i].getAttribute('data-skills-pane') || '';
            var list = getSkillsPaneList(panes[i]);
            if (!scope || !list) {
                continue;
            }
            if (window.__agentPivotScrollState
                && typeof window.__agentPivotScrollState.capture === 'function') {
                state[scope] = {
                    anchor: window.__agentPivotScrollState.capture(list, {
                        itemSelector: SKILLS_SCROLL_ITEM_SELECTOR,
                        getKey: getSkillsScrollItemKey,
                    }),
                };
            } else {
                state[scope] = { scrollTop: list.scrollTop };
            }
        }
        return state;
    }

    function restoreSkillsListScroll(wrapper, state) {
        if (!wrapper || !wrapper.querySelectorAll || !state) {
            return;
        }
        var panes = wrapper.querySelectorAll('[data-skills-pane]');
        for (var i = 0; i < panes.length; i++) {
            var scope = panes[i].getAttribute('data-skills-pane') || '';
            var saved = state[scope];
            var list = getSkillsPaneList(panes[i]);
            if (!saved || !list) {
                continue;
            }
            if (saved.anchor && window.__agentPivotScrollState
                && typeof window.__agentPivotScrollState.restore === 'function'
                && window.__agentPivotScrollState.restore(list, saved.anchor, {
                    itemSelector: SKILLS_SCROLL_ITEM_SELECTOR,
                    getKey: getSkillsScrollItemKey,
                })) {
                continue;
            }
            var maxScrollTop = Math.max(0, list.scrollHeight - list.clientHeight);
            var fallback = saved.anchor ? saved.anchor.scrollTop : saved.scrollTop;
            list.scrollTop = Math.min(Math.max(0, Number(fallback) || 0), maxScrollTop);
        }
    }

    function replaceSkillsHtml(html, settlement) {
        var skillsWrapper = document.querySelector
            ? document.querySelector('#ai-panel-skills .sticky-groups-wrapper')
            : null;
        if (!skillsWrapper || typeof html !== 'string') {
            return false;
        }
        var collapsedSkillGroups = captureSkillCollapsedGroups(skillsWrapper);
        var expandedSkillCards = captureSkillExpandedCards(skillsWrapper);
        var listScroll = captureSkillsListScroll(skillsWrapper);
        // Skill ⋯ menus hold one-shot actions derived from pre-mutation rows;
        // folder/section menus carry toggle state and get restored instead.
        if (skillFolderMenu && skillFolderMenu.__identity && skillFolderMenu.__identity.skill) {
            closeSkillFolderMenu();
        }
        var folderMenuState = captureSkillFolderMenuState();
        var focused = document.activeElement && document.activeElement.getAttribute
            ? {
                dirPath: document.activeElement.getAttribute('data-skill-scope-action'),
                operation: document.activeElement.getAttribute('data-skill-scope-operation'),
            }
            : null;
        var candidatePending = settlement ? skillScopeActionPending[settlement.requestId] : null;
        var settledPending = candidatePending && isMatchingSkillScopeSettlement(settlement, candidatePending)
            ? candidatePending
            : null;
        if (settledPending) {
            delete skillScopeActionPending[settlement.requestId];
        }
        skillsWrapper.outerHTML = html;
        var nextSkillsWrapper = document.querySelector('#ai-panel-skills .sticky-groups-wrapper');
        restoreSkillCollapsedGroups(nextSkillsWrapper, collapsedSkillGroups);
        restoreSkillExpandedCards(nextSkillsWrapper, expandedSkillCards);
        restoreSkillFolderMenuState(folderMenuState);
        restorePendingSkillScopeActions();
        applySkillAgentFilter();
        layoutSkillsSplit();
        restoreSkillsListScroll(nextSkillsWrapper, listScroll);
        announceSkillScopeSettlement(settlement, settledPending);
        if (focused && focused.dirPath) {
            var nextFocused = findSkillScopeActionButton(focused.dirPath, focused.operation);
            if (!nextFocused && settledPending && settlement.ok && settlement.resultDirPath) {
                nextFocused = findSkillScopeActionButton(settlement.resultDirPath, 'apply-to-project');
            }
            if (nextFocused && typeof nextFocused.focus === 'function') {
                // The target may sit in a collapsed detail (e.g. the record moved
                // scopes): open it so the focus continuation stays visible.
                var focusHolder = nextFocused.closest('.skill-row-holder');
                var focusDetail = focusHolder && focusHolder.querySelector('.skill-detail');
                if (focusDetail && focusDetail.hidden) {
                    focusDetail.hidden = false;
                    var focusRow = focusHolder.querySelector('.skill-row[data-skill-dir]');
                    if (focusRow) {
                        focusRow.classList.add('skill-detail-open');
                    }
                }
                nextFocused.focus();
            } else if (settledPending && nextSkillsWrapper && typeof nextSkillsWrapper.focus === 'function') {
                nextSkillsWrapper.setAttribute('tabindex', '-1');
                nextSkillsWrapper.focus();
            }
        }
        return true;
    }

    function settleSkillScopeActionWithoutHtml(settlement) {
        var pending = settlement && skillScopeActionPending[settlement.requestId];
        if (!pending || !isMatchingSkillScopeSettlement(settlement, pending) || settlement.ok) {
            return false;
        }
        delete skillScopeActionPending[settlement.requestId];
        var button = findSkillScopeActionButton(pending.dirPath, pending.operation);
        if (button) {
            button.removeAttribute('aria-disabled');
            button.classList.remove('pending');
            button.textContent = pending.label;
        }
        announceSkillScopeSettlement(settlement, pending);
        return true;
    }

    function applySkillAgentFilter() {
        var panel = document.querySelector
            ? document.querySelector('#ai-panel-skills')
            : null;
        if (!panel) {
            return;
        }
        var row = panel.querySelector('[data-skill-filter-row]');
        if (!row) {
            return;
        }
        var buttons = row.querySelectorAll('[data-skill-filter]');
        for (var i = 0; i < buttons.length; i++) {
            buttons[i].classList.toggle('is-active', buttons[i].getAttribute('data-skill-filter') === skillAgentFilter);
        }
        // NOTE: the `hidden` attribute cannot hide .skill-row-holder/.group
        // (author display rules beat the UA [hidden] rule) — use a class.
        var cards = panel.querySelectorAll('.skill-row[data-skill-dir]');
        for (var c = 0; c < cards.length; c++) {
            var agents = cards[c].getAttribute('data-skill-agents') || '';
            var show = skillAgentFilter === 'all'
                || (' ' + agents + ' ').indexOf(' ' + skillAgentFilter + ' ') !== -1;
            var container = cards[c].closest('.skill-row-holder') || cards[c];
            container.classList.toggle('skill-filter-hidden', !show);
        }
        // Children first (reverse document order) so parent folders see their
        // children's computed visibility.
        var sections = panel.querySelectorAll('.group.steward-section, .skill-source-group');
        for (var s = sections.length - 1; s >= 0; s--) {
            var section = sections[s];
            var sectionCards = section.querySelectorAll('.skill-row[data-skill-dir]');
            var sectionVisible = 0;
            for (var sc = 0; sc < sectionCards.length; sc++) {
                var scContainer = sectionCards[sc].closest('.skill-row-holder') || sectionCards[sc];
                if (!scContainer.classList.contains('skill-filter-hidden')) {
                    sectionVisible += 1;
                }
            }
            if (section.classList.contains('skill-source-group')) {
                section.classList.toggle('skill-filter-hidden', sectionVisible === 0);
            } else {
                var childFolders = section.querySelectorAll('.skill-folder');
                var visibleChildFolders = 0;
                for (var cf = 0; cf < childFolders.length; cf++) {
                    if (!childFolders[cf].classList.contains('skill-filter-hidden')) {
                        visibleChildFolders += 1;
                    }
                }
                // Empty leaf folders (created via "+") always stay visible; a folder
                // or section hides only when nothing inside it — cards or child
                // folders — is visible.
                var emptyLeaf = section.classList.contains('skill-folder')
                    && sectionCards.length === 0 && childFolders.length === 0;
                section.classList.toggle('skill-filter-hidden',
                    sectionVisible === 0 && visibleChildFolders === 0 && !emptyLeaf);
            }
            var countEl = section.querySelector(':scope > .group-title > .group-title-badge')
                || section.querySelector(':scope > .skill-source-header > .skill-source-count');
            if (countEl) {
                countEl.textContent = String(sectionVisible);
            }
        }
    }

    function captureSkillCollapsedGroups(wrapper) {
        // Folder nodes are keyed by store + folder path (stable across re-renders);
        // every other section keeps its data-group-id key.
        var ids = [];
        var folders = [];
        if (wrapper && wrapper.querySelectorAll) {
            var collapsed = wrapper.querySelectorAll('.group.steward-section.collapsed');
            for (var i = 0; i < collapsed.length; i++) {
                if (collapsed[i].classList.contains('skill-folder')) {
                    continue;
                }
                ids.push(collapsed[i].getAttribute('data-group-id'));
            }
            var folderNodes = wrapper.querySelectorAll('.skill-folder[data-skill-folder]');
            for (var f = 0; f < folderNodes.length; f++) {
                if (folderNodes[f].classList.contains('collapsed')) {
                    folders.push(folderNodes[f].getAttribute('data-skill-store') + '|' + folderNodes[f].getAttribute('data-skill-folder'));
                }
            }
        }
        return { ids: ids, folders: folders };
    }

    function restoreSkillCollapsedGroups(wrapper, state) {
        if (!wrapper || !state) {
            return;
        }
        var ids = state.ids || [];
        for (var i = 0; i < ids.length; i++) {
            var group = wrapper.querySelector('.group.steward-section[data-group-id="' + ids[i] + '"]');
            if (group) {
                group.classList.add('collapsed');
            }
        }
        var folderKeys = state.folders || [];
        if (!folderKeys.length || !wrapper.querySelectorAll) {
            return;
        }
        var folderNodes = wrapper.querySelectorAll('.skill-folder[data-skill-folder]');
        for (var f = 0; f < folderNodes.length; f++) {
            var key = folderNodes[f].getAttribute('data-skill-store') + '|' + folderNodes[f].getAttribute('data-skill-folder');
            if (folderKeys.indexOf(key) !== -1) {
                folderNodes[f].classList.add('collapsed');
            }
        }
    }

    function onSkillMoveInputKeydown(event) {
        var input = event.target && event.target.closest ? event.target.closest('[data-skill-move-folder]') : null;
        if (!input || event.key !== 'Enter') {
            return;
        }
        event.preventDefault();
        var detail = input.closest('.skill-detail');
        var button = detail && detail.querySelector('[data-skill-move-set]');
        if (button && typeof button.click === 'function') {
            button.click();
        }
    }

    // Scope is positional: switches in the global section act on user-level agent
    // roots, switches in the project section on the current project's agent roots.
    // There is no panel-level scope selector anymore.
    function skillSwitchScope(el) {
        return el.closest && el.closest('[data-group-id="project-skills"]') ? 'project' : 'user';
    }

    var skillFolderMenu = null;

    function closeSkillFolderMenu() {
        if (skillFolderMenu) {
            skillFolderMenu.remove();
            skillFolderMenu = null;
        }
    }

    function onSkillFolderMenuKeydown(event) {
        if (event.key === 'Escape') {
            closeSkillFolderMenu();
        }
    }

    // One shared context menu for folder batch actions (VS Code "More Actions"
    // style): agent switches + delete, built from the ⋯ button's data attributes.
    function positionSkillFolderMenu(menu, button) {
        var rect = menu.getBoundingClientRect();
        var anchor = button.getBoundingClientRect();
        var viewportPadding = 4;
        var left = anchor.right - rect.width;
        var top = anchor.bottom + 2;
        if (left + rect.width + viewportPadding > window.innerWidth) {
            left = Math.max(viewportPadding, window.innerWidth - rect.width - viewportPadding);
        }
        if (left < viewportPadding) {
            left = viewportPadding;
        }
        if (top + rect.height + viewportPadding > window.innerHeight) {
            top = Math.max(viewportPadding, anchor.top - rect.height - 2);
        }
        menu.style.left = left + 'px';
        menu.style.top = top + 'px';
    }

    function appendMenuAgentToggles(menu, button, folder, scope) {
        var agents = ['kimi', 'claude', 'codex'];
        for (var i = 0; i < agents.length; i++) {
            var agent = agents[i];
            var state = button.getAttribute('data-state-' + agent) || 'off';
            var item = document.createElement('div');
            item.className = 'custom-context-menu-item skill-folder-menu-item';
            var label = document.createElement('span');
            label.className = 'skill-folder-menu-agent';
            label.textContent = agent;
            var toggle = document.createElement('button');
            toggle.type = 'button';
            toggle.className = 'skill-ios-toggle' + (state === 'on' ? '' : ' ' + state);
            toggle.title = (state === 'on' ? 'Disable every skill under ' : 'Enable every skill under ')
                + (folder || 'this section') + ' for ' + agent;
            toggle.setAttribute('data-folder-toggle', folder);
            toggle.setAttribute('data-folder-agent', agent);
            toggle.setAttribute('data-folder-scope', scope);
            item.appendChild(label);
            item.appendChild(toggle);
            menu.appendChild(item);
        }
        var separator = document.createElement('div');
        separator.className = 'custom-context-menu-separator';
        menu.appendChild(separator);
    }

    function appendMenuAction(menu, className, text) {
        var item = document.createElement('div');
        item.className = 'custom-context-menu-item ' + className;
        item.textContent = text;
        menu.appendChild(item);
        return item;
    }

    function openSkillFolderMenu(button) {
        closeSkillFolderMenu();
        var folder = button.getAttribute('data-folder-menu') || '';
        var scope = button.getAttribute('data-folder-scope') || 'user';
        var storeNode = button.closest('[data-skill-store]');
        var menu = document.createElement('div');
        menu.className = 'custom-context-menu skill-folder-menu visible';
        if (storeNode) {
            menu.setAttribute('data-skill-store', storeNode.getAttribute('data-skill-store'));
        }
        // DOM construction (not innerHTML) so disk-derived folder names can
        // never break out of attributes and inject markup.
        appendMenuAgentToggles(menu, button, folder, scope);
        var newItem = appendMenuAction(menu, 'skill-folder-menu-new', 'New subfolder');
        newItem.setAttribute('data-skill-menu-new-folder', folder);
        newItem.setAttribute('data-folder-scope', scope);
        var removeItem = appendMenuAction(menu, 'skill-folder-menu-remove', 'Delete empty folder');
        removeItem.setAttribute('data-skill-remove-folder', folder);
        document.body.appendChild(menu);
        positionSkillFolderMenu(menu, button);
        menu.__sourceButton = button;
        menu.__identity = { section: false, folder: folder, scope: scope };
        skillFolderMenu = menu;
    }

    // Per-skill ⋯ menu: one-shot actions derived from the row's own DOM
    // (unmanaged rows carry a Centralize hover action, central rows a move
    // editor), so disk-derived names can never inject markup.
    function openSkillMenu(button) {
        closeSkillFolderMenu();
        var dirPath = button.getAttribute('data-skill-menu') || '';
        var holder = button.closest('.skill-row-holder');
        var menu = document.createElement('div');
        menu.className = 'custom-context-menu skill-folder-menu skill-menu visible';
        var openButton = holder && holder.querySelector('.skill-acts [data-skill-open]');
        var openItem = appendMenuAction(menu, 'skill-menu-open', 'Open SKILL.md');
        openItem.setAttribute('data-skill-open', openButton ? openButton.getAttribute('data-skill-open') || '' : '');
        if (holder && holder.querySelector('[data-skill-centralize]')) {
            var centralizeItem = appendMenuAction(menu, 'skill-menu-centralize', 'Centralize');
            centralizeItem.setAttribute('data-skill-centralize', dirPath);
            var deleteItem = appendMenuAction(menu, 'skill-menu-delete skill-folder-menu-remove', 'Delete');
            deleteItem.setAttribute('data-skill-delete', dirPath);
        }
        if (holder && holder.querySelector('[data-skill-move-edit]')) {
            var moveItem = appendMenuAction(menu, 'skill-menu-move', 'Move to folder…');
            moveItem.setAttribute('data-skill-move-edit', dirPath);
        }
        document.body.appendChild(menu);
        positionSkillFolderMenu(menu, button);
        menu.__sourceButton = button;
        menu.__identity = { skill: dirPath };
        skillFolderMenu = menu;
    }

    // Section (global / project) ⋯ menu: store-level actions.
    function openSkillSectionMenu(button) {
        closeSkillFolderMenu();
        var scope = button.getAttribute('data-section-menu') || 'user';
        var menu = document.createElement('div');
        menu.className = 'custom-context-menu skill-folder-menu visible';
        var storeNode = button.closest('[data-skill-store]');
        if (storeNode) {
            menu.setAttribute('data-skill-store', storeNode.getAttribute('data-skill-store'));
        }
        appendMenuAgentToggles(menu, button, '', scope);
        var newItem = appendMenuAction(menu, 'skill-folder-menu-new', 'New folder');
        newItem.setAttribute('data-skill-menu-new-folder', '');
        newItem.setAttribute('data-folder-scope', scope);
        var migrateItem = appendMenuAction(menu, 'skill-folder-menu-migrate', 'Migrate to central…');
        migrateItem.setAttribute('data-skill-menu-migrate', scope);
        if (scope === 'user') {
            var locationItem = appendMenuAction(
                menu,
                'skill-folder-menu-location',
                'Change Global Skills Location…'
            );
            locationItem.setAttribute('data-change-global-skills-location', '');
        }
        document.body.appendChild(menu);
        positionSkillFolderMenu(menu, button);
        menu.__sourceButton = button;
        menu.__identity = { section: true, folder: '', scope: scope };
        skillFolderMenu = menu;
    }

    // Keep the ⋯ menu open across per-agent toggles: the switch gets a pending
    // look (never an optimistic committed state) and the authoritative
    // skills-updated re-syncs it afterwards. Popup state stays webview-local.
    function captureSkillFolderMenuState() {
        if (!skillFolderMenu || !skillFolderMenu.__identity || skillFolderMenu.__identity.skill) {
            return null;
        }
        return { identity: skillFolderMenu.__identity };
    }

    function restoreSkillFolderMenuState(state) {
        if (!state || !skillFolderMenu) {
            return;
        }
        var identity = state.identity;
        var candidates = document.querySelectorAll(identity.section ? '[data-section-menu]' : '[data-folder-menu]');
        var button = null;
        for (var i = 0; i < candidates.length; i++) {
            var candidate = candidates[i];
            if (identity.section) {
                if (candidate.getAttribute('data-section-menu') === identity.scope) {
                    button = candidate;
                    break;
                }
            } else if (candidate.getAttribute('data-folder-menu') === identity.folder
                && candidate.getAttribute('data-folder-scope') === identity.scope) {
                button = candidate;
                break;
            }
        }
        if (!button) {
            closeSkillFolderMenu();
            return;
        }
        var menu = skillFolderMenu;
        var agents = ['kimi', 'claude', 'codex'];
        for (var j = 0; j < agents.length; j++) {
            var agent = agents[j];
            var sw = menu.querySelector('[data-folder-agent="' + agent + '"]');
            if (!sw) {
                continue;
            }
            var next = button.getAttribute('data-state-' + agent) || 'off';
            sw.classList.remove('off', 'indeterminate', 'skill-toggle-pending');
            sw.disabled = false;
            if (next !== 'on') {
                sw.classList.add(next);
            }
            var folder = sw.getAttribute('data-folder-toggle') || '';
            var target = folder ? 'every skill under ' + folder : 'every skill in this section';
            sw.setAttribute('title', (next === 'on' ? 'Disable ' : 'Enable ') + target + ' for ' + agent);
        }
        menu.__sourceButton = button;
        positionSkillFolderMenu(menu, button);
    }

    function captureSkillExpandedCards(wrapper) {
        var dirs = [];
        if (wrapper && wrapper.querySelectorAll) {
            var open = wrapper.querySelectorAll('.skill-row.skill-detail-open');
            for (var i = 0; i < open.length; i++) {
                dirs.push(open[i].getAttribute('data-skill-dir'));
            }
        }
        return dirs;
    }

    function restoreSkillExpandedCards(wrapper, dirs) {
        if (!wrapper || !dirs || !dirs.length) {
            return;
        }
        var cards = wrapper.querySelectorAll('.skill-row[data-skill-dir]');
        for (var i = 0; i < cards.length; i++) {
            if (dirs.indexOf(cards[i].getAttribute('data-skill-dir')) === -1) {
                continue;
            }
            var detail = getSkillRowDetail(cards[i]);
            if (detail) {
                detail.hidden = false;
                cards[i].classList.add('skill-detail-open');
            }
        }
    }

    // --- Global / Project split panes -------------------------------------
    // Each scope section lives in a .skills-pane so the two sections scroll
    // independently; the resizer sizes the project pane. The split container
    // gets an explicit viewport-fitting height (document offset is scroll
    // invariant, so one pass is enough and body scroll clamps to ~0). A null
    // ratio means "auto": the project pane is content-sized up to a CSS cap.
    var SKILLS_PANE_MIN_PX = 72;
    var SKILLS_SPLIT_BOTTOM_GAP_PX = 6;
    var SKILLS_PANE_KEY_STEP_PX = 24;
    // The dragged project-pane share persists in webview view state (same
    // pattern as aiSessionTabs) so it survives window reloads.
    var SKILLS_PANEL_STATE_KEY = 'skillsPanel';

    function readSkillsPanelState() {
        var api = window.vscode;
        if (!api || typeof api.getState !== 'function') {
            return {};
        }
        var state = api.getState() || {};
        var panel = state[SKILLS_PANEL_STATE_KEY];
        return panel && typeof panel === 'object' && !Array.isArray(panel) ? panel : {};
    }

    function readPersistedProjectPaneRatio() {
        var ratio = Number(readSkillsPanelState().projectPaneRatio);
        return Number.isFinite(ratio) && ratio > 0 && ratio < 1 ? ratio : null;
    }

    function persistSkillsProjectPaneRatio() {
        var api = window.vscode;
        if (!api || typeof api.setState !== 'function') {
            return;
        }
        var state = typeof api.getState === 'function' ? api.getState() || {} : {};
        var panel = Object.assign({}, readSkillsPanelState());
        if (skillsProjectPaneRatio === null) {
            delete panel.projectPaneRatio;
        } else {
            panel.projectPaneRatio = skillsProjectPaneRatio;
        }
        var patch = {};
        patch[SKILLS_PANEL_STATE_KEY] = panel;
        api.setState(Object.assign({}, state, patch));
    }

    var skillsProjectPaneRatio = readPersistedProjectPaneRatio();
    var skillsPaneDragState = null;
    var skillsLayoutScheduled = false;

    function findSkillsSplit() {
        return document.querySelector
            ? document.querySelector('#ai-panel-skills [data-skills-split]')
            : null;
    }

    function getSkillsPaneParts(split) {
        var panes = [];
        var resizers = [];
        if (!split || !split.children) {
            return { panes: panes, resizers: resizers };
        }
        for (var i = 0; i < split.children.length; i++) {
            var child = split.children[i];
            if (!child.getAttribute) {
                continue;
            }
            if (child.hasAttribute('data-skills-pane')) {
                panes.push(child);
            } else if (child.hasAttribute('data-skills-pane-resizer')) {
                resizers.push(child);
            }
        }
        return { panes: panes, resizers: resizers };
    }

    function getSkillsPaneSection(pane) {
        return pane.querySelector
            ? pane.querySelector(':scope > .group.steward-section')
            : null;
    }

    // A pane is "sized" (participates in the split) only while its section is
    // actually visible: collapsed or agent-filtered-out sections collapse their
    // pane to header height / zero so the other pane gets the space.
    function isSkillsPaneSized(pane) {
        var section = getSkillsPaneSection(pane);
        return Boolean(section)
            && !section.classList.contains('collapsed')
            && !section.classList.contains('skill-filter-hidden');
    }

    // Natural content height of a pane's section: header plus the full list
    // content (list.scrollHeight reports the content even while constrained).
    function measureSkillsPaneContentHeight(pane) {
        var section = getSkillsPaneSection(pane);
        if (!section || !section.querySelector) {
            return 0;
        }
        var header = section.querySelector(':scope > .group-title');
        var list = section.querySelector(':scope > .group-list');
        var height = 4; // grid gap + header border
        if (header) {
            height += header.offsetHeight || 0;
        }
        if (list) {
            height += list.scrollHeight || 0;
        }
        return height;
    }

    // Explicit pixel height for the sized project pane: the dragged share when
    // set, otherwise the content height capped to the auto share of the split.
    function computeSkillsProjectPaneHeight(projectPane, inner) {
        var max = Math.max(inner - SKILLS_PANE_MIN_PX, SKILLS_PANE_MIN_PX);
        var px;
        if (skillsProjectPaneRatio !== null) {
            px = Math.round(inner * skillsProjectPaneRatio);
            px = Math.max(px, SKILLS_PANE_MIN_PX);
        } else {
            px = Math.min(measureSkillsPaneContentHeight(projectPane), Math.floor(inner * 0.45));
        }
        return Math.min(px, max);
    }

    function layoutSkillsSplit() {
        var split = findSkillsSplit();
        if (!split || typeof split.getBoundingClientRect !== 'function'
            || !split.getClientRects().length) {
            return false; // hidden (another tab) — keep the last applied state
        }
        var parts = getSkillsPaneParts(split);
        if (!parts.panes.length) {
            split.style.height = '';
            return false;
        }
        var rect = split.getBoundingClientRect();
        var scrollY = window.scrollY || window.pageYOffset || 0;
        var docTop = rect.top + scrollY;
        var resizerHeight = 0;
        for (var r = 0; r < parts.resizers.length; r++) {
            resizerHeight += parts.resizers[r].getBoundingClientRect().height;
        }
        var available = Math.max(
            window.innerHeight - docTop - SKILLS_SPLIT_BOTTOM_GAP_PX,
            SKILLS_PANE_MIN_PX * parts.panes.length + resizerHeight
        );
        split.style.height = Math.round(available) + 'px';

        var sized = parts.panes.map(isSkillsPaneSized);
        var sizedCount = sized.filter(Boolean).length;
        for (var i = 0; i < parts.panes.length; i++) {
            var pane = parts.panes[i];
            pane.classList.toggle('skills-pane-sized', sized[i]);
            // Both sized: the global pane grows around the sized project pane.
            // Only one sized: that pane takes the whole split.
            var grow = sized[i] && (sizedCount === 1
                || pane.getAttribute('data-skills-pane') === 'user');
            pane.classList.toggle('skills-pane-grow', grow);
        }
        var inner = Math.max(available - resizerHeight, SKILLS_PANE_MIN_PX);
        for (var p = 0; p < parts.panes.length; p++) {
            var projectPane = parts.panes[p];
            if (projectPane.getAttribute('data-skills-pane') !== 'project') {
                continue;
            }
            if (sized[p] && sizedCount > 1) {
                projectPane.style.height = computeSkillsProjectPaneHeight(projectPane, inner) + 'px';
            } else {
                projectPane.style.height = '';
            }
        }
        for (var z = 0; z < parts.resizers.length; z++) {
            var resizer = parts.resizers[z];
            resizer.hidden = sizedCount < 2;
            if (sizedCount > 1) {
                var projectSizedPane = null;
                for (var q = 0; q < parts.panes.length; q++) {
                    if (parts.panes[q].getAttribute('data-skills-pane') === 'project') {
                        projectSizedPane = parts.panes[q];
                    }
                }
                if (projectSizedPane) {
                    var percent = Math.round(projectSizedPane.getBoundingClientRect().height / inner * 100);
                    resizer.setAttribute('aria-valuenow', String(Math.min(100, Math.max(0, percent))));
                }
            }
        }
        return true;
    }

    function scheduleSkillsLayout() {
        if (skillsLayoutScheduled) {
            return;
        }
        skillsLayoutScheduled = true;
        if (typeof requestAnimationFrame === 'function') {
            requestAnimationFrame(function () {
                skillsLayoutScheduled = false;
                layoutSkillsSplit();
            });
            return;
        }
        skillsLayoutScheduled = false;
        layoutSkillsSplit();
    }

    function applySkillsProjectPaneHeight(projectPane, inner, nextPx) {
        var clamped = Math.min(Math.max(nextPx, SKILLS_PANE_MIN_PX),
            Math.max(inner - SKILLS_PANE_MIN_PX, SKILLS_PANE_MIN_PX));
        skillsProjectPaneRatio = clamped / inner;
        projectPane.style.height = Math.round(clamped) + 'px';
    }

    function onSkillsPaneResizerPointerDown(event) {
        var resizer = event.target && event.target.closest
            ? event.target.closest('[data-skills-pane-resizer]')
            : null;
        if (!resizer || (event.button !== 0 && event.button !== undefined)) {
            return;
        }
        var split = resizer.closest('[data-skills-split]');
        var parts = getSkillsPaneParts(split);
        var projectPane = null;
        for (var i = 0; i < parts.panes.length; i++) {
            if (parts.panes[i].getAttribute('data-skills-pane') === 'project') {
                projectPane = parts.panes[i];
            }
        }
        if (!projectPane || resizer.hidden) {
            return;
        }
        event.preventDefault();
        var resizerHeight = resizer.getBoundingClientRect().height;
        skillsPaneDragState = {
            pointerId: event.pointerId,
            startY: event.clientY,
            startHeight: projectPane.getBoundingClientRect().height,
            inner: Math.max(split.getBoundingClientRect().height - resizerHeight, SKILLS_PANE_MIN_PX),
            projectPane: projectPane,
            resizer: resizer,
        };
        resizer.classList.add('skills-pane-resizer-active');
        if (document.body) {
            document.body.classList.add('skills-pane-resizing');
        }
        if (event.pointerId !== undefined && typeof resizer.setPointerCapture === 'function') {
            try {
                resizer.setPointerCapture(event.pointerId);
            } catch (_error) { /* capture is best-effort */ }
        }
    }

    function onSkillsPaneResizerPointerMove(event) {
        if (!skillsPaneDragState
            || (skillsPaneDragState.pointerId !== undefined && event.pointerId !== skillsPaneDragState.pointerId)) {
            return;
        }
        // The project pane sits below the resizer: dragging down shrinks it.
        var next = skillsPaneDragState.startHeight - (event.clientY - skillsPaneDragState.startY);
        applySkillsProjectPaneHeight(skillsPaneDragState.projectPane, skillsPaneDragState.inner, next);
        var percent = Math.round(skillsPaneDragState.projectPane.getBoundingClientRect().height
            / skillsPaneDragState.inner * 100);
        skillsPaneDragState.resizer.setAttribute('aria-valuenow', String(Math.min(100, Math.max(0, percent))));
    }

    function onSkillsPaneResizerPointerUp(event) {
        if (!skillsPaneDragState
            || (skillsPaneDragState.pointerId !== undefined && event.pointerId !== skillsPaneDragState.pointerId)) {
            return;
        }
        skillsPaneDragState.resizer.classList.remove('skills-pane-resizer-active');
        if (document.body) {
            document.body.classList.remove('skills-pane-resizing');
        }
        if (event.pointerId !== undefined
            && typeof skillsPaneDragState.resizer.releasePointerCapture === 'function') {
            try {
                skillsPaneDragState.resizer.releasePointerCapture(event.pointerId);
            } catch (_error) { /* capture is best-effort */ }
        }
        skillsPaneDragState = null;
        persistSkillsProjectPaneRatio();
        layoutSkillsSplit();
    }

    function onSkillsPaneResizerKeydown(event) {
        var resizer = event.target && event.target.closest
            ? event.target.closest('[data-skills-pane-resizer]')
            : null;
        if (!resizer || (event.key !== 'ArrowUp' && event.key !== 'ArrowDown')) {
            return;
        }
        var split = resizer.closest('[data-skills-split]');
        var projectPane = split && split.querySelector
            ? split.querySelector('[data-skills-pane="project"]')
            : null;
        if (!projectPane || resizer.hidden) {
            return;
        }
        event.preventDefault();
        var direction = event.key === 'ArrowUp' ? 1 : -1;
        var inner = Math.max(split.getBoundingClientRect().height
            - resizer.getBoundingClientRect().height, SKILLS_PANE_MIN_PX);
        applySkillsProjectPaneHeight(projectPane, inner,
            projectPane.getBoundingClientRect().height + direction * SKILLS_PANE_KEY_STEP_PX);
        persistSkillsProjectPaneRatio();
        layoutSkillsSplit();
    }

    var skillDragState = null;

    function findSkillDropFolder(event) {
        if (!skillDragState) {
            return null;
        }
        var folder = event.target && event.target.closest
            ? event.target.closest('.skill-folder')
            : null;
        var section = event.target && event.target.closest
            ? event.target.closest('.group.steward-section[data-skill-store]')
            : null;
        var target = folder || section;
        if (!target) {
            return null;
        }
        // A card can only move inside its own store: user skills in the global
        // section, project skills in the project section.
        var targetScope = folder
            ? folder.getAttribute('data-skill-folder-scope')
            : (section.getAttribute('data-group-id') === 'project-skills' ? 'project' : 'user');
        if (targetScope !== skillDragState.scope) {
            return null;
        }
        return {
            element: target,
            folder: folder ? folder.getAttribute('data-skill-folder') || '' : '',
        };
    }

    function onSkillDragStart(event) {
        var container = event.target && event.target.closest
            ? event.target.closest('.skill-row-holder[data-skill-scope]')
            : null;
        if (!container) {
            return;
        }
        var card = container.querySelector('.skill-row[data-skill-dir]');
        if (!card) {
            return;
        }
        skillDragState = {
            dirPath: card.getAttribute('data-skill-dir'),
            scope: container.getAttribute('data-skill-scope'),
        };
        container.classList.add('skill-row-dragging');
        if (event.dataTransfer) {
            event.dataTransfer.effectAllowed = 'move';
            event.dataTransfer.setData('text/plain', skillDragState.dirPath);
        }
    }

    function onSkillDragOver(event) {
        var target = findSkillDropFolder(event);
        if (!target) {
            return;
        }
        event.preventDefault();
        if (event.dataTransfer) {
            event.dataTransfer.dropEffect = 'move';
        }
        target.element.classList.add('skill-drop-target');
    }

    function onSkillDragLeave(event) {
        var target = findSkillDropFolder(event);
        if (target && event.relatedTarget && target.element.contains(event.relatedTarget)) {
            return;
        }
        if (target) {
            target.element.classList.remove('skill-drop-target');
        }
    }

    function onSkillDrop(event) {
        var target = findSkillDropFolder(event);
        if (!target) {
            return;
        }
        event.preventDefault();
        target.element.classList.remove('skill-drop-target');
        options.postMessage({
            type: 'move-skill-to-folder',
            dirPath: skillDragState.dirPath,
            folder: target.folder,
        });
    }

    function onSkillDragEnd(event) {
        if (skillDragState) {
            var dragging = document.querySelectorAll('.skill-row-dragging');
            for (var i = 0; i < dragging.length; i++) {
                dragging[i].classList.remove('skill-card-dragging');
            }
        }
        skillDragState = null;
        var targets = document.querySelectorAll('.skill-drop-target');
        for (var t = 0; t < targets.length; t++) {
            targets[t].classList.remove('skill-drop-target');
        }
    }

    function onSkillCardClick(event) {
        var filter = event.target && event.target.closest ? event.target.closest('[data-skill-filter]') : null;
        if (filter) {
            event.preventDefault();
            skillAgentFilter = filter.getAttribute('data-skill-filter') || 'all';
            applySkillAgentFilter();
            return;
        }
        if (skillFolderMenu && !(event.target && event.target.closest && event.target.closest('.skill-folder-menu'))) {
            closeSkillFolderMenu();
        }
        var scopeAction = event.target && event.target.closest ? event.target.closest('[data-skill-scope-action]') : null;
        if (scopeAction) {
            event.preventDefault();
            event.stopPropagation();
            if (scopeAction.disabled || scopeAction.getAttribute('aria-disabled') === 'true'
                || scopeAction.classList.contains('pending')) {
                return;
            }
            var requestId = nextSkillScopeActionRequestId();
            var pending = {
                requestId: requestId,
                dirPath: scopeAction.getAttribute('data-skill-scope-action') || '',
                operation: scopeAction.getAttribute('data-skill-scope-operation') || '',
                label: scopeAction.textContent || '',
            };
            skillScopeActionPending[requestId] = pending;
            markSkillScopeActionPending(scopeAction, pending);
            options.postMessage({
                type: 'skill-scope-action',
                version: 1,
                requestId: requestId,
                dirPath: pending.dirPath,
                operation: pending.operation,
            });
            return;
        }
        var skillMenuButton = event.target && event.target.closest ? event.target.closest('[data-skill-menu]') : null;
        if (skillMenuButton) {
            event.preventDefault();
            event.stopPropagation();
            if (skillFolderMenu && skillFolderMenu.__sourceButton === skillMenuButton) {
                closeSkillFolderMenu();
            } else {
                openSkillMenu(skillMenuButton);
            }
            return;
        }
        var sectionMenuButton = event.target && event.target.closest ? event.target.closest('[data-section-menu]') : null;
        if (sectionMenuButton) {
            event.preventDefault();
            event.stopPropagation();
            if (skillFolderMenu && skillFolderMenu.__sourceButton === sectionMenuButton) {
                closeSkillFolderMenu();
            } else {
                openSkillSectionMenu(sectionMenuButton);
            }
            return;
        }
        var folderMenuButton = event.target && event.target.closest ? event.target.closest('[data-folder-menu]') : null;
        if (folderMenuButton) {
            event.preventDefault();
            event.stopPropagation();
            if (skillFolderMenu && skillFolderMenu.__sourceButton === folderMenuButton) {
                closeSkillFolderMenu();
            } else {
                openSkillFolderMenu(folderMenuButton);
            }
            return;
        }
        var folderToggle = event.target && event.target.closest ? event.target.closest('[data-folder-toggle]') : null;
        if (folderToggle) {
            event.preventDefault();
            event.stopPropagation();
            var folderNode = folderToggle.closest('[data-skill-store]');
            // The menu stays open for multi-agent changes; pending ≠ committed,
            // the authoritative skills-updated re-syncs the switch.
            folderToggle.classList.add('skill-toggle-pending');
            folderToggle.disabled = true;
            options.postMessage({
                type: 'folder-toggle-skill-links',
                storeRoot: folderNode ? folderNode.getAttribute('data-skill-store') : '',
                folder: folderToggle.getAttribute('data-folder-toggle'),
                scope: folderToggle.getAttribute('data-folder-scope'),
                agent: folderToggle.getAttribute('data-folder-agent'),
                enabled: !folderToggle.classList.contains('off') && !folderToggle.classList.contains('indeterminate'),
            });
            return;
        }
        var moveEdit = event.target && event.target.closest ? event.target.closest('[data-skill-move-edit]') : null;
        if (moveEdit) {
            event.preventDefault();
            event.stopPropagation();
            closeSkillFolderMenu();
            // Reveal the row's detail with the move editor open and focused.
            var moveDir = moveEdit.getAttribute('data-skill-move-edit');
            var moveRows = document.querySelectorAll ? document.querySelectorAll('.skill-row[data-skill-dir]') : [];
            for (var mr = 0; mr < moveRows.length; mr++) {
                if (moveRows[mr].getAttribute('data-skill-dir') !== moveDir) {
                    continue;
                }
                var moveDetail = moveRows[mr].closest('.skill-row-holder').querySelector('.skill-detail');
                if (moveDetail) {
                    moveDetail.hidden = false;
                    moveRows[mr].classList.add('skill-detail-open');
                    var moveEditor = moveDetail.querySelector('.skill-move-editor');
                    if (moveEditor) {
                        moveEditor.hidden = false;
                        var moveInput = moveEditor.querySelector('[data-skill-move-folder]');
                        if (moveInput && typeof moveInput.focus === 'function') {
                            moveInput.focus();
                        }
                    }
                }
                break;
            }
            return;
        }
        var moveSet = event.target && event.target.closest ? event.target.closest('[data-skill-move-set]') : null;
        if (moveSet) {
            event.preventDefault();
            event.stopPropagation();
            var moveDetail = moveSet.closest('.skill-detail');
            var moveInput = moveDetail && moveDetail.querySelector('[data-skill-move-folder]');
            options.postMessage({
                type: 'move-skill-to-folder',
                dirPath: moveSet.getAttribute('data-skill-move-set'),
                folder: moveInput ? moveInput.value : '',
            });
            return;
        }
        var newFolder = event.target && event.target.closest ? event.target.closest('[data-skill-menu-new-folder]') : null;
        if (newFolder) {
            event.preventDefault();
            event.stopPropagation();
            closeSkillFolderMenu();
            options.postMessage({
                type: 'create-skill-folder',
                scope: newFolder.getAttribute('data-folder-scope'),
                parentFolder: newFolder.getAttribute('data-skill-menu-new-folder'),
            });
            return;
        }
        var removeFolder = event.target && event.target.closest ? event.target.closest('[data-skill-remove-folder]') : null;
        if (removeFolder) {
            event.preventDefault();
            event.stopPropagation();
            var menuFolder = removeFolder.closest('.skill-folder-menu');
            var removeNode = menuFolder
                ? (skillFolderMenu && skillFolderMenu.__sourceButton
                    ? skillFolderMenu.__sourceButton.closest('[data-skill-store]')
                    : null)
                : removeFolder.closest('[data-skill-store]');
            closeSkillFolderMenu();
            options.postMessage({
                type: 'remove-skill-folder',
                storeRoot: removeNode ? removeNode.getAttribute('data-skill-store') : '',
                folder: removeFolder.getAttribute('data-skill-remove-folder'),
            });
            return;
        }
        var deleteSkill = event.target && event.target.closest ? event.target.closest('[data-skill-delete]') : null;
        if (deleteSkill) {
            event.preventDefault();
            event.stopPropagation();
            closeSkillFolderMenu();
            options.postMessage({ type: 'delete-skill', dirPath: deleteSkill.getAttribute('data-skill-delete') });
            return;
        }
        var applySuggestion = event.target && event.target.closest ? event.target.closest('[data-skill-apply-suggestion]') : null;
        if (applySuggestion) {
            event.preventDefault();
            event.stopPropagation();
            options.postMessage({ type: 'apply-skill-collection', name: applySuggestion.getAttribute('data-skill-apply-suggestion') });
            return;
        }
        var dismissSuggestion = event.target && event.target.closest ? event.target.closest('[data-skill-dismiss-suggestion]') : null;
        if (dismissSuggestion) {
            event.preventDefault();
            event.stopPropagation();
            options.postMessage({ type: 'dismiss-skill-collection', name: dismissSuggestion.getAttribute('data-skill-dismiss-suggestion') });
            return;
        }
        var centralToggle = event.target && event.target.closest ? event.target.closest('[data-central-toggle]') : null;
        if (centralToggle) {
            event.preventDefault();
            event.stopPropagation();
            options.postMessage({
                type: 'central-toggle-skill',
                dirPath: centralToggle.getAttribute('data-central-toggle'),
                source: centralToggle.getAttribute('data-central-source'),
                scope: skillSwitchScope(centralToggle),
                enabled: !centralToggle.classList.contains('off'),
            });
            return;
        }
        var centralize = event.target && event.target.closest ? event.target.closest('[data-skill-centralize]') : null;
        if (centralize) {
            event.preventDefault();
            event.stopPropagation();
            closeSkillFolderMenu();
            options.postMessage({ type: 'centralize-skill', dirPath: centralize.getAttribute('data-skill-centralize') });
            return;
        }
        var migrateCentral = event.target && event.target.closest ? event.target.closest('[data-skill-menu-migrate]') : null;
        if (migrateCentral) {
            event.preventDefault();
            event.stopPropagation();
            closeSkillFolderMenu();
            options.postMessage({ type: 'migrate-skills-to-central', scope: migrateCentral.getAttribute('data-skill-menu-migrate') });
            return;
        }
        var changeGlobalSkillsLocation = event.target && event.target.closest
            ? event.target.closest('[data-change-global-skills-location]')
            : null;
        if (changeGlobalSkillsLocation) {
            event.preventDefault();
            event.stopPropagation();
            closeSkillFolderMenu();
            options.postMessage({ type: 'change-global-skills-location' });
            return;
        }
        var sync = event.target && event.target.closest ? event.target.closest('[data-skill-sync]') : null;
        if (sync) {
            event.preventDefault();
            event.stopPropagation();
            options.postMessage({
                type: 'sync-skill',
                sourceDir: sync.getAttribute('data-skill-sync'),
                targetDir: sync.getAttribute('data-skill-sync-target'),
            });
            return;
        }
        var copy = event.target && event.target.closest ? event.target.closest('[data-skill-copy]') : null;
        if (copy) {
            event.preventDefault();
            event.stopPropagation();
            options.postMessage({
                type: 'copy-skill',
                sourceDir: copy.getAttribute('data-skill-copy'),
                targetRoot: copy.getAttribute('data-skill-copy-root'),
            });
            return;
        }
        var fix = event.target && event.target.closest ? event.target.closest('[data-skill-fix]') : null;
        if (fix) {
            event.preventDefault();
            event.stopPropagation();
            options.postMessage({
                type: 'fix-skill-diagnostic',
                dirPath: fix.getAttribute('data-skill-fix'),
                code: fix.getAttribute('data-skill-fix-code'),
            });
            return;
        }
        var openButton = event.target && event.target.closest ? event.target.closest('[data-skill-open]') : null;
        if (openButton) {
            event.preventDefault();
            event.stopPropagation();
            closeSkillFolderMenu();
            options.postMessage({ type: 'open-skill-file', skillFilePath: openButton.getAttribute('data-skill-open') });
            return;
        }
        var skillCard = event.target && event.target.closest ? event.target.closest('.skill-row[data-skill-dir]') : null;
        if (skillCard) {
            if (event.target.closest && event.target.closest('.skill-detail')) {
                return;
            }
            var detail = getSkillRowDetail(skillCard);
            if (detail) {
                detail.hidden = !detail.hidden;
                skillCard.classList.toggle('skill-detail-open', !detail.hidden);
            }
        }
    }

    function setSkillAgentFilter(value) {
        skillAgentFilter = value;
        applySkillAgentFilter();
    }

    if (typeof document.addEventListener === 'function') {
        document.addEventListener('click', onSkillCardClick);
        document.addEventListener('keydown', onSkillMoveInputKeydown);
        document.addEventListener('keydown', onSkillFolderMenuKeydown);
        document.addEventListener('keydown', onSkillsPaneResizerKeydown);
        document.addEventListener('dragstart', onSkillDragStart);
        document.addEventListener('dragover', onSkillDragOver);
        document.addEventListener('dragleave', onSkillDragLeave);
        document.addEventListener('drop', onSkillDrop);
        document.addEventListener('dragend', onSkillDragEnd);
        document.addEventListener('pointerdown', onSkillsPaneResizerPointerDown);
        document.addEventListener('pointermove', onSkillsPaneResizerPointerMove);
        document.addEventListener('pointerup', onSkillsPaneResizerPointerUp);
        document.addEventListener('pointercancel', onSkillsPaneResizerPointerUp);
    }

    if (typeof window.addEventListener === 'function') {
        window.addEventListener('resize', scheduleSkillsLayout);
    }

    // Re-layout when pane content visibility changes (collapse, agent filter)
    // or when an ancestor panel's hidden attribute toggles (tab switches).
    // Attribute-only: authoritative HTML replacements call layout explicitly.
    if (typeof MutationObserver === 'function' && document.body) {
        var skillsSplitObserver = new MutationObserver(function (mutations) {
            for (var i = 0; i < mutations.length; i++) {
                var target = mutations[i].target;
                if (!target || target.nodeType !== 1) {
                    continue;
                }
                if (mutations[i].attributeName === 'hidden') {
                    scheduleSkillsLayout();
                    return;
                }
                if (mutations[i].attributeName === 'class'
                    && target.closest
                    && target.closest('[data-skills-split]')) {
                    scheduleSkillsLayout();
                    return;
                }
            }
        });
        skillsSplitObserver.observe(document.body, {
            subtree: true,
            attributes: true,
            attributeFilter: ['hidden', 'class'],
        });
    }
    scheduleSkillsLayout();

    return {
        applySkillAgentFilter,
        captureSkillCollapsedGroups,
        captureSkillExpandedCards,
        captureSkillFolderMenuState,
        layoutSkillsSplit,
        replaceSkillsHtml,
        restoreSkillCollapsedGroups,
        restoreSkillExpandedCards,
        restoreSkillFolderMenuState,
        revealSkillCard,
        setSkillAgentFilter,
        settleSkillScopeActionWithoutHtml,
    };
}

/* src/webview/webviewProjectsPanelScripts.js */
function getProjectIdsFromGroup(group) {
    return Array.from(group.querySelectorAll('.project[data-id]:not([data-virtual-project])'))
        .map(project => project.getAttribute('data-id'));
}

function arraysEqual(left, right) {
    return left.length === right.length
        && left.every((value, index) => value === right[index]);
}

function isProjectsPanelOrderConsistent(panel, message) {
    if (!panel || typeof panel.querySelectorAll !== 'function') {
        return false;
    }
    var groups = Array.from(panel.querySelectorAll(
        '.groups-wrapper > .group[data-group-id]:not([data-virtual-group])'
    ));
    if (groups.length !== message.groupOrders.length) {
        return false;
    }
    for (var index = 0; index < groups.length; index += 1) {
        var expected = message.groupOrders[index];
        if (groups[index].getAttribute('data-group-id') !== expected.groupId
            || !arraysEqual(getProjectIdsFromGroup(groups[index]), expected.projectIds)) {
            return false;
        }
    }
    var favoritesGroup = panel.querySelector(
        '.group[data-system-group="__favorites"]'
    );
    var favoriteIds = favoritesGroup
        ? Array.from(favoritesGroup.querySelectorAll('.project[data-id]'))
            .map(project => project.getAttribute('data-id'))
        : [];
    return arraysEqual(favoriteIds, message.favoriteProjectIds);
}

function getProjectsFocusTarget(panel) {
    var activeElement = document.activeElement;
    if (!activeElement || !panel || !panel.contains(activeElement)) {
        return null;
    }
    var project = activeElement.closest ? activeElement.closest('.project[data-id]') : null;
    var action = activeElement.closest ? activeElement.closest('[data-action]') : null;
    return project ? {
        groupId: project.closest('.group[data-group-id]')
            ? project.closest('.group[data-group-id]').getAttribute('data-group-id') || ''
            : '',
        projectId: project.getAttribute('data-id'),
        action: action ? action.getAttribute('data-action') : null,
    } : null;
}

function getProjectScrollItemKey(project) {
    var group = project.closest('.group[data-group-id]');
    return JSON.stringify([
        group ? group.getAttribute('data-group-id') || '' : '',
        project.getAttribute('data-id') || '',
    ]);
}

function captureProjectsPanelState(panel) {
    var state = {
        windowScrollY: window.scrollY,
        focus: getProjectsFocusTarget(panel),
        groups: Array.from(panel.querySelectorAll(
            '.group[data-group-id]'
        )).map(function (group) {
            var list = group.querySelector('.group-list');
            return {
                groupId: group.getAttribute('data-group-id') || '',
                anchor: list && window.__agentPivotScrollState
                    ? window.__agentPivotScrollState.capture(list, {
                        itemSelector: '.project[data-id]',
                        getKey: getProjectScrollItemKey,
                    })
                    : null,
            };
        }),
    };
    if (!state.focus) {
        return state;
    }
    var focusGroup = findProjectsPanelGroup(panel, state.focus.groupId);
    var focusList = focusGroup && focusGroup.querySelector('.group-list');
    var focusProject = focusList && Array.from(
        focusList.querySelectorAll('.project[data-id]')
    ).find(project => project.getAttribute('data-id') === state.focus.projectId);
    var groupState = state.groups.find(group => group.groupId === state.focus.groupId);
    if (!focusList || !focusProject || !groupState || !groupState.anchor) {
        return state;
    }
    groupState.anchor.itemKey = getProjectScrollItemKey(focusProject);
    groupState.anchor.itemOffset = focusProject.getBoundingClientRect().top
        - focusList.getBoundingClientRect().top;
    return state;
}

function findProjectsPanelGroup(panel, groupId) {
    return Array.from(panel.querySelectorAll('.group[data-group-id]'))
        .find(group => (group.getAttribute('data-group-id') || '') === groupId)
        || null;
}

function restoreProjectsPanelAnchors(panel, state) {
    if (!state || !Array.isArray(state.groups) || !window.__agentPivotScrollState) {
        return;
    }
    state.groups.forEach(function (savedGroup) {
        if (!savedGroup.anchor) {
            return;
        }
        var group = findProjectsPanelGroup(panel, savedGroup.groupId);
        var list = group && group.querySelector('.group-list');
        if (!list) {
            return;
        }
        window.__agentPivotScrollState.restore(list, savedGroup.anchor, {
            itemSelector: '.project[data-id]',
            getKey: getProjectScrollItemKey,
        });
    });
}

function restoreProjectsWindowScroll(state) {
    if (state && Number.isFinite(state.windowScrollY)) {
        window.scrollTo(0, state.windowScrollY);
    }
}

function restoreProjectsFocus(panel, target) {
    if (!target || !panel) {
        return;
    }
    var group = findProjectsPanelGroup(panel, target.groupId || '');
    var project = group && Array.from(group.querySelectorAll('.project[data-id]'))
        .find(candidate => candidate.getAttribute('data-id') === target.projectId);
    if (!project) {
        return;
    }
    var focusTarget = project;
    if (target.action) {
        focusTarget = Array.from(project.querySelectorAll('[data-action]'))
            .find(candidate => candidate.getAttribute('data-action') === target.action);
    }
    if (focusTarget && typeof focusTarget.focus === 'function') {
        if (!focusTarget.getAttribute('tabindex')) {
            focusTarget.setAttribute('tabindex', '-1');
        }
        focusTarget.focus({ preventScroll: true });
    }
}

/* src/webview/webviewDashboardValidationScripts.js */
function normalizeDashboardTab(tab) {
    return tab === 'projects' || tab === 'todo' || tab === 'ai' ? tab : 'open';
}

function getAdjacentDashboardTab(tab, key) {
    tab = normalizeDashboardTab(tab);
    var tabs = ['open', 'projects', 'todo', 'ai'];
    var currentIndex = tabs.indexOf(tab);
    if (key === 'Home') {
        return tabs[0];
    }
    if (key === 'End') {
        return tabs[tabs.length - 1];
    }
    if (key === 'ArrowRight') {
        return tabs[(currentIndex + 1) % tabs.length];
    }
    if (key === 'ArrowLeft') {
        return tabs[(currentIndex + tabs.length - 1) % tabs.length];
    }
    return tab;
}

function validateProjectsPanelMessage(message) {
    return !!message
        && message.type === 'projects-panel-content'
        && message.version === 1
        && Number.isSafeInteger(message.requestId)
        && message.requestId > 0
        && typeof message.html === 'string';
}

function validateProjectsPanelUpdatedMessage(message) {
    if (!message
        || message.type !== 'projects-panel-updated'
        || message.version !== 1
        || !Number.isSafeInteger(message.sequence)
        || message.sequence < 1
        || (message.mode !== 'replace' && message.mode !== 'preserve-order')
        || typeof message.html !== 'string'
        || normalizeDashboardSearchCatalog(message.searchCatalog) !== message.searchCatalog
        || !Array.isArray(message.groupOrders)
        || !Array.isArray(message.favoriteProjectIds)) {
        return false;
    }
    var groupIds = new Set();
    var savedProjectIds = new Set();
    for (var group of message.groupOrders) {
        if (!group
            || typeof group.groupId !== 'string'
            || !group.groupId
            || groupIds.has(group.groupId)
            || !Array.isArray(group.projectIds)) {
            return false;
        }
        groupIds.add(group.groupId);
        for (var projectId of group.projectIds) {
            if (typeof projectId !== 'string'
                || !projectId
                || savedProjectIds.has(projectId)) {
                return false;
            }
            savedProjectIds.add(projectId);
        }
    }
    var favoriteIds = new Set();
    for (var favoriteId of message.favoriteProjectIds) {
        if (typeof favoriteId !== 'string'
            || !favoriteId
            || favoriteIds.has(favoriteId)) {
            return false;
        }
        favoriteIds.add(favoriteId);
    }
    return true;
}

function validateTodoPanelMessage(message) {
    return !!message
        && message.type === 'todo-panel-content'
        && message.version === 1
        && Number.isSafeInteger(message.requestId)
        && message.requestId > 0
        && typeof message.html === 'string';
}

function validateTodoPanelUpdatedMessage(message) {
    return !!message
        && message.type === 'todo-panel-updated'
        && message.version === 1
        && typeof message.html === 'string'
        && normalizeDashboardSearchCatalog(message.searchCatalog) === message.searchCatalog;
}

function hasExactObjectKeys(value, requiredKeys, optionalKeys) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        return false;
    }
    var allowedKeys = requiredKeys.concat(optionalKeys || []);
    var keys = Object.keys(value);
    return requiredKeys.every(key => Object.prototype.hasOwnProperty.call(value, key))
        && keys.every(key => allowedKeys.indexOf(key) >= 0);
}

function validatePromptPanelSnapshot(snapshot) {
    if (!hasExactObjectKeys(
        snapshot,
        ['version', 'revision', 'selectedPromptId', 'prompts'],
        ['readOnlyReason']
    )
        || snapshot.version !== 1
        || !Number.isSafeInteger(snapshot.revision)
        || snapshot.revision < 0
        || (snapshot.selectedPromptId !== null
            && (typeof snapshot.selectedPromptId !== 'string' || !snapshot.selectedPromptId))
        || !Array.isArray(snapshot.prompts)
        || (snapshot.readOnlyReason !== undefined
            && snapshot.readOnlyReason !== 'invalid-data'
            && snapshot.readOnlyReason !== 'unsupported-version')) {
        return false;
    }

    var promptIds = new Set();
    var promptNames = new Set();
    for (var prompt of snapshot.prompts) {
        if (!hasExactObjectKeys(prompt, ['id', 'name', 'text'])
            || typeof prompt.id !== 'string'
            || !prompt.id
            || typeof prompt.name !== 'string'
            || !prompt.name.trim()
            || typeof prompt.text !== 'string'
            || !prompt.text.trim()
            || promptIds.has(prompt.id)
            || promptNames.has(prompt.name.toLowerCase())) {
            return false;
        }
        promptIds.add(prompt.id);
        promptNames.add(prompt.name.toLowerCase());
    }
    return snapshot.selectedPromptId === null || promptIds.has(snapshot.selectedPromptId);
}

function validateAiPanelMessage(message) {
    return hasExactObjectKeys(message, [
        'type',
        'version',
        'authoritySequence',
        'requestId',
        'target',
        'snapshot',
        'html',
    ])
        && message.type === 'ai-panel-content'
        && message.version === 1
        && Number.isSafeInteger(message.authoritySequence)
        && message.authoritySequence > 0
        && typeof message.requestId === 'string'
        && message.requestId.length > 0
        && message.requestId.length <= 128
        && message.target === 'global-prompt-library'
        && validatePromptPanelSnapshot(message.snapshot)
        && typeof message.html === 'string';
}

function validatePromptPanelUpdatedMessage(message) {
    return hasExactObjectKeys(message, [
        'type',
        'version',
        'authoritySequence',
        'target',
        'snapshot',
        'html',
    ])
        && message.type === 'prompt-panel-updated'
        && message.version === 1
        && Number.isSafeInteger(message.authoritySequence)
        && message.authoritySequence > 0
        && message.target === 'global-prompt-library'
        && validatePromptPanelSnapshot(message.snapshot)
        && typeof message.html === 'string';
}

function normalizeDashboardSearchCatalog(value) {
    if (value
        && value.version === 3
        && Array.isArray(value.sessions)
        && Array.isArray(value.worktrees)
        && Array.isArray(value.openWorkspaces)
        && Array.isArray(value.savedProjects)
        && Array.isArray(value.todos)
        && (value.skills === undefined || Array.isArray(value.skills))) {
        return value;
    }
    return { version: 3, sessions: [], worktrees: [], openWorkspaces: [], savedProjects: [], todos: [] };
}

function replaceDashboardSearchCatalogState(state, catalog) {
    return Object.assign({}, state, {
        catalog: normalizeDashboardSearchCatalog(catalog),
    });
}

/* src/webview/webviewDashboardSearchScripts.js */
function readInitialDashboardSearchCatalog() {
    var element = document.getElementById('dashboard-search-catalog');
    try {
        return normalizeDashboardSearchCatalog(JSON.parse(element ? element.textContent || '' : ''));
    } catch (_error) {
        return normalizeDashboardSearchCatalog(null);
    }
}

function globToDashboardRegex(value) {
    var escaped = String(value || '')
        .replace(/[.+^${}()|[\]\\]/g, '\\$&')
        .replace(/\*/g, '.*')
        .replace(/\?/g, '.');
    return new RegExp(escaped, 'i');
}

function filterDashboardCatalog(catalog, query) {
    catalog = normalizeDashboardSearchCatalog(catalog);
    var regex = globToDashboardRegex(query);
    var sections = [
        { id: 'ai-sessions', title: 'AI SESSIONS', type: 'session', items: catalog.sessions },
        { id: 'worktrees', title: 'WORKTREES', type: 'worktree', items: catalog.worktrees },
        { id: 'open-workspaces', title: 'OPEN WORKSPACES', type: 'open-workspace', items: catalog.openWorkspaces },
        { id: 'saved-projects', title: 'SAVED PROJECTS', type: 'saved-project', items: catalog.savedProjects },
        { id: 'todos', title: 'TODO RESULTS', type: 'todo', items: catalog.todos },
        { id: 'skills', title: 'SKILLS', type: 'skill', items: catalog.skills || [] },
    ];
    return sections
        .map(section => ({
            id: section.id,
            title: section.title,
            type: section.type,
            items: section.items.filter(item => regex.test(String(item.searchText || ''))),
        }))
        .filter(section => section.items.length > 0);
}

function renderDashboardSearchResults(container, sections) {
    if (!container) {
        return;
    }
    while (container.firstChild) {
        container.removeChild(container.firstChild);
    }
    if (!sections.length) {
        var empty = document.createElement('div');
        empty.className = 'dashboard-search-empty';
        empty.setAttribute('role', 'status');
        empty.textContent = 'No matching projects or AI sessions.';
        container.appendChild(empty);
        return;
    }

    sections.forEach(section => {
        var sectionElement = document.createElement('section');
        sectionElement.className = 'dashboard-search-section';
        sectionElement.dataset.sectionType = section.type;
        var heading = document.createElement('h2');
        heading.className = 'dashboard-search-section-title';
        heading.textContent = section.title;
        sectionElement.appendChild(heading);

        section.items.forEach(item => {
            var button = document.createElement('button');
            button.type = 'button';
            button.className = 'dashboard-search-result';
            button.dataset.projectId = String(item.projectId || '');

            var title = document.createElement('span');
            title.className = 'dashboard-search-result-title';
            title.textContent = String(item.name || item.title || '');
            button.appendChild(title);

            var metadata = document.createElement('span');
            metadata.className = 'dashboard-search-result-meta';
            if (section.type === 'session') {
                button.dataset.provider = String(item.provider || '');
                button.dataset.sessionId = String(item.sessionId || '');
                button.dataset.searchAction = 'reveal-workspace-session';
                button.dataset.workspaceId = String(item.workspaceId || '');
                button.dataset.workspaceNavigationIdentity = String(item.workspaceNavigationIdentity || '');
                metadata.textContent = [item.workspaceName, item.provider].filter(Boolean).join(' · ');
                if (item.active === true) {
                    var activeBadge = document.createElement('span');
                    activeBadge.className = 'dashboard-search-result-status active';
                    activeBadge.textContent = 'Active';
                    metadata.appendChild(activeBadge);
                }
            } else if (section.type === 'worktree') {
                button.dataset.searchAction = 'reveal-workspace-worktree';
                button.dataset.workspaceId = String(item.workspaceId || '');
                button.dataset.workspaceNavigationIdentity = String(item.workspaceNavigationIdentity || '');
                button.dataset.repositoryKey = String(item.repositoryKey || '');
                button.dataset.worktreePath = String(item.canonicalWorktreePath || '');
                metadata.textContent = [item.workspaceName, item.activity, `${item.sessionCount || 0} sessions`]
                    .filter(Boolean).join(' · ');
            } else if (section.type === 'open-workspace') {
                button.dataset.workspaceId = String(item.workspaceId || '');
                button.dataset.workspaceNavigationIdentity = String(item.navigationIdentity || '');
                button.dataset.searchAction = item.current === true
                    ? 'show-current-workspace'
                    : 'switch-open-workspace';
                metadata.textContent = [item.description, item.environmentLabel].filter(Boolean).join(' · ');
            } else if (section.type === 'skill') {
                button.dataset.searchAction = 'reveal-skill';
                button.dataset.skillDir = String(item.dirPath || '');
                metadata.textContent = [item.scope === 'project' ? 'Project' : 'Global', item.description].filter(Boolean).join(' · ');
            } else if (section.type === 'todo') {
                button.dataset.searchAction = 'show-todo';
                button.dataset.todoId = String(item.todoId || '');
                button.dataset.groupId = String(item.groupId || '');
                button.classList.toggle('completed', item.completed === true);
                var groupBadge = document.createElement('span');
                groupBadge.className = 'dashboard-search-result-group steward-badge';
                groupBadge.textContent = String(item.groupTitle || '');
                metadata.appendChild(groupBadge);
                var priority = document.createElement('span');
                priority.className = 'dashboard-search-result-priority';
                priority.textContent = String(item.priority || '').toUpperCase();
                metadata.appendChild(priority);
                if (item.completed === true) {
                    var status = document.createElement('span');
                    status.className = 'dashboard-search-result-status';
                    status.textContent = 'Completed';
                    metadata.appendChild(status);
                }
            } else {
                button.dataset.searchAction = 'open-saved-project';
                metadata.textContent = [item.description].concat(item.groupLabels || []).filter(Boolean).join(' · ');
            }
            button.appendChild(metadata);
            sectionElement.appendChild(button);
        });
        container.appendChild(sectionElement);
    });
}

/* src/webview/webviewDashboardProjectsPanelScripts.js */
function createDashboardProjectsPanel(injected) {
    injected = injected || {};
    var options = injected.options;
    var panels = injected.panels;
    var scheduleTimeout = injected.scheduleTimeout;
    var cancelTimeout = injected.cancelTimeout;
    var panelRequestTimeoutMs = injected.panelRequestTimeoutMs;
    var showPanelLoading = injected.showPanelLoading;
    var showPanelUnavailable = injected.showPanelUnavailable;
    var restoreScroll = injected.restoreScroll;
    var replaceSearchCatalog = injected.replaceSearchCatalog;
    var getActiveTab = injected.getActiveTab;
    var getSearchQuery = injected.getSearchQuery;
    var getPendingScrollRestoreTab = injected.getPendingScrollRestoreTab;
    var setPendingScrollRestoreTab = injected.setPendingScrollRestoreTab;

    var projectsState = 'unloaded';
    var projectsRequestId = 0;
    var acceptedProjectsRequestId = 0;
    var acceptedProjectsUpdateSequence = 0;
    var projectsPanelReplacementGeneration = 0;
    var projectsRequestAttempts = 0;
    var projectsRequestTimer = null;

    function scheduleProjectsRequestTimeout(requestId) {
        if (!scheduleTimeout) {
            return;
        }
        if (projectsRequestTimer !== null) {
            cancelTimeout(projectsRequestTimer);
        }
        projectsRequestTimer = scheduleTimeout(function () {
            projectsRequestTimer = null;
            if (projectsState !== 'loading' || requestId !== projectsRequestId) {
                return;
            }
            projectsState = 'unloaded';
            if (projectsRequestAttempts < 2 && getActiveTab() === 'projects' && !getSearchQuery()) {
                ensureProjectsPanel();
                return;
            }
            showPanelUnavailable('projects');
        }, panelRequestTimeoutMs);
    }

    function ensureProjectsPanel() {
        if (projectsState !== 'unloaded') {
            return;
        }
        projectsState = 'loading';
        projectsRequestAttempts += 1;
        projectsRequestId += 1;
        showPanelLoading('projects');
        options.postMessage({
            type: 'request-projects-panel',
            version: 1,
            requestId: projectsRequestId,
        });
        scheduleProjectsRequestTimeout(projectsRequestId);
    }

    function applyProjectsPanelMessage(message) {
        if (!validateProjectsPanelMessage(message)
            || projectsState !== 'loading'
            || message.requestId !== projectsRequestId
            || message.requestId <= acceptedProjectsRequestId
            || !panels.projects) {
            return false;
        }

        acceptedProjectsRequestId = message.requestId;
        if (projectsRequestTimer !== null) {
            cancelTimeout(projectsRequestTimer);
            projectsRequestTimer = null;
        }
        projectsRequestAttempts = 0;
        panels.projects.innerHTML = message.html;
        projectsState = 'mounted';
        if (typeof options.onProjectsMounted === 'function') {
            options.onProjectsMounted(panels.projects);
        }
        if (getPendingScrollRestoreTab() === 'projects') {
            setPendingScrollRestoreTab(null);
            if (getActiveTab() === 'projects' && !getSearchQuery()) {
                restoreScroll('projects');
            }
        }
        return true;
    }

    function replaceProjectsPanelHtml(html) {
        var panelState = captureProjectsPanelState(panels.projects);
        var replacementGeneration = ++projectsPanelReplacementGeneration;
        panels.projects.innerHTML = html;
        projectsState = 'mounted';
        if (typeof options.onProjectsMounted === 'function') {
            options.onProjectsMounted(panels.projects);
        }
        restoreProjectsPanelAnchors(panels.projects, panelState);
        restoreProjectsFocus(panels.projects, panelState.focus);
        restoreProjectsWindowScroll(panelState);
        requestAnimationFrame(() => {
            if (replacementGeneration !== projectsPanelReplacementGeneration) {
                return;
            }
            restoreProjectsPanelAnchors(panels.projects, panelState);
            restoreProjectsWindowScroll(panelState);
        });
    }

    function applyProjectsPanelUpdatedMessage(message) {
        if (!validateProjectsPanelUpdatedMessage(message)
            || message.sequence <= acceptedProjectsUpdateSequence
            || !panels.projects) {
            return false;
        }
        acceptedProjectsUpdateSequence = message.sequence;
        replaceSearchCatalog(message.searchCatalog);
        if (projectsState !== 'mounted') {
            return true;
        }
        if (message.mode === 'preserve-order' && isProjectsPanelOrderConsistent(panels.projects, message)) {
            projectsPanelReplacementGeneration += 1;
            return true;
        }
        replaceProjectsPanelHtml(message.html);
        return true;
    }

    return {
        ensureProjectsPanel: ensureProjectsPanel,
        applyProjectsPanelMessage: applyProjectsPanelMessage,
        applyProjectsPanelUpdatedMessage: applyProjectsPanelUpdatedMessage,
        getAcceptedProjectsUpdateSequence: () => acceptedProjectsUpdateSequence,
        getProjectsState: () => projectsState,
    };
}

/* src/webview/webviewDashboardTodoPanelScripts.js */
function createDashboardTodoPanel(injected) {
    injected = injected || {};
    var options = injected.options;
    var panels = injected.panels;
    var scheduleTimeout = injected.scheduleTimeout;
    var cancelTimeout = injected.cancelTimeout;
    var panelRequestTimeoutMs = injected.panelRequestTimeoutMs;
    var showPanelLoading = injected.showPanelLoading;
    var showPanelUnavailable = injected.showPanelUnavailable;
    var restoreScroll = injected.restoreScroll;
    var replaceSearchCatalog = injected.replaceSearchCatalog;
    var getActiveTab = injected.getActiveTab;
    var getSearchQuery = injected.getSearchQuery;
    var getPendingScrollRestoreTab = injected.getPendingScrollRestoreTab;
    var setPendingScrollRestoreTab = injected.setPendingScrollRestoreTab;

    var todoState = 'unloaded';
    var todoRequestId = 0;
    var acceptedTodoRequestId = 0;
    var todoRequestAttempts = 0;
    var todoRequestTimer = null;
    var pendingTodoSearchTarget = null;

    function scheduleTodoRequestTimeout(requestId) {
        if (!scheduleTimeout) {
            return;
        }
        if (todoRequestTimer !== null) {
            cancelTimeout(todoRequestTimer);
        }
        todoRequestTimer = scheduleTimeout(function () {
            todoRequestTimer = null;
            if (todoState !== 'loading' || requestId !== todoRequestId) {
                return;
            }
            todoState = 'unloaded';
            if (todoRequestAttempts < 2 && getActiveTab() === 'todo' && !getSearchQuery()) {
                ensureTodoPanel();
                return;
            }
            showPanelUnavailable('todo');
        }, panelRequestTimeoutMs);
    }

    function ensureTodoPanel() {
        if (todoState !== 'unloaded') {
            return;
        }
        todoState = 'loading';
        todoRequestAttempts += 1;
        todoRequestId += 1;
        showPanelLoading('todo');
        options.postMessage({
            type: 'request-todo-panel',
            version: 1,
            requestId: todoRequestId,
        });
        scheduleTodoRequestTimeout(todoRequestId);
    }

    function revealPendingTodoSearchTarget() {
        if (!pendingTodoSearchTarget || !panels.todo || pendingTodoSearchTarget.focusScheduled) {
            return false;
        }
        var scheduledTarget = pendingTodoSearchTarget;
        scheduledTarget.focusScheduled = true;
        requestAnimationFrame(() => {
            if (pendingTodoSearchTarget !== scheduledTarget) {
                return;
            }
            scheduledTarget.focusScheduled = false;
            if (window.__agentPivotTodo
                && typeof window.__agentPivotTodo.openDetail === 'function'
                && window.__agentPivotTodo.openDetail(scheduledTarget.todoId)) {
                pendingTodoSearchTarget = null;
                return;
            }
            var todoItem = Array.from(panels.todo.querySelectorAll('.todo-item[data-todo-id]'))
                .find(item => item.getAttribute('data-todo-id') === scheduledTarget.todoId);
            var todoGroup = todoItem && todoItem.closest ? todoItem.closest('.todo-group') : null;
            if (!todoItem || (todoGroup && todoGroup.classList.contains('collapsed'))) {
                if (!scheduledTarget.revealRequested) {
                    scheduledTarget.revealRequested = true;
                    options.postMessage({
                        type: 'todo-reveal',
                        todoId: scheduledTarget.todoId,
                        groupId: scheduledTarget.groupId,
                    });
                }
                return;
            }
            if (!todoItem.isConnected) {
                return;
            }

            todoItem.setAttribute('tabindex', '-1');
            try {
                todoItem.scrollIntoView({ block: 'nearest' });
                todoItem.focus();
            } catch (_error) {
                todoItem.removeAttribute('tabindex');
                return;
            }
            if (!todoItem.isConnected || document.activeElement !== todoItem) {
                todoItem.removeAttribute('tabindex');
                return;
            }
            pendingTodoSearchTarget = null;
            todoItem.addEventListener('blur', () => todoItem.removeAttribute('tabindex'), { once: true });
        });
        return true;
    }

    function applyTodoPanelMessage(message) {
        if (!validateTodoPanelMessage(message)
            || todoState !== 'loading'
            || message.requestId !== todoRequestId
            || message.requestId <= acceptedTodoRequestId
            || !panels.todo) {
            return false;
        }

        acceptedTodoRequestId = message.requestId;
        if (todoRequestTimer !== null) {
            cancelTimeout(todoRequestTimer);
            todoRequestTimer = null;
        }
        todoRequestAttempts = 0;
        panels.todo.innerHTML = message.html;
        todoState = 'mounted';
        if (normalizeDashboardSearchCatalog(message.searchCatalog) === message.searchCatalog) {
            replaceSearchCatalog(message.searchCatalog);
        }
        if (typeof options.onTodoMounted === 'function') {
            options.onTodoMounted(panels.todo, message);
        }
        if (getPendingScrollRestoreTab() === 'todo') {
            setPendingScrollRestoreTab(null);
            if (getActiveTab() === 'todo' && !getSearchQuery()) {
                restoreScroll('todo');
            }
        }
        revealPendingTodoSearchTarget();
        return true;
    }

    function applyTodoPanelUpdatedMessage(message) {
        if (!validateTodoPanelUpdatedMessage(message) || !panels.todo) {
            return false;
        }

        var activeElement = document.activeElement;
        var restoreShowCompletedFocus = !!activeElement
            && panels.todo.contains(activeElement)
            && activeElement.getAttribute('data-action') === 'todo-toggle-show-completed';
        var fallbackWindowScrollY = restoreShowCompletedFocus
            ? window.scrollY
            : null;
        if (todoRequestTimer !== null) {
            cancelTimeout(todoRequestTimer);
            todoRequestTimer = null;
        }
        todoRequestAttempts = 0;
        replaceSearchCatalog(message.searchCatalog);
        var refreshed = todoState === 'mounted'
            && message.snapshot
            && typeof options.onTodoRefresh === 'function'
            && options.onTodoRefresh(panels.todo, message) === true;
        if (!refreshed) {
            panels.todo.innerHTML = message.html;
            todoState = 'mounted';
            if (typeof options.onTodoMounted === 'function') {
                options.onTodoMounted(panels.todo, message);
            }
            if (restoreShowCompletedFocus) {
                var showCompletedToggle = panels.todo.querySelector(
                    '[data-action="todo-toggle-show-completed"]'
                );
                if (showCompletedToggle) {
                    showCompletedToggle.focus({ preventScroll: true });
                    if (Number.isFinite(fallbackWindowScrollY)) {
                        window.scrollTo(0, fallbackWindowScrollY);
                    }
                }
            }
        }
        revealPendingTodoSearchTarget();
        return true;
    }

    return {
        ensureTodoPanel: ensureTodoPanel,
        revealPendingTodoSearchTarget: revealPendingTodoSearchTarget,
        applyTodoPanelMessage: applyTodoPanelMessage,
        applyTodoPanelUpdatedMessage: applyTodoPanelUpdatedMessage,
        setPendingTodoSearchTarget: target => { pendingTodoSearchTarget = target; },
        getTodoState: () => todoState,
    };
}

/* src/webview/webviewDashboardAiPanelScripts.js */
function createDashboardAiPanel(injected) {
    injected = injected || {};
    var options = injected.options;
    var panels = injected.panels;
    var scheduleTimeout = injected.scheduleTimeout;
    var cancelTimeout = injected.cancelTimeout;
    var panelRequestTimeoutMs = injected.panelRequestTimeoutMs;
    var showPanelLoading = injected.showPanelLoading;
    var showPanelUnavailable = injected.showPanelUnavailable;
    var restoreScroll = injected.restoreScroll;
    var replaceSearchCatalog = injected.replaceSearchCatalog;
    var getActiveTab = injected.getActiveTab;
    var getSearchQuery = injected.getSearchQuery;
    var getPendingScrollRestoreTab = injected.getPendingScrollRestoreTab;
    var setPendingScrollRestoreTab = injected.setPendingScrollRestoreTab;
    var skillPanel = injected.skillPanel;
    var getPendingSkillReveal = injected.getPendingSkillReveal;
    var setPendingSkillReveal = injected.setPendingSkillReveal;

    var aiState = 'unloaded';
    var aiRequestId = null;
    var aiRequestAttempts = 0;
    var aiRequestTimer = null;
    var aiRequestSequence = 0;
    var issuedAiRequestIds = new Set();
    var pendingAiSubtab = null;
    var pendingPromptRefresh = null;

    function scheduleAiRequestTimeout(requestId) {
        if (!scheduleTimeout) {
            return;
        }
        if (aiRequestTimer !== null) {
            cancelTimeout(aiRequestTimer);
        }
        aiRequestTimer = scheduleTimeout(function () {
            aiRequestTimer = null;
            if (aiState !== 'loading' || requestId !== aiRequestId) {
                return;
            }
            aiState = 'unloaded';
            if (aiRequestAttempts < 2 && getActiveTab() === 'ai' && !getSearchQuery()) {
                ensureAiPanel();
                return;
            }
            showPanelUnavailable('ai');
        }, panelRequestTimeoutMs);
    }

    function createFreshAiRequestId() {
        aiRequestSequence += 1;
        var randomId = '';
        try {
            if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
                randomId = crypto.randomUUID();
            }
        } catch (_error) {
            randomId = '';
        }
        if (!randomId) {
            randomId = Date.now().toString(36)
                + '-' + Math.random().toString(36).slice(2);
        }
        var requestId = randomId + '-' + aiRequestSequence.toString(36);
        while (issuedAiRequestIds.has(requestId)) {
            aiRequestSequence += 1;
            requestId = randomId + '-' + aiRequestSequence.toString(36);
        }
        issuedAiRequestIds.add(requestId);
        return requestId;
    }

    function ensureAiPanel() {
        if (aiState !== 'unloaded') {
            return;
        }
        aiState = 'loading';
        aiRequestAttempts += 1;
        aiRequestId = createFreshAiRequestId();
        showPanelLoading('ai');
        options.postMessage({
            type: 'request-ai-panel',
            version: 1,
            requestId: aiRequestId,
            target: 'global-prompt-library',
        });
        scheduleAiRequestTimeout(aiRequestId);
    }

    function failAiPanelMount(previousHtml) {
        if (aiRequestTimer !== null) {
            cancelTimeout(aiRequestTimer);
            aiRequestTimer = null;
        }
        panels.ai.innerHTML = previousHtml;
        aiState = 'unloaded';
        aiRequestAttempts = 0;
        showPanelUnavailable('ai');
        return false;
    }

    function getInstalledPromptSurface(message) {
        if (!panels.ai
            || typeof panels.ai.querySelectorAll !== 'function'
            || !message
            || !message.snapshot) {
            return null;
        }
        var surfaces = Array.from(panels.ai.querySelectorAll('[data-prompt-surface]'));
        if (surfaces.length !== 1 || typeof surfaces[0].getAttribute !== 'function') {
            return null;
        }
        var revisionValue = surfaces[0].getAttribute('data-prompt-revision');
        if (typeof revisionValue !== 'string' || !/^(0|[1-9]\d*)$/.test(revisionValue)) {
            return null;
        }
        var revision = Number(revisionValue);
        return Number.isSafeInteger(revision) && revision === message.snapshot.revision
            ? surfaces[0]
            : null;
    }

    function applyAiPanelMessage(message) {
        if (!validateAiPanelMessage(message)
            || aiState !== 'loading'
            || message.requestId !== aiRequestId
            || !panels.ai) {
            return false;
        }

        var previousHtml = panels.ai.innerHTML;
        try {
            panels.ai.innerHTML = message.html;
        } catch (_error) {
            return failAiPanelMount(previousHtml);
        }
        if (!getInstalledPromptSurface(message)
            || !window.__agentPivotPrompts
            || typeof window.__agentPivotPrompts.mount !== 'function') {
            return failAiPanelMount(previousHtml);
        }
        try {
            if (window.__agentPivotPrompts.mount(panels.ai, message) !== true) {
                return failAiPanelMount(previousHtml);
            }
        } catch (_error) {
            return failAiPanelMount(previousHtml);
        }
        if (aiRequestTimer !== null) {
            cancelTimeout(aiRequestTimer);
            aiRequestTimer = null;
        }
        aiRequestAttempts = 0;
        aiState = 'mounted';
        drainPendingPromptRefresh();
        applyPendingAiSubtab();
        skillPanel.applySkillAgentFilter();
        if (typeof skillPanel.layoutSkillsSplit === 'function') {
            skillPanel.layoutSkillsSplit();
        }
        if (getPendingSkillReveal()) {
            var revealDir = getPendingSkillReveal();
            setPendingSkillReveal(null);
            skillPanel.revealSkillCard(revealDir);
        }
        if (getPendingScrollRestoreTab() === 'ai') {
            setPendingScrollRestoreTab(null);
            if (getActiveTab() === 'ai' && !getSearchQuery()) {
                restoreScroll('ai');
            }
        }
        return true;
    }

    function applyPendingAiSubtab() {
        if (pendingAiSubtab !== 'prompts'
            || aiState !== 'mounted'
            || !panels.ai
            || typeof panels.ai.querySelector !== 'function') {
            return false;
        }
        var promptTab = panels.ai.querySelector('#ai-tab-prompts');
        if (!promptTab || typeof promptTab.click !== 'function') {
            return false;
        }
        pendingAiSubtab = null;
        promptTab.click();
        return true;
    }

    function applyPromptPanelUpdatedMessage(message) {
        if (!validatePromptPanelUpdatedMessage(message)) {
            return false;
        }
        if (aiState !== 'mounted') {
            if (pendingPromptRefresh
                && message.authoritySequence <= pendingPromptRefresh.authoritySequence) {
                return false;
            }
            pendingPromptRefresh = message;
            return true;
        }
        if (!window.__agentPivotPrompts
            || typeof window.__agentPivotPrompts.applyRefresh !== 'function') {
            return false;
        }
        return window.__agentPivotPrompts.applyRefresh(message) === true;
    }

    function drainPendingPromptRefresh() {
        var refresh = pendingPromptRefresh;
        pendingPromptRefresh = null;
        return refresh ? applyPromptPanelUpdatedMessage(refresh) : false;
    }

    return {
        ensureAiPanel: ensureAiPanel,
        applyAiPanelMessage: applyAiPanelMessage,
        applyPendingAiSubtab: applyPendingAiSubtab,
        applyPromptPanelUpdatedMessage: applyPromptPanelUpdatedMessage,
        setPendingAiSubtab: subtab => { pendingAiSubtab = subtab; },
        getAiState: () => aiState,
    };
}

/* src/webview/webviewDashboardScripts.js */
function initDashboard(options) {
    options = options || {};
    var storageKey = 'agentPivot.activeDashboardTab';
    var scrollPositions = { open: 0, projects: 0, todo: 0, ai: 0 };
    var activeTab = normalizeDashboardTab(sessionStorage.getItem(storageKey));
    var pendingScrollRestoreTab = null;
    var panelRequestTimeoutMs = Number(options.panelRequestTimeoutMs) > 0
        ? Number(options.panelRequestTimeoutMs)
        : 5000;
    var scheduleTimeout = options.setTimeout
        || (typeof setTimeout === 'function' ? setTimeout : null);
    var cancelTimeout = options.clearTimeout
        || (typeof clearTimeout === 'function' ? clearTimeout : function () {});
    var catalog = readInitialDashboardSearchCatalog();
    var searchQuery = String(options.initialSearchQuery || '').trim();
    var tabButtons = Array.from(document.querySelectorAll('[data-dashboard-tab]'));
    var panels = {
        open: document.getElementById('dashboard-tab-open'),
        projects: document.getElementById('dashboard-tab-projects'),
        todo: document.getElementById('dashboard-tab-todo'),
        ai: document.getElementById('dashboard-panel-ai'),
    };
    var tablist = document.querySelector ? document.querySelector('[role="tablist"]') : null;
    var collapseButton = document.querySelector ? document.querySelector('[data-action="toggle-all-groups"]') : null;
    var searchResults = document.getElementById('dashboard-search-results');

    function restoreScroll(tab) {
        requestAnimationFrame(() => {
            window.scrollTo(0, scrollPositions[normalizeDashboardTab(tab)] || 0);
        });
    }

    function renderActiveTab() {
        Object.keys(panels).forEach(tab => {
            if (panels[tab]) {
                panels[tab].hidden = tab !== activeTab;
            }
        });
        tabButtons.forEach(button => {
            var selected = normalizeDashboardTab(button.getAttribute('data-dashboard-tab')) === activeTab;
            button.setAttribute('aria-selected', selected ? 'true' : 'false');
            button.setAttribute('tabindex', selected ? '0' : '-1');
            button.classList.toggle('active', selected);
        });
    }

    function renderSearchMode() {
        var active = searchQuery.length > 0;
        if (tablist) {
            tablist.hidden = active;
        }
        if (collapseButton) {
            collapseButton.hidden = active;
        }
        Object.keys(panels).forEach(tab => {
            if (panels[tab]) {
                panels[tab].hidden = active || tab !== activeTab;
            }
        });
        if (searchResults) {
            searchResults.hidden = !active;
        }
        document.body.classList.toggle('dashboard-search-active', active);
        if (active) {
            renderDashboardSearchResults(searchResults, filterDashboardCatalog(catalog, searchQuery));
        }
    }

    function notifyActiveTabChanged() {
        if (typeof options.onActiveTabChanged === 'function') {
            options.onActiveTabChanged(activeTab);
        }
        if (collapseButton && activeTab === 'ai') {
            collapseButton.disabled = true;
            collapseButton.setAttribute('aria-disabled', 'true');
            collapseButton.setAttribute('title', 'No groups to collapse in AI');
            collapseButton.setAttribute('aria-label', 'No groups to collapse in AI');
        }
    }

    function getPanelLoadingElement(tab) {
        var panel = panels[tab];
        if (!panel || !panel.querySelector) {
            return null;
        }
        return panel.querySelector(tab === 'projects'
            ? '.dashboard-projects-loading'
            : tab === 'todo'
                ? '.dashboard-todo-loading'
                : '.dashboard-ai-loading');
    }

    function showPanelLoading(tab) {
        var loadingElement = getPanelLoadingElement(tab);
        if (!loadingElement) {
            return;
        }
        loadingElement.textContent = tab === 'projects'
            ? 'Loading projects…'
            : tab === 'todo'
                ? 'Loading todos…'
                : 'Loading AI configuration…';
        loadingElement.hidden = false;
    }

    function showPanelUnavailable(tab) {
        var loadingElement = getPanelLoadingElement(tab);
        if (!loadingElement) {
            return;
        }
        loadingElement.textContent = (tab === 'projects'
            ? 'Projects'
            : tab === 'todo'
                ? 'TODO'
                : 'AI configuration')
            + ' are temporarily unavailable. Select this tab to retry.';
        loadingElement.hidden = false;
    }








    function activateTab(tab, saveScroll) {
        tab = normalizeDashboardTab(tab);
        saveScroll = saveScroll !== false;
        if (tab !== activeTab) {
            if (saveScroll) {
                scrollPositions[activeTab] = window.scrollY || 0;
            }
            activeTab = tab;
            sessionStorage.setItem(storageKey, activeTab);
        }
        renderActiveTab();
        if (searchQuery) {
            renderSearchMode();
            notifyActiveTabChanged();
            return;
        }
        if (activeTab === 'projects') {
            if (projectsPanel.getProjectsState() === 'mounted') {
                restoreScroll('projects');
            } else {
                pendingScrollRestoreTab = 'projects';
                projectsPanel.ensureProjectsPanel();
            }
        } else if (activeTab === 'todo') {
            if (todoPanel.getTodoState() === 'mounted') {
                restoreScroll('todo');
            } else {
                pendingScrollRestoreTab = 'todo';
                todoPanel.ensureTodoPanel();
            }
        } else if (activeTab === 'ai') {
            if (aiPanel.getAiState() === 'mounted') {
                restoreScroll('ai');
            } else {
                pendingScrollRestoreTab = 'ai';
                aiPanel.ensureAiPanel();
            }
        } else {
            restoreScroll(activeTab);
        }
        notifyActiveTabChanged();
    }

    function setSearchQuery(query) {
        var nextQuery = String(query || '').trim();
        var wasActive = searchQuery.length > 0;
        if (!wasActive && nextQuery) {
            scrollPositions[activeTab] = window.scrollY || 0;
        }
        searchQuery = nextQuery;
        renderSearchMode();
        if (!searchQuery && wasActive) {
            renderActiveTab();
            if (activeTab === 'projects' && projectsPanel.getProjectsState() !== 'mounted') {
                pendingScrollRestoreTab = 'projects';
                projectsPanel.ensureProjectsPanel();
            } else if (activeTab === 'todo' && todoPanel.getTodoState() !== 'mounted') {
                pendingScrollRestoreTab = 'todo';
                todoPanel.ensureTodoPanel();
            } else if (activeTab === 'ai' && aiPanel.getAiState() !== 'mounted') {
                pendingScrollRestoreTab = 'ai';
                aiPanel.ensureAiPanel();
            } else {
                restoreScroll(activeTab);
            }
        }
        notifyActiveTabChanged();
    }

    function replaceSearchCatalog(nextCatalog) {
        var state = replaceDashboardSearchCatalogState({
            activeTab,
            searchQuery,
            scrollPositions,
            catalog,
        }, nextCatalog);
        catalog = state.catalog;
        if (searchQuery) {
            renderDashboardSearchResults(searchResults, filterDashboardCatalog(catalog, searchQuery));
        }
    }

    var pendingSkillReveal = null;

    function onSearchResultClick(event) {
        var button = event.target && event.target.closest
            ? event.target.closest('.dashboard-search-result[data-search-action]')
            : null;
        if (!button) {
            return;
        }
        var action = button.dataset.searchAction;
        if (action === 'resume-session') {
            var provider = button.dataset.provider;
            if (provider !== 'codex' && provider !== 'kimi' && provider !== 'claude') {
                return;
            }
            if (typeof window.__agentPivotAcknowledgeSession === 'function') {
                window.__agentPivotAcknowledgeSession(provider, button.dataset.sessionId);
            }
            options.postMessage({
                type: 'resume-' + provider + '-session',
                provider,
                projectId: button.dataset.projectId,
                sessionId: button.dataset.sessionId,
            });
            return;
        }
        if (action === 'reveal-skill') {
            if (typeof options.clearSearch === 'function') {
                options.clearSearch();
            } else {
                setSearchQuery('');
            }
            pendingSkillReveal = String(button.dataset.skillDir || '');
            activateTab('ai', false);
            if (aiPanel.getAiState() === 'mounted') {
                var revealDir = pendingSkillReveal;
                pendingSkillReveal = null;
                skillPanel.revealSkillCard(revealDir);
            }
            return;
        }
        if (action === 'reveal-workspace-session') {
            if (typeof options.clearSearch === 'function') {
                options.clearSearch();
            } else {
                setSearchQuery('');
            }
            activateTab('open', false);
            if (typeof window.__agentPivotRevealWorkspaceSession === 'function') {
                window.__agentPivotRevealWorkspaceSession(
                    button.dataset.workspaceNavigationIdentity,
                    button.dataset.provider,
                    button.dataset.sessionId
                );
            }
            return;
        }
        if (action === 'reveal-workspace-worktree') {
            if (typeof options.clearSearch === 'function') {
                options.clearSearch();
            } else {
                setSearchQuery('');
            }
            activateTab('open', false);
            if (typeof window.__agentPivotRevealWorkspaceWorktree === 'function') {
                window.__agentPivotRevealWorkspaceWorktree(
                    button.dataset.workspaceNavigationIdentity,
                    button.dataset.repositoryKey,
                    button.dataset.worktreePath
                );
            } else if (typeof window.__agentPivotRevealWorkspace === 'function') {
                window.__agentPivotRevealWorkspace(button.dataset.workspaceNavigationIdentity);
            }
            return;
        }
        if (action === 'show-current-workspace') {
            if (typeof options.clearSearch === 'function') {
                options.clearSearch();
            } else {
                setSearchQuery('');
            }
            activateTab('open', false);
            if (typeof window.__agentPivotRevealWorkspace === 'function') {
                window.__agentPivotRevealWorkspace(button.dataset.workspaceNavigationIdentity);
            }
            return;
        }
        if (action === 'switch-open-workspace') {
            options.postMessage({
                type: 'selected-workspace',
                workspaceId: button.dataset.workspaceId,
                navigationIdentity: button.dataset.workspaceNavigationIdentity,
            });
            return;
        }
        if (action === 'open-saved-project') {
            options.postMessage({
                type: 'selected-project',
                projectId: button.dataset.projectId,
                projectOpenType: 0,
            });
            return;
        }
        if (action === 'show-todo') {
            todoPanel.setPendingTodoSearchTarget({
                todoId: String(button.dataset.todoId || ''),
                groupId: String(button.dataset.groupId || ''),
                revealRequested: false,
                focusScheduled: false,
            });
            if (typeof options.clearSearch === 'function') {
                options.clearSearch();
            } else {
                setSearchQuery('');
            }
            activateTab('todo', false);
            if (todoPanel.getTodoState() === 'mounted') {
                todoPanel.revealPendingTodoSearchTarget();
            }
        }
    }

    var skillPanel = initSkillPanel({
        postMessage: options.postMessage,
        aiPanel: panels.ai,
    });
    var projectsPanel = createDashboardProjectsPanel({
        options: options,
        panels: panels,
        scheduleTimeout: scheduleTimeout,
        cancelTimeout: cancelTimeout,
        panelRequestTimeoutMs: panelRequestTimeoutMs,
        showPanelLoading: showPanelLoading,
        showPanelUnavailable: showPanelUnavailable,
        restoreScroll: restoreScroll,
        replaceSearchCatalog: replaceSearchCatalog,
        getActiveTab: () => activeTab,
        getSearchQuery: () => searchQuery,
        getPendingScrollRestoreTab: () => pendingScrollRestoreTab,
        setPendingScrollRestoreTab: value => { pendingScrollRestoreTab = value; },
    });
    var todoPanel = createDashboardTodoPanel({
        options: options,
        panels: panels,
        scheduleTimeout: scheduleTimeout,
        cancelTimeout: cancelTimeout,
        panelRequestTimeoutMs: panelRequestTimeoutMs,
        showPanelLoading: showPanelLoading,
        showPanelUnavailable: showPanelUnavailable,
        restoreScroll: restoreScroll,
        replaceSearchCatalog: replaceSearchCatalog,
        getActiveTab: () => activeTab,
        getSearchQuery: () => searchQuery,
        getPendingScrollRestoreTab: () => pendingScrollRestoreTab,
        setPendingScrollRestoreTab: value => { pendingScrollRestoreTab = value; },
    });
    var aiPanel = createDashboardAiPanel({
        options: options,
        panels: panels,
        scheduleTimeout: scheduleTimeout,
        cancelTimeout: cancelTimeout,
        panelRequestTimeoutMs: panelRequestTimeoutMs,
        showPanelLoading: showPanelLoading,
        showPanelUnavailable: showPanelUnavailable,
        restoreScroll: restoreScroll,
        replaceSearchCatalog: replaceSearchCatalog,
        getActiveTab: () => activeTab,
        getSearchQuery: () => searchQuery,
        getPendingScrollRestoreTab: () => pendingScrollRestoreTab,
        setPendingScrollRestoreTab: value => { pendingScrollRestoreTab = value; },
        skillPanel: skillPanel,
        getPendingSkillReveal: () => pendingSkillReveal,
        setPendingSkillReveal: value => { pendingSkillReveal = value; },
    });













    tabButtons.forEach(button => {
        button.addEventListener('click', () => {
            activateTab(button.getAttribute('data-dashboard-tab'));
        });
        button.addEventListener('keydown', event => {
            var tab = normalizeDashboardTab(button.getAttribute('data-dashboard-tab'));
            if (event.key === 'ArrowLeft'
                || event.key === 'ArrowRight'
                || event.key === 'Home'
                || event.key === 'End') {
                event.preventDefault();
                var adjacentTab = getAdjacentDashboardTab(tab, event.key);
                var adjacentButton = tabButtons.find(candidate =>
                    normalizeDashboardTab(candidate.getAttribute('data-dashboard-tab')) === adjacentTab
                );
                if (adjacentButton) {
                    adjacentButton.focus();
                }
                return;
            }
            if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                activateTab(tab);
            }
        });
    });

    window.addEventListener('message', event => {
        if (event && event.data && event.data.type === 'projects-panel-content') {
            projectsPanel.applyProjectsPanelMessage(event.data);
        }
        if (event && event.data && event.data.type === 'projects-panel-updated') {
            if (validateProjectsPanelUpdatedMessage(event.data)
                && event.data.sequence <= projectsPanel.getAcceptedProjectsUpdateSequence()) {
                return;
            }
            if (!projectsPanel.applyProjectsPanelUpdatedMessage(event.data)) {
                options.postMessage({
                    type: 'request-full-refresh',
                    reason: 'invalid-projects-panel-update',
                });
            }
        }
        if (event && event.data && event.data.type === 'todo-panel-content') {
            todoPanel.applyTodoPanelMessage(event.data);
        }
        if (event && event.data && event.data.type === 'todo-panel-updated') {
            todoPanel.applyTodoPanelUpdatedMessage(event.data);
        }
        if (event && event.data && event.data.type === 'ai-panel-content') {
            aiPanel.applyAiPanelMessage(event.data);
        }
        if (event && event.data && event.data.type === 'prompt-panel-updated') {
            aiPanel.applyPromptPanelUpdatedMessage(event.data);
        }
        if (event && event.data && event.data.type === 'skills-updated') {
            skillPanel.replaceSkillsHtml(event.data.html, event.data.settlement);
        }
        if (event && event.data && event.data.type === 'skill-scope-action-result') {
            skillPanel.settleSkillScopeActionWithoutHtml(event.data);
        }
        if (event && event.data
            && event.data.type === 'select-dashboard-tab'
            && event.data.version === 1
            && event.data.tab === 'ai'
            && event.data.aiSubtab === 'prompts') {
            if (searchQuery && typeof options.clearSearch === 'function') {
                options.clearSearch();
            }
            if (searchQuery) {
                setSearchQuery('');
            }
            aiPanel.setPendingAiSubtab('prompts');
            activateTab('ai');
            aiPanel.applyPendingAiSubtab();
        }
        if (event && event.data
            && event.data.type === 'reveal-workspace-worktree-requested'
            && event.data.version === 1
            && Object.keys(event.data).length === 5
            && typeof event.data.navigationIdentity === 'string'
            && event.data.navigationIdentity
            && typeof event.data.repositoryKey === 'string'
            && event.data.repositoryKey
            && typeof event.data.canonicalWorktreePath === 'string'
            && event.data.canonicalWorktreePath) {
            if (searchQuery && typeof options.clearSearch === 'function') {
                options.clearSearch();
            }
            if (searchQuery) {
                setSearchQuery('');
            }
            activateTab('open', false);
            if (typeof window.__agentPivotRevealWorkspaceWorktree === 'function') {
                window.__agentPivotRevealWorkspaceWorktree(
                    event.data.navigationIdentity,
                    event.data.repositoryKey,
                    event.data.canonicalWorktreePath
                );
            }
        }
    });
    if (searchResults) {
        searchResults.addEventListener('click', onSearchResultClick);
    }
    renderActiveTab();
    if (searchQuery) {
        renderSearchMode();
    } else if (activeTab === 'projects') {
        pendingScrollRestoreTab = 'projects';
        projectsPanel.ensureProjectsPanel();
    } else if (activeTab === 'todo') {
        pendingScrollRestoreTab = 'todo';
        todoPanel.ensureTodoPanel();
    } else if (activeTab === 'ai') {
        pendingScrollRestoreTab = 'ai';
        aiPanel.ensureAiPanel();
    }
    document.body.classList.remove('preload');
    notifyActiveTabChanged();

    return {
        activateTab,
        applyProjectsPanelMessage: projectsPanel.applyProjectsPanelMessage,
        applyProjectsPanelUpdatedMessage: projectsPanel.applyProjectsPanelUpdatedMessage,
        applyTodoPanelMessage: todoPanel.applyTodoPanelMessage,
        applyTodoPanelUpdatedMessage: todoPanel.applyTodoPanelUpdatedMessage,
        applyAiPanelMessage: aiPanel.applyAiPanelMessage,
        applyPromptPanelUpdatedMessage: aiPanel.applyPromptPanelUpdatedMessage,
        ensureProjectsPanel: projectsPanel.ensureProjectsPanel,
        ensureTodoPanel: todoPanel.ensureTodoPanel,
        ensureAiPanel: aiPanel.ensureAiPanel,
        getActiveTab: () => activeTab,
        getProjectsState: projectsPanel.getProjectsState,
        getTodoState: todoPanel.getTodoState,
        getAiState: aiPanel.getAiState,
        getScrollPosition: tab => scrollPositions[normalizeDashboardTab(tab)],
        isSearchActive: () => searchQuery.length > 0,
        replaceSearchCatalog,
        setSearchQuery,
    };
}

/* src/webview/webviewPromptProtocolScripts.js */
var PROMPT_VERSION = 1;

var PROMPT_TARGET = 'global-prompt-library';

var MAX_REQUEST_ID_LENGTH = 128;

var OPERATIONS = new Set([
    'create',
    'update',
    'delete',
    'reorder',
    'select-default',
]);

var ERROR_CODES = new Set([
    'invalid',
    'not-found',
    'conflict',
    'storage',
    'settings-write-conflict',
    'unsupported-version',
    'cancelled',
]);

var INSERT_ERROR_CODES = new Set([
    'no-active-terminal',
    'prompt-unavailable',
    'prompt-not-found',
    'terminal-unavailable',
]);

function clonePromptValue(value) {
    if (value === null || value === undefined) {
        return value;
    }
    return JSON.parse(JSON.stringify(value));
}

function correlationKey(message) {
    return [
        message.version,
        message.requestId,
        message.target,
        message.operation,
    ].join(':');
}

function insertCorrelationKey(message) {
    return [
        message.version,
        message.requestId,
        message.target,
        'insert-terminal',
    ].join(':');
}

function hasExactKeys(value, requiredKeys, optionalKeys) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        return false;
    }
    var allowedKeys = requiredKeys.concat(optionalKeys || []);
    var keys = Object.keys(value);
    return requiredKeys.every(function (key) {
        return Object.prototype.hasOwnProperty.call(value, key);
    }) && keys.every(function (key) {
        return allowedKeys.indexOf(key) >= 0;
    });
}

function isRequestId(value) {
    return typeof value === 'string'
        && value.length > 0
        && value.length <= MAX_REQUEST_ID_LENGTH;
}

function isAuthoritySequence(value) {
    return Number.isSafeInteger(value) && value > 0;
}

function isPromptSnapshot(snapshot) {
    if (!hasExactKeys(
        snapshot,
        ['version', 'revision', 'selectedPromptId', 'prompts'],
        ['readOnlyReason']
    )
        || snapshot.version !== PROMPT_VERSION
        || !Number.isSafeInteger(snapshot.revision)
        || snapshot.revision < 0
        || (snapshot.selectedPromptId !== null
            && (typeof snapshot.selectedPromptId !== 'string'
                || snapshot.selectedPromptId.length === 0))
        || !Array.isArray(snapshot.prompts)
        || (snapshot.readOnlyReason !== undefined
            && snapshot.readOnlyReason !== 'invalid-data'
            && snapshot.readOnlyReason !== 'unsupported-version')) {
        return false;
    }

    var ids = new Set();
    var names = new Set();
    for (var prompt of snapshot.prompts) {
        if (!hasExactKeys(prompt, ['id', 'name', 'text'])
            || typeof prompt.id !== 'string'
            || prompt.id.length === 0
            || typeof prompt.name !== 'string'
            || prompt.name.trim().length === 0
            || typeof prompt.text !== 'string'
            || prompt.text.trim().length === 0
            || ids.has(prompt.id)
            || names.has(prompt.name.toLowerCase())) {
            return false;
        }
        ids.add(prompt.id);
        names.add(prompt.name.toLowerCase());
    }
    return snapshot.selectedPromptId === null || ids.has(snapshot.selectedPromptId);
}

function isCommandResult(message) {
    return hasExactKeys(message, [
        'type',
        'version',
        'authoritySequence',
        'requestId',
        'target',
        'operation',
        'success',
        'snapshot',
        'html',
    ], ['errorCode'])
        && message.type === 'prompt-command-result'
        && message.version === PROMPT_VERSION
        && isAuthoritySequence(message.authoritySequence)
        && isRequestId(message.requestId)
        && message.target === PROMPT_TARGET
        && OPERATIONS.has(message.operation)
        && typeof message.success === 'boolean'
        && isPromptSnapshot(message.snapshot)
        && typeof message.html === 'string'
        && (message.success
            ? message.errorCode === undefined
            : ERROR_CODES.has(message.errorCode));
}

function isInsertResult(message) {
    return hasExactKeys(message, [
        'type',
        'version',
        'requestId',
        'target',
        'success',
        'errorCode',
    ])
        && message.type === 'prompt-insert-terminal-result'
        && message.version === PROMPT_VERSION
        && isRequestId(message.requestId)
        && message.target === PROMPT_TARGET
        && typeof message.success === 'boolean'
        && (message.success
            ? message.errorCode === null
            : INSERT_ERROR_CODES.has(message.errorCode));
}

function isRefresh(message) {
    return hasExactKeys(message, [
        'type',
        'version',
        'authoritySequence',
        'target',
        'snapshot',
        'html',
    ])
        && message.type === 'prompt-panel-updated'
        && message.version === PROMPT_VERSION
        && isAuthoritySequence(message.authoritySequence)
        && message.target === PROMPT_TARGET
        && isPromptSnapshot(message.snapshot)
        && typeof message.html === 'string';
}

function readSurfaceRevision(surface) {
    if (!surface || typeof surface.getAttribute !== 'function') {
        return null;
    }
    var value = surface.getAttribute('data-prompt-revision');
    if (typeof value !== 'string' || !/^(0|[1-9]\d*)$/.test(value)) {
        return null;
    }
    var revision = Number(value);
    return Number.isSafeInteger(revision) ? revision : null;
}

function mutationAnnouncement(operation) {
    if (operation === 'create') return 'Saving new Prompt…';
    if (operation === 'update') return 'Saving Prompt changes…';
    if (operation === 'delete') return 'Waiting for Prompt deletion confirmation…';
    if (operation === 'reorder') return 'Saving Prompt order…';
    return 'Saving default Prompt…';
}

function successAnnouncement(operation) {
    if (operation === 'create') return 'Prompt created.';
    if (operation === 'update') return 'Prompt updated.';
    if (operation === 'delete') return 'Prompt deleted.';
    if (operation === 'reorder') return 'Prompt order saved.';
    return 'Default Prompt updated.';
}

function errorAnnouncement(code) {
    if (code === 'cancelled') return 'Prompt deletion was cancelled.';
    if (code === 'conflict') {
        return 'Prompts changed elsewhere. Reopen the form to review your draft.';
    }
    if (code === 'not-found') return 'That Prompt no longer exists.';
    if (code === 'invalid') return 'Check the Prompt fields and try again.';
    if (code === 'unsupported-version') {
        return 'This Prompt library needs a newer version of Agent Pivot.';
    }
    if (code === 'settings-write-conflict') {
        return 'Save or revert User Settings, then try again. Your Prompt draft is still here.';
    }
    return 'Could not save the Prompt change. The latest saved library is shown.';
}

function insertErrorAnnouncement(code) {
    if (code === 'no-active-terminal') {
        return 'No active terminal is available to receive the Prompt.';
    }
    if (code === 'prompt-unavailable') {
        return 'AI Prompts are currently unavailable.';
    }
    if (code === 'prompt-not-found') {
        return 'That Prompt is no longer available.';
    }
    return 'The selected terminal is no longer available.';
}

function closest(target, selector) {
    return target && typeof target.closest === 'function'
        ? target.closest(selector)
        : null;
}

function setInsertPending(control, pending) {
    if (!control || typeof control.setAttribute !== 'function') {
        return;
    }
    if (pending) {
        control.setAttribute('aria-disabled', 'true');
        control.setAttribute('data-prompt-insert-pending', 'true');
    } else {
        control.removeAttribute('aria-disabled');
        control.removeAttribute('data-prompt-insert-pending');
    }
}

function surfaceHtmlHasRevision(html, revision) {
    var trimmed = String(html || '').trim();
    if (!trimmed) {
        return false;
    }
    if (typeof document.createElement === 'function') {
        try {
            var template = document.createElement('template');
            template.innerHTML = trimmed;
            if (!template.content
                || template.content.childElementCount !== 1
                || !template.content.firstElementChild
                || !template.content.firstElementChild.hasAttribute('data-prompt-surface')) {
                return false;
            }
            return readSurfaceRevision(template.content.firstElementChild) === revision;
        } catch (_error) {
            return false;
        }
    }
    var opening = trimmed.match(/^<[a-zA-Z][\w:-]*\b([^>]*)>/);
    if (!opening || !/\bdata-prompt-surface(?:\s|=|>)/.test(opening[0])) {
        return false;
    }
    var revisionMatch = opening[0].match(
        /\bdata-prompt-revision\s*=\s*["'](0|[1-9]\d*)["']/
    );
    return Boolean(revisionMatch) && Number(revisionMatch[1]) === revision;
}

function readField(form, name) {
    var field = form && typeof form.querySelector === 'function'
        ? form.querySelector('[name="' + name + '"]')
        : null;
    return field ? String(field.value || '') : '';
}

function resetPromptForm(form) {
    if (!form) {
        return;
    }
    if (typeof form.reset === 'function') {
        form.reset();
    }
    clearFieldError(form, 'name');
    clearFieldError(form, 'text');
    form.hidden = true;
}

function formMatchesDraft(form, draft) {
    if (!form || !draft) {
        return false;
    }
    var kind = form.getAttribute('data-prompt-form');
    if (kind !== draft.kind) {
        return false;
    }
    return kind === 'create'
        || form.getAttribute('data-prompt-id') === draft.promptId;
}

function clearFieldError(form, name) {
    var error = form.querySelector('[data-prompt-field-error="' + name + '"]');
    var field = form.querySelector('[name="' + name + '"]');
    if (error) error.textContent = '';
    if (field && typeof field.removeAttribute === 'function') {
        field.removeAttribute('aria-invalid');
    }
}

function setFieldError(form, name, message) {
    var error = form.querySelector('[data-prompt-field-error="' + name + '"]');
    var field = form.querySelector('[name="' + name + '"]');
    if (error) error.textContent = message;
    if (field && typeof field.setAttribute === 'function') {
        field.setAttribute('aria-invalid', 'true');
    }
}

function tabName(tab) {
    var id = tab && (tab.id || tab.getAttribute('id'));
    var match = typeof id === 'string' ? id.match(/^ai-tab-(prompts|skills|mcp|hooks)$/) : null;
    return match ? match[1] : null;
}

